def _planner_explicit_exact_response_goal(text: str) -> bool:
    """Share Goal-layer exact-response framing without an import cycle."""

    from apps.shell.agent.runtime.goal_runtime import (
        _explicit_exact_response_goal,
    )

    return _explicit_exact_response_goal(text)


class TaskIntentRouter:
    """Deterministic first-pass task intent router.

    Later phases can add model-assisted classification. This conservative
    router gives Chat, Bubble, Live2D, and Studio the same public intent shape.
    """

    def candidate_intents(
        self,
        prompt: str,
        metadata: Mapping[str, Any] | None = None,
    ) -> list[TaskIntentSnapshot]:
        text = _clean_prompt(prompt)
        metadata = metadata or {}
        if _planner_explicit_exact_response_goal(text):
            # Framing owns the whole request. Domain-looking payload tokens
            # such as CODE_REPORT are response data, not tool authority.
            return []
        if _chat_status_meta_text_hint(text) and not _code_task_write_requested(text):
            return []
        invalid_palette_reason = _invalid_command_palette_request_reason(text)
        if invalid_palette_reason:
            return [
                TaskIntentSnapshot(
                    intent_id=_stable_id("intent", "desktop_operation", text),
                    kind="desktop_operation",
                    title="Desktop Operation",
                    user_goal=text,
                    confidence=0.95,
                    description=(
                        "Command palette execution requires a non-empty command and "
                        "uses confirmation rather than message sending."
                    ),
                    inputs={"invalid_command_palette_request": invalid_palette_reason},
                    missing_inputs=(
                        ["command_palette_command"]
                        if invalid_palette_reason == "missing_command"
                        else []
                    ),
                    risk_level="medium",
                )
            ]
        candidates = [
            self._data_analysis_intent(text, metadata),
            self._media_playback_intent(text, metadata),
            self._system_control_intent(text, metadata),
            self._file_access_intent(text, metadata),
            self._desktop_operation_intent(text, metadata),
            self._web_research_intent(text, metadata),
            self._report_generation_intent(text, metadata),
            self._code_task_intent(text, metadata),
            self._file_organization_intent(text, metadata),
            self._workflow_intent(text, metadata),
            self._multi_agent_intent(text, metadata),
            self._communication_intent(text, metadata),
            self._information_capture_intent(text, metadata),
            self._clipboard_intent(text, metadata),
            self._schedule_intent(text, metadata),
        ]
        return sorted(
            [intent for intent in candidates if intent.confidence > 0],
            key=lambda intent: (_intent_rank_score(intent, text), intent.confidence),
            reverse=True,
        )

    def route(self, prompt: str, metadata: Mapping[str, Any] | None = None) -> TaskIntentSnapshot:
        candidates = self.candidate_intents(prompt, metadata)
        if candidates:
            return candidates[0]
        return TaskIntentSnapshot(
            intent_id=_stable_id("intent", "general", prompt),
            kind="general",
            title="General Task",
            user_goal=_clean_prompt(prompt),
            confidence=0.25,
            description="General task without a stronger specialized route.",
            preferred_capabilities=["artifact.write"],
        )

    def _data_analysis_intent(
        self,
        text: str,
        metadata: Mapping[str, Any],
    ) -> TaskIntentSnapshot:
        if scheduled_runnable_payload(text):
            return _empty_intent("data_analysis", text)
        if _spreadsheet_cell_edit_ui_hint(text):
            return _empty_intent("data_analysis", text)
        if _desktop_ui_field_edit_hint(text):
            return _empty_intent("data_analysis", text)
        if _looks_like_current_page_link_artifact_request(text):
            return _empty_intent("data_analysis", text)
        if (
            _explicit_app_open_request(text)
            and _app_capability_discovery_hint(text)
            and not _data_analysis_action_requested(text)
        ):
            return _empty_intent("data_analysis", text)
        if _app_file_open_discovery_hint(text, metadata) and not _data_analysis_action_requested(text):
            return _empty_intent("data_analysis", text)
        if _looks_like_document_report_analysis_request(text, metadata):
            return _empty_intent("data_analysis", text)
        if _looks_like_data_analysis_concept_question(text):
            return _empty_intent("data_analysis", text)
        score = _score_terms(
            text,
            [
                "data analysis",
                "analyze data",
                "analyse data",
                "dataset",
                "csv",
                "xlsx",
                "excel",
                "spreadsheet",
                "table",
                "pandas",
                "chart",
                "plot",
                "visualization",
                "数据分析",
                "分析数据",
                "数据集",
                "表格",
                "电子表格",
                "可视化",
                "图表",
                "统计",
            ],
        )
        source_hint = data_source_hint(text, metadata)
        source_scope = data_source_scope_hint(text, metadata)
        named_source = named_data_source_hint(text)
        source_name = str(named_source.get("name") or "").strip()
        source_selection = _file_open_selection_hint(text)
        context_source = _task_context_source_hint(text)
        current_page_context = _looks_like_current_page_data_context_source(text)
        visible_context = _looks_like_visible_data_context_source(text)
        desktop_visible_context = _looks_like_desktop_visible_data_context_source(text)
        app_search_result_source = _data_analysis_app_search_result_source_hint(text)
        running_spreadsheet_app_hint = _running_spreadsheet_app_context_hint(text)
        if desktop_visible_context:
            context_source = "visible_text"
            if source_scope == "Desktop" and not source_hint:
                source_scope = ""
        elif app_search_result_source and not context_source:
            context_source = "app_search_result"
        elif not context_source and current_page_context:
            context_source = "current_page_content"
        elif running_spreadsheet_app_hint and not source_hint and not context_source:
            context_source = "visible_text"
        elif (
            visible_context
            and not current_page_context
            and context_source not in {"selection", "clipboard"}
        ):
            context_source = "visible_text"
        if (
            app_search_result_source
            and not _app_search_result_analysis_action_requested(
                text,
                app_search_result_source,
            )
        ):
            return _empty_intent("data_analysis", text)
        can_discover_source = _contains_any(
            text,
            ["数据", "数据集", "表格", "data", "dataset", "table", "csv", "xlsx", "json"],
        )
        has_source = bool(
            source_hint
            or source_scope
            or source_name
            or context_source
            or app_search_result_source
        )
        if score <= 0 and has_source and _contains_any(text, ["分析", "统计", "汇总", "可视化"]):
            score = 0.16
        if (
            score <= 0
            and can_discover_source
            and _data_analysis_action_requested(text)
        ):
            score = 0.14
        if (
            score <= 0
            and context_source in {"selection", "clipboard"}
            and _contains_any(text, ["分析", "统计", "汇总", "可视化", "数据", "表格", "data", "table"])
        ):
            score = 0.22
        if _looks_like_data_delivery_without_analysis(text):
            return _empty_intent("data_analysis", text)
        if score <= 0:
            return _empty_intent("data_analysis", text)
        result_open_app_hint = _analysis_result_open_app_hint(text)
        spreadsheet_app_hint = _spreadsheet_ui_app_hint(text)
        if (
            result_open_app_hint
            and context_source
            and _canonical_spreadsheet_app_hint(source_scope) == result_open_app_hint
        ):
            source_scope = ""
        source_scope_is_output = bool(
            source_scope and source_scope == _artifact_output_location_hint(text)
        )
        scoped_source_hint = (
            source_hint
            if source_scope_is_output
            else _scoped_data_source_path(source_hint, source_scope)
        )
        source_kind = (
            "text_table"
            if app_search_result_source
            and data_source_kind_hint(source_hint, text) == "unknown"
            else data_source_kind_hint(source_hint, text)
        )
        expected_outputs = _data_analysis_expected_outputs(
            text,
            result_open_app_hint=result_open_app_hint,
        )
        inputs = {
            "data_source_hint": scoped_source_hint,
            "data_source_kind": source_kind,
            "runtime_goal_capabilities": ["data.analysis"],
        }
        if spreadsheet_app_hint and spreadsheet_app_hint != result_open_app_hint:
            inputs["spreadsheet_app_hint"] = spreadsheet_app_hint
        if running_spreadsheet_app_hint and context_source == "visible_text" and not source_hint:
            inputs["running_spreadsheet_app_hint"] = running_spreadsheet_app_hint
        if result_open_app_hint:
            inputs["analysis_result_open_app_hint"] = result_open_app_hint
        if source_name and not source_hint:
            inputs["data_source_name_hint"] = source_name
        if source_selection and not source_hint:
            inputs["data_source_selection_hint"] = source_selection
        if context_source:
            inputs["context_source"] = context_source
        if app_search_result_source:
            inputs["app_search_result_hint"] = app_search_result_source
        if (
            source_scope
            and not source_hint
            and not (
                context_source
                and source_scope == _artifact_output_location_hint(text)
            )
        ):
            inputs["data_source_scope_hint"] = source_scope
        communication_target = _data_analysis_communication_target_hint(text)
        if communication_target:
            inputs["communication_target_hint"] = communication_target
        app_write_target = (
            {}
            if communication_target
            else _app_write_followup_target_hint(text)
        )
        if not app_write_target and not communication_target:
            app_capability_target = _app_capability_discovery_hint(text)
            app_write_target = _discovered_app_write_followup_target_hint(
                text,
                require_data_analysis=not bool(context_source and app_capability_target),
            )
        if app_write_target:
            inputs.update(app_write_target)
        output_target = _task_output_target_hint(text)
        if output_target:
            inputs["output_target_hint"] = output_target
        terminal_effect_capabilities = _data_analysis_terminal_effect_capabilities(
            output_target=output_target,
            app_write_target=app_write_target,
            communication_target=communication_target,
        )
        if terminal_effect_capabilities:
            inputs["runtime_goal_terminal_effect_capabilities"] = (
                terminal_effect_capabilities
            )
        artifact_paths = _artifact_output_paths(
            text,
            data_analysis_artifacts_expected(
                expected_outputs,
                text,
            ),
        )
        inputs["runtime_goal_targets"] = {
            "data.analysis": _data_analysis_semantic_goal_target(
                inputs,
                artifact_paths=artifact_paths,
            )
        }
        preferred_capabilities = [
            "data.analysis",
            *(["desktop.app_control"] if spreadsheet_app_hint else []),
            *(
                ["desktop.app_discovery", "desktop.app_control", "desktop.ui_operation"]
                if running_spreadsheet_app_hint
                else []
            ),
            *(["clipboard.read_write"] if output_target == "clipboard" else []),
        ]
        app_write_target_capability = isinstance(
            app_write_target.get("target_app_capability_hint")
            if isinstance(app_write_target, Mapping)
            else None,
            Mapping,
        )
        if app_search_result_source:
            preferred_capabilities.extend(
                ["desktop.app_discovery", "desktop.app_control", "desktop.ui_operation"]
            )
        if app_write_target:
            preferred_capabilities.append("desktop.app_control")
            preferred_capabilities.append("desktop.ui_operation")
            if app_write_target_capability:
                preferred_capabilities.extend(
                    ["desktop.app_discovery", "desktop.ui_operation"]
                )
        if communication_target:
            if str(communication_target.get("app_name") or "").strip() or (
                str(communication_target.get("channel") or "").strip() == "email"
            ):
                preferred_capabilities.append("desktop.app_control")
            preferred_capabilities.append("communication.compose")
        preferred_capabilities = list(dict.fromkeys(preferred_capabilities))
        return TaskIntentSnapshot(
            intent_id=_stable_id("intent", "data_analysis", text),
            kind="data_analysis",
            title="Data Analysis",
            user_goal=text,
            confidence=min(0.95, 0.48 + score),
            description="Analyze structured data and produce a report or artifact.",
            inputs=inputs,
            expected_outputs=expected_outputs,
            required_capabilities=(
                [
                    "desktop.app_discovery",
                    "desktop.ui_operation",
                    "terminal.execution",
                    "artifact.write",
                    *(["desktop.app_control"] if app_write_target else []),
                ]
                if app_search_result_source
                else [
                    "file.workspace_read",
                    "terminal.execution",
                    "artifact.write",
                    *(
                        ["desktop.app_discovery", "desktop.ui_operation"]
                        if app_write_target_capability
                        else []
                    ),
                    *(["desktop.app_control"] if app_write_target else []),
                    *(
                        ["desktop.ui_operation"]
                        if app_write_target and not app_write_target_capability
                        else []
                    ),
                ]
            ),
            preferred_capabilities=preferred_capabilities,
            missing_inputs=[] if has_source else ["data_source"],
            risk_level="medium",
        )

    def _desktop_operation_intent(
        self,
        text: str,
        metadata: Mapping[str, Any],
    ) -> TaskIntentSnapshot:
        readonly_discovery = _pure_desktop_discovery_question(text)
        app_control_text = _authorized_app_control_text(
            _speech_act_strip_unauthorized_contextual_tails(text)
        )
        if (
            _APP_CONTROL_AUTHORITY_ACTION_RE.search(text)
            and not _APP_CONTROL_AUTHORITY_ACTION_RE.search(app_control_text)
            and not _text_has_authorized_family_action(
                text,
                _DESKTOP_NON_APP_AUTHORITY_ACTION_RE,
            )
            and not readonly_discovery
        ):
            return _empty_intent("desktop_operation", text)
        if (
            not app_control_text
            and _negated_app_control_clause(text)
            and not readonly_discovery
        ):
            return _empty_intent("desktop_operation", text)
        if _looks_like_non_action_desktop_validation_task(text):
            return _empty_intent("desktop_operation", text)
        if _explicit_browser_url_hint(text) and not type_into_ui_hint(text):
            return _empty_intent("desktop_operation", text)
        if _chat_status_meta_text_hint(text):
            return _empty_intent("desktop_operation", text)
        if _direct_communication_candidate_hint(text):
            return _empty_intent("desktop_operation", text)
        if _known_web_destination_search_hint(text):
            return _empty_intent("desktop_operation", text)
        if _looks_like_non_desktop_content_task(text):
            return _empty_intent("desktop_operation", text)
        transform_target = _dynamic_context_transform_target_hint(text)
        if str(transform_target.get("target_action_hint") or "").strip() == "current_input_write":
            return _empty_intent("desktop_operation", text)
        if named_data_source_hint(text) and _data_analysis_action_requested(text):
            return _empty_intent("desktop_operation", text)
        spreadsheet_cell_edit = _spreadsheet_cell_edit_ui_hint(text)
        desktop_ui_field_edit = _desktop_ui_field_edit_hint(text)
        if (
            _looks_like_generic_data_source_analysis_request(text)
            and not spreadsheet_cell_edit
            and not desktop_ui_field_edit
        ):
            return _empty_intent("desktop_operation", text)
        app_capability = _app_capability_discovery_hint(text)
        explicit_capability_app_name = _app_capability_explicit_app_name_hint(
            text,
            app_capability,
        )
        if explicit_capability_app_name:
            app_capability = {}
        if not app_capability and _browser_window_desktop_ui_operation_requested(text):
            app_capability = {"query": "browser", "description": "browser"}
        generic_browser_search = _generic_browser_app_search_hint(text)
        if _web_search_query(text) and (
            _generic_browser_app_target_requested(text)
            or _is_generic_browser_app_label(_app_name_hint(app_control_text))
        ):
            return _empty_intent("desktop_operation", text)
        if generic_browser_search and not app_capability:
            app_capability = {"query": "browser", "description": "browser"}
        ui_type_target = type_into_ui_hint(text)
        file_open_discovery_candidate = _app_file_open_discovery_hint(
            text,
            metadata,
        ) or _generic_app_file_open_discovery_hint(
            text,
            metadata,
            app_capability=app_capability,
        )
        selected_app_target_path = (
            ""
            if file_open_discovery_candidate
            else (
                _selected_discovered_app_target_path_hint(text)
                if app_capability and not ui_type_target
                else ""
            )
        )
        file_open_discovery = (
            {} if selected_app_target_path else file_open_discovery_candidate
        )
        app_search_app_hint = "" if app_capability else _app_name_hint(app_control_text)
        if (
            _explicit_system_settings_request(text)
            and not spreadsheet_cell_edit
            and not desktop_ui_field_edit
            and not _explicit_known_app_action_target_hint(text)
            and not (app_search_app_hint and _app_search_hint(text, app_search_app_hint))
        ):
            return _empty_intent("desktop_operation", text)
        if (
            _report_file_context_hint(text)
            and _desktop_content_artifact_requested(text)
            and not app_capability
            and not _app_name_hint(app_control_text)
        ):
            return _empty_intent("desktop_operation", text)
        ui_inspection = ui_inspection_hint(text)
        window_verification_app = _explicit_app_window_verification_app_name_hint(
            text
        )
        if ui_inspection is None and window_verification_app:
            ui_inspection = {
                "role_filter": "",
                "limit": 80,
                "app_name": window_verification_app,
            }
        if (
            isinstance(ui_inspection, Mapping)
            and _desktop_window_text_context_hint(text)
            and not str(ui_inspection.get("role_filter") or "").strip()
        ):
            ui_inspection = {**ui_inspection, "role_filter": "text"}
        if not app_capability and isinstance(ui_inspection, Mapping):
            app_capability = _scoped_app_label_capability_hint(
                str(ui_inspection.get("app_name") or "")
            )
        screen_capture = screen_capture_hint(text)
        if (
            screen_capture is not None
            and _code_task_write_requested(text)
            and not _explicit_screen_capture_requested(text, text.lower())
        ):
            screen_capture = None
        if (
            ui_inspection is None
            and screen_capture is None
            and _ambiguous_visible_target_action_requested(text)
        ):
            primary_click_target = click_target_hint(text)
            ui_inspection = {
                "role_filter": str((primary_click_target or {}).get("role_filter") or ""),
                "limit": 80,
            }
        control_presence_inspection = ui_control_presence_hint(text)
        app_management = app_management_hint(text)
        foreground_management = foreground_management_hint(text)
        safe_shortcut = safe_shortcut_hint(text)
        safe_shortcut_sequence = safe_shortcut_sequence_hint(text)
        if safe_shortcut_sequence:
            safe_shortcut = dict(safe_shortcut_sequence[0])
        browser_scope_candidate = _browser_scoped_safe_shortcut_app_candidate(
            text,
            safe_shortcut,
        )
        invalid_browser_scope = bool(
            browser_scope_candidate
            and not _is_browser_or_search_app_name(browser_scope_candidate)
        )
        if invalid_browser_scope:
            safe_shortcut = None
            safe_shortcut_sequence = []
        if _browser_foreground_safe_shortcut_hint(safe_shortcut):
            app_capability = {}
        creative_canvas = _creative_canvas_create_hint(text)
        if creative_canvas and safe_shortcut is None:
            safe_shortcut = {"action": "new_document"}
        if creative_canvas and ui_inspection is None and screen_capture is None:
            ui_inspection = {"role_filter": "text", "limit": 80}
        safe_key = safe_key_hint(text)
        safe_scroll = safe_scroll_hint(text)
        hotkey = hotkey_hint(text)
        hotkey_overrides_safe_shortcut = _explicit_hotkey_should_override_safe_shortcut(
            text,
            hotkey,
            safe_shortcut,
        )
