def _service_input_preview(
    intent: TaskIntentSnapshot,
    *,
    capability_id: str,
    target_name: str,
) -> dict[str, Any]:
    action = _service_action(capability_id, intent)
    payload: dict[str, Any] = {
        "objective": str(intent.user_goal or "").strip(),
        "title": str(intent.title or "").strip(),
        "target_name": str(target_name or "").strip(),
        "intent_kind": str(intent.kind or "").strip(),
        "orchestration_action": action,
        "orchestration_kind": (
            "workflow" if capability_id == "workflow.orchestration" else "group_run"
        ),
    }
    workflow_action = str(intent.inputs.get("workflow_action_hint") or "").strip()
    if workflow_action:
        payload["workflow_action_hint"] = workflow_action
    if capability_id == "group.multi_agent":
        group_task_plan = _group_task_plan_preview(intent.user_goal)
        if group_task_plan:
            payload["group_task_plan"] = group_task_plan
    delivery_target = intent.inputs.get("communication_target_hint")
    if isinstance(delivery_target, Mapping):
        payload["delivery_target"] = {
            str(key): value
            for key, value in delivery_target.items()
            if str(key or "").strip() and value not in (None, "", [], {})
        }
    return payload


def _group_task_plan_preview(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    if not value:
        return {}
    if not _contains_any(
        value,
        (
            "分别",
            "分工",
            "各自",
            "parallel",
            "separately",
            "split",
            "divide",
        ),
    ):
        return {}
    split_tasks = _group_split_work_items(value)
    if split_tasks and _contains_any(value, ("分工", "split", "divide")):
        return {
            "strategy": "role_split_then_delivery",
            "tasks": split_tasks,
        }
    topics = _group_parallel_research_topics(value)
    if len(topics) >= 2:
        tasks = [
            {
                "task_id": f"research-{index}",
                "role": "researcher",
                "objective": f"调研 {topic}",
                "expected_output": "research_notes",
            }
            for index, topic in enumerate(topics[:4], start=1)
        ]
        return {
            "strategy": "parallel_research_then_synthesis",
            "tasks": [
                *tasks,
                {
                    "task_id": "synthesize-findings",
                    "role": "synthesizer",
                    "objective": "汇总并对比各研究任务的结果",
                    "expected_output": "summary_report",
                    "depends_on": [task["task_id"] for task in tasks],
                },
            ],
        }
    if split_tasks:
        return {
            "strategy": "role_split_then_delivery",
            "tasks": split_tasks,
        }
    return {}


def _group_parallel_research_topics(text: str) -> list[str]:
    value = _clean_prompt(text)
    match = re.search(
        r"(?:调研|研究|比较|分析|搜索|research|compare|analy[sz]e)\s*(?P<topics>.+?)"
        r"(?:然后|之后|最后|并(?:汇总|总结|输出|产出)|再|$)",
        value,
        flags=re.IGNORECASE,
    )
    if not match:
        return []
    raw_topics = str(match.group("topics") or "").strip(" ：:，,。；;")
    raw_topics = re.sub(
        r"(?:的)?(?:差异|区别|架构|agent\s+architecture|architecture)$",
        "",
        raw_topics,
        flags=re.IGNORECASE,
    ).strip(" 的")
    parts = re.split(r"\s*(?:和|与|及|、|,|，|\band\b|\bvs\.?\b)\s*", raw_topics)
    topics: list[str] = []
    for part in parts:
        topic = str(part or "").strip(" ：:，,。；; ")
        if not topic or topic in topics:
            continue
        topics.append(topic)
    return topics


def _group_split_work_items(text: str) -> list[dict[str, str]]:
    value = _clean_prompt(text)
    match = re.search(
        r"一个(?P<first>[^，,。；;]+)[，,；;]\s*(?:另?一个|一个)(?P<second>[^，,。；;]+)",
        value,
    )
    if not match:
        return []
    first = str(match.group("first") or "").strip()
    second = str(match.group("second") or "").strip()
    tasks = []
    for index, objective in enumerate((first, second), start=1):
        if not objective:
            continue
        tasks.append(
            {
                "task_id": f"role-task-{index}",
                "role": "specialist",
                "objective": objective,
                "expected_output": "task_result",
            }
        )
    return tasks


_DESKTOP_OPERATION_TOOL_ALIASES = {
    "app.open": "desktop.open_app",
    "app.focus": "desktop.focus_app",
    "desktop.windows": "desktop.list_windows",
    "desktop.ui_elements": "desktop.read_ui",
    "desktop.hotkey": "desktop.shortcut",
    "desktop.type_text": "desktop.type",
}


_OPEN_PATH_WITH_APP_TOOL_CANDIDATES = ("desktop.open_path_with_app", "app.open_path_with_app")


def _is_open_path_with_app_tool(tool_name: str | None) -> bool:
    return str(tool_name or "").strip() in _OPEN_PATH_WITH_APP_TOOL_CANDIDATES


def _first_allowed(tools: Iterable[str], allowed: set[str] | None) -> str | None:
    candidates: list[str] = []
    for raw_tool in tools:
        tool = str(raw_tool or "").strip()
        if not tool:
            continue
        if tool not in candidates:
            candidates.append(tool)
        alias = _DESKTOP_OPERATION_TOOL_ALIASES.get(tool)
        if alias and alias not in candidates:
            candidates.append(alias)
    if not candidates:
        return None
    legacy_selected = next(
        (
            candidate
            for candidate in candidates
            if allowed is None or candidate in allowed
        ),
        None,
    )
    if not legacy_selected:
        return None

    # Keep legacy candidate order at this low-level compatibility seam.  The
    # capability/action-aware per-step pass performs readiness ranking after
    # the step has enough semantic context to do so safely.
    from apps.shell.agent.runtime.tool_candidate_selection import (
        current_tool_candidate_selection_context,
        select_tool_candidate,
    )

    selection_context = current_tool_candidate_selection_context()
    readiness_tools = {
        tool_name for tool_name, _facts in selection_context.readiness_by_tool
    }
    if not any(candidate in readiness_tools for candidate in candidates):
        return legacy_selected
    selection = select_tool_candidate(
        candidates,
        allowed if allowed is not None else candidates,
    )
    if any(
        candidate.readiness_class in {"ready", "blocked"}
        for candidate in selection.ranked_candidates
    ):
        return selection.selected_tool or legacy_selected
    return legacy_selected


def _return_followup_tool(
    hotkey_payload: Mapping[str, Any],
    allowed: set[str] | None,
) -> str | None:
    if (
        str(hotkey_payload.get("key") or "").strip().lower() in {"return", "enter"}
        and not hotkey_payload.get("modifiers")
    ):
        return _first_allowed(("desktop.hotkey", "desktop.submit_foreground"), allowed)
    return _first_allowed(("desktop.hotkey",), allowed)


def _return_followup_input_preview(
    tool_name: str | None,
    hotkey_payload: Mapping[str, Any],
) -> dict[str, Any]:
    if tool_name == "desktop.submit_foreground":
        return {"action": "confirm"}
    return dict(hotkey_payload)


def _app_scoped_safe_shortcut_split_tools(
    app_name: str,
    mode: str,
    allowed: set[str] | None,
) -> tuple[str | None, str | None]:
    return _app_scoped_operation_split_tools(
        app_name,
        mode,
        ("desktop.safe_shortcut",),
        allowed,
    )


def _app_scoped_operation_split_tools(
    app_name: str,
    mode: str,
    operation_tools: Iterable[str],
    allowed: set[str] | None,
) -> tuple[str | None, str | None]:
    if not app_name:
        return None, None
    app_tool = _first_allowed(app_control_tool_candidates(mode or "focus"), allowed)
    operation_tool = _first_allowed(operation_tools, allowed)
    if not app_tool or not operation_tool:
        return None, None
    return app_tool, operation_tool


def _append_app_scoped_safe_shortcut_steps(
    steps: list[ToolPlanStepSnapshot],
    intent: TaskIntentSnapshot,
    *,
    step_id: str,
    title: str,
    app_name: str,
    mode: str,
    shortcut_action: str,
    allowed: set[str] | None,
    depends_on: list[str],
    prepare_reason: str,
    shortcut_reason: str,
    fallback_reason: str,
) -> str:
    clean_mode = mode or "focus"
    app_foreground_tool = _first_allowed(
        app_foreground_tool_candidates(clean_mode, "safe_shortcut"),
        allowed,
    )
    if app_name and app_foreground_tool:
        steps.append(
            _step(
                intent,
                step_id,
                title,
                "desktop.app_control",
                app_foreground_tool,
                input_preview={"app_name": app_name, "action": shortcut_action},
                depends_on=depends_on,
                action="shortcut",
                risk_level="low",
                approval_required=False,
                reason=fallback_reason,
            )
        )
        return step_id

    app_tool, shortcut_tool = _app_scoped_safe_shortcut_split_tools(
        app_name,
        clean_mode,
        allowed,
    )
    if app_name and app_tool and shortcut_tool:
        steps.append(
            _step(
                intent,
                "open-or-focus-app",
                "Open or focus app",
                "desktop.app_control",
                app_tool,
                input_preview={"app_name": app_name},
                depends_on=depends_on,
                reason=prepare_reason,
            )
        )
        steps.append(
            _step(
                intent,
                step_id,
                title,
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": shortcut_action},
                depends_on=["open-or-focus-app"],
                action="shortcut",
                risk_level="low",
                approval_required=False,
                reason=shortcut_reason,
            )
        )
        return step_id

    steps.append(
        _step(
            intent,
            step_id,
            title,
            "desktop.app_control",
            app_foreground_tool,
            input_preview={"app_name": app_name, "action": shortcut_action},
            depends_on=depends_on,
            action="shortcut",
            risk_level="low",
            approval_required=False,
            reason=fallback_reason,
        )
    )
    return step_id


def _context_source_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    source: str,
    *,
    step_prefix: str,
    capability_id: str,
) -> list[ToolPlanStepSnapshot]:
    if source == "selection":
        steps = []
        copy_tool = _first_allowed(("desktop.safe_shortcut",), allowed)
        if copy_tool:
            steps.append(
                _step(
                    intent,
                    f"copy-selected-{step_prefix}-context",
                    "Copy selected context",
                    _context_source_capability_id(source, copy_tool, capability_id),
                    copy_tool,
                    input_preview={"action": "copy"},
                    reason="Copy the explicit user-selected text before using it as task context.",
                )
            )
        read_tool = _first_allowed(("clipboard.read",), allowed)
        if read_tool:
            steps.append(
                _step(
                    intent,
                    f"read-{step_prefix}-context",
                    "Read captured context",
                    _context_source_capability_id(source, read_tool, capability_id),
                    read_tool,
                    depends_on=[f"copy-selected-{step_prefix}-context"] if copy_tool else [],
                    reason="Read the copied text so the next step uses inspected context.",
                )
            )
        return steps

    if source == "clipboard":
        tool_name = _first_allowed(("clipboard.read",), allowed)
        return [
            _step(
                intent,
                f"read-{step_prefix}-context",
                "Read captured context",
                _context_source_capability_id(source, tool_name, capability_id),
                tool_name,
                reason="Read the explicitly requested clipboard contents before using them as task context.",
            )
        ]

    if source == "current_page_link":
        tool_name = _first_allowed(("browser.current_page", "desktop.safe_shortcut"), allowed)
        payload = {"action": "copy_current_page_link"} if tool_name == "desktop.safe_shortcut" else {}
        return [
            _step(
                intent,
                f"read-{step_prefix}-context",
                "Read captured context",
                _context_source_capability_id(source, tool_name, capability_id),
                tool_name,
                input_preview=payload,
                reason="Capture the current page reference before using it as task context.",
            )
        ]

    if source == "current_page_content":
        tool_name = _first_allowed(
            ("browser.extract_text", "browser.current_page", "desktop.ui_elements", "screen.capture"),
            allowed,
        )
        return [
            _step(
                intent,
                f"read-{step_prefix}-context",
                "Read captured context",
                _context_source_capability_id(source, tool_name, capability_id),
                tool_name,
                input_preview=_information_capture_context_payload(tool_name),
                reason="Inspect the current page or window text before using it as task context.",
            )
        ]

    if source == "screen_capture":
        tool_name = _first_allowed(("screen.capture",), allowed)
        return [
            _step(
                intent,
                f"read-{step_prefix}-context",
                "Capture screen context",
                _context_source_capability_id(source, tool_name, capability_id),
                tool_name,
                input_preview={"reason": "Capture the screen before sending it."},
                reason="Capture the explicitly requested screenshot before using it as task context.",
            )
        ]

    if source == "visible_text":
        tool_name = _first_allowed(("desktop.ui_elements", "screen.capture"), allowed)
        return [
            _step(
                intent,
                f"read-{step_prefix}-context",
                "Read captured context",
                _context_source_capability_id(source, tool_name, capability_id),
                tool_name,
                input_preview=_information_capture_context_payload(tool_name),
                reason="Inspect visible text before using it as task context.",
            )
        ]

    if source == "file":
        file_context = intent.inputs.get("file_context_hint")
        if not isinstance(file_context, Mapping):
            return []
        path = str(file_context.get("path") or "").strip()
        if not path:
            return []
        pattern = str(file_context.get("pattern") or "").strip()
        file_type = str(file_context.get("file_type") or "").strip()
        selection = str(file_context.get("selection") or "").strip()
        tool_candidates = (
            (
                "workspace.list",
                "fs.find_files",
                "file.search",
                "workspace.read",
                "fs.read_file",
                "file.read",
            )
            if pattern and not _looks_like_specific_data_source_path(path)
            else (
                "workspace.read",
                "fs.read_file",
                "file.read",
                "workspace.list",
                "fs.find_files",
                "file.search",
            )
        )
        tool_name = _first_allowed(tool_candidates, allowed)
        input_preview: dict[str, str] = {"path": path}
        if tool_name in {"workspace.list", "fs.find_files", "file.search"}:
            if pattern:
                input_preview["pattern"] = pattern
            if file_type:
                input_preview["file_type"] = file_type
            if selection:
                input_preview["selection"] = selection
        return [
            _step(
                intent,
                f"read-{step_prefix}-context",
                "Read file context",
                _context_source_capability_id(source, tool_name, capability_id),
                tool_name,
                input_preview=input_preview,
                reason="Read or list the explicit local file context before using it in the task.",
            )
        ]

    return []


def _app_search_result_context_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    direct_message: Mapping[str, Any],
    *,
    step_prefix: str,
    capability_id: str,
) -> list[ToolPlanStepSnapshot]:
    source_app = str(direct_message.get("source_app_name") or "").strip()
    source_scope = str(direct_message.get("source_scope") or "").strip()
    query = _clean_app_search_query(
        str(direct_message.get("source_app_search_query") or "")
    )
    if not query:
        return []

    steps: list[ToolPlanStepSnapshot] = []
    depends_on: list[str] = []
    source_mode = str(direct_message.get("source_app_mode") or "focus").strip() or "focus"
    source_app_scoped_shortcut_tool = (
        _first_allowed(app_foreground_tool_candidates(source_mode, "safe_shortcut"), allowed)
        if source_app
        else None
    )
    if source_app:
        discover_tool = _first_allowed(("desktop.list_apps", "desktop.running_apps"), allowed)
        discover_input = (
            {"query": source_app, "limit": 20}
            if discover_tool == "desktop.list_apps"
            else {}
        )
        steps.append(
            _step(
                intent,
                "discover-app-search-source",
                "Discover source app",
                "desktop.app_discovery",
                discover_tool,
                input_preview=discover_input,
                action="list_apps",
                reason="Discover the requested source app before searching inside it.",
            )
        )
        depends_on = ["discover-app-search-source"]
        source_tool_candidates = (
            ("app.open", "app.focus") if source_mode == "open" else ("app.focus", "app.open")
        )
        source_tool = _first_allowed(source_tool_candidates, allowed)
        if source_tool:
            steps.append(
                _step(
                    intent,
                    "open-app-search-source",
                    "Open or focus source app",
                    "desktop.app_control",
                    source_tool,
                    input_preview={"app_name": source_app},
                    depends_on=depends_on,
                    action="open_app" if source_tool == "app.open" else "focus_app",
                    reason="Prepare the source app before using its in-app search.",
                )
            )
            depends_on = ["open-app-search-source"]
            if source_tool == "app.open" and "app.focus" in (allowed or set()):
                steps.append(
                    _step(
                        intent,
                        "focus-app-search-source",
                        "Focus source app",
                        "desktop.app_control",
                        "app.focus",
                        input_preview={"app_name": source_app},
                        depends_on=depends_on,
                        action="focus_app",
                        reason="Focus the source app after opening it.",
                    )
                )
                depends_on = ["focus-app-search-source"]
        elif not source_app_scoped_shortcut_tool:
            steps.append(
                _step(
                    intent,
                    "open-app-search-source",
                    "Open or focus source app",
                    "desktop.app_control",
                    None,
                    input_preview={"app_name": source_app},
                    depends_on=depends_on,
                    action="focus_app",
                    reason="Prepare the source app before using its in-app search.",
                )
            )
            depends_on = ["open-app-search-source"]
    elif source_scope == "foreground":
        discover_tool = _first_allowed(("desktop.running_apps", "desktop.active_window"), allowed)
        steps.append(
            _step(
                intent,
                "discover-app-search-source",
                "Discover foreground app",
                "desktop.app_discovery",
                discover_tool,
                input_preview={},
                action="active_window" if discover_tool == "desktop.active_window" else "list_apps",
                reason="Inspect the foreground app before searching inside it.",
            )
        )
        depends_on = ["discover-app-search-source"]

    shortcut_tool = _first_allowed(("desktop.safe_shortcut",), allowed)
    shortcut_input = {"action": "find"}
    if not shortcut_tool and source_app:
        shortcut_tool = source_app_scoped_shortcut_tool
        if shortcut_tool:
            shortcut_input = {"app_name": source_app, "action": "find"}
    type_tool, type_input = _safe_type_text_operation_preview(
        app_name=source_app,
        mode=source_mode,
        allowed=allowed,
        payload={"text": query},
    )
    submit_tool = _first_allowed(("desktop.search_submit",), allowed)
    read_tool = _first_allowed(("desktop.ui_elements", "screen.capture"), allowed)
    read_input = (
        {"role_filter": "text", "limit": 120}
        if read_tool == "desktop.ui_elements"
        else {"reason": "Read the source app search result before composing."}
        if read_tool == "screen.capture"
        else {}
    )
    if source_app and read_tool == "desktop.ui_elements":
        read_input["app_name"] = source_app

    steps.extend(
        [
            _step(
                intent,
                "focus-app-search-field",
                "Focus app search field",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview=shortcut_input,
                depends_on=depends_on,
                action="shortcut",
                reason="Open the source app search field with a safe shortcut.",
            ),
            _step(
                intent,
                "type-app-search-query",
                "Type app search query",
                "desktop.ui_operation",
                type_tool,
                input_preview=type_input,
                depends_on=["focus-app-search-field"],
                action="type",
                reason="Type only the explicit source-app search query.",
            ),
            _step(
                intent,
                "submit-app-search",
                "Submit app search",
                "desktop.ui_operation",
                submit_tool,
                input_preview={},
                depends_on=["type-app-search-query"],
                action="submit_search",
                reason="Submit the source-app search before reading the result.",
            ),
            _step(
                intent,
                f"read-{step_prefix}-context",
                "Read app search result",
                _context_source_capability_id("app_search_result", read_tool, capability_id),
                read_tool,
                input_preview=read_input,
                depends_on=["submit-app-search"],
                action="read_ui",
                reason=(
                    "Read the app search result so the model can generate the requested "
                    "message body from observed content."
                ),
            ),
        ]
    )
    return steps


def _data_analysis_context_source_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    source: str,
) -> list[ToolPlanStepSnapshot]:
    if source == "app_search_result":
        app_search_result = intent.inputs.get("app_search_result_hint")
        if not isinstance(app_search_result, Mapping):
            app_search_result = _data_analysis_app_search_result_source_hint(
                intent.user_goal
            )
        return _app_search_result_context_steps(
            intent,
            allowed,
            app_search_result,
            step_prefix="data",
            capability_id="data.analysis",
        )
    if (
        source in {"current_page_content", "visible_text"}
        and _contains_any(
            intent.user_goal,
            ("表格", "数据", "table", "tabular", "spreadsheet", "data", "csv"),
        )
    ):
        if source == "visible_text":
            visible_context_tool = _first_allowed(("desktop.ui_elements", "screen.capture"), allowed)
            if visible_context_tool:
                return _context_source_steps(
                    intent,
                    allowed,
                    source,
                    step_prefix="data",
                    capability_id="data.analysis",
                )
        browser_context_tool = (
            _first_allowed(("browser.extract_text", "browser.current_page"), allowed)
            if source == "current_page_content"
            else None
        )
        if source == "current_page_content" and browser_context_tool:
            return _context_source_steps(
                intent,
                allowed,
                source,
                step_prefix="data",
                capability_id="data.analysis",
            )
        shortcut_tool = _first_allowed(("desktop.safe_shortcut",), allowed)
        read_tool = _first_allowed(("clipboard.read",), allowed)
        if shortcut_tool and read_tool:
            return [
                _step(
                    intent,
                    "select-current-data-context",
                    "Select current data context",
                    "desktop.ui_operation",
                    shortcut_tool,
                    input_preview={"action": "select_all"},
                    reason="Select visible foreground data before copying it for local analysis.",
                ),
                _step(
                    intent,
                    "copy-current-data-context",
                    "Copy current data context",
                    "clipboard.read_write",
                    shortcut_tool,
                    input_preview={"action": "copy"},
                    depends_on=["select-current-data-context"],
                    reason="Copy the selected foreground table or data into the clipboard.",
                ),
                _step(
                    intent,
                    "read-data-context",
                    "Read captured context",
                    "clipboard.read_write",
                    read_tool,
                    depends_on=["copy-current-data-context"],
                    reason="Read the copied foreground data before running analysis.",
                ),
            ]
    return _context_source_steps(
        intent,
        allowed,
        source,
        step_prefix="data",
        capability_id="data.analysis",
    )


def _dynamic_context_ui_transfer_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    hint: Mapping[str, Any],
    base_steps: list[ToolPlanStepSnapshot],
) -> list[ToolPlanStepSnapshot]:
    source = str(hint.get("source") or "").strip()
    action = str(hint.get("action") or "").strip()
    target_kind = str(hint.get("target_kind") or "").strip()
    target = str(hint.get("target") or "").strip()
    app_name = str(hint.get("app_name") or "").strip()
    mode = str(hint.get("mode") or "focus").strip() or "focus"
    source_requires_shortcut = source in {
        "selection",
        "current_page_link",
        "current_page_content",
    }
    target_requires_paste = target_kind in {"app_paste", "current_input", "ui_field"}
    shortcut_tool = _first_allowed(("desktop.safe_shortcut",), allowed)
    if (source_requires_shortcut or target_requires_paste) and not shortcut_tool:
        return list(base_steps)

    app_paste_tool: str | None = None
    field_click_app_tool: str | None = None
    field_click_tool: str | None = None
    if target_kind == "app_paste":
        if not app_name:
            return list(base_steps)
        app_paste_app_tool, app_paste_shortcut_tool = _app_scoped_safe_shortcut_split_tools(
            app_name,
            mode,
            allowed,
        )
        app_paste_tool = _first_allowed(
            app_foreground_tool_candidates(mode, "safe_shortcut"),
            allowed,
        )
        if not ((app_paste_app_tool and app_paste_shortcut_tool) or app_paste_tool):
            return list(base_steps)
    elif target_kind == "ui_field":
        if not target:
            return list(base_steps)
        if app_name:
            field_click_app_tool, field_click_tool = _app_scoped_operation_split_tools(
                app_name,
                mode,
                ("desktop.click_ui_element",),
                allowed,
            )
            field_click_app_scoped_tool = _first_allowed(
                app_foreground_tool_candidates(mode, "click_ui_element"),
                allowed,
            )
            if not field_click_tool:
                field_click_tool = field_click_app_scoped_tool
        else:
            field_click_tool = _first_allowed(("desktop.click_ui_element",), allowed)
        if not field_click_tool:
            return list(base_steps)
    elif action != "copy_context" and target_kind != "current_input":
        return list(base_steps)

    steps = list(base_steps)
    previous_step_id = steps[-1].step_id if steps else ""

    def append_step(step: ToolPlanStepSnapshot) -> None:
        nonlocal previous_step_id
        steps.append(step)
        previous_step_id = step.step_id

    if source == "selection":
        append_step(
            _step(
                intent,
                "copy-selected-dynamic-context",
                "Copy selected context",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "copy"},
                depends_on=[previous_step_id] if previous_step_id else [],
                reason="Copy the selected content before transferring it to the requested UI target.",
            )
        )
    elif source == "current_page_link":
        append_step(
            _step(
                intent,
                "copy-current-page-link-context",
                "Copy current page link",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "copy_current_page_link"},
                depends_on=[previous_step_id] if previous_step_id else [],
                reason="Copy the current page link before transferring it to the requested UI target.",
            )
        )
    elif source == "current_page_content":
        append_step(
            _step(
                intent,
                "select-current-page-content",
                "Select current page content",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "select_all"},
                depends_on=[previous_step_id] if previous_step_id else [],
                reason="Select the current page content before copying it for transfer.",
            )
        )
        append_step(
            _step(
                intent,
                "copy-current-page-content",
                "Copy current page content",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "copy"},
                depends_on=["select-current-page-content"],
                reason="Copy the selected page content before transferring it to the requested UI target.",
            )
        )
    elif source != "clipboard":
        return list(base_steps)

    if action == "copy_context":
        return steps

    if target_kind == "app_paste":
        if app_paste_app_tool and app_paste_shortcut_tool:
            append_step(
                _step(
                    intent,
                    "open-or-focus-app",
                    "Open or focus app",
                    "desktop.app_control",
                    app_paste_app_tool,
                    input_preview={"app_name": app_name},
                    depends_on=[previous_step_id] if previous_step_id else [],
                    reason="Prepare the requested app before pasting the captured context.",
                )
            )
            append_step(
                _step(
                    intent,
                    "paste-context-into-app",
                    "Paste context into app",
                    "desktop.ui_operation",
                    app_paste_shortcut_tool,
                    input_preview={"action": "paste"},
                    depends_on=[previous_step_id],
                    action="shortcut",
                    reason="Paste the captured context into the foreground app.",
                )
            )
        else:
            append_step(
                _step(
                    intent,
                    "paste-context-into-app",
                    "Paste context into app",
                    "desktop.app_control",
                    app_paste_tool,
                    input_preview={"app_name": app_name, "action": "paste"},
                    depends_on=[previous_step_id] if previous_step_id else [],
                    action="shortcut",
                    reason="Focus or open the requested app and paste the captured context.",
                )
            )
    else:
        if target_kind == "ui_field":
            field_payload = {
                "target": target,
                "role_filter": "text",
                "limit": 80,
                "click_count": 1,
            }
            if field_click_app_tool:
                append_step(
                    _step(
                        intent,
                        "open-or-focus-app",
                        "Open or focus app",
                        "desktop.app_control",
                        field_click_app_tool,
                        input_preview={"app_name": app_name},
                        depends_on=[previous_step_id] if previous_step_id else [],
                        reason="Prepare the requested app before focusing the transfer field.",
                    )
                )
            elif field_click_tool and field_click_tool.startswith("app."):
                field_payload = {"app_name": app_name, **field_payload}
            append_step(
                _step(
                    intent,
                    "focus-context-transfer-field",
                    "Focus transfer field",
                    "desktop.ui_operation",
                    field_click_tool,
                    input_preview=field_payload,
                    depends_on=[previous_step_id] if previous_step_id else [],
                    action="click",
                    reason="Focus the requested text field before pasting the captured context.",
                )
            )
        append_step(
            _step(
                intent,
                "paste-context-into-field",
                "Paste context",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "paste"},
                depends_on=[previous_step_id] if previous_step_id else [],
                action="shortcut",
                reason="Paste the captured context into the focused input.",
            )
        )

    verify_tool = _first_allowed(
        ("desktop.ui_elements", "desktop.active_window", "screen.capture"),
        allowed,
    )
    steps.append(
        _step(
            intent,
            "verify-desktop-result",
            "Verify desktop result",
            "desktop.app_discovery",
            verify_tool,
            input_preview=_desktop_verify_input_preview(
                verify_tool,
                app_name=app_name,
                operation_preview={"target": target} if target else {},
            ),
            depends_on=[previous_step_id] if previous_step_id else [],
            reason="Observe the destination UI after transferring context.",
        )
    )
    return steps


def _file_scope_input_preview(
    location_hint: str,
    file_type_hint: str,
    file_pattern_hint: str,
    selection_hint: str = "",
) -> dict[str, str]:
    preview: dict[str, str] = {}
    if location_hint:
        preview["path"] = location_hint
    if file_type_hint:
        preview["file_type"] = file_type_hint
    if file_pattern_hint:
        preview["pattern"] = file_pattern_hint
    if selection_hint:
        preview["selection"] = selection_hint
    return preview


def _data_source_inspect_input_preview(
    path: str,
    source_kind: str,
    source_name: str = "",
    selection_hint: str = "",
) -> dict[str, str]:
    preview: dict[str, str] = {}
    clean_path = str(path or "").strip()
    clean_name = _clean_data_source_name_pattern(source_name)
    if clean_path:
        preview["path"] = clean_path
    pattern = _data_source_pattern_hint(source_kind)
    if clean_name and pattern:
        pattern = _named_data_source_pattern(clean_name, pattern)
    elif clean_name:
        pattern = f"*{clean_name}*"
    if pattern and not _looks_like_specific_data_source_path(clean_path):
        preview["pattern"] = pattern
        if str(source_kind or "").strip() != "unknown":
            preview["file_type"] = str(source_kind or "").strip()
    if selection_hint:
        preview["selection"] = selection_hint
    return preview


def _clean_data_source_name_pattern(source_name: str) -> str:
    value = str(source_name or "").strip()
    if not value:
        return ""
    return re.sub(r"[*?\\[\\]{}]", "", value).strip()


def _named_data_source_pattern(source_name: str, base_pattern: str) -> str:
    if base_pattern.startswith("*."):
        return f"*{source_name}*{base_pattern[1:]}"
    if base_pattern.startswith("*.{") and base_pattern.endswith("}"):
        return f"*{source_name}*{base_pattern[1:]}"
    return base_pattern


def _scoped_data_source_path(source_hint: str, source_scope: str) -> str:
    clean_source = str(source_hint or "").strip()
    clean_scope = str(source_scope or "").strip()
    if (
        clean_source
        and clean_scope
        and not re.match(r"^(?:~|/|\.{1,2}/)", clean_source)
        and "/" not in clean_source
        and "\\" not in clean_source
    ):
        return f"{clean_scope.rstrip('/')}/{clean_source}"
    return clean_source


def _data_source_pattern_hint(source_kind: str) -> str:
    return {
        "csv": "*.csv",
        "tsv": "*.tsv",
        "xlsx": "*.xlsx",
        "xls": "*.xls",
        "jsonl": "*.jsonl",
        "json": "*.json",
        "parquet": "*.parquet",
        "pdf": "*.pdf",
        "text": "*.txt",
        "text_table": "*.{csv,tsv,xls,xlsx,json,jsonl,txt,md,markdown}",
    }.get(str(source_kind or "").strip().lower(), "")


def _looks_like_specific_data_source_path(path: str) -> bool:
    return bool(
        re.search(
            r"\.(?:csv|tsv|xlsx|xls|jsonl|json|parquet|txt|md|markdown)$",
            str(path or "").strip(),
            flags=re.IGNORECASE,
        )
    )


def _file_apply_input_preview(
    location_hint: str,
    operation_hint: str,
    file_type_hint: str = "",
    file_pattern_hint: str = "",
    destination_hint: str = "",
    selection_hint: str = "",
) -> dict[str, str]:
    preview: dict[str, str] = {}
    if location_hint:
        preview["path"] = location_hint
    if operation_hint:
        preview["operation"] = operation_hint
    if file_type_hint:
        preview["file_type"] = file_type_hint
    if file_pattern_hint:
        preview["pattern"] = file_pattern_hint
    if destination_hint:
        preview["destination"] = destination_hint
    if selection_hint:
        preview["selection"] = selection_hint
    return preview


def _file_apply_tool_candidates(operation_hint: str) -> tuple[str, ...]:
    operation = str(operation_hint or "").strip()
    if operation in {"organize", "archive", "move"}:
        return ("file.organize", "fs.move_file", "terminal.run", "python.run")
    if operation == "rename":
        return ("terminal.run", "python.run")
    return ("terminal.run", "python.run")


def _context_source_capability_id(source: str, tool_name: str | None, fallback: str) -> str:
    clean_tool = str(tool_name or "").strip()
    if source in {"selection", "clipboard"}:
        return "clipboard.read_write"
    if source == "app_search_result":
        return "desktop.app_discovery"
    if source in {"current_page_link", "current_page_content"}:
        if clean_tool.startswith("browser."):
            return "browser.research"
        if clean_tool == "desktop.safe_shortcut":
            return "desktop.ui_operation"
        if clean_tool in {"desktop.ui_elements", "screen.capture"}:
            return "desktop.app_discovery"
    if source == "visible_text":
        return "desktop.app_discovery"
    if source == "screen_capture":
        return "desktop.app_discovery"
    if source == "file":
        return "file.workspace_read"
    return fallback


def _context_source_required_capability(source: str) -> str:
    clean_source = str(source or "").strip()
    if clean_source in {"selection", "clipboard"}:
        return "clipboard.read_write"
    if clean_source in {"current_page_link", "current_page_content"}:
        return "browser.research"
    if clean_source == "visible_text":
        return "desktop.app_discovery"
    if clean_source == "screen_capture":
        return "desktop.app_discovery"
    if clean_source == "file":
        return "file.workspace_read"
    return "artifact.write"


def _direct_communication_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    direct_message: Mapping[str, Any],
) -> list[ToolPlanStepSnapshot]:
    app_name = str(direct_message.get("app_name") or "").strip()
    recipient = str(direct_message.get("recipient") or "").strip()
    body = str(direct_message.get("body") or "").strip()
    body_source = str(direct_message.get("body_source") or "").strip()
    transform = str(direct_message.get("content_transform_hint") or "").strip()
    channel = str(direct_message.get("channel") or "").strip()
    send_action = str(direct_message.get("send_action") or "send").strip() or "send"
    mode = str(direct_message.get("mode") or "focus").strip() or "focus"
    if not channel and _running_app_scope_label(app_name):
        channel = (
            _generic_communication_target_channel_hint(intent.user_goal)
            or _communication_delivery_channel_hint(intent.user_goal)
        )
    running_app_query = _running_scoped_communication_app_query(app_name, channel)
    if running_app_query:
        selected_app_steps = _direct_communication_discovered_app_steps(
            intent,
            allowed,
            recipient=recipient,
            body=body,
            body_source=body_source,
            channel=_communication_channel_for_app_query(running_app_query, channel),
            send_action=send_action,
            discovery_scope="running",
        )
        if selected_app_steps:
            return selected_app_steps
    if not app_name:
        selected_app_steps = _direct_communication_discovered_app_steps(
            intent,
            allowed,
            recipient=recipient,
            body=body,
            body_source=body_source,
            channel=channel,
            send_action=send_action,
        )
        if selected_app_steps:
            return selected_app_steps
    if not app_name and channel == "email" and send_action in {"send", "draft"}:
        app_name = _default_communication_app_for_channel(
            channel,
            mode,
            allowed,
            require_send=send_action != "draft",
        )
    if (
        not app_name
        or not recipient
        or (
            not body
            and body_source
            not in {
                "app_search_result",
                "clipboard",
                "selection",
                "screen_capture",
                "current_page_link",
                "current_page_content",
                "visible_text",
                "file",
            }
        )
    ):
        return []
    app_shortcut_tool = _first_allowed(
        app_foreground_tool_candidates(mode, "safe_shortcut"),
        allowed,
    )
    app_tool, shortcut_tool = _communication_app_scoped_shortcut_split_tools(
        app_name,
        mode,
        allowed,
    )
    type_tool, recipient_type_input = _safe_type_text_operation_preview(
        app_name=app_name,
        mode=mode,
        allowed=allowed,
        payload={"text": recipient},
    )
    recipient_submit_tool = _app_search_submit_operation_tool(allowed)
    send_tool = _communication_send_operation_tool(allowed)
    steps: list[ToolPlanStepSnapshot] = []
    source_step_id = ""
    generated_body = _direct_message_requires_generated_body(direct_message)
    literal_body = bool(
        body
        and not generated_body
        and body_source in {"", "explicit_user_text"}
    )
    if (
        body_source == "current_page_link"
        and not _first_allowed(("desktop.safe_shortcut",), allowed)
        and _first_allowed(("browser.current_page",), allowed)
    ):
        generated_body = True
    if generated_body and body_source:
        context_steps = (
            _app_search_result_context_steps(
                intent,
                allowed,
                direct_message,
                step_prefix="communication",
                capability_id="communication.compose",
            )
            if body_source == "app_search_result"
            else _context_source_steps(
                intent,
                allowed,
                body_source,
                step_prefix="communication",
                capability_id="communication.compose",
            )
        )
        steps.extend(context_steps)
        if context_steps:
            source_step_id = context_steps[-1].step_id
    elif body_source == "selection":
        source_step_id = "copy-communication-body-source"
        copy_tool = _communication_safe_shortcut_operation_tool(allowed)
        copy_input = _communication_shortcut_input_preview(copy_tool, "copy")
        if not copy_tool and app_name:
            copy_tool = app_shortcut_tool
            if str(copy_tool or "").startswith("app."):
                copy_input = _communication_shortcut_input_preview(
                    copy_tool,
                    "copy",
                    app_name=app_name,
                )
        steps.append(
            _step(
                intent,
                source_step_id,
                "Copy communication body source",
                "communication.compose",
                copy_tool,
                input_preview=copy_input,
                action="copy_selection",
                reason="Copy the explicit selection before using it as the message body.",
            )
        )
    elif body_source == "current_page_link":
        source_step_id = "copy-communication-body-source"
        steps.append(
            _step(
                intent,
                source_step_id,
                "Copy communication body source",
                "communication.compose",
                _first_allowed(("desktop.safe_shortcut",), allowed),
                input_preview={"action": "copy_current_page_link"},
                action="copy_current_page_link",
                reason="Copy the current page link before using it as the message body.",
            )
        )

    observed_safe_compose = _communication_observed_safe_compose_available(
        allowed,
        require_send=send_action != "draft",
    )
    focus_depends_on = [source_step_id] if source_step_id else []
    if (
        observed_safe_compose
        and not app_shortcut_tool
        and not (app_tool and shortcut_tool)
        and body
        and not body_source
    ):
        if mode == "open":
            open_tool = _first_allowed(
                ("app.open", "desktop.open_app", "app.focus", "desktop.focus_app"),
                allowed,
            )
        else:
            open_tool = _first_allowed(
                ("app.focus", "desktop.focus_app", "app.open", "desktop.open_app"),
                allowed,
            )
        observe_tool = _first_allowed(
            ("desktop.ui_elements", "desktop.read_ui"),
            allowed,
        )
        steps.extend(
            [
                _step(
                    intent,
                    "open-or-focus-app",
                    "Open or focus app",
                    "desktop.app_control",
                    open_tool,
                    input_preview={"app_name": app_name},
                    depends_on=focus_depends_on,
                    reason="Prepare the requested communication app before observing its compose UI.",
                ),
                _step(
                    intent,
                    "inspect-communication-compose-ui",
                    "Inspect communication compose UI",
                    "desktop.app_discovery",
                    observe_tool,
                    input_preview={"app_name": app_name, "role_filter": "text", "limit": 80},
                    depends_on=["open-or-focus-app"],
                    action="read_ui",
                    reason="Observe the communication UI before focusing recipient and message fields.",
                ),
                _step(
                    intent,
                    "type-communication-recipient",
                    "Type communication recipient",
                    "communication.compose",
                    "desktop.type_into_ui_element",
                    input_preview={
                        "app_name": app_name,
                        "target": _communication_compose_recipient_target(channel),
                        "text": recipient,
                        "role_filter": "text",
                        "limit": 80,
                    },
                    risk_level="medium",
                    approval_required=True,
                    depends_on=["inspect-communication-compose-ui"],
                    action="type",
                    reason="Type only the explicit recipient after observing the communication UI.",
                ),
                _step(
                    intent,
                    "submit-communication-recipient-search",
                    "Submit communication recipient search",
                    "communication.compose",
                    recipient_submit_tool,
                    input_preview=_app_search_submit_input_preview(recipient_submit_tool),
                    risk_level=_app_search_submit_risk_level(recipient_submit_tool),
                    approval_required=_app_search_submit_approval_required(recipient_submit_tool),
                    depends_on=["type-communication-recipient"],
                    action="submit_search",
                    reason=(
                        "Confirm the recipient with the dedicated safe submit tool when available; "
                        "otherwise use the foreground submit fallback through the approval gate."
                    ),
                ),
                _step(
                    intent,
                    "inspect-communication-message-ui",
                    "Inspect communication message UI",
                    "desktop.app_discovery",
                    observe_tool,
                    input_preview={"app_name": app_name, "role_filter": "text", "limit": 80},
                    depends_on=["submit-communication-recipient-search"],
                    action="read_ui",
                    reason="Observe the message field after recipient selection.",
                ),
                _step(
                    intent,
                    "draft-communication-message",
                    "Draft communication message",
                    "communication.compose",
                    "desktop.type_into_ui_element",
                    input_preview={
                        "app_name": app_name,
                        "target": _communication_compose_body_target(channel),
                        "text": body,
                        "role_filter": "text",
                        "limit": 80,
                    },
                    risk_level="medium",
                    approval_required=True,
                    depends_on=["inspect-communication-message-ui"],
                    action="draft_message",
                    reason=(
                        "Type only the explicit message body and stop before sending."
                        if send_action == "draft"
                        else "Type only the explicit message body before the approval-gated send step."
                    ),
                ),
            ]
        )
        if send_action == "send":
            steps.append(
                _step(
                    intent,
                    "send-communication-message",
                    "Send communication message",
                    "communication.compose",
                    send_tool,
                    input_preview={"action": "send"},
                    risk_level="high",
                    approval_required=True,
                    depends_on=["draft-communication-message"],
                    action="send_message",
                    reason="Final message sending remains approval-gated.",
                )
            )
        return steps

    if app_tool and shortcut_tool:
        steps.append(
            _step(
                intent,
                "open-or-focus-app",
                "Open or focus app",
                "desktop.app_control",
                app_tool,
                input_preview={"app_name": app_name},
                depends_on=focus_depends_on,
                reason="Prepare the requested communication app before resolving the recipient.",
            )
        )
        focus_depends_on = ["open-or-focus-app"]
        focus_tool = shortcut_tool
        focus_input = _communication_shortcut_input_preview(
            shortcut_tool,
            _communication_recipient_focus_action(channel),
        )
        focus_capability = "communication.compose"
        focus_reason = "Open foreground recipient search with a generic safe shortcut."
    else:
        focus_tool = app_shortcut_tool
        focus_input = {
            "app_name": app_name,
            "action": _communication_recipient_focus_action(channel),
        }
        focus_capability = "communication.compose"
        focus_reason = "Open the app's recipient search with a safe shortcut before drafting the message."
    steps.extend(
        [
            _step(
                intent,
                "focus-communication-recipient-search",
                "Focus communication recipient search",
                focus_capability,
                focus_tool,
                input_preview=focus_input,
                action="resolve_recipient",
                depends_on=focus_depends_on,
                reason=focus_reason,
            ),
            _step(
                intent,
                "type-communication-recipient",
                "Type communication recipient",
                "communication.compose",
                type_tool,
                input_preview=recipient_type_input,
                risk_level=_desktop_operation_risk_level(
                    type_tool,
                    literal_user_text=True,
                ),
                approval_required=_desktop_operation_approval_required(
                    type_tool,
                    literal_user_text=True,
                ),
                depends_on=["focus-communication-recipient-search"],
                action="type",
                reason="Type only the explicit recipient from the user prompt.",
            ),
            _step(
                intent,
                "submit-communication-recipient-search",
                "Submit communication recipient search",
                "communication.compose",
                recipient_submit_tool,
                input_preview=_app_search_submit_input_preview(recipient_submit_tool),
                risk_level=_app_search_submit_risk_level(recipient_submit_tool),
                approval_required=_app_search_submit_approval_required(recipient_submit_tool),
                depends_on=["type-communication-recipient"],
                action="submit_search",
                reason=(
                    "Select or search the recipient with the dedicated safe submit tool when available; "
                    "otherwise use the foreground submit fallback through the approval gate."
                ),
            ),
        ]
    )
    if body_source in {"clipboard", "selection", "current_page_link"} and not generated_body:
        paste_tool = _communication_safe_shortcut_operation_tool(allowed)
        paste_input = _communication_shortcut_input_preview(paste_tool, "paste")
        if not paste_tool and app_name:
            paste_tool = app_shortcut_tool
            if str(paste_tool or "").startswith("app."):
                paste_input = _communication_shortcut_input_preview(
                    paste_tool,
                    "paste",
                    app_name=app_name,
                )
        steps.append(
            _step(
                intent,
                "paste-communication-message",
                "Paste communication message",
                "communication.compose",
                paste_tool,
                input_preview=paste_input,
                risk_level=_desktop_operation_risk_level(paste_tool),
                approval_required=_desktop_operation_approval_required(paste_tool),
                depends_on=["submit-communication-recipient-search"],
                action="paste",
                reason="Paste the requested clipboard-backed context into the message draft.",
            )
        )
        send_depends_on = ["paste-communication-message"]
    else:
        if generated_body and body_source:
            draft_input = {"body_source": body_source}
            if body:
                draft_input["instruction"] = body
        else:
            draft_input = {"text": body} if body else {"body_source": body_source}
        if transform:
            draft_input["transform"] = transform
        draft_tool, draft_input = _safe_type_text_operation_preview(
            app_name=app_name,
            mode=mode,
            allowed=allowed,
            payload=draft_input,
        )
        steps.append(
            _step(
                intent,
                "draft-communication-message",
                "Draft communication message",
                "communication.compose",
                draft_tool,
                input_preview=draft_input,
                risk_level=_desktop_operation_risk_level(
                    draft_tool,
                    literal_user_text=literal_body,
                ),
                approval_required=_desktop_operation_approval_required(
                    draft_tool,
                    literal_user_text=literal_body,
                ),
                depends_on=["submit-communication-recipient-search"],
                action="draft_message",
                reason=(
                    "Draft the generated message body from inspected context before the approval-gated send step."
                    if generated_body
                    else (
                        "Type only the explicit message body and stop before sending."
                        if send_action == "draft"
                        else "Type only the explicit message body before the approval-gated send step."
                    )
                ),
            )
        )
        send_depends_on = ["draft-communication-message"]

    if send_action == "draft":
        return steps

    steps.append(
        _step(
            intent,
            "send-communication-message",
            "Send communication message",
            "communication.compose",
            send_tool,
            input_preview=_communication_send_input_preview(send_tool),
            risk_level="high",
            approval_required=True,
            depends_on=send_depends_on,
            action="send_message",
            reason="Final message sending remains approval-gated.",
        )
    )
    verify_tool = _first_allowed(("desktop.ui_elements", "desktop.read_ui", "screen.capture"), allowed)
    if verify_tool:
        steps.append(
            _step(
                intent,
                "verify-communication-message",
                "Verify communication message",
                "desktop.app_discovery",
                verify_tool,
                input_preview=_communication_verify_input_preview(verify_tool, app_name),
                depends_on=["send-communication-message"],
                action=_desktop_discovery_action(verify_tool),
                reason="Observe the communication app after the approval-gated send action.",
            )
        )
    return steps


def _communication_safe_shortcut_operation_tool(allowed: set[str] | None) -> str | None:
    return _first_allowed(
        ("desktop.safe_shortcut", "desktop.shortcut", "desktop.hotkey"),
        allowed,
    )


def _communication_app_scoped_shortcut_split_tools(
    app_name: str,
    mode: str,
    allowed: set[str] | None,
) -> tuple[str | None, str | None]:
    if not app_name:
        return None, None
    app_tool = _first_allowed(app_control_tool_candidates(mode or "focus"), allowed)
    shortcut_tool = _communication_safe_shortcut_operation_tool(allowed)
    if not app_tool or not shortcut_tool:
        return None, None
    return app_tool, shortcut_tool


def _communication_shortcut_input_preview(
    tool_name: str | None,
    action: str,
    *,
    app_name: str = "",
) -> dict[str, Any]:
    clean_tool = str(tool_name or "").strip()
    clean_action = str(action or "").strip()
    if clean_tool in {"desktop.shortcut", "desktop.hotkey"}:
        if clean_action == "find":
            return {"key": "f", "modifiers": ["command"]}
        if clean_action == "new_message":
            return {"key": "n", "modifiers": ["command"]}
        if clean_action == "paste":
            return {"key": "v", "modifiers": ["command"]}
        if clean_action == "copy":
            return {"key": "c", "modifiers": ["command"]}
        if clean_action in {"confirm", "send", "submit_search"}:
            return {"key": "return", "modifiers": []}
    if clean_tool.startswith("app."):
        return {"app_name": app_name, "action": clean_action}
    return {"action": clean_action}


def _communication_send_operation_tool(allowed: set[str] | None) -> str | None:
    return _first_allowed(
        ("desktop.submit_foreground", "desktop.shortcut", "desktop.hotkey"),
        allowed,
    )


def _communication_send_input_preview(tool_name: str | None) -> dict[str, Any]:
    return _communication_shortcut_input_preview(tool_name, "send")


def _communication_verify_input_preview(
    tool_name: str | None,
    app_name: str,
) -> dict[str, Any]:
    clean_tool = str(tool_name or "").strip()
    if clean_tool in {"desktop.ui_elements", "desktop.read_ui"}:
        preview = {"role_filter": "text", "limit": 80}
        if app_name:
            preview["app_name"] = app_name
        return preview
    return {"reason": "Verify communication send result"}


def _direct_communication_discovered_app_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    *,
    recipient: str,
    body: str,
    body_source: str,
    channel: str,
    send_action: str,
    discovery_scope: str = "installed",
) -> list[ToolPlanStepSnapshot]:
    if channel not in {"email", "message"} or not recipient:
        return []
    query = "mail" if channel == "email" else "messaging"
    discovery_tool = _first_allowed(
        ("desktop.running_apps",)
        if discovery_scope == "running"
        else ("desktop.list_apps",),
        allowed,
    )
    selected_app_tool = _selected_discovered_app_tool(
        allowed,
        safe_shortcut={"action": "new_message"},
        mode=_selected_discovered_app_prepare_mode(discovery_tool, "open"),
    )
    if not discovery_tool or selected_app_tool not in {
        "app.open_and_safe_shortcut",
        "app.focus_and_safe_shortcut",
    }:
        return []
    selection_source = _selected_app_selection_source(discovery_tool)
    selected_app = _selected_app_placeholder(selection_source)
    steps: list[ToolPlanStepSnapshot] = []
    discovery_depends_on: list[str] = []
    if body_source:
        context_steps = _context_source_steps(
            intent,
            allowed,
            body_source,
            step_prefix="communication",
            capability_id="communication.compose",
        )
        steps.extend(context_steps)
        if context_steps:
            discovery_depends_on = [context_steps[-1].step_id]
    steps.append(
        _step(
            intent,
            "discover_apps-desktop-state",
            "Discover desktop state",
            "desktop.app_discovery",
            discovery_tool,
            input_preview=(
                {"query": query, "limit": 20}
                if discovery_tool == "desktop.list_apps"
                else {}
            ),
            depends_on=discovery_depends_on,
            reason=(
                "Discover a running communication app by capability before drafting "
                "the user-requested message."
                if discovery_tool == "desktop.running_apps"
                else "Discover an installed communication app by capability before drafting "
                "the user-requested message."
            ),
        )
    )
    steps.append(
        _step(
            intent,
            "open-selected-discovered-app",
            "Open selected discovered app",
            "desktop.ui_operation",
            selected_app_tool,
            input_preview={
                "app_name": selected_app,
                "selection_source": selection_source,
                "query": query,
                "action": "new_message",
            },
            depends_on=["discover_apps-desktop-state"],
            action="safe_shortcut",
            reason=(
                f"After {selection_source} returns candidates, runtime resolves the best "
                "matching communication app before opening compose."
            ),
        )
    )
    compose_hint = {
        "send_action": send_action,
        "channel": channel,
        "recipient": recipient,
    }
    if body:
        compose_hint["body"] = body
    if body_source:
        compose_hint["body_source"] = body_source
    transform = str(intent.inputs.get("content_transform_hint") or "").strip()
    if transform:
        compose_hint["content_transform_hint"] = transform
    selected_intent = intent.model_copy(
        update={
            "inputs": {
                **intent.inputs,
                "app_capability_hint": {
                    "query": query,
                    "description": "email" if query == "mail" else "messaging",
                },
                "safe_shortcut_hint": {"action": "new_message"},
                "communication_compose_hint": compose_hint,
                "selected_app_selection_source_hint": selection_source,
            }
        }
    )
    _append_selected_discovered_communication_compose_steps(
        steps,
        selected_intent,
        allowed,
        query=query,
        selected_app_tool=selected_app_tool,
        depends_on="open-selected-discovered-app",
    )
    return steps


def _running_scoped_communication_app_query(app_name: str, channel: str) -> str:
    if not _running_app_scope_label(app_name):
        return ""
    scoped_hint = _scoped_app_label_capability_hint(app_name)
    query = str(scoped_hint.get("query") or "").strip()
    if query in {"mail", "messaging"}:
        return query
    if channel == "email":
        return "mail"
    if channel == "message":
        return "messaging"
    return ""


def _communication_channel_for_app_query(query: str, fallback: str) -> str:
    if query == "mail":
        return "email"
    if query == "messaging":
        return "message"
    return fallback


def _running_app_scope_label(value: str) -> bool:
    return _contains_any(
        value,
        (
            "当前打开",
            "当前已打开",
            "已打开",
            "打开的",
            "正在运行",
            "运行中",
            "开着",
            "已开启",
            "当前",
            "前台",
            "currently open",
            "already open",
            "running",
            "open",
            "current",
            "foreground",
        ),
    )


def _communication_draft_input_preview(direct_message: Mapping[str, Any]) -> dict[str, Any]:
    preview: dict[str, Any] = {}
    for key in ("app_name", "recipient", "body", "body_source", "content_transform_hint", "channel"):
        value = str(direct_message.get(key) or "").strip()
        if value:
            preview[key] = value
    return preview


def _communication_draft_should_use_artifact(
    direct_message: Any,
    allowed: set[str] | None,
) -> bool:
    if not isinstance(direct_message, Mapping):
        return False
    if str(direct_message.get("send_action") or "").strip() != "draft":
        return False
    if str(direct_message.get("app_name") or "").strip():
        return False
    return bool(_first_allowed(("artifact.write",), allowed))


def _default_communication_app_for_channel(
    channel: str,
    mode: str,
    allowed: set[str] | None,
    *,
    require_send: bool = True,
) -> str:
    if channel != "email":
        return ""
    if not _communication_desktop_compose_tools_available(
        mode,
        allowed,
        require_send=require_send,
    ):
        return ""
    return "Mail"


def _generic_communication_app_query_for_channel(channel: str) -> str:
    if channel == "email":
        return "email"
    if channel in {"message", "chat"}:
        return "chat"
    return ""


def _communication_desktop_compose_tools_available(
    mode: str,
    allowed: set[str] | None,
    *,
    require_send: bool,
) -> bool:
    if allowed is None:
        return True
    app_shortcut_tool = _first_allowed(
        app_foreground_tool_candidates(mode, "safe_shortcut"),
        allowed,
    )
    app_tool, shortcut_tool = _app_scoped_safe_shortcut_split_tools("Mail", mode, allowed)
    if not app_shortcut_tool and not (app_tool and shortcut_tool):
        return False
    return bool(
        _first_allowed(
            _safe_type_text_operation_candidates("Mail", mode),
            allowed,
        )
        and _first_allowed(("desktop.search_submit",), allowed)
        and (
            not require_send
            or _first_allowed(("desktop.submit_foreground",), allowed)
        )
    )


def _communication_observed_safe_compose_available(
    allowed: set[str] | None,
    *,
    require_send: bool,
) -> bool:
    if allowed is None:
        return True
    if not _first_allowed(
        ("app.open", "app.focus", "desktop.open_app", "desktop.focus_app"),
        allowed,
    ):
        return False
    if not _first_allowed(("desktop.ui_elements", "desktop.read_ui"), allowed):
        return False
    if not _first_allowed(("desktop.safe_click", "desktop.click"), allowed):
        return False
    if not _first_allowed(
        ("desktop.safe_type_text", "desktop.type_text", "desktop.type"),
        allowed,
    ):
        return False
    return bool(not require_send or _first_allowed(("desktop.submit_foreground",), allowed))


def _communication_recipient_focus_action(channel: str) -> str:
    if channel == "email":
        return "new_message"
    return "find"


def _direct_message_requires_generated_body(direct_message: Mapping[str, Any]) -> bool:
    body_source = str(direct_message.get("body_source") or "").strip()
    transform = str(direct_message.get("content_transform_hint") or "").strip()
    if transform and body_source:
        return True
    return body_source in {
        "app_search_result",
        "screen_capture",
        "current_page_content",
        "visible_text",
        "file",
    }


def _current_page_find_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
) -> list[ToolPlanStepSnapshot]:
    source = str(intent.inputs.get("context_source") or "").strip()
    query = str(intent.inputs.get("query") or "").strip()
    shortcut_tool = _first_allowed(("desktop.safe_shortcut",), allowed)
    type_tool = _first_allowed(("desktop.safe_type_text",), allowed)
    steps: list[ToolPlanStepSnapshot] = []

    if source == "selection":
        steps.append(
            _step(
                intent,
                "copy-selected-page-find-query",
                "Copy selected page find query",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "copy"},
                action="shortcut",
                reason="Copy the explicit selection before using it as the current-page find query.",
            )
        )

    steps.append(
        _step(
            intent,
            "open-current-page-find",
            "Open current page find",
            "desktop.ui_operation",
            shortcut_tool,
            input_preview={"action": "find"},
            depends_on=["copy-selected-page-find-query"] if source == "selection" else [],
            action="shortcut",
            reason="Open the foreground browser page find box with the standard safe shortcut.",
        )
    )

    if source in {"selection", "clipboard"}:
        steps.append(
            _step(
                intent,
                "paste-current-page-find-query",
                "Paste current page find query",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "paste"},
                depends_on=["open-current-page-find"],
                action="shortcut",
                reason="Paste the selected or clipboard text into the current-page find box.",
            )
        )
        return steps

    steps.append(
        _step(
            intent,
            "type-current-page-find-query",
            "Type current page find query",
            "desktop.ui_operation",
            type_tool,
            input_preview={"text": query} if query else {},
            depends_on=["open-current-page-find"],
            action="type",
            reason="Type the explicit query into the current-page find box.",
        )
    )
    return steps


def _dynamic_context_browser_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
) -> list[ToolPlanStepSnapshot]:
    source = str(intent.inputs.get("context_source") or "").strip()
    app_name = str(intent.inputs.get("app_name") or "").strip()
    shortcut_tool = _first_allowed(("desktop.safe_shortcut",), allowed)
    submit_tool = _first_allowed(("desktop.search_submit",), allowed)
    steps: list[ToolPlanStepSnapshot] = []

    if source == "selection":
        steps.append(
            _step(
                intent,
                "copy-selected-browser-context",
                "Copy selected browser context",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "copy"},
                action="shortcut",
                reason="Copy the explicit selection before searching or opening it in the browser.",
            )
        )

    focus_depends_on = ["copy-selected-browser-context"] if source == "selection" else []
    focus_tool = shortcut_tool
    focus_payload = {"action": "focus_address_bar"}
    focus_capability = "desktop.ui_operation"
    if app_name:
        app_tool, app_shortcut_tool = _app_scoped_safe_shortcut_split_tools(
            app_name,
            "open",
            allowed,
        )
        app_focus_tool = _first_allowed(
            app_foreground_tool_candidates("open", "safe_shortcut"),
            allowed,
        )
        if app_tool and app_shortcut_tool:
            steps.append(
                _step(
                    intent,
                    "open-or-focus-app",
                    "Open or focus app",
                    "desktop.app_control",
                    app_tool,
                    input_preview={"app_name": app_name},
                    depends_on=focus_depends_on,
                    reason="Prepare the requested browser before focusing its address bar.",
                )
            )
            focus_depends_on = ["open-or-focus-app"]
            focus_tool = app_shortcut_tool
        elif app_focus_tool:
            focus_tool = app_focus_tool
            focus_payload = {"app_name": app_name, "action": "focus_address_bar"}
            focus_capability = "desktop.app_control"
    steps.append(
        _step(
            intent,
            "focus-browser-address-bar",
            "Focus browser address bar",
            focus_capability,
            focus_tool,
            input_preview=focus_payload,
            depends_on=focus_depends_on,
            action="shortcut",
            reason="Use the requested browser address bar so selected or clipboard text can be opened or searched.",
        )
    )
    steps.append(
        _step(
            intent,
            "paste-browser-context",
            "Paste browser context",
            "desktop.ui_operation",
            shortcut_tool,
            input_preview={"action": "paste"},
            depends_on=["focus-browser-address-bar"],
            action="shortcut",
            reason="Paste the selected or clipboard text into the browser address bar.",
        )
    )
    steps.append(
        _step(
            intent,
            "submit-browser-context",
            "Submit browser context",
            "desktop.ui_operation",
            submit_tool,
            input_preview={},
            depends_on=["paste-browser-context"],
            action="submit",
            risk_level="low",
            approval_required=False,
            reason="Submit the browser address bar query with the dedicated safe search submit tool.",
        )
    )
    return steps


def _selected_discovered_app_tool(
    allowed: set[str] | None,
    *,
    safe_shortcut: Mapping[str, Any] | None,
    target_path: str = "",
    mode: str = "open",
) -> str:
    if str(target_path or "").strip():
        tool_name = _first_allowed(_OPEN_PATH_WITH_APP_TOOL_CANDIDATES, allowed)
        if tool_name:
            return tool_name
    if isinstance(safe_shortcut, Mapping) and str(safe_shortcut.get("action") or "").strip():
        shortcut_tools = (
            ("app.focus_and_safe_shortcut", "app.open_and_safe_shortcut")
            if mode == "focus"
            else ("app.open_and_safe_shortcut", "app.focus_and_safe_shortcut")
        )
        tool_name = _first_allowed(shortcut_tools, allowed)
        if tool_name:
            return tool_name
    tool_name = _first_allowed(app_control_tool_candidates(mode), allowed)
    if tool_name:
        return tool_name
    return ""


def _selected_discovered_app_prepare_mode(
    discovery_tool: str | None,
    mode: str,
) -> str:
    if str(discovery_tool or "").strip() == "desktop.running_apps":
        return "focus"
    clean_mode = str(mode or "").strip()
    if clean_mode in {"open", "focus"}:
        return clean_mode
    return "open"


def _selected_discovered_app_operation_preview(
    tool_name: str,
    *,
    safe_shortcut: Mapping[str, Any] | None,
) -> dict[str, Any]:
    if tool_name not in {"app.open_and_safe_shortcut", "app.focus_and_safe_shortcut"}:
        return {}
    action = str((safe_shortcut or {}).get("action") or "").strip()
    return {"action": action} if action else {}


def _append_selected_discovered_foreground_compose_steps(
    steps: list[ToolPlanStepSnapshot],
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    *,
    depends_on: str,
) -> None:
    if isinstance(intent.inputs.get("communication_compose_hint"), Mapping):
        return
    if isinstance(intent.inputs.get("model_generated_content_hint"), Mapping):
        return
    safe_shortcut = (
        intent.inputs.get("safe_shortcut_hint")
        if isinstance(intent.inputs.get("safe_shortcut_hint"), Mapping)
        else {}
    )
    if str((safe_shortcut or {}).get("action") or "").strip() in {
        "new_document",
        "new_note",
        "new_task",
    }:
        return
    pending_action = discovered_app_pending_user_action(intent.user_goal)
    if pending_action and (
        click_target_hint(pending_action) or type_into_ui_hint(pending_action)
    ):
        return
    compose_text = str(intent.inputs.get("foreground_compose_text_hint") or "").strip()
    if not compose_text:
        return
    selected_app_payload = _selected_discovered_app_input_context(intent)
    type_tool = _first_allowed(
        (
            *app_foreground_tool_candidates("focus", "safe_type_text"),
            *app_foreground_tool_candidates("open", "safe_type_text"),
            "desktop.safe_type_text",
            "desktop.type_text",
        ),
        allowed,
    )
    if not type_tool:
        return
    type_input_preview = {"text": compose_text}
    if str(type_tool or "").startswith("app."):
        type_input_preview = {
            **selected_app_payload,
            "text": compose_text,
        }
    type_step_id = "operate-foreground-ui-followup-type"
    steps.append(
        _step(
            intent,
            type_step_id,
            "Type after selected app create action",
            "desktop.ui_operation",
            type_tool,
            input_preview=type_input_preview,
            risk_level="medium",
            approval_required=True,
            depends_on=[depends_on],
            action="type",
            reason=(
                "After runtime resolves and opens a capable app, type only the explicit "
                "text requested by the user; writing into the selected app remains approval-gated."
            ),
        )
    )
    verify_depends_on = type_step_id
    submit_action = str(
        intent.inputs.get("foreground_submit_action_hint")
        or submit_action_hint(intent.user_goal)
        or ""
    ).strip()
    if submit_action:
        submit_step_id = "submit-foreground-ui"
        steps.append(
            _step(
                intent,
                submit_step_id,
                "Submit foreground UI",
                "desktop.ui_operation",
                _first_allowed(("desktop.submit_foreground",), allowed),
                input_preview={"action": submit_action},
                depends_on=[type_step_id],
                action="submit",
                risk_level="high",
                approval_required=True,
                reason=(
                    "Submit only after the runtime-resolved selected app has been opened and the "
                    "explicit user text has been typed."
                ),
            )
        )
        verify_depends_on = submit_step_id
    verify_tool = _first_allowed(
        ("desktop.ui_elements", "desktop.active_window", "screen.capture"),
        allowed,
    )
    if not verify_tool:
        return
    steps.append(
        _step(
            intent,
            "verify-desktop-result",
            "Verify desktop result",
            "desktop.app_discovery",
            verify_tool,
            input_preview=_selected_discovered_app_verify_input(
                intent,
                verify_tool,
                operation_preview={},
            ),
            depends_on=[verify_depends_on],
            action=_desktop_discovery_action(verify_tool),
            reason="Observe the selected app after typing the requested text.",
        )
    )


def _selected_discovered_app_query(intent: TaskIntentSnapshot) -> str:
    app_capability = intent.inputs.get("app_capability_hint")
    if isinstance(app_capability, Mapping):
        query = str(app_capability.get("query") or "").strip()
        if query:
            return query
    desktop_discovery = intent.inputs.get("desktop_discovery_hint")
    if isinstance(desktop_discovery, Mapping):
        return str(desktop_discovery.get("query") or "").strip()
    return ""


def _with_selected_app_selection_source(
    intent: TaskIntentSnapshot,
    selection_source: str,
) -> TaskIntentSnapshot:
    clean_source = _selected_discovered_app_selection_source_value(selection_source)
    if not clean_source:
        return intent
    return intent.model_copy(
        update={
            "inputs": {
                **intent.inputs,
                "selected_app_selection_source_hint": clean_source,
            }
        }
    )


def _selected_discovered_app_selection_source(intent: TaskIntentSnapshot) -> str:
    return (
        _selected_discovered_app_selection_source_value(
            intent.inputs.get("selected_app_selection_source_hint")
        )
        or "desktop.list_apps"
    )


def _selected_discovered_app_selection_source_value(value: Any) -> str:
    clean = str(value or "").strip()
    if clean in {"desktop.list_apps", "desktop.running_apps"}:
        return clean
    return ""


def _append_selected_discovered_app_observation_step(
    steps: list[ToolPlanStepSnapshot],
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    *,
    depends_on: str,
) -> None:
    inputs = intent.inputs if isinstance(intent.inputs, Mapping) else {}
    ui_inspection = (
        inputs.get("ui_inspection_hint")
        if isinstance(inputs.get("ui_inspection_hint"), Mapping)
        else {}
    )
    screen_capture = (
        inputs.get("screen_capture_hint")
        if isinstance(inputs.get("screen_capture_hint"), Mapping)
        else {}
    )
    needs_followup_observation = discovered_app_open_needs_model_followup(
        inputs,
        intent.user_goal,
    )
    if ui_inspection and not needs_followup_observation:
        if (
            isinstance(inputs.get("safe_shortcut_hint"), Mapping)
            or str(inputs.get("foreground_compose_text_hint") or "").strip()
            or isinstance(inputs.get("creative_canvas_hint"), Mapping)
        ):
            return
    pending_action = discovered_app_pending_user_action(intent.user_goal)
    click_target = click_target_hint(pending_action)
    if (
        not ui_inspection
        and not screen_capture
        and not needs_followup_observation
        and not click_target
    ):
        return
    if (
        not click_target
        and safe_shortcut_hint(pending_action)
        or safe_key_hint(pending_action)
        or safe_scroll_hint(pending_action)
        or safe_click_hint(pending_action)
        or hotkey_hint(pending_action)
    ):
        return
    if any(step.step_id == "observe-selected-discovered-app" for step in steps):
        return
    tool_name = _first_allowed(
        ("desktop.ui_elements", "desktop.read_ui", "screen.capture"),
        allowed,
    )
    if tool_name in {"desktop.ui_elements", "desktop.read_ui"}:
        input_preview = {
            key: ui_inspection[key]
            for key in ("role_filter", "limit")
            if key in ui_inspection and ui_inspection[key] not in (None, "")
        } or {"limit": 80}
    else:
        input_preview = (
            {"reason": "continue requested discovered app action"}
            if tool_name == "screen.capture"
            else {}
        )
    steps.append(
        _step(
            intent,
            "observe-selected-discovered-app",
            "Observe selected discovered app",
            "desktop.app_discovery",
            tool_name,
            input_preview=input_preview,
            depends_on=[depends_on],
            action=_desktop_discovery_action(tool_name),
            reason=(
                "Observe the runtime-resolved selected app after opening it because the user asked "
                "for a follow-up desktop action, not just app launch."
            ),
        )
    )


def _append_selected_discovered_launch_verification_step(
    steps: list[ToolPlanStepSnapshot],
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    *,
    depends_on: str,
) -> None:
    if not steps or steps[-1].step_id != depends_on:
        return
    selected_step = next((step for step in steps if step.step_id == depends_on), None)
    if selected_step is None:
        return
    selected_tool = str(selected_step.tool_name or "").strip()
    selected_payload = (
        selected_step.input_preview
        if isinstance(selected_step.input_preview, Mapping)
        else {}
    )
    embedded_action = bool(str(selected_payload.get("action") or "").strip()) or selected_tool in {
        "app.open_and_safe_shortcut",
        "app.focus_and_safe_shortcut",
    }
    verify_tool = _first_allowed(
        (
            (
                "desktop.ui_elements",
                "desktop.verify",
                "desktop.active_window",
                "screen.capture",
            )
            if embedded_action
            else (
                "desktop.verify",
                "desktop.active_window",
                "desktop.ui_elements",
                "screen.capture",
            )
        ),
        allowed,
    )
    if not verify_tool:
        return
    if verify_tool in {"desktop.ui_elements", "desktop.read_ui"}:
        input_preview = {"limit": 80} if embedded_action else {}
    elif verify_tool == "screen.capture":
        input_preview = {
            "reason": (
                "verify selected discovered app action"
                if embedded_action
                else "verify selected discovered app launch"
            )
        }
    else:
        input_preview = {}
    if verify_tool == "desktop.verify" and not embedded_action and selected_tool in {
        "app.open", "desktop.open_app",
    }:
        input_preview = {
            "app_name": str(selected_payload.get("app_name") or ""),
            "verification_goal": "app_running",
        }
    steps.append(
        _step(
            intent,
            "verify-desktop-result",
            "Verify desktop result",
            "desktop.app_discovery",
            verify_tool,
            input_preview=input_preview,
            depends_on=[depends_on],
            action=_desktop_discovery_action(verify_tool),
            reason=(
                "Observe the selected discovered app after opening or focusing it, "
                "so the desktop execution path follows discover, act, verify."
            ),
        )
    )


def _selected_discovered_app_input_context(intent: TaskIntentSnapshot) -> dict[str, str]:
    selection_source = _selected_discovered_app_selection_source(intent)
    return {
        "app_name": _selected_app_placeholder(selection_source),
        "selection_source": selection_source,
        "query": _selected_discovered_app_query(intent),
    }


def _selected_discovered_app_operation_input(
    intent: TaskIntentSnapshot,
    tool_name: str | None,
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    if str(tool_name or "").startswith("app."):
        return {
            **_selected_discovered_app_input_context(intent),
            **dict(payload),
        }
    return dict(payload)


def _selected_discovered_app_verify_input(
    intent: TaskIntentSnapshot,
    tool_name: str | None,
    operation_preview: Mapping[str, Any],
) -> dict[str, Any]:
    payload = _desktop_verify_input_preview(
        tool_name,
        app_name=_selected_app_placeholder(_selected_discovered_app_selection_source(intent)),
        operation_preview=operation_preview,
    )
    if str(payload.get("app_name") or "").strip() in {
        "<selected app from desktop.list_apps>",
        "<selected app from desktop.running_apps>",
    }:
        return {**payload, **_selected_discovered_app_input_context(intent)}
    return payload


def _append_selected_discovered_dynamic_context_transfer_steps(
    steps: list[ToolPlanStepSnapshot],
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    hint: Mapping[str, Any],
    *,
    discovery_step_id: str,
    open_step_id: str,
) -> bool:
    source = str(hint.get("source") or "").strip()
    action = str(hint.get("action") or "").strip()
    target_kind = str(hint.get("target_kind") or "").strip()
    if action != "transfer_context" or target_kind != "app_paste":
        return False
    if source not in {"selection", "clipboard", "current_page_link", "current_page_content"}:
        return False
    if not any(step.step_id == open_step_id for step in steps):
        return False

    paste_tool = _first_allowed(
        (
            "desktop.safe_shortcut",
            "app.focus_and_safe_shortcut",
            "app.open_and_safe_shortcut",
        ),
        allowed,
    )
    if not paste_tool:
        return False

    source_steps = _selected_discovered_dynamic_context_source_steps(
        intent,
        allowed,
        source,
    )
    if source_steps is None:
        return False
    if source_steps:
        steps[:0] = source_steps
        source_dependency = source_steps[-1].step_id
        for index, step in enumerate(steps):
            if step.step_id != discovery_step_id:
                continue
            depends_on = [
                item
                for item in [*step.depends_on, source_dependency]
                if item
            ]
            steps[index] = step.model_copy(
                update={"depends_on": _unique_capabilities(depends_on)}
            )
            break

    paste_input = (
        {"action": "paste"}
        if paste_tool == "desktop.safe_shortcut"
        else _selected_discovered_app_operation_input(
            intent,
            paste_tool,
            {"action": "paste"},
        )
    )
    steps.append(
        _step(
            intent,
            "paste-context-into-selected-discovered-app",
            "Paste context into selected app",
            "desktop.ui_operation",
            paste_tool,
            input_preview=paste_input,
            depends_on=[open_step_id],
            action="shortcut",
            reason=(
                "Paste the captured dynamic context into the runtime-resolved selected app "
                "after app discovery and focus."
            ),
        )
    )
    verify_tool = _first_allowed(
        ("desktop.ui_elements", "desktop.read_ui", "desktop.active_window", "screen.capture"),
        allowed,
    )
    if verify_tool:
        steps.append(
            _step(
                intent,
                "verify-selected-discovered-app-action",
                "Verify selected app action",
                "desktop.visual_verification",
                verify_tool,
                input_preview=(
                    {"reason": "verify selected discovered app context transfer"}
                    if verify_tool == "screen.capture"
                    else _selected_discovered_app_verify_input(
                        intent,
                        verify_tool,
                        {"limit": 80},
                    )
                    or {"limit": 80}
                ),
                depends_on=["paste-context-into-selected-discovered-app"],
                action=_desktop_discovery_action(verify_tool),
                reason=(
                    "Verify the selected discovered app after pasting dynamic context "
                    "before reporting completion."
                ),
            )
        )
    return True


def _selected_discovered_dynamic_context_source_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    source: str,
) -> list[ToolPlanStepSnapshot] | None:
    if source == "clipboard":
        return []
    shortcut_tool = _first_allowed(("desktop.safe_shortcut",), allowed)
    if not shortcut_tool:
        return None
    if source == "selection":
        return [
            _step(
                intent,
                "copy-selected-dynamic-context",
                "Copy selected context",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "copy"},
                action="copy_selection",
                reason="Copy the selected content before opening the target discovered app.",
            )
        ]
    if source == "current_page_link":
        return [
            _step(
                intent,
                "copy-current-page-link-context",
                "Copy current page link",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "copy_current_page_link"},
                action="copy_current_page_link",
                reason="Copy the current page link before opening the target discovered app.",
            )
        ]
    if source == "current_page_content":
        return [
            _step(
                intent,
                "select-current-page-content",
                "Select current page content",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "select_all"},
                action="shortcut",
                reason="Select the current page content before copying it for transfer.",
            ),
            _step(
                intent,
                "copy-current-page-content",
                "Copy current page content",
                "desktop.ui_operation",
                shortcut_tool,
                input_preview={"action": "copy"},
                depends_on=["select-current-page-content"],
                action="copy_selection",
                reason="Copy the current page content before opening the target discovered app.",
            ),
        ]
    return None


def _append_selected_discovered_generic_action_steps(
    steps: list[ToolPlanStepSnapshot],
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    *,
    depends_on: str,
) -> None:
    if isinstance(intent.inputs.get("model_generated_content_hint"), Mapping):
        return
    if any(
        step.step_id.startswith("operate-foreground-ui-followup")
        or step.step_id
        in {
            "inspect-selected-communication-compose-ui",
            "type-selected-communication-recipient",
            "type-selected-communication-body",
            "submit-foreground-ui",
        }
        for step in steps
    ):
        return
    pending_action = discovered_app_pending_user_action(intent.user_goal)
    if not pending_action or _looks_like_discovered_creative_action(intent, pending_action):
        return

    inputs = intent.inputs if isinstance(intent.inputs, Mapping) else {}
    raw_click_target = inputs.get("click_target_hint")
    raw_type_target = inputs.get("type_into_ui_hint")
    raw_safe_shortcut = inputs.get("safe_shortcut_hint")
    raw_safe_key = inputs.get("safe_key_hint")
    raw_safe_scroll = inputs.get("safe_scroll_hint")
    raw_safe_click = inputs.get("safe_click_hint")
    raw_hotkey = inputs.get("hotkey_hint")

    click_target = (
        dict(raw_click_target)
        if isinstance(raw_click_target, Mapping) and raw_click_target
        else click_target_hint(pending_action)
    )
    type_target = (
        dict(raw_type_target)
        if isinstance(raw_type_target, Mapping) and raw_type_target
        else type_into_ui_hint(pending_action)
    )
    raw_safe_shortcut_payload = (
        raw_safe_shortcut if isinstance(raw_safe_shortcut, Mapping) else {}
    )
    safe_shortcut_action = str(
        raw_safe_shortcut_payload.get("action") or ""
    ).strip()
    safe_type_text = "" if type_target else str(inputs.get("safe_type_text_hint") or "").strip()
    if (
        not safe_type_text
        and not type_target
        and safe_shortcut_action in {"new_document", "new_note", "new_task"}
    ):
        safe_type_text = str(inputs.get("foreground_compose_text_hint") or "").strip()
    if (
        not safe_type_text
        and not type_target
        and safe_shortcut_action not in {"new_document", "new_note", "new_task"}
    ):
        safe_type_text = safe_type_text_hint(pending_action)
    if _looks_like_discovered_app_capability_phrase(safe_type_text):
        safe_type_text = ""
    if _text_hint_is_ui_target_tail(pending_action, safe_type_text, click_target):
        safe_type_text = ""
    safe_shortcut = (
        dict(raw_safe_shortcut)
        if isinstance(raw_safe_shortcut, Mapping) and raw_safe_shortcut
        else safe_shortcut_hint(pending_action)
    )
    safe_key = (
        dict(raw_safe_key)
        if isinstance(raw_safe_key, Mapping) and raw_safe_key
        else None
        if safe_shortcut
        else safe_key_hint(pending_action)
    )
    safe_scroll = (
        dict(raw_safe_scroll)
        if isinstance(raw_safe_scroll, Mapping) and raw_safe_scroll
        else safe_scroll_hint(pending_action)
    )
    safe_click = (
        dict(raw_safe_click)
        if isinstance(raw_safe_click, Mapping) and raw_safe_click
        else safe_click_hint(pending_action)
    )
    hotkey = (
        dict(raw_hotkey)
        if isinstance(raw_hotkey, Mapping) and raw_hotkey
        else None
        if safe_shortcut or safe_key
        else hotkey_hint(pending_action)
    )
    submit_action = submit_action_hint(pending_action)
    followup_return_hotkey = None
    if (type_target or safe_type_text) and not _input_then_submit_hint(pending_action):
        followup_return_hotkey = (
            _explicit_return_key_followup_hint(pending_action)
            or _return_hotkey_followup_hint(pending_action)
        )
    if followup_return_hotkey:
        submit_action = ""
    if safe_shortcut and _selected_discovered_open_step_already_runs_shortcut(
        steps,
        safe_shortcut,
    ):
        safe_shortcut = {}
    previous_step = depends_on
    planned_action = False
    click_already_planned = False

    if (
        click_target
        and (type_target or safe_type_text)
        and _pending_action_click_precedes_type(pending_action)
    ):
        click_tool = _first_allowed(
            (
                "app.focus_and_click_ui_element",
                "app.open_and_click_ui_element",
                "desktop.click_ui_element",
            ),
            allowed,
        )
        if click_tool:
            steps.append(
                _step(
                    intent,
                    "operate-selected-discovered-app-ui",
                    "Operate selected app UI",
                    "desktop.ui_operation",
                    click_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        click_tool,
                        {**click_target, "limit": 80},
                    ),
                    depends_on=[previous_step],
                    action="click",
                    risk_level="medium",
                    approval_required=True,
                    reason=(
                        "Click the requested visible control before typing the follow-up "
                        "text in the runtime-resolved selected app."
                    ),
                )
            )
            previous_step = "operate-selected-discovered-app-ui"
            planned_action = True
            click_already_planned = True

    if safe_shortcut:
        shortcut_tool = _first_allowed(
            (
                "app.focus_and_safe_shortcut",
                "app.open_and_safe_shortcut",
                "desktop.safe_shortcut",
            ),
            allowed,
        )
        if shortcut_tool:
            steps.append(
                _step(
                    intent,
                    "shortcut-selected-discovered-app",
                    "Run selected app shortcut",
                    "desktop.ui_operation",
                    shortcut_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        shortcut_tool,
                        safe_shortcut,
                    ),
                    depends_on=[previous_step],
                    action="shortcut",
                    risk_level=_desktop_operation_risk_level(shortcut_tool),
                    approval_required=_desktop_operation_approval_required(
                        shortcut_tool
                    ),
                    reason=(
                        "After opening and observing the runtime-resolved selected app, execute the "
                        "requested safe foreground shortcut without adding app-specific rules."
                    ),
                )
            )
            previous_step = "shortcut-selected-discovered-app"
            planned_action = True

    if hotkey:
        hotkey_tool = _first_allowed(
            (
                "app.focus_and_hotkey",
                "app.open_and_hotkey",
                "desktop.hotkey",
                "desktop.shortcut",
            ),
            allowed,
        )
        if hotkey_tool:
            steps.append(
                _step(
                    intent,
                    "hotkey-selected-discovered-app",
                    "Run selected app hotkey",
                    "desktop.ui_operation",
                    hotkey_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        hotkey_tool,
                        hotkey,
                    ),
                    depends_on=[previous_step],
                    action="shortcut",
                    risk_level="medium",
                    approval_required=True,
                    reason=(
                        "Use the parsed foreground hotkey against the runtime-resolved selected app "
                        "after discovery and UI observation."
                    ),
                )
            )
            previous_step = "hotkey-selected-discovered-app"
            planned_action = True

    if safe_key:
        key_tool = _first_allowed(
            (
                "app.focus_and_safe_key",
                "app.open_and_safe_key",
                "desktop.safe_key",
            ),
            allowed,
        )
        if key_tool:
            steps.append(
                _step(
                    intent,
                    "key-selected-discovered-app",
                    "Press key in selected app",
                    "desktop.ui_operation",
                    key_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        key_tool,
                        safe_key,
                    ),
                    depends_on=[previous_step],
                    action="key",
                    risk_level=_desktop_operation_risk_level(key_tool),
                    approval_required=_desktop_operation_approval_required(key_tool),
                    reason=(
                        "Press the requested safe key in the runtime-resolved selected app through "
                        "the generic foreground operation path."
                    ),
                )
            )
            previous_step = "key-selected-discovered-app"
            planned_action = True

    if safe_scroll:
        scroll_tool = _first_allowed(
            (
                "app.focus_and_safe_scroll",
                "app.open_and_safe_scroll",
                "desktop.safe_scroll",
            ),
            allowed,
        )
        if scroll_tool:
            steps.append(
                _step(
                    intent,
                    "scroll-selected-discovered-app",
                    "Scroll selected app",
                    "desktop.ui_operation",
                    scroll_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        scroll_tool,
                        safe_scroll,
                    ),
                    depends_on=[previous_step],
                    action="scroll",
                    risk_level=_desktop_operation_risk_level(scroll_tool),
                    approval_required=_desktop_operation_approval_required(scroll_tool),
                    reason=(
                        "Scroll the runtime-resolved selected app after discovery instead of falling "
                        "back to app-specific rules."
                    ),
                )
            )
            previous_step = "scroll-selected-discovered-app"
            planned_action = True

    if type_target:
        type_tool = _first_allowed(
            (
                "app.focus_and_type_into_ui_element",
                "app.open_and_type_into_ui_element",
                "desktop.type_into_ui_element",
            ),
            allowed,
        )
        if type_tool:
            steps.append(
                _step(
                    intent,
                    "type-selected-discovered-app-ui",
                    "Type into selected app UI",
                    "desktop.ui_operation",
                    type_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        type_tool,
                        {**type_target, "limit": 80},
                    ),
                    depends_on=[previous_step],
                    action="type",
                    risk_level="medium",
                    approval_required=True,
                    reason=(
                        "Type the requested text into a visible UI element of the runtime-resolved selected "
                        "app using the generic UI operation path."
                    ),
                )
            )
            previous_step = "type-selected-discovered-app-ui"
            planned_action = True
    elif safe_type_text:
        literal_user_text = _safe_type_text_has_literal_user_provenance(
            intent,
            safe_type_text,
        )
        type_text_tool = _first_allowed(
            (
                "app.focus_and_safe_type_text",
                "app.open_and_safe_type_text",
                "desktop.safe_type_text",
                "desktop.type_text",
            ),
            allowed,
        )
        if type_text_tool:
            steps.append(
                _step(
                    intent,
                    "type-selected-discovered-app-text",
                    "Type text in selected app",
                    "desktop.ui_operation",
                    type_text_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        type_text_tool,
                        {"text": safe_type_text},
                    ),
                    depends_on=[previous_step],
                    action="type",
                    risk_level=_desktop_operation_risk_level(
                        type_text_tool,
                        literal_user_text=literal_user_text,
                    ),
                    approval_required=_desktop_operation_approval_required(
                        type_text_tool,
                        literal_user_text=literal_user_text,
                    ),
                    reason=(
                        "Type explicit user-provided text into the foreground selected app "
                        "through the normal safe typing tool."
                    ),
                )
            )
            previous_step = "type-selected-discovered-app-text"
            planned_action = True

    if safe_click and not type_target:
        click_tool = _first_allowed(
            (
                "app.focus_and_safe_click",
                "app.open_and_safe_click",
                "desktop.safe_click",
                "desktop.click",
            ),
            allowed,
        )
        if click_tool:
            steps.append(
                _step(
                    intent,
                    "click-selected-discovered-app-point",
                    "Click selected app point",
                    "desktop.ui_operation",
                    click_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        click_tool,
                        safe_click,
                    ),
                    depends_on=[previous_step],
                    action="click",
                    risk_level=_desktop_operation_risk_level(click_tool),
                    approval_required=_desktop_operation_approval_required(click_tool),
                    reason=(
                        "Use the requested safe point click after opening the discovered "
                        "app, without relying on an app-specific branch."
                    ),
                )
            )
            previous_step = "click-selected-discovered-app-point"
            planned_action = True

    elif click_target and not click_already_planned:
        click_tool = _first_allowed(
            (
                "app.focus_and_click_ui_element",
                "app.open_and_click_ui_element",
                "desktop.click_ui_element",
            ),
            allowed,
        )
        if click_tool:
            steps.append(
                _step(
                    intent,
                    "operate-selected-discovered-app-ui",
                    "Operate selected app UI",
                    "desktop.ui_operation",
                    click_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        click_tool,
                        {**click_target, "limit": 80},
                    ),
                    depends_on=[previous_step],
                    action="click",
                    risk_level="medium",
                    approval_required=True,
                    reason=(
                        "Click the requested visible control after the app was selected by "
                        "capability discovery, not by an app-specific rule."
                    ),
                )
            )
            previous_step = "operate-selected-discovered-app-ui"
            planned_action = True

    if followup_return_hotkey and planned_action:
        followup_return_tool = _return_followup_tool(followup_return_hotkey, allowed)
        if followup_return_tool:
            steps.append(
                _step(
                    intent,
                    "return-selected-discovered-app-action",
                    "Press Return in selected app",
                    "desktop.ui_operation",
                    followup_return_tool,
                    input_preview=_return_followup_input_preview(
                        followup_return_tool,
                        followup_return_hotkey,
                    ),
                    depends_on=[previous_step],
                    action="shortcut",
                    risk_level="medium",
                    approval_required=True,
                    reason=(
                        "Press Return only after the explicit selected-app foreground input "
                        "sequence is planned."
                    ),
                )
            )
            previous_step = "return-selected-discovered-app-action"
            planned_action = True

    if submit_action and (planned_action or not click_target):
        submit_tool = _first_allowed(("desktop.submit_foreground", "desktop.search_submit"), allowed)
        if submit_tool:
            submit_input = (
                {"action": submit_action}
                if submit_tool == "desktop.submit_foreground"
                else {}
            )
            steps.append(
                _step(
                    intent,
                    "submit-selected-discovered-app-action",
                    "Submit selected app action",
                    "desktop.ui_operation",
                    submit_tool,
                    input_preview=submit_input,
                    depends_on=[previous_step],
                    action="submit",
                    risk_level="medium",
                    approval_required=True,
                    reason=(
                        "Submit or confirm the requested foreground action after the selected "
                        "app operation."
                    ),
                )
            )
            previous_step = "submit-selected-discovered-app-action"
            planned_action = True

    if not planned_action:
        return
    verify_tool = _first_allowed(
        ("desktop.ui_elements", "desktop.read_ui", "screen.capture"),
        allowed,
    )
    if not verify_tool:
        return
    steps.append(
        _step(
            intent,
            "verify-selected-discovered-app-action",
            "Verify selected app action",
            "desktop.visual_verification",
            verify_tool,
            input_preview=(
                {"reason": "verify selected discovered app action"}
                if verify_tool == "screen.capture"
                else _selected_discovered_app_verify_input(
                    intent,
                    verify_tool,
                    {"limit": 80},
                )
                or {"limit": 80}
            ),
            depends_on=[previous_step],
            action=_desktop_discovery_action(verify_tool),
            reason=(
                "Verify the selected discovered app after the generic foreground operation "
                "before reporting completion."
            ),
        )
    )


def _selected_discovered_open_step_already_runs_shortcut(
    steps: list[ToolPlanStepSnapshot],
    safe_shortcut: Mapping[str, str],
) -> bool:
    action = str(safe_shortcut.get("action") or "").strip()
    if not action:
        return False
    for step in steps:
        if step.step_id != "open-selected-discovered-app":
            continue
        if step.tool_name not in {
            "app.open_and_safe_shortcut",
            "app.focus_and_safe_shortcut",
            "desktop.safe_shortcut",
        }:
            continue
        input_preview = step.input_preview if isinstance(step.input_preview, Mapping) else {}
        if str(input_preview.get("action") or "").strip() == action:
            return True
    return False


def _append_selected_discovered_creative_action_steps(
    steps: list[ToolPlanStepSnapshot],
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    *,
    depends_on: str,
) -> None:
    pending_action = discovered_app_pending_user_action(intent.user_goal)
    if not _looks_like_discovered_creative_action(intent, pending_action):
        return
    previous_step = depends_on
    safe_shortcut = (
        intent.inputs.get("safe_shortcut_hint")
        if isinstance(intent.inputs.get("safe_shortcut_hint"), Mapping)
        else {}
    )
    safe_shortcut_action = str((safe_shortcut or {}).get("action") or "").strip()
    compose_text = str(intent.inputs.get("foreground_compose_text_hint") or "").strip()
    creative_canvas = (
        intent.inputs.get("creative_canvas_hint")
        if isinstance(intent.inputs.get("creative_canvas_hint"), Mapping)
        else {}
    )
    if safe_shortcut_action in {"new_document", "new_note", "new_task"}:
        shortcut_tool = _first_allowed(
            (
                "app.focus_and_safe_shortcut",
                "app.open_and_safe_shortcut",
                "desktop.safe_shortcut",
            ),
            allowed,
        )
        if shortcut_tool and not _selected_discovered_open_step_already_runs_shortcut(
            steps,
            dict(safe_shortcut),
        ):
            steps.append(
                _step(
                    intent,
                    "shortcut-selected-discovered-app",
                    "Run selected app shortcut",
                    "desktop.ui_operation",
                    shortcut_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        shortcut_tool,
                        dict(safe_shortcut),
                    ),
                    depends_on=[previous_step],
                    action="shortcut",
                    risk_level="medium",
                    approval_required=True,
                    reason=(
                        "Create the requested document or canvas in the runtime-resolved selected app "
                        "before typing foreground content."
                    ),
                )
            )
            previous_step = "shortcut-selected-discovered-app"
    if compose_text:
        type_text_tool = _first_allowed(
            (
                "app.focus_and_safe_type_text",
                "app.open_and_safe_type_text",
                "desktop.safe_type_text",
                "desktop.type_text",
            ),
            allowed,
        )
        if type_text_tool:
            steps.append(
                _step(
                    intent,
                    "type-selected-discovered-app-text",
                    "Type text in selected app",
                    "desktop.ui_operation",
                    type_text_tool,
                    input_preview=_selected_discovered_app_operation_input(
                        intent,
                        type_text_tool,
                        {"text": compose_text},
                    ),
                    depends_on=[previous_step],
                    action="type",
                    risk_level="medium",
                    approval_required=True,
                    reason=(
                        "Type explicit user-provided content only after the selected app "
                        "has created the requested document or canvas."
                    ),
                )
            )
            previous_step = "type-selected-discovered-app-text"
    if _creative_action_requests_circle(pending_action):
        select_shape_tool = _first_allowed(
            ("app.focus_and_click_ui_element", "desktop.click_ui_element"),
            allowed,
        )
        shape_input = {
            "target": "circle ellipse shape",
            "role_filter": "button",
            "limit": 80,
            "click_count": 1,
        }
        steps.append(
            _step(
                intent,
                "select-discovered-app-circle-tool",
                "Select circle shape tool",
                "desktop.ui_operation",
                select_shape_tool,
                input_preview=_selected_discovered_app_operation_input(
                    intent,
                    select_shape_tool,
                    shape_input,
                ),
                depends_on=[previous_step],
                action="click",
                risk_level="medium",
                approval_required=True,
                reason=(
                    "After observing the runtime-resolved selected drawing app, choose the visible "
                    "circle or ellipse shape control using the app UI rather than a hardcoded app rule."
                ),
            )
        )
        previous_step = "select-discovered-app-circle-tool"

    if _creative_action_requests_save(pending_action):
        save_tool = _first_allowed(
            ("app.focus_and_hotkey", "app.open_and_hotkey", "desktop.hotkey", "desktop.shortcut"),
            allowed,
        )
        steps.append(
            _step(
                intent,
                "save-discovered-app-creative-result",
                "Save creative result",
                "desktop.ui_operation",
                save_tool,
                input_preview=_selected_discovered_app_operation_input(
                    intent,
                    save_tool,
                    {"key": "s", "modifiers": ["command"]},
                ),
                depends_on=[previous_step],
                action="shortcut",
                risk_level="medium",
                approval_required=True,
                reason=(
                    "The user explicitly asked to save the creative result; use the standard "
                    "foreground save shortcut through the normal approval and policy gate."
                ),
            )
        )
        previous_step = "save-discovered-app-creative-result"

    verify_tool = _first_allowed(
        ("desktop.ui_elements", "desktop.read_ui", "screen.capture"),
        allowed,
    )
    if not verify_tool:
        return
    steps.append(
        _step(
            intent,
            "verify-discovered-app-creative-result",
            "Verify creative result",
            "desktop.visual_verification",
            verify_tool,
            input_preview=(
                {"reason": "verify discovered app creative result"}
                if verify_tool == "screen.capture"
                else {"limit": 80}
            ),
            depends_on=[previous_step],
            action=_desktop_discovery_action(verify_tool),
            reason=(
                "Verify the foreground creative result after the planned UI operations before "
                "claiming the drawing task is complete."
            ),
        )
    )


def _looks_like_discovered_creative_action(
    intent: TaskIntentSnapshot,
    pending_action: str,
) -> bool:
    clean_pending_action = str(pending_action or "").strip()
    safe_shortcut = (
        intent.inputs.get("safe_shortcut_hint")
        if isinstance(intent.inputs.get("safe_shortcut_hint"), Mapping)
        else {}
    )
    compose_text = str(intent.inputs.get("foreground_compose_text_hint") or "").strip()
    creative_canvas = (
        intent.inputs.get("creative_canvas_hint")
        if isinstance(intent.inputs.get("creative_canvas_hint"), Mapping)
        else {}
    )
    if not str(pending_action or "").strip() and not safe_shortcut and not compose_text and not creative_canvas:
        return False
    if (
        clean_pending_action
        and not safe_shortcut
        and not compose_text
        and not creative_canvas
        and _looks_like_discovered_app_capability_phrase(clean_pending_action)
    ):
        return False
    text = f"{intent.user_goal} {pending_action}".strip()
    if not text:
        return False
    app_capability = intent.inputs.get("app_capability_hint")
    capability_description = (
        str(app_capability.get("description") or "")
        if isinstance(app_capability, Mapping)
        else ""
    )
    capability_query = (
        str(app_capability.get("query") or "")
        if isinstance(app_capability, Mapping)
        else ""
    )
    safe_shortcut_action = str((safe_shortcut or {}).get("action") or "").strip()
    action_text = clean_pending_action or compose_text or safe_shortcut_action
    creative_app = bool(
        re.search(
            r"(?:画图|绘图|图片|图像|白板|流程图|思维导图|脑图|"
            r"image|drawing|paint|design|whiteboard|diagram|flowchart|mind\s*map)",
            f"{capability_description} {capability_query}",
            flags=re.IGNORECASE,
        )
    )
    creative_action = bool(
        creative_canvas
        or compose_text
        or safe_shortcut_action in {"new_document", "new_note", "new_task"}
        or
        re.search(
            r"(?:画|绘制|设计|draw|paint|sketch|design)",
            action_text,
            flags=re.IGNORECASE,
        )
    )
    return creative_app and creative_action


def _looks_like_discovered_app_capability_phrase(value: str) -> bool:
    return bool(
        re.fullmatch(
            r"(?:一个|一款|一类|某个|某款|some|an?|any)?\s*"
            r"(?:能|可以|可用于|用于|用来|capable\s+of|for)?\s*"
            r".{0,40}?(?:应用(?:程序)?|app|application|软件|工具|程序|编辑器)",
            str(value or "").strip(),
            flags=re.IGNORECASE,
        )
    )


def _creative_action_requests_circle(text: str) -> bool:
    return bool(
        re.search(
            r"(?:圆|圆形|椭圆|circle|ellipse|oval)",
            str(text or ""),
            flags=re.IGNORECASE,
        )
    )


def _creative_action_requests_save(text: str) -> bool:
    return bool(
        re.search(
            r"(?:保存|存到|存储|导出|save|export)",
            str(text or ""),
            flags=re.IGNORECASE,
        )
    )


def _append_selected_discovered_communication_compose_steps(
    steps: list[ToolPlanStepSnapshot],
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    *,
    query: str,
    selected_app_tool: str,
    depends_on: str,
) -> None:
    if selected_app_tool not in {
        "app.open_and_safe_shortcut",
        "app.focus_and_safe_shortcut",
    }:
        return
    if str(query or "").strip().lower() not in {"mail", "messaging"}:
        return
    safe_shortcut = intent.inputs.get("safe_shortcut_hint")
    if str((safe_shortcut or {}).get("action") or "").strip() != "new_message":
        return
    compose_hint = intent.inputs.get("communication_compose_hint")
    if not isinstance(compose_hint, Mapping):
        compose_hint = {}
    selected_app_context = _selected_discovered_app_input_context(intent)
    selected_app = str(selected_app_context.get("app_name") or "").strip()
    selected_app_source = str(selected_app_context.get("selection_source") or "").strip()
    selected_app_operation_context = (
        selected_app_context
        if selected_app_source == "desktop.running_apps"
        else {"app_name": selected_app}
    )
    channel = str(compose_hint.get("channel") or "").strip()
    recipient = str(compose_hint.get("recipient") or "").strip()
    body = str(compose_hint.get("body") or "").strip()
    body_source = str(compose_hint.get("body_source") or "").strip()
    transform = str(compose_hint.get("content_transform_hint") or "").strip()
    send_action = str(compose_hint.get("send_action") or "").strip()
    previous_step = depends_on

    inspect_tool = _first_allowed(("desktop.inspect_app", "desktop.ui_elements"), allowed)
    inspect_input = (
        {
            "app_name": selected_app,
            "open_if_needed": False,
            "focus": True,
            "role_filter": "text",
            "limit": 80,
            **(
                {
                    "selection_source": selected_app_source,
                    "query": str(selected_app_context.get("query") or "").strip(),
                }
                if selected_app_source == "desktop.running_apps"
                else {}
            ),
        }
        if inspect_tool == "desktop.inspect_app"
        else {
            **(
                selected_app_context
                if selected_app_source == "desktop.running_apps"
                else {}
            ),
            "role_filter": "text",
            "limit": 80,
        }
    )
    steps.append(
        _step(
            intent,
            "inspect-selected-communication-compose-ui",
            "Inspect selected communication compose UI",
            "desktop.app_discovery",
            inspect_tool,
            input_preview=inspect_input,
            depends_on=[depends_on],
            action="read_ui",
            reason=(
                "After runtime resolves and opens a capable communication app, inspect "
                "the compose UI before filling recipient or message fields."
            ),
        )
    )
    if inspect_tool:
        previous_step = "inspect-selected-communication-compose-ui"

    if recipient:
        recipient_tool = _first_allowed(
            ("app.focus_and_type_into_ui_element", "desktop.type_into_ui_element"),
            allowed,
        )
        recipient_input = {
            "target": _communication_compose_recipient_target(channel),
            "text": recipient,
            "role_filter": "text",
            "limit": 80,
        }
        if str(recipient_tool or "").startswith("app."):
            recipient_input = {**selected_app_operation_context, **recipient_input}
        if not recipient_tool:
            recipient_tool, recipient_input = _safe_type_text_operation_preview(
                app_name=selected_app,
                mode="focus",
                allowed=allowed,
                payload={"text": recipient},
            )
        steps.append(
            _step(
                intent,
                "fill-selected-communication-recipient",
                "Fill selected communication recipient",
                "communication.compose",
                recipient_tool,
                input_preview=recipient_input,
                risk_level=_desktop_operation_risk_level(recipient_tool),
                approval_required=_desktop_operation_approval_required(recipient_tool),
                depends_on=[previous_step],
                action="type",
                reason=(
                    "Type only the explicit recipient after the compose UI has been observed."
                ),
            )
        )
        if recipient_tool:
            previous_step = "fill-selected-communication-recipient"
        recipient_submit_tool = _app_search_submit_operation_tool(allowed)
        if recipient_submit_tool:
            steps.append(
                _step(
                    intent,
                    "submit-selected-communication-recipient",
                    "Submit selected communication recipient",
                    "communication.compose",
                    recipient_submit_tool,
                    input_preview=_app_search_submit_input_preview(recipient_submit_tool),
                    risk_level=_app_search_submit_risk_level(recipient_submit_tool),
                    approval_required=_app_search_submit_approval_required(recipient_submit_tool),
                    depends_on=[previous_step],
                    action="submit_search",
                    reason=(
                        "Confirm the selected recipient with the dedicated safe submit tool when available; "
                        "otherwise use the foreground submit fallback through the approval gate."
                    ),
                )
            )
            previous_step = "submit-selected-communication-recipient"

    if body or body_source:
        body_tool = _first_allowed(
            ("app.focus_and_type_into_ui_element", "desktop.type_into_ui_element"),
            allowed,
        )
        if body:
            body_input = {
                "target": _communication_compose_body_target(channel),
                "text": body,
                "role_filter": "text",
                "limit": 80,
            }
            if str(body_tool or "").startswith("app."):
                body_input = {**selected_app_operation_context, **body_input}
            if not body_tool:
                body_tool, body_input = _safe_type_text_operation_preview(
                    app_name=selected_app,
                    mode="focus",
                    allowed=allowed,
                    payload={"text": body},
                )
        else:
            body_input = {"body_source": body_source}
            if transform:
                body_input["transform"] = transform
            body_tool, body_input = _safe_type_text_operation_preview(
                app_name=selected_app,
                mode="focus",
                allowed=allowed,
                payload=body_input,
            )
        steps.append(
            _step(
                intent,
                "draft-selected-communication-message",
                "Draft selected communication message",
                "communication.compose",
                body_tool,
                input_preview=body_input,
                risk_level=_desktop_operation_risk_level(body_tool),
                approval_required=_desktop_operation_approval_required(body_tool),
                depends_on=[previous_step],
                action="draft_message",
                reason=(
                    "Draft the generated message body from inspected context into the observed compose UI."
                    if body_source
                    else "Type only the explicit message body into the observed compose UI."
                ),
            )
        )
        if body_tool:
            previous_step = "draft-selected-communication-message"

    if send_action == "send" and (body or body_source):
        steps.append(
            _step(
                intent,
                "send-selected-communication-message",
                "Send selected communication message",
                "communication.compose",
                _first_allowed(("desktop.submit_foreground",), allowed),
                input_preview={"action": "send"},
                risk_level="high",
                approval_required=True,
                depends_on=[previous_step],
                action="send_message",
                reason="Final message sending remains approval-gated after discovery and drafting.",
            )
        )


def _communication_compose_recipient_target(channel: str) -> str:
    return "To" if str(channel or "").strip() == "email" else "recipient"


def _communication_compose_body_target(channel: str) -> str:
    return "message body" if str(channel or "").strip() == "email" else "message"


def _information_capture_context_payload(tool_name: str | None) -> dict[str, Any]:
    if tool_name in {"desktop.ui_elements", "desktop.read_ui"}:
        return {"role_filter": "text", "limit": 80}
    if tool_name == "screen.capture":
        return {"reason": "capture note context"}
    return {}


def _step_action(step_key: str, capability_id: str, tool_name: str | None) -> str:
    if step_key == "discover-desktop-state":
        return "list_apps"
    if step_key == "inspect-app":
        return "inspect_app"
    if step_key == "open-or-focus-app":
        return "focus_app" if tool_name in {"app.focus", "desktop.focus_app"} else "open_app"
    if step_key == "list-app-windows":
        return "list_windows"
    if step_key == "focus-app-window":
        return "focus_window"
    if step_key == "read-foreground-ui":
        return "read_ui"
    if step_key == "capture-screen":
        return "capture_screen"
    if step_key == "manage-app":
        return _app_management_action(tool_name)
    if step_key == "manage-foreground":
        return _foreground_management_action(tool_name)
    if step_key == "verify-desktop-result":
        return "read_ui" if tool_name in {"desktop.ui_elements", "desktop.read_ui"} else "verify"
    if step_key.startswith("operate-foreground-ui"):
        return _desktop_operation_action(tool_name)
    if step_key == "submit-foreground-ui":
        return "submit"
    if step_key == "submit-foreground-search":
        return "submit"
    if step_key == "focus-app-search-field":
        return _desktop_operation_action(tool_name)
    if step_key == "type-app-search-query":
        return "type"
    if step_key == "submit-app-search":
        return "submit"
    if step_key == "open-spotlight-search":
        return "shortcut"
    if step_key == "type-spotlight-search-query":
        return "type"
    if step_key == "submit-browser-context":
        return "submit"
    if step_key in {"open-system-settings", "open-system-settings-fallback"}:
        return "open_settings"
    if step_key == "read-system-settings-ui":
        return "read_ui"
    if capability_id == "desktop.app_discovery":
        return _desktop_discovery_action(tool_name)
    if capability_id == "data.analysis":
        return "analyze_data_file" if tool_name == "data.analyze" else "run_python_analysis"
    if capability_id == "artifact.write":
        return "write_artifact"
    if capability_id in {"file.workspace_read", "file.organization"}:
        return "inspect_paths" if capability_id == "file.organization" else "read_file"
    if capability_id == "file.desktop_access":
        return "reveal_path" if tool_name == "desktop.reveal_path" else "open_path"
    if capability_id == "browser.research":
        if _is_context_source_tool(tool_name):
            return _context_source_action(tool_name)
        if tool_name == "browser.current_page":
            return "read_current_page"
        if tool_name == "browser.screenshot":
            return "screenshot"
        return "extract_text" if tool_name and "extract_text" in tool_name else "open_url"
    if capability_id == "media.playback":
        return "play"
    if capability_id == "system.control":
        if tool_name == "system.settings_open":
            return "open_settings"
        return "control_system"
    if capability_id == "schedule.reminder":
        if _is_context_source_tool(tool_name):
            return _context_source_action(tool_name)
        return "schedule_task"
    if capability_id == "information.capture":
        if tool_name == "artifact.write":
            return "write_artifact"
        return _context_source_action(tool_name)
    if capability_id == "communication.compose":
        if _is_context_source_tool(tool_name):
            return _context_source_action(tool_name)
        if tool_name == "desktop.submit_foreground":
            return "send_message"
        if tool_name == "desktop.search_submit":
            return "submit_search"
        if tool_name in {"app.open_and_safe_shortcut", "app.focus_and_safe_shortcut"}:
            return "resolve_recipient"
        return "draft_message"
    if capability_id == "clipboard.read_write":
        return "read_clipboard" if tool_name == "clipboard.read" else "write_clipboard"
    return ""


def _is_context_source_tool(tool_name: str | None) -> bool:
    clean_tool = str(tool_name or "")
    return clean_tool in {
        "clipboard.read",
        "desktop.safe_shortcut",
        "browser.current_page",
        "browser.extract_text",
        "desktop.ui_elements",
        "desktop.read_ui",
        "screen.capture",
    }


def _context_source_action(tool_name: str | None) -> str:
    clean_tool = str(tool_name or "")
    if clean_tool == "notes.create":
        return "create_note"
    if clean_tool == "clipboard.read":
        return "read_clipboard"
    if clean_tool == "desktop.safe_shortcut":
        return "shortcut"
    if clean_tool == "browser.current_page":
        return "read_current_page"
    if clean_tool.startswith("browser."):
        return "extract_text"
    if clean_tool in {"desktop.ui_elements", "desktop.read_ui"}:
        return "read_ui"
    if clean_tool == "screen.capture":
        return "capture_screen"
    return "capture"


_MEDIA_APP_OPEN_TOOLS = {"app.open", "desktop.open_app"}
_MEDIA_APP_FOCUS_TOOLS = {"app.focus", "desktop.focus_app"}


def _is_media_app_open_tool(tool_name: str | None) -> bool:
    return str(tool_name or "").strip() in _MEDIA_APP_OPEN_TOOLS


def _is_media_app_open_or_focus_tool(tool_name: str | None) -> bool:
    clean_tool = str(tool_name or "").strip()
    return clean_tool in _MEDIA_APP_OPEN_TOOLS or clean_tool in _MEDIA_APP_FOCUS_TOOLS


def _media_app_open_focus_action(tool_name: str | None) -> str:
    clean_tool = str(tool_name or "").strip()
    if clean_tool == "desktop.open_app":
        return "open_app"
    if clean_tool == "desktop.focus_app":
        return "focus_app"
    if clean_tool == "app.focus":
        return "focus"
    return "open"


def _media_shortcut_input_submits(input_preview: Mapping[str, Any] | None) -> bool:
    if not isinstance(input_preview, Mapping):
        return False
    action = str(input_preview.get("action") or "").strip().lower()
    key = str(input_preview.get("key") or "").strip().lower()
    return action in {"confirm", "submit", "search"} or key in {"return", "enter"}


def _desktop_operation_action(tool_name: str | None) -> str:
    clean_tool = str(tool_name or "")
    if "click" in clean_tool:
        return "click"
    if "type" in clean_tool:
        return "type"
    if "shortcut" in clean_tool or "hotkey" in clean_tool:
        return "shortcut"
    if "scroll" in clean_tool:
        return "scroll"
    if "key" in clean_tool:
        return "key"
    return "operate_ui"


def _safe_type_text_has_literal_user_provenance(
    intent: TaskIntentSnapshot,
    text: str,
) -> bool:
    literal_text = str(text or "").strip()
    if not literal_text:
        return False
    if isinstance(intent.inputs.get("model_generated_content_hint"), Mapping):
        return False
    if isinstance(intent.inputs.get("foreground_paste_hint"), Mapping):
        return False
    routed_texts = {
        str(intent.inputs.get("safe_type_text_hint") or "").strip(),
        str(intent.inputs.get("foreground_compose_text_hint") or "").strip(),
    }
    if literal_text not in routed_texts:
        return False
    return _foreground_text_has_explicit_literal_provenance(
        intent.user_goal,
        literal_text,
    )


def _desktop_operation_risk_level(
    tool_name: str | None,
    *,
    literal_user_text: bool = False,
) -> str:
    clean_tool = str(tool_name or "")
    if "safe_type_text" in clean_tool:
        return "low" if literal_user_text else "medium"
    if (
        "safe_shortcut" in clean_tool
        or "safe_key" in clean_tool
        or "safe_scroll" in clean_tool
        or "safe_click" in clean_tool
    ):
        return "low"
    return "medium"


def _desktop_operation_approval_required(
    tool_name: str | None,
    *,
    literal_user_text: bool = False,
) -> bool:
    return (
        _desktop_operation_risk_level(
            tool_name,
            literal_user_text=literal_user_text,
        )
        != "low"
    )


def _app_scoped_operation_should_inspect(
    tool_name: str | None,
    *,
    screen_capture: Mapping[str, Any] | None,
    ui_inspection: Mapping[str, Any] | None,
) -> bool:
    clean_tool = str(tool_name or "").strip()
    if clean_tool in {
        "app.focus_and_safe_shortcut",
        "app.open_and_safe_shortcut",
    }:
        return screen_capture is not None or ui_inspection is not None
    if clean_tool.startswith(("app.focus_and_", "app.open_and_")):
        return True
    return screen_capture is not None or ui_inspection is not None


def _desktop_plan_has_prepared_foreground_app(
    steps: Iterable[ToolPlanStepSnapshot],
) -> bool:
    for step in steps:
        tool_name = str(step.tool_name or "").strip()
        preview = step.input_preview if isinstance(step.input_preview, Mapping) else {}
        if tool_name == "desktop.inspect_app" and (
            bool(preview.get("open_if_needed")) or bool(preview.get("focus"))
        ):
            return True
        if step.step_id in {
            "open-or-focus-app",
            "focus-opened-app",
            "focus-app-window",
            "open-selected-discovered-app",
        } and (
            tool_name in {
                "app.open",
                "desktop.open_app",
                "app.focus",
                "desktop.focus_app",
            }
            or tool_name.startswith(("app.open_and_", "app.focus_and_"))
        ):
            return True
    return False


def _desktop_operation_after_prepared_preflight(
    tool_name: str | None,
    input_preview: Mapping[str, Any] | None,
    *,
    allowed: set[str] | None,
) -> tuple[str | None, dict[str, Any]]:
    """Revalidate the prepared app identity immediately before acting.

    A preflight observation is not an authorization to later mutate whichever
    app happens to be frontmost. Approval and model latency can create a gap in
    which the foreground app changes, so keep an app-scoped composite and only
    narrow ``open`` to ``focus`` after the preflight has opened the target.
    """

    clean_tool = str(tool_name or "").strip()
    if clean_tool.startswith("app.focus_and_"):
        return tool_name, dict(input_preview or {})
    if not clean_tool.startswith("app.open_and_"):
        return tool_name, dict(input_preview or {})
    if (
        clean_tool == "app.open_and_type_into_ui_element"
        and _first_allowed(("desktop.verify",), allowed)
    ):
        # Keep the app-scoped action on the receipt-producing path.  The
        # focus-only variant cannot mint the private, agent-owned-window
        # exact-content receipt consumed by desktop.verify.
        return tool_name, dict(input_preview or {})
    focus_tool = clean_tool.replace("app.open_and_", "app.focus_and_", 1)
    resolved_tool = _first_allowed((focus_tool,), allowed)
    if not resolved_tool:
        return tool_name, dict(input_preview or {})
    return resolved_tool, dict(input_preview or {})


def _inspect_app_can_remain_readonly_before_operation(
    tool_name: str | None,
    operation_preview: Mapping[str, Any] | None,
) -> bool:
    clean_tool = str(tool_name or "").strip()
    if clean_tool not in {"app.open_and_safe_shortcut", "app.focus_and_safe_shortcut"}:
        return False
    preview = operation_preview if isinstance(operation_preview, Mapping) else {}
    action = str(preview.get("action") or "").strip()
    return action in {"new_document", "new_note", "new_task"}


def _app_management_action(tool_name: str | None) -> str:
    clean_tool = str(tool_name or "")
    if clean_tool == "app.show":
        return "show_app"
    if clean_tool == "app.status":
        return "status_app"
    if clean_tool == "app.hide":
        return "hide_app"
    if clean_tool == "app.minimize":
        return "minimize_app"
    if clean_tool == "app.quit":
        return "quit_app"
    return "manage_app"


def _foreground_management_action(tool_name: str | None) -> str:
    clean_tool = str(tool_name or "")
    if clean_tool == "desktop.hide_app":
        return "hide_app"
    if clean_tool == "desktop.show_all_apps":
        return "show_all_apps"
    if clean_tool == "desktop.minimize_window":
        return "minimize_window"
    if clean_tool == "desktop.close_window":
        return "close_window"
    if clean_tool == "desktop.quit_app":
        return "quit_app"
    return "manage_foreground"


def _desktop_verify_tool_candidates(
    depends_on: list[str],
    *,
    source_tools: list[str | None] | None = None,
) -> tuple[str, ...]:
    if any(
        str(tool_name or "").strip()
        in {
            "app.open_and_type_into_ui_element",
            "desktop.type_into_ui_element",
        }
        for tool_name in source_tools or []
    ):
        return (
            "desktop.verify",
            "desktop.ui_elements",
            "desktop.read_ui",
            "desktop.windows",
            "desktop.active_window",
            "screen.capture",
        )
    if _desktop_verify_depends_on_ui_operation(depends_on):
        return (
            "desktop.ui_elements",
            "desktop.verify",
            "desktop.windows",
            "desktop.active_window",
            "screen.capture",
        )
    return (
        "desktop.verify",
        "desktop.active_window",
        "desktop.windows",
        "desktop.ui_elements",
        "screen.capture",
    )


def _desktop_verify_reason(depends_on: list[str]) -> str:
    if _desktop_verify_depends_on_ui_operation(depends_on):
        return "Read foreground UI or windows after the UI action to verify the visible result."
    return "Observe the foreground state after desktop execution."


def _desktop_verify_depends_on_ui_operation(depends_on: list[str]) -> bool:
    return any(
        step_id.startswith("operate-foreground-ui") or step_id == "submit-foreground-ui"
        for step_id in depends_on
    )


def _preflight_ui_observation_input_preview(
    operation_preview: Mapping[str, Any],
    *,
    app_name: str,
) -> dict[str, Any]:
    preview = {
        key: operation_preview[key]
        for key in ("role_filter", "limit", "selection_source", "query")
        if key in operation_preview and operation_preview[key] not in (None, "")
    }
    if app_name:
        preview["app_name"] = app_name
    preview.setdefault("limit", 80)
    return preview


def _desktop_verify_input_preview(
    tool_name: str | None,
    *,
    app_name: str,
    operation_preview: Mapping[str, Any],
) -> dict[str, Any]:
    if tool_name in {"desktop.windows", "desktop.list_windows", "desktop.verify"}:
        return {"app_name": app_name} if app_name else {}
    if tool_name not in {"desktop.ui_elements", "desktop.read_ui"}:
        return {}
    preview = {
        key: operation_preview[key]
        for key in ("role_filter", "limit")
        if key in operation_preview and operation_preview[key] not in (None, "")
    }
    if app_name:
        preview["app_name"] = app_name
    return preview


def _desktop_inspect_app_input_preview(
    app_name: str,
    ui_payload: Mapping[str, Any],
    *,
    open_if_needed: bool,
    focus: bool,
) -> dict[str, Any]:
    preview: dict[str, Any] = {
        "app_name": app_name,
        "open_if_needed": open_if_needed,
        "focus": focus,
    }
    for key in ("role_filter", "limit"):
        if key in ui_payload and ui_payload[key] not in (None, ""):
            preview[key] = ui_payload[key]
    return preview


def _media_playback_verify_step(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    *,
    control_tool_name: str | None = None,
) -> ToolPlanStepSnapshot | None:
    action = str(intent.inputs.get("action") or "").strip() or "play"
    if action == "status" or str(control_tool_name or "").strip().startswith("media."):
        return None
    tool_name = _first_allowed(
        ("desktop.ui_elements", "desktop.active_window", "screen.capture"),
        allowed,
    )
    if not tool_name:
        return None
    return _step(
        intent,
        "verify-media-playback",
        "Verify media playback",
        "desktop.app_discovery",
        tool_name,
        input_preview=_media_playback_verify_input_preview(tool_name),
        depends_on=["control-media-playback"],
        action=_desktop_discovery_action(tool_name),
        reason="Observe the media app after changing playback state.",
    )


def _media_playback_verify_input_preview(
    tool_name: str | None,
) -> dict[str, Any]:
    if tool_name in {"desktop.ui_elements", "desktop.read_ui"}:
        return {"role_filter": "", "limit": 80}
    if tool_name == "screen.capture":
        return {"reason": "verify media playback"}
    return {}


def _system_control_verify_step(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    tool_name: str | None,
) -> ToolPlanStepSnapshot | None:
    if tool_name != "system.volume":
        return None
    payload = intent.inputs.get("payload") if isinstance(intent.inputs, Mapping) else {}
    payload = payload if isinstance(payload, Mapping) else {}
    action = str(payload.get("action") or "").strip()
    if action == "status":
        return None
    verify_tool = _first_allowed(("system.volume",), allowed)
    if verify_tool != "system.volume":
        return None
    return _step(
        intent,
        "verify-system-state",
        "Verify system state",
        "system.control",
        verify_tool,
        input_preview={"action": "status"},
        depends_on=["control-system-state"],
        action="verify",
        reason="Read the system volume after changing it so the agent can confirm the requested state.",
    )


def _service_action(capability_id: str, intent: TaskIntentSnapshot | None = None) -> str:
    if capability_id == "workflow.orchestration":
        action_hint = str(
            ((intent.inputs if intent is not None else {}) or {}).get("workflow_action_hint")
            or ""
        ).strip()
        if action_hint == "create":
            return "create_workflow"
        if action_hint == "debug":
            return "debug_workflow"
        return "start_workflow"
    if capability_id == "group.multi_agent":
        return "start_group_run"
    return ""


def _service_tool_candidates(
    capability_id: str,
    intent: TaskIntentSnapshot | None = None,
) -> tuple[str, ...]:
    if capability_id == "workflow.orchestration":
        action_hint = str(
            ((intent.inputs if intent is not None else {}) or {}).get("workflow_action_hint")
            or ""
        ).strip()
        if action_hint == "create":
            return ("workflow.create", "workflow.start", "workflow.run", "workflow.list")
        if action_hint == "debug":
            return ("workflow.debug", "workflow.start", "workflow.run", "workflow.list")
        return ("workflow.start", "workflow.run", "workflow.list")
    if capability_id == "group.multi_agent":
        return ("group.start", "group.run", "agent.group_run", "group.list")
    return ()


def _desktop_discovery_action(tool_name: str | None) -> str:
    clean_tool = str(tool_name or "")
    if clean_tool == "desktop.permissions":
        return "diagnose_permissions"
    if clean_tool == "desktop.active_window":
        return "read_active_window"
    if clean_tool == "desktop.running_apps":
        return "read_running_apps"
    if clean_tool == "desktop.list_apps":
        return "list_apps"
    if clean_tool == "desktop.open_app":
        return "open_app"
    if clean_tool == "desktop.focus_app":
        return "focus_app"
    if clean_tool == "desktop.inspect_app":
        return "inspect_app"
    if clean_tool in {"desktop.windows", "desktop.list_windows"}:
        return "list_windows"
    if clean_tool in {"desktop.ui_elements", "desktop.read_ui"}:
        return "read_ui"
    if clean_tool == "desktop.verify":
        return "verify"
    if clean_tool == "screen.capture":
        return "capture_screen"
    return "discover"


def _allowed_tool_set(allowed_tools: Iterable[str] | None) -> set[str] | None:
    if allowed_tools is None:
        return None
    return {str(tool or "").strip() for tool in allowed_tools if str(tool or "").strip()}


def _planner_prefers_background_desktop(
    metadata: Mapping[str, Any] | None,
) -> bool:
    if not isinstance(metadata, Mapping):
        return False
    value = metadata.get("prefer_background_desktop")
    if value is True or str(value or "").strip().lower() in {
        "1",
        "true",
        "yes",
        "on",
    }:
        return True
    for key in (
        "desktop_execution_policy",
        "yachiyo_desktop_execution_policy",
        "desktop_interaction_policy",
    ):
        nested = metadata.get(key)
        if (
            nested is not metadata
            and isinstance(nested, Mapping)
            and _planner_prefers_background_desktop(nested)
        ):
            return True
    return False


def _planner_readiness_context(
    metadata: Mapping[str, Any] | None,
) -> dict[str, dict[str, list[str]]]:
    if not isinstance(metadata, Mapping):
        return {}
    missing = _merge_issue_maps(
        _metadata_issue_map(
            metadata,
            "desktop_missing_permissions_by_capability",
            "desktop_missing_permissions",
        ),
        _capability_snapshot_issues(metadata, "missing_permissions"),
        _flat_issue_tokens_by_capability(
            metadata.get("missing_permissions"),
            issue_kind="missing",
        ),
    )
    blocking = _merge_issue_maps(
        _metadata_issue_map(
            metadata,
            "desktop_blocking_conditions_by_capability",
            "desktop_runtime_blocking_conditions_by_capability",
            "desktop_runtime_blocking_conditions",
            "desktop_blocking_conditions",
        ),
        _capability_snapshot_issues(metadata, "blocking_conditions"),
        _flat_issue_tokens_by_capability(
            metadata.get("blocking_conditions"),
            issue_kind="blocking",
        ),
    )
    context: dict[str, dict[str, list[str]]] = {}
    if missing:
        context["missing_permissions"] = missing
    if blocking:
        context["blocking_conditions"] = blocking
    return context


_TOOL_READINESS_METADATA_KEYS = (
    "tool_readiness_by_tool",
    "runtime_tool_readiness_by_tool",
    "provider_tool_readiness",
    "desktop_tool_readiness_by_tool",
)

_TOOL_READINESS_NESTED_METADATA_KEYS = (
    "metadata",
    "readiness",
    "provider_readiness",
    "desktop_execution_policy",
    "yachiyo_desktop_execution_policy",
    "desktop_interaction_policy",
)


def _planner_tool_readiness_context(
    metadata: Mapping[str, Any] | None,
    *,
    allowed: set[str] | None,
    capability_readiness: Mapping[str, Mapping[str, Iterable[str]]],
) -> dict[str, dict[str, Any]]:
    """Build conservative per-tool facts for deterministic route selection.

    Capability-level permission failures remain useful as hard blockers, while
    unchecked/unknown provider health is accepted only as explicit per-tool
    status and never promoted to a failure here.
    """

    facts_by_tool: dict[str, dict[str, Any]] = {}
    candidate_tools = set(allowed or ())
    if allowed is None:
        candidate_tools.update(
            tool_name
            for tools in DESKTOP_CAPABILITY_TOOLS.values()
            for tool_name in tools
        )
    for tool_name in candidate_tools:
        capability_id = _desktop_policy_capability_id_for_tool(tool_name)
        if not capability_id:
            continue
        missing = desktop_tool_missing_permissions(
            tool_name,
            capability_id=capability_id,
            missing_permissions=capability_readiness.get("missing_permissions") or {},
        )
        blocking = desktop_tool_blocking_conditions(
            tool_name,
            capability_id=capability_id,
            blocking_conditions=capability_readiness.get("blocking_conditions") or {},
        )
        blockers = _unique_capabilities((*missing, *blocking))
        if blockers:
            facts_by_tool[tool_name] = {
                "status": "blocked",
                "blocked": True,
                "blockers": blockers,
            }

    explicit = _explicit_tool_readiness_metadata(metadata)
    for tool_name, facts in explicit.items():
        facts_by_tool[tool_name] = {
            **facts_by_tool.get(tool_name, {}),
            **facts,
        }
    return facts_by_tool


def _explicit_tool_readiness_metadata(
    metadata: Mapping[str, Any] | None,
) -> dict[str, dict[str, Any]]:
    if not isinstance(metadata, Mapping):
        return {}
    seen: set[int] = set()

    def collect(source: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
        source_id = id(source)
        if source_id in seen:
            return {}
        seen.add(source_id)
        collected: dict[str, dict[str, Any]] = {}
        for key in _TOOL_READINESS_NESTED_METADATA_KEYS:
            nested = source.get(key)
            if not isinstance(nested, Mapping):
                continue
            for tool_name, facts in collect(nested).items():
                collected[tool_name] = {**collected.get(tool_name, {}), **facts}
        for key in _TOOL_READINESS_METADATA_KEYS:
            payload = source.get(key)
            if not isinstance(payload, Mapping):
                continue
            for raw_tool_name, raw_facts in payload.items():
                tool_name = str(raw_tool_name or "").strip()
                if not tool_name:
                    continue
                facts = _normalise_planner_tool_readiness_facts(raw_facts)
                if facts:
                    collected[tool_name] = {
                        **collected.get(tool_name, {}),
                        **facts,
                    }
        return collected

    return collect(metadata)


def _normalise_planner_tool_readiness_facts(value: Any) -> dict[str, Any]:
    if isinstance(value, str):
        return {"status": value.strip()} if value.strip() else {}
    if not isinstance(value, Mapping):
        return {}
    facts = dict(value)
    for nested_key in ("route", "provider", "adapter"):
        nested = facts.get(nested_key)
        if isinstance(nested, Mapping):
            facts = {**dict(nested), **facts}
    health = facts.get("health")
    if isinstance(health, Mapping):
        if not str(facts.get("status") or "").strip():
            facts["status"] = health.get("status")
        if health.get("checked") is True:
            facts.setdefault("health_checked", True)
            if isinstance(health.get("ok"), bool):
                facts.setdefault("health_ok", health.get("ok"))
        # ``ok=false`` before a probe is not evidence of failure.
        elif str(health.get("status") or "").strip() in {
            "",
            "not_checked",
            "unknown",
            "installed_not_checked",
        }:
            facts.pop("health_ok", None)
    return {
        str(key): item
        for key, item in facts.items()
        if key not in {"route", "provider", "adapter", "health"}
        and item is not None
    }


def _select_best_runtime_step_tools(
    steps: list[ToolPlanStepSnapshot],
    *,
    allowed: set[str] | None,
    readiness_by_tool: Mapping[str, Mapping[str, Any]],
    prefer_background: bool,
    use_selected_candidate_policy: bool = False,
) -> list[ToolPlanStepSnapshot]:
    """Select one trusted route per semantic step without exposing reasoning."""

    from apps.shell.agent.runtime.tool_candidate_selection import (
        select_tool_candidate,
    )
    from apps.shell.agent.runtime.tool_capabilities import (
        action_ids_for_tool,
        registered_tool_names_for_capability,
    )

    updated: list[ToolPlanStepSnapshot] = []
    for step in steps:
        primary = str(step.tool_name or "").strip()
        original_fallbacks = _unique_capabilities(step.fallback_tools)
        candidates = _unique_capabilities((primary, *original_fallbacks))
        dynamic_candidates: set[str] = set()
        if step.capability_id and step.action:
            for tool_name in registered_tool_names_for_capability(step.capability_id):
                if (
                    step.action in action_ids_for_tool(tool_name)
                    and _dynamic_tool_accepts_step_input(tool_name, step.input_preview)
                    and tool_name not in candidates
                ):
                    candidates.append(tool_name)
                    dynamic_candidates.add(tool_name)
        if not candidates:
            updated.append(step)
            continue
        if not dynamic_candidates and not any(
            candidate in readiness_by_tool for candidate in candidates
        ):
            updated.append(step)
            continue

        allowed_candidates: Iterable[str] = (
            allowed if allowed is not None else candidates
        )
        selection = select_tool_candidate(
            candidates,
            allowed_candidates,
            required_capability=step.capability_id or None,
            # A dynamically registered adapter entered this candidate set only
            # through an exact capability/action binding and schema check. Pass
            # that action through so the explicit adapter outranks a generic
            # built-in fallback without applying action validation to legacy-
            # only steps whose historical action vocabulary is broader.
            required_action=step.action if dynamic_candidates else None,
            readiness_by_tool=readiness_by_tool,
            prefer_background=prefer_background,
        )
        eligible = {
            candidate.tool_name: candidate
            for candidate in selection.ranked_candidates
        }
        ranking_signal = any(
            candidate.readiness_class in {"ready", "blocked"}
            for candidate in selection.ranked_candidates
        )
        if not ranking_signal and not dynamic_candidates:
            # The selector is an incremental route chooser, not a migration of
            # every historical planner semantic.  With no route evidence and
            # no explicitly bound adapter to add, preserve the complete step
            # byte-for-byte (including specialised approval and fallback
            # policy) so legacy intent templates retain their contract.
            updated.append(step)
            continue
        selected_tool = (
            primary
            if not ranking_signal and not dynamic_candidates and primary in eligible
            else selection.selected_tool
        )
        if not selected_tool:
            updated.append(
                step.model_copy(
                    update={
                        "tool_name": None,
                        "execution_mode": None,
                        "status": "unavailable",
                        "fallback_tools": [],
                    }
                )
            )
            continue

        selected_candidate = eligible[selected_tool]
        ranked_fallbacks = (
            [candidate.tool_name for candidate in selection.ranked_candidates]
            if ranking_signal
            else [candidate for candidate in candidates if candidate in eligible]
        )
        fallback_tools = [
            candidate
            for candidate in ranked_fallbacks
            if candidate != selected_tool
        ]
        # Preserve explicitly declared cross-capability recovery routes only
        # when they still satisfy the Runtime's schema/dispatch trust boundary.
        generic_fallback_selection = select_tool_candidate(
            original_fallbacks,
            allowed_candidates,
        )
        trusted_fallbacks = {
            candidate.tool_name
            for candidate in generic_fallback_selection.ranked_candidates
        }
        for candidate in original_fallbacks:
            if (
                candidate != selected_tool
                and candidate in trusted_fallbacks
                and candidate not in fallback_tools
            ):
                fallback_tools.append(candidate)

        status = str(step.status or "planned")
        if status != "skipped":
            status = "unavailable" if selected_candidate.blocked else "planned"
        updated.append(
            step.model_copy(
                update={
                    "tool_name": selected_tool,
                    "fallback_tools": fallback_tools,
                    "execution_mode": desktop_tool_execution_mode_for_input(
                        selected_tool,
                        step.input_preview,
                    ),
                    "risk_level": (
                        selected_candidate.risk_level
                        if use_selected_candidate_policy
                        else (
                            _higher_runtime_risk_level(
                                str(step.risk_level or "low"),
                                selected_candidate.risk_level,
                            )
                            if selected_tool in dynamic_candidates
                            else step.risk_level
                        )
                    ),
                    "approval_required": (
                        selected_candidate.approval_required
                        if use_selected_candidate_policy
                        else bool(
                            step.approval_required
                            or (
                                selected_tool in dynamic_candidates
                                and selected_candidate.approval_required
                            )
                        )
                    ),
                    "status": status,
                }
            )
        )
    return updated


def _dynamic_tool_accepts_step_input(
    tool_name: str,
    input_preview: Mapping[str, Any] | None,
) -> bool:
    from apps.shell.agent.tools.policy import TOOL_DESCRIPTORS

    descriptor = TOOL_DESCRIPTORS.get(str(tool_name or "").strip())
    if descriptor is None or not callable(getattr(descriptor, "validate_payload", None)):
        return False
    try:
        descriptor.validate_payload(dict(input_preview or {}))
    except Exception:
        return False
    return True


def _higher_runtime_risk_level(current: str, candidate: str) -> str:
    order = {"none": 0, "low": 1, "medium": 2, "high": 3, "critical": 4}
    current_level = str(current or "low").strip().lower()
    candidate_level = str(candidate or "low").strip().lower()
    return (
        candidate_level
        if order.get(candidate_level, 2) > order.get(current_level, 2)
        else current_level
    )


def _apply_readiness_to_steps(
    steps: list[ToolPlanStepSnapshot],
    readiness: Mapping[str, Mapping[str, Iterable[str]]],
) -> list[ToolPlanStepSnapshot]:
    updated: list[ToolPlanStepSnapshot] = []
    for step in steps:
        issues = _step_readiness_issues(step, readiness)
        if not issues["missing_permissions"] and not issues["blocking_conditions"]:
            updated.append(step)
            continue
        input_preview = dict(step.input_preview or {})
        if issues["missing_permissions"]:
            input_preview["missing_permissions"] = issues["missing_permissions"]
        if issues["blocking_conditions"]:
            input_preview["blocking_conditions"] = issues["blocking_conditions"]
        reason_suffix = _readiness_reason_suffix(issues)
        updated.append(
            step.model_copy(
                update={
                    "input_preview": input_preview,
                    "reason": f"{step.reason} {reason_suffix}".strip(),
                    "status": "unavailable",
                }
            )
        )
    return updated


def _step_readiness_issues(
    step: ToolPlanStepSnapshot,
    readiness: Mapping[str, Mapping[str, Iterable[str]]],
) -> dict[str, list[str]]:
    tool_name = str(step.tool_name or "").strip()
    if not tool_name:
        return {"missing_permissions": [], "blocking_conditions": []}
    policy_capability_id = _desktop_policy_capability_id_for_tool(tool_name)
    if not policy_capability_id:
        return {"missing_permissions": [], "blocking_conditions": []}
    missing_by_capability = readiness.get("missing_permissions") or {}
    blocking_by_capability = readiness.get("blocking_conditions") or {}
    return {
        "missing_permissions": desktop_tool_missing_permissions(
            tool_name,
            capability_id=policy_capability_id,
            missing_permissions=missing_by_capability,
        ),
        "blocking_conditions": desktop_tool_blocking_conditions(
            tool_name,
            capability_id=policy_capability_id,
            blocking_conditions=blocking_by_capability,
        ),
    }


def _desktop_policy_capability_id_for_tool(tool_name: str) -> str:
    clean_tool = str(tool_name or "").strip()
    if not clean_tool:
        return ""
    for capability_id, tools in DESKTOP_CAPABILITY_TOOLS.items():
        if capability_id == "desktop_execution":
            continue
        if clean_tool in tools:
            return capability_id
    return (
        "desktop_execution"
        if clean_tool in DESKTOP_CAPABILITY_TOOLS["desktop_execution"]
        else ""
    )


def _readiness_reason_suffix(issues: Mapping[str, Iterable[str]]) -> str:
    missing = _issue_tokens(issues.get("missing_permissions"))
    blocking = _issue_tokens(issues.get("blocking_conditions"))
    parts = []
    if missing:
        parts.append(f"missing permissions: {', '.join(missing)}")
    if blocking:
        parts.append(f"runtime blockers: {', '.join(blocking)}")
    if not parts:
        return ""
    return f"Current desktop readiness marks this step unavailable ({'; '.join(parts)})."


def _metadata_issue_map(metadata: Mapping[str, Any], *keys: str) -> dict[str, list[str]]:
    for key in keys:
        payload = metadata.get(key)
        if isinstance(payload, Mapping):
            return _clean_issue_map(payload)
    return {}


def _capability_snapshot_issues(
    metadata: Mapping[str, Any],
    issue_field: str,
) -> dict[str, list[str]]:
    issue_map: dict[str, list[str]] = {}
    capability_sources = []
    for key in ("desktop_capabilities", "desktop_execution_capabilities", "capabilities"):
        payload = metadata.get(key)
        if isinstance(payload, Mapping):
            capability_sources.append(payload)
    readiness = metadata.get("readiness")
    if isinstance(readiness, Mapping) and isinstance(readiness.get("capabilities"), Mapping):
        capability_sources.append(readiness["capabilities"])
    for capabilities in capability_sources:
        for capability_id, capability in capabilities.items():
            if not isinstance(capability, Mapping):
                continue
            tokens = _issue_tokens(capability.get(issue_field))
            if tokens:
                issue_map[str(capability_id or "").strip()] = tokens
    return _clean_issue_map(issue_map)


def _flat_issue_tokens_by_capability(value: Any, *, issue_kind: str) -> dict[str, list[str]]:
    result: dict[str, list[str]] = {}
    for token in _issue_tokens(value):
        capability_id = _capability_id_for_flat_issue_token(token, issue_kind=issue_kind)
        if not capability_id:
            continue
        result.setdefault(capability_id, [])
        if token not in result[capability_id]:
            result[capability_id].append(token)
    return result


def _capability_id_for_flat_issue_token(token: str, *, issue_kind: str) -> str:
    clean = str(token or "").strip()
    if issue_kind == "blocking":
        if clean == "foreground_focus_unavailable":
            return "foreground_activation"
        if clean == "desktop_session_locked":
            return "desktop_execution"
    return {
        "accessibility": "foreground_input",
        "automation": "app_control",
        "automation_or_accessibility": "active_window",
        "chrome_cdp": "browser_control",
        "foreground_focus": "foreground_activation",
        "music_app": "media_control",
        "open_command": "app_control",
        "screen_capture_probe_failed": "screen_capture",
        "screen_recording": "screen_capture",
        "unsupported_platform": "desktop_execution",
    }.get(clean, "")


def _merge_issue_maps(*maps: Mapping[str, Iterable[str]]) -> dict[str, list[str]]:
    merged: dict[str, list[str]] = {}
    for issue_map in maps:
        for capability_id, raw_tokens in issue_map.items():
            clean_capability_id = str(capability_id or "").strip()
            if not clean_capability_id:
                continue
            for token in _issue_tokens(raw_tokens):
                values = merged.setdefault(clean_capability_id, [])
                if token not in values:
                    values.append(token)
    return merged


def _clean_issue_map(value: Mapping[str, Any]) -> dict[str, list[str]]:
    return _merge_issue_maps(
        {
            str(capability_id or "").strip(): _issue_tokens(tokens)
            for capability_id, tokens in value.items()
        }
    )


def _issue_tokens(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        raw_values = re.split(r"[,\s]+", value)
    elif isinstance(value, Iterable) and not isinstance(value, (bytes, bytearray, Mapping)):
        raw_values = []
        for item in value:
            raw_values.extend(_issue_tokens(item))
    else:
        raw_values = [str(value)]
    tokens: list[str] = []
    for item in raw_values:
        clean = str(item or "").strip()
        if clean and clean not in tokens:
            tokens.append(clean)
    return tokens


def _normalize_intent_for_allowed_tools(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
) -> TaskIntentSnapshot:
    if intent.kind == "desktop_operation":
        intent = _normalize_desktop_create_intent_inputs(intent)
    if allowed is None or intent.kind != "web_research":
        return intent
    browser_action = str(intent.inputs.get("browser_action") or "").strip()
    readable_after_open = bool(
        allowed & {"browser.extract_text", "browser.current_page", "browser.extract"}
    )
    if (
        browser_action == "open_url_extract"
        and "browser.open_url_and_extract_text" not in allowed
        and (
            "browser.open_url" in allowed
            or "browser.search" in allowed
            or "browser.open" in allowed
        )
    ):
        inputs = dict(intent.inputs)
        if readable_after_open:
            inputs["post_open_action"] = "extract_text"
        if inputs.get("query") and ("browser.open_url" in allowed or "browser.search" in allowed):
            inputs["browser_action"] = "open_search"
        else:
            inputs["browser_action"] = "open_url"
        return intent.model_copy(update={"inputs": inputs})
    return intent


def _normalize_desktop_create_intent_inputs(
    intent: TaskIntentSnapshot,
) -> TaskIntentSnapshot:
    safe_shortcut = intent.inputs.get("safe_shortcut_hint")
    if not isinstance(safe_shortcut, Mapping):
        return intent
    if str((safe_shortcut or {}).get("action") or "").strip() not in {
        "new_document",
        "new_note",
        "new_task",
    }:
        return intent
    if not isinstance(intent.inputs.get("app_capability_hint"), Mapping):
        return intent
    if not isinstance(intent.inputs.get("app_search_hint"), Mapping):
        return intent
    inputs = dict(intent.inputs)
    inputs.pop("app_search_hint", None)
    return intent.model_copy(update={"inputs": inputs})


def _select_intent_for_allowed_tools(
    candidates: list[TaskIntentSnapshot],
    allowed: set[str] | None,
) -> TaskIntentSnapshot:
    selected = candidates[0]
    if allowed is None:
        return selected
    browser_open_available = bool(
        {"browser.open_url", "browser.search", "browser.open"} & allowed
    )
    if not browser_open_available:
        return selected
    if selected.kind != "desktop_operation":
        return selected
    generic_browser_discovery = (
        isinstance(selected.inputs.get("generic_browser_discovery_hint"), Mapping)
        and isinstance(selected.inputs.get("app_search_hint"), Mapping)
    )
    generic_desktop_fallback = not any(
        value
        for key, value in selected.inputs.items()
        if key != "preflight_ui_before_action"
    )
    if not (generic_browser_discovery or generic_desktop_fallback):
        return selected
    for candidate in candidates[1:]:
        if candidate.kind != "web_research":
            continue
        if str(candidate.inputs.get("browser_action") or "").strip() != "open_search":
            continue
        if str(candidate.inputs.get("query") or "").strip():
            return candidate
    return selected


def _missing_capabilities(
    snapshots: list[Any],
    *,
    required_capability_ids: Iterable[str] | None = None,
) -> list[str]:
    required = {
        str(capability_id or "").strip()
        for capability_id in required_capability_ids or []
        if str(capability_id or "").strip()
    }
    missing = []
    for snapshot in snapshots:
        capability_id = str(getattr(snapshot, "capability_id", "") or "")
        if required and capability_id not in required:
            continue
        tools = list(getattr(snapshot, "tools", []) or [])
        available_tools = list(getattr(snapshot, "available_tools", []) or [])
        if tools and not available_tools:
            missing.append(capability_id)
    return [item for item in missing if item]


def _capability_plan_snapshot(
    intent: TaskIntentSnapshot,
    snapshots: list[Any],
    steps: list[ToolPlanStepSnapshot],
    *,
    required_capabilities: Iterable[str],
) -> CapabilityPlanSnapshot:
    required = _unique_capabilities(required_capabilities)
    preferred = _unique_capabilities(intent.preferred_capabilities)
    step_tools = _step_tools_by_capability(steps)
    step_ids = _step_ids_by_capability(steps)
    step_approvals = _step_approval_capabilities(steps)
    items: list[CapabilityPlanItemSnapshot] = []
    for snapshot in snapshots:
        capability_id = str(getattr(snapshot, "capability_id", "") or "").strip()
        if not capability_id:
            continue
        available_tools = _unique_capabilities(getattr(snapshot, "available_tools", None) or [])
        missing_tools = _unique_capabilities(getattr(snapshot, "missing_tools", None) or [])
        tools = _unique_capabilities(getattr(snapshot, "tools", None) or [])
        selected_tools = step_tools.get(capability_id, [])
        # Explicitly bound plugin adapters are discovered by the trusted
        # selector rather than by capability-registry name prefixes.  Reflect
        # a selected adapter in the consumer-safe capability summary without
        # exposing ranking internals.
        tools = _unique_capabilities((*tools, *selected_tools))
        available_tools = _unique_capabilities((*available_tools, *selected_tools))
        missing_tools = [tool for tool in missing_tools if tool not in selected_tools]
        status = _capability_plan_item_status(
            tools=tools,
            available_tools=available_tools,
            missing_tools=missing_tools,
            selected_tools=selected_tools,
        )
        approval_required = bool(getattr(snapshot, "approval_required", False)) or (
            capability_id in step_approvals
        )
        item = CapabilityPlanItemSnapshot(
            capability_id=capability_id,
            title=str(getattr(snapshot, "title", "") or capability_id).strip(),
            category=str(getattr(snapshot, "category", "") or "general").strip(),
            status=status,
            required=capability_id in required,
            preferred=capability_id in preferred,
            reason=_capability_plan_reason(
                intent,
                capability_id,
                required=capability_id in required,
                preferred=capability_id in preferred,
                status=status,
                selected_tools=selected_tools,
            ),
            selected_tools=selected_tools,
            available_tools=available_tools,
            missing_tools=missing_tools,
            planned_step_ids=step_ids.get(capability_id, []),
            discovery_actions=_unique_capabilities(
                getattr(snapshot, "discovery_actions", None) or []
            ),
            execution_actions=_unique_capabilities(
                getattr(snapshot, "execution_actions", None) or []
            ),
            output_kinds=_unique_capabilities(getattr(snapshot, "output_kinds", None) or []),
            risk_level=str(getattr(snapshot, "risk_level", "") or "low").strip(),
            approval_required=approval_required,
        )
        items.append(item)
    return CapabilityPlanSnapshot(
        plan_id=_stable_id("capability-plan", intent.kind, intent.user_goal),
        title=f"{intent.title} Capability Plan",
        intent_kind=intent.kind,
        items=items,
        required_capabilities=required,
        preferred_capabilities=preferred,
        available_capabilities=[
            item.capability_id for item in items if item.status != "missing"
        ],
        missing_capabilities=[
            item.capability_id for item in items if item.status == "missing"
        ],
        approvals_required=[
            item.capability_id for item in items if item.approval_required
        ],
    )


def _step_tools_by_capability(
    steps: Iterable[ToolPlanStepSnapshot],
) -> dict[str, list[str]]:
    tools: dict[str, list[str]] = {}
    for step in steps:
        capability_id = str(step.capability_id or "").strip()
        tool_name = str(step.tool_name or "").strip()
        if not capability_id or not tool_name:
            continue
        bucket = tools.setdefault(capability_id, [])
        if tool_name not in bucket:
            bucket.append(tool_name)
    return tools


def _step_ids_by_capability(
    steps: Iterable[ToolPlanStepSnapshot],
) -> dict[str, list[str]]:
    step_ids: dict[str, list[str]] = {}
    for step in steps:
        capability_id = str(step.capability_id or "").strip()
        step_id = str(step.step_id or "").strip()
        if not capability_id or not step_id:
            continue
        bucket = step_ids.setdefault(capability_id, [])
        if step_id not in bucket:
            bucket.append(step_id)
    return step_ids


def _step_approval_capabilities(
    steps: Iterable[ToolPlanStepSnapshot],
) -> set[str]:
    return {
        str(step.capability_id or "").strip()
        for step in steps
        if bool(step.approval_required) and str(step.capability_id or "").strip()
    }


def _capability_plan_item_status(
    *,
    tools: list[str],
    available_tools: list[str],
    missing_tools: list[str],
    selected_tools: list[str],
) -> str:
    if tools and not available_tools and not selected_tools:
        return "missing"
    if tools and missing_tools:
        return "degraded"
    return "available"


def _capability_plan_reason(
    intent: TaskIntentSnapshot,
    capability_id: str,
    *,
    required: bool,
    preferred: bool,
    status: str,
    selected_tools: list[str],
) -> str:
    if status == "missing":
        return "Required by the selected task intent, but no matching runtime tools are available."
    if selected_tools:
        return "Selected because the tool plan has concrete steps for this capability."
    if required:
        return "Required by the selected task intent."
    if preferred:
        return "Preferred support capability for the selected task intent."
    return f"Available support capability for {intent.kind}."


def _unavailable_required_step_capabilities(
    steps: Iterable[ToolPlanStepSnapshot],
    *,
    required_capability_ids: Iterable[str] | None = None,
) -> list[str]:
    required = {
        str(capability_id or "").strip()
        for capability_id in required_capability_ids or []
        if str(capability_id or "").strip()
    }
    missing: list[str] = []
    for step in steps:
        if str(step.status or "").strip() != "unavailable":
            continue
        if str(step.step_id or "").strip() == "verify-desktop-result":
            continue
        capability_id = str(step.capability_id or "").strip()
        if not capability_id:
            continue
        if required and capability_id not in required:
            continue
        if capability_id not in missing:
            missing.append(capability_id)
    return missing


def _required_capabilities_for_plan(
    intent: TaskIntentSnapshot,
    steps: list[ToolPlanStepSnapshot],
) -> list[str]:
    if intent.kind == "data_analysis":
        required = (
            ["data.analysis"]
            if any(step.tool_name == "data.analyze" for step in steps)
            else (_step_required_capabilities(steps) or list(intent.required_capabilities))
        )
        if any(step.step_id == "open-spreadsheet-app" for step in steps) and (
            "desktop.app_control" not in required
        ):
            required.insert(0, "desktop.app_control")
        for capability_id in _step_required_capabilities(steps):
            if capability_id not in required:
                required.append(capability_id)
        return required
    return _step_required_capabilities(steps) or list(intent.required_capabilities)


def _step_required_capabilities(steps: Iterable[ToolPlanStepSnapshot]) -> list[str]:
    required: list[str] = []
    for step in steps:
        capability_id = str(step.capability_id or "").strip()
        if capability_id and capability_id not in required:
            required.append(capability_id)
    return required


def _artifacts_expected(intent: TaskIntentSnapshot, steps: list[ToolPlanStepSnapshot]) -> list[str]:
    for step in steps:
        if step.tool_name == "data.analyze":
            artifact_paths = step.input_preview.get("artifact_paths")
            if isinstance(artifact_paths, list):
                return [
                    str(path or "").strip()
                    for path in artifact_paths
                    if str(path or "").strip()
                ]
            artifact_path = str(step.input_preview.get("artifact_path") or "").strip()
            return [artifact_path or "analysis-report.md"]
    artifact_write_paths = _artifact_write_paths_from_steps(steps)
    if intent.kind == "web_research":
        browser_action = str(intent.inputs.get("browser_action") or "").strip()
        if browser_action in {"screenshot", "open_url_screenshot"}:
            return ["browser/current-page.png"]
        if browser_action and artifact_write_paths:
            return artifact_write_paths
        if browser_action:
            return []
    if not any(step.tool_name == "artifact.write" for step in steps):
        return []
    if artifact_write_paths:
        return artifact_write_paths
    if intent.kind == "data_analysis":
        return data_analysis_artifacts_expected(intent.expected_outputs, intent.user_goal)
    if intent.kind == "web_research":
        return ["research-summary.md"]
    if intent.kind == "code_task":
        return ["code-task-summary.md"]
    if intent.kind == "file_organization":
        operation_hint = str(intent.inputs.get("operation_hint") or "").strip()
        if operation_hint == "duplicate_inventory":
            return ["duplicate-file-report.md"]
        if operation_hint == "inventory":
            return ["file-inventory.md"]
        return ["file-organization-plan.md"]
    if intent.kind == "information_capture":
        return ["captured-note.md"]
    return ["report.md"]


def _artifact_write_paths_from_steps(steps: Iterable[ToolPlanStepSnapshot]) -> list[str]:
    for step in steps:
        if step.tool_name != "artifact.write":
            continue
        paths = step.input_preview.get("paths")
        if isinstance(paths, list):
            return [
                str(path or "").strip()
                for path in paths
                if str(path or "").strip()
            ]
        path = str(step.input_preview.get("path") or "").strip()
        if path:
            return [path]
    return []


def _artifact_source_step_id(
    artifact: str,
    steps: Iterable[ToolPlanStepSnapshot],
) -> str | None:
    target = str(artifact or "").strip()
    candidates = list(steps)
    if target:
        for step in candidates:
            if target in _artifact_paths_from_step(step):
                return step.step_id
    for step in candidates:
        if step.tool_name in {"artifact.write", "data.analyze"} or step.action == "write_artifact":
            return step.step_id
    return None


def _artifact_paths_from_step(step: ToolPlanStepSnapshot) -> list[str]:
    paths = step.input_preview.get("paths")
    if isinstance(paths, list):
        return [
            str(path or "").strip()
            for path in paths
            if str(path or "").strip()
        ]
    artifact_paths = step.input_preview.get("artifact_paths")
    if isinstance(artifact_paths, list):
        return [
            str(path or "").strip()
            for path in artifact_paths
            if str(path or "").strip()
        ]
    values = (
        step.input_preview.get("artifact_path"),
        step.input_preview.get("path") if step.tool_name == "artifact.write" else "",
    )
    return [str(path or "").strip() for path in values if str(path or "").strip()]


def _append_artifact_reveal_step(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    artifact_paths: Iterable[str],
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    if not _artifact_reveal_requested(intent.user_goal):
        return steps
    path = _artifact_reveal_path(intent.user_goal, artifact_paths)
    if not path:
        return steps
    return [
        *steps,
        _step(
            intent,
            "reveal-artifact-in-finder",
            "Reveal artifact in Finder",
            "file.desktop_access",
            _first_allowed(("desktop.reveal_path",), allowed),
            input_preview={"path": path},
            depends_on=[depends_on],
            reason="Reveal the generated artifact through Finder only after the artifact-producing step finishes.",
        ),
    ]


def _data_analysis_support_method_input_preview(
    command: str,
    artifact_paths: Iterable[str],
) -> dict[str, Any]:
    paths = [
        str(path or "").strip()
        for path in artifact_paths
        if str(path or "").strip()
    ]
    preview: dict[str, Any] = {
        "command": str(command or ""),
        "artifact_path": paths[0] if paths else "analysis-report.md",
    }
    if len(paths) > 1:
        preview["artifact_paths"] = paths
    return preview


def _data_analysis_semantic_goal_target(
    inputs: Mapping[str, Any],
    *,
    artifact_paths: Iterable[str],
) -> dict[str, Any]:
    """Describe the analysis result without naming its execution adapter."""

    paths = [
        str(path or "").strip()
        for path in artifact_paths
        if str(path or "").strip()
    ]
    target: dict[str, Any] = {
        "kind": "data_analysis",
        "action": "analyze",
    }
    source_fields = (
        ("data_source_hint", "path"),
        ("data_source_kind", "source_kind"),
        ("context_source", "context_source"),
        ("data_source_scope_hint", "source_scope"),
        ("data_source_name_hint", "source_name"),
        ("data_source_selection_hint", "selection"),
    )
    for input_key, target_key in source_fields:
        value = inputs.get(input_key)
        if value not in (None, "", [], {}):
            target[target_key] = deepcopy(value)
    if not target.get("path") and not target.get("context_source"):
        target.update(
            {
                "expected_path": "<selected file from workspace.list>",
                "resolution_required": True,
            }
        )
    target["artifact_path"] = paths[0] if paths else "analysis-report.md"
    return target


def _data_analysis_terminal_effect_capabilities(
    *,
    output_target: str,
    app_write_target: Mapping[str, Any],
    communication_target: Mapping[str, Any],
) -> list[str]:
    """Declare only output effects that the user's analysis request names."""

    capabilities: list[str] = []
    if str(output_target or "").strip() == "clipboard":
        capabilities.append("clipboard.read_write")
    if app_write_target:
        capabilities.append("desktop.ui_operation")
    if communication_target:
        capabilities.append("communication.compose")
    return list(dict.fromkeys(capabilities))


def _append_data_analysis_artifact_verifier(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    artifact_paths: Iterable[str],
) -> None:
    paths = [
        str(path or "").strip()
        for path in artifact_paths
        if str(path or "").strip()
    ]
    verification_path = paths[0] if paths else "analysis-report.md"
    steps.append(
        _step(
            intent,
            "verify-analysis-artifact",
            "Read back analysis artifact",
            "file.workspace_read",
            _first_allowed(EXACT_FILE_READBACK_VERIFIER_TOOL_PREFERENCE, allowed),
            input_preview={"path": verification_path},
            depends_on=["run-analysis", "write-analysis-artifact"],
            reason=(
                "Independently read back the produced analysis artifact before "
                "the Runtime may complete the data-analysis goal."
            ),
        )
    )


def _append_data_analysis_followup_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    artifact_paths: Iterable[str],
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    paths = [str(path or "").strip() for path in artifact_paths if str(path or "").strip()]
    if _task_output_target_hint(intent.user_goal) == "clipboard":
        followup_steps = [
            *steps,
            _clipboard_output_step(
                intent,
                allowed,
                depends_on=[depends_on],
                body_source="analysis_result",
            ),
        ]
    else:
        followup_steps = _append_analysis_result_open_app_steps(
            intent,
            allowed,
            steps,
            artifact_paths=paths,
            depends_on=depends_on,
        )
        followup_steps = _append_artifact_reveal_step(
            intent,
            allowed,
            followup_steps,
            artifact_paths=paths,
            depends_on=depends_on,
        )
    followup_steps = _append_analysis_app_write_target_steps(
        intent,
        allowed,
        followup_steps,
        artifact_paths=paths,
        depends_on=depends_on,
    )
    followup_steps = _append_analysis_discovered_app_write_target_steps(
        intent,
        allowed,
        followup_steps,
        artifact_paths=paths,
        depends_on=depends_on,
    )
    return _append_analysis_communication_steps(
        intent,
        allowed,
        followup_steps,
        artifact_paths=paths,
        depends_on=depends_on,
    )


def _append_analysis_result_open_app_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    artifact_paths: Iterable[str],
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    app_name = str(intent.inputs.get("analysis_result_open_app_hint") or "").strip()
    if not app_name:
        return steps
    path = _analysis_result_open_path(intent.user_goal, artifact_paths, app_name)
    if not path:
        return steps
    tool_name = _first_allowed(
        (*_OPEN_PATH_WITH_APP_TOOL_CANDIDATES, "desktop.open_path"),
        allowed,
    )
    input_preview = {"path": path}
    if _is_open_path_with_app_tool(tool_name):
        input_preview["app_name"] = app_name
    return [
        *steps,
        _step(
            intent,
            "open-analysis-artifact-with-app",
            "Open analysis artifact",
            "file.desktop_access",
            tool_name,
            input_preview=input_preview,
            depends_on=[depends_on],
            action="open_path_with_app" if _is_open_path_with_app_tool(tool_name) else "open_path",
            reason=(
                "Open the generated analysis artifact only after the analysis step has "
                "produced it."
            ),
        ),
    ]


def _analysis_result_open_path(
    text: str,
    artifact_paths: Iterable[str],
    app_name: str,
) -> str:
    paths = [
        str(path or "").strip()
        for path in artifact_paths
        if str(path or "").strip()
    ]
    if not paths:
        return ""
    value = _clean_prompt(text)
    if app_name in {"Excel", "Numbers"}:
        table_path = _first_path_with_suffix(paths, (".csv", ".tsv", ".xlsx"))
        if table_path:
            return table_path
    if _contains_any(value, ("图表", "趋势图", "chart", "plot")):
        chart_path = _first_path_with_suffix(paths, (".png", ".jpg", ".jpeg", ".svg"))
        if chart_path:
            return chart_path
    return _artifact_reveal_path(text, paths)


def _append_analysis_app_write_target_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    artifact_paths: Iterable[str],
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    target_app = str(intent.inputs.get("target_app_hint") or "").strip()
    target_action = str(intent.inputs.get("target_action_hint") or "").strip()
    if not target_app or target_action != "app_paste":
        return steps
    artifact_path = _analysis_communication_artifact_path(
        intent.user_goal,
        artifact_paths,
    )
    if not artifact_path:
        return steps
    container_action = str(
        intent.inputs.get("target_container_action_hint") or ""
    ).strip()
    next_steps = [*steps]
    previous_step = depends_on
    if container_action:
        previous_step = _append_app_scoped_safe_shortcut_steps(
            next_steps,
            intent,
            step_id="prepare-analysis-target-app",
            title="Prepare target app",
            app_name=target_app,
            mode="open",
            shortcut_action=container_action,
            allowed=allowed,
            depends_on=[previous_step],
            prepare_reason=(
                "Open or focus the requested app after the analysis artifact is available."
            ),
            shortcut_reason=(
                "Create the requested target container before inserting the analysis report."
            ),
            fallback_reason=(
                "Open or focus the requested app and create the target container with one safe app-scoped action."
            ),
        )
    else:
        next_steps.append(
            _step(
                intent,
                "prepare-analysis-target-app",
                "Prepare target app",
                "desktop.app_control",
                _first_allowed(("app.focus", "app.open"), allowed),
                input_preview={
                    "app_name": target_app,
                    "target_action": target_action,
                    "body_source": "analysis_artifact",
                    "artifact_path": artifact_path,
                },
                depends_on=[previous_step],
                reason=(
                    "Open or focus the requested app after the local analysis artifact is available."
                ),
            )
        )
        previous_step = "prepare-analysis-target-app"

    insert_tool, insert_input = _safe_type_text_operation_preview(
        app_name=target_app,
        mode="focus",
        allowed=allowed,
        payload={
            "body_source": "analysis_artifact",
            "artifact_path": artifact_path,
            "target_action": target_action,
            **(
                {"container_action": container_action}
                if container_action
                else {}
            ),
        },
    )
    next_steps.append(
        _step(
            intent,
            "insert-analysis-into-target-app",
            "Insert analysis into target app",
            "desktop.ui_operation",
            insert_tool,
            input_preview=insert_input,
            risk_level=_desktop_operation_risk_level(insert_tool),
            approval_required=_desktop_operation_approval_required(insert_tool),
            depends_on=[previous_step],
            action="type",
            reason=(
                "Insert the generated analysis artifact into the prepared foreground target app."
            ),
        )
    )
    return _append_analysis_target_app_verification_step(
        intent,
        allowed,
        next_steps,
        app_name=target_app,
        depends_on="insert-analysis-into-target-app",
    )


def _append_analysis_discovered_app_write_target_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    artifact_paths: Iterable[str],
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    target_capability = intent.inputs.get("target_app_capability_hint")
    target_action = str(intent.inputs.get("target_action_hint") or "").strip()
    if not isinstance(target_capability, Mapping) or target_action != "app_paste":
        return steps
    artifact_path = _analysis_communication_artifact_path(
        intent.user_goal,
        artifact_paths,
    )
    if not artifact_path:
        return steps
    query = str(target_capability.get("query") or "").strip()
    if not query:
        return steps
    container_action = str(
        intent.inputs.get("target_container_action_hint") or ""
    ).strip()
    safe_shortcut = {"action": container_action} if container_action else None
    selected_app_tool = _selected_discovered_app_tool(
        allowed,
        safe_shortcut=safe_shortcut,
    )
    if not selected_app_tool:
        return steps
    selected_app_input = {
        "app_name": "<selected app from desktop.list_apps>",
        "selection_source": "desktop.list_apps",
        "query": query,
        "target_action": target_action,
        "body_source": "analysis_artifact",
        "artifact_path": artifact_path,
        **_selected_discovered_app_operation_preview(
            selected_app_tool,
            safe_shortcut=safe_shortcut,
        ),
    }
    selected_app_capability = (
        "desktop.app_control"
        if selected_app_tool in {"app.open", "desktop.open_app"}
        else "desktop.ui_operation"
    )
    selected_app_action = (
        "safe_shortcut"
        if selected_app_tool in {"app.open_and_safe_shortcut", "app.focus_and_safe_shortcut"}
        else "open_app"
    )
    next_steps = [
        *steps,
        _step(
            intent,
            "discover-analysis-target-app",
            "Discover analysis target app",
            "desktop.app_discovery",
            _first_allowed(("desktop.list_apps",), allowed),
            input_preview={"query": query, "limit": 20},
            depends_on=[depends_on],
            reason=(
                "Discover an installed app by capability before writing the generated "
                "analysis result into it."
            ),
        ),
        _step(
            intent,
            "prepare-analysis-discovered-target-app",
            "Prepare discovered analysis target app",
            selected_app_capability,
            selected_app_tool,
            input_preview=selected_app_input,
            depends_on=["discover-analysis-target-app"],
            action=selected_app_action,
            reason=(
                "After desktop.list_apps returns candidates, runtime resolves the best "
                "matching app and prepares it for the generated analysis report."
            ),
        ),
    ]
    insert_tool, insert_input = _safe_type_text_operation_preview(
        app_name="<selected app from desktop.list_apps>",
        mode="focus",
        allowed=allowed,
        payload={
            "body_source": "analysis_artifact",
            "artifact_path": artifact_path,
            "target_action": target_action,
            **(
                {"container_action": container_action}
                if container_action
                else {}
            ),
        },
    )
    insert_input = _with_selected_app_payload(
        insert_tool,
        insert_input,
        {"selection_source": "desktop.list_apps", "query": query},
    )
    next_steps.append(
        _step(
            intent,
            "insert-analysis-into-target-app",
            "Insert analysis into target app",
            "desktop.ui_operation",
            insert_tool,
            input_preview=insert_input,
            risk_level=_desktop_operation_risk_level(insert_tool),
            approval_required=_desktop_operation_approval_required(insert_tool),
            depends_on=["prepare-analysis-discovered-target-app"],
            action="type",
            reason=(
                "Insert the generated analysis artifact into the selected foreground target app."
            ),
        )
    )
    return _append_analysis_target_app_verification_step(
        intent,
        allowed,
        next_steps,
        app_name="<selected app from desktop.list_apps>",
        depends_on="insert-analysis-into-target-app",
        selected_app_payload={"selection_source": "desktop.list_apps", "query": query},
    )


def _append_analysis_target_app_verification_step(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    app_name: str,
    depends_on: str,
    selected_app_payload: Mapping[str, Any] | None = None,
) -> list[ToolPlanStepSnapshot]:
    verify_tool = _first_allowed(
        ("desktop.ui_elements", "desktop.read_ui", "screen.capture"),
        allowed,
    )
    if not verify_tool:
        return steps
    if verify_tool == "screen.capture":
        input_preview = {"reason": "Verify the analysis was inserted into the target app."}
    else:
        input_preview = {
            "app_name": app_name,
            **dict(selected_app_payload or {}),
            "role_filter": "text",
            "limit": 80,
        }
    return [
        *steps,
        _step(
            intent,
            "verify-analysis-target-app",
            "Verify analysis target app",
            "desktop.ui_operation",
            verify_tool,
            input_preview=input_preview,
            depends_on=[depends_on],
            action="read_ui" if verify_tool != "screen.capture" else "capture_screen",
            reason=(
                "Inspect the target app after insertion so the runtime can replan if the analysis is not visible."
            ),
        ),
    ]


def _append_orchestration_communication_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    orchestration_kind: str,
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    target = intent.inputs.get("communication_target_hint")
    if not isinstance(target, Mapping):
        return steps
    recipient = str(target.get("recipient") or "").strip()
    if not recipient:
        return steps
    label = "workflow" if orchestration_kind == "workflow" else "group-run"
    title_label = "workflow" if orchestration_kind == "workflow" else "group run"
    default_artifact = (
        "workflow-result.md"
        if orchestration_kind == "workflow"
        else "group-run-result.md"
    )
    artifact_path = _artifact_output_path(intent.user_goal, default_artifact)
    artifact_tool = _first_allowed(("artifact.write",), allowed)
    next_steps = list(steps)
    compose_depends_on = depends_on
    body_source = "model_generated_content"
    if artifact_tool:
        write_step_id = f"write-{label}-result-artifact"
        next_steps.append(
            _step(
                intent,
                write_step_id,
                f"Write {title_label} result artifact",
                "artifact.write",
                artifact_tool,
                input_preview={
                    "path": artifact_path,
                    "body_source": "model_generated_content",
                    "source": str(target.get("body_source") or "").strip()
                    or f"{orchestration_kind}_result",
                },
                depends_on=[depends_on],
                action="write_artifact",
                reason=(
                    f"Materialize the {title_label} result as a replayable artifact before "
                    "using it in a follow-up communication."
                ),
            )
        )
        compose_depends_on = write_step_id
        body_source = "artifact"

    app_name = str(target.get("app_name") or "").strip()
    channel = str(target.get("channel") or "").strip()
    transform = str(target.get("content_transform_hint") or "").strip()
    mode = str(target.get("mode") or "focus").strip() or "focus"
    send_action = str(target.get("send_action") or "send").strip() or "send"
    selected_app_payload: dict[str, Any] = {}
    communication_steps: list[ToolPlanStepSnapshot] = []
    if not app_name:
        app_name = _default_communication_app_for_channel(
            channel,
            mode,
            allowed,
            require_send=send_action == "send",
        )
    if not app_name:
        app_query = _generic_communication_app_query_for_channel(channel)
        discover_tool = _first_allowed(("desktop.list_apps",), allowed)
        if app_query and discover_tool and _communication_desktop_compose_tools_available(
            mode,
            allowed,
            require_send=send_action == "send",
        ):
            app_name = "<selected app from desktop.list_apps>"
            selected_app_payload = {
                "selection_source": "desktop.list_apps",
                "query": app_query,
            }
            mode = "open"
            communication_steps.append(
                _step(
                    intent,
                    f"discover-{label}-communication-app",
                    "Discover communication app",
                    "desktop.app_discovery",
                    discover_tool,
                    input_preview={"query": app_query, "limit": 20},
                    depends_on=[compose_depends_on],
                    action="list_apps",
                    reason=(
                        f"Discover an installed communication app before sending the {title_label} result."
                    ),
                )
            )
    if not app_name:
        if not artifact_tool:
            return next_steps
        draft_input = {
            "recipient": recipient,
            "body_source": body_source,
        }
        if body_source == "artifact":
            draft_input["artifact_path"] = artifact_path
        if transform:
            draft_input["transform"] = transform
        return [
            *next_steps,
            _step(
                intent,
                f"draft-{label}-communication",
                f"Draft {title_label} communication",
                "communication.compose",
                artifact_tool,
                input_preview=draft_input,
                approval_required=True,
                risk_level="medium",
                depends_on=[compose_depends_on],
                action="draft_message",
                reason=(
                    f"Create a reviewable communication draft from the {title_label} result "
                    "when the target app cannot be resolved deterministically."
                ),
            ),
        ]

    app_shortcut_tool = _first_allowed(
        app_foreground_tool_candidates(mode, "safe_shortcut"),
        allowed,
    )
    app_tool, shortcut_tool = _app_scoped_safe_shortcut_split_tools(app_name, mode, allowed)
    type_tool, recipient_type_input = _safe_type_text_operation_preview(
        app_name=app_name,
        mode=mode,
        allowed=allowed,
        payload={"text": recipient},
    )
    recipient_type_input = _with_selected_app_payload(
        type_tool,
        recipient_type_input,
        selected_app_payload,
    )
    search_submit_tool = _app_search_submit_operation_tool(allowed)
    send_tool = _first_allowed(("desktop.submit_foreground",), allowed)
    discover_step_id = f"discover-{label}-communication-app"
    open_step_id = f"open-or-focus-{label}-communication-app"
    focus_step_id = f"focus-{label}-communication-recipient-search"
    type_step_id = f"type-{label}-communication-recipient"
    submit_step_id = f"submit-{label}-communication-recipient-search"
    draft_step_id = f"draft-{label}-communication-message"
    focus_depends_on = [discover_step_id] if selected_app_payload else [compose_depends_on]
    if app_tool and shortcut_tool:
        communication_steps.append(
            _step(
                intent,
                open_step_id,
                "Open or focus communication app",
                "desktop.app_control",
                app_tool,
                input_preview={"app_name": app_name, **selected_app_payload},
                depends_on=focus_depends_on,
                reason=f"Prepare the requested communication app after the {title_label} result is available.",
            )
        )
        focus_depends_on = [open_step_id]
        focus_tool = shortcut_tool
        focus_input = {"action": _communication_recipient_focus_action(channel)}
        focus_capability = "communication.compose"
        focus_reason = "Open foreground recipient search with a generic safe shortcut."
    else:
        focus_tool = app_shortcut_tool
        focus_input = {
            "app_name": app_name,
            **selected_app_payload,
            "action": _communication_recipient_focus_action(channel),
        }
        focus_capability = "communication.compose"
        focus_reason = f"Open the app's recipient search after the {title_label} result is available."

    draft_input = {"body_source": body_source}
    if body_source == "artifact":
        draft_input["artifact_path"] = artifact_path
    if transform:
        draft_input["transform"] = transform
    draft_tool, draft_input = _safe_type_text_operation_preview(
        app_name=app_name,
        mode=mode,
        allowed=allowed,
        payload=draft_input,
    )
    draft_input = _with_selected_app_payload(draft_tool, draft_input, selected_app_payload)
    communication_steps.extend(
        [
            _step(
                intent,
                focus_step_id,
                "Focus communication recipient search",
                focus_capability,
                focus_tool,
                input_preview=focus_input,
                action="resolve_recipient",
                depends_on=focus_depends_on,
                reason=focus_reason,
            ),
            _step(
                intent,
                type_step_id,
                "Type communication recipient",
                "communication.compose",
                type_tool,
                input_preview=recipient_type_input,
                depends_on=[focus_step_id],
                action="type",
                reason="Type only the explicit recipient from the user prompt.",
            ),
            _step(
                intent,
                submit_step_id,
                "Submit communication recipient search",
                "communication.compose",
                search_submit_tool,
                input_preview=_app_search_submit_input_preview(search_submit_tool),
                risk_level=_app_search_submit_risk_level(search_submit_tool),
                approval_required=_app_search_submit_approval_required(search_submit_tool),
                depends_on=[type_step_id],
                action="submit_search",
                reason=(
                    "Select or search the recipient with the dedicated safe submit tool when available; "
                    "otherwise use the foreground submit fallback through the approval gate."
                ),
            ),
            _step(
                intent,
                draft_step_id,
                f"Draft {title_label} communication message",
                "communication.compose",
                draft_tool,
                input_preview=draft_input,
                depends_on=[submit_step_id],
                action="draft_message",
                reason=(
                    f"Draft the message from the {title_label} result before any approval-gated send step."
                ),
            ),
        ]
    )
    if send_action == "send":
        communication_steps.append(
            _step(
                intent,
                f"send-{label}-communication-message",
                f"Send {title_label} communication message",
                "communication.compose",
                send_tool,
                input_preview={"action": "send"},
                risk_level="high",
                approval_required=True,
                depends_on=[draft_step_id],
                action="send_message",
                reason="Final message sending remains approval-gated.",
            )
    )
    return [*next_steps, *communication_steps]


def _append_analysis_app_only_communication_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    app_name: str,
    mode: str,
    artifact_path: str,
    transform: str,
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    app_tool = _first_allowed(app_control_tool_candidates(mode), allowed)
    if not app_tool:
        return steps
    draft_input = {
        "body_source": "analysis_artifact",
        "artifact_path": artifact_path,
    }
    if transform:
        draft_input["transform"] = transform
    draft_tool, draft_input = _safe_type_text_operation_preview(
        app_name=app_name,
        mode=mode,
        allowed=allowed,
        payload=draft_input,
    )
    next_steps = [
        *steps,
        _step(
            intent,
            "open-or-focus-analysis-communication-app",
            "Open or focus communication app",
            "desktop.app_control",
            app_tool,
            input_preview={"app_name": app_name},
            depends_on=[depends_on],
            reason=(
                "Prepare the requested communication app after the analysis artifact is "
                "available, even when the user did not name a recipient."
            ),
        ),
        _step(
            intent,
            "draft-analysis-communication-message",
            "Draft analysis communication message",
            "communication.compose",
            draft_tool,
            input_preview=draft_input,
            depends_on=["open-or-focus-analysis-communication-app"],
            action="draft_message",
            reason=(
                "Draft the analysis artifact into the requested communication app without "
                "sending when no explicit recipient was provided."
            ),
        ),
    ]
    verify_tool = _first_allowed(("desktop.ui_elements", "desktop.active_window", "screen.capture"), allowed)
    if not verify_tool:
        return next_steps
    verify_input = (
        {"reason": "Verify the analysis draft is visible in the communication app."}
        if verify_tool == "screen.capture"
        else {"app_name": app_name, "role_filter": "text", "limit": 80}
    )
    return [
        *next_steps,
        _step(
            intent,
            "verify-analysis-communication-app",
            "Verify analysis communication app",
            "desktop.ui_operation",
            verify_tool,
            input_preview=verify_input,
            depends_on=["draft-analysis-communication-message"],
            action="read_ui" if verify_tool != "screen.capture" else "capture_screen",
            reason=(
                "Inspect the communication app after drafting so the runtime can replan "
                "if the content is not visible."
            ),
        ),
    ]


def _append_analysis_communication_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    artifact_paths: Iterable[str],
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    target = intent.inputs.get("communication_target_hint")
    if not isinstance(target, Mapping):
        return steps
    recipient = str(target.get("recipient") or "").strip()
    app_name = str(target.get("app_name") or "").strip()
    if not recipient and not app_name:
        return steps
    artifact_path = _analysis_communication_artifact_path(intent.user_goal, artifact_paths)
    if not artifact_path:
        return steps
    channel = str(target.get("channel") or "").strip()
    transform = str(target.get("content_transform_hint") or "").strip()
    mode = str(target.get("mode") or "focus").strip() or "focus"
    selected_app_payload: dict[str, Any] = {}
    communication_steps: list[ToolPlanStepSnapshot] = []
    if app_name and not recipient:
        return _append_analysis_app_only_communication_steps(
            intent,
            allowed,
            steps,
            app_name=app_name,
            mode=mode,
            artifact_path=artifact_path,
            transform=transform,
            depends_on=depends_on,
        )
    if not app_name:
        app_name = _default_communication_app_for_channel(channel, mode, allowed)
    if not app_name:
        app_query = _generic_communication_app_query_for_channel(channel)
        discover_tool = _first_allowed(("desktop.list_apps",), allowed)
        if app_query and discover_tool and _communication_desktop_compose_tools_available(
            mode,
            allowed,
            require_send=str(target.get("send_action") or "").strip() == "send",
        ):
            app_name = "<selected app from desktop.list_apps>"
            selected_app_payload = {
                "selection_source": "desktop.list_apps",
                "query": app_query,
            }
            mode = "open"
            communication_steps.append(
                _step(
                    intent,
                    "discover-analysis-communication-app",
                    "Discover communication app",
                    "desktop.app_discovery",
                    discover_tool,
                    input_preview={"query": app_query, "limit": 20},
                    depends_on=[depends_on],
                    action="list_apps",
                    reason="Discover an installed communication app before sending the generated analysis artifact.",
                )
            )
    if not app_name:
        draft_input = {
            "recipient": recipient,
            "body_source": "analysis_artifact",
            "artifact_path": artifact_path,
        }
        if transform:
            draft_input["transform"] = transform
        return [
            *steps,
            _step(
                intent,
                "draft-analysis-communication",
                "Draft analysis communication",
                "communication.compose",
                _first_allowed(("artifact.write",), allowed),
                input_preview=draft_input,
                approval_required=True,
                risk_level="medium",
                depends_on=[depends_on],
                action="draft_message",
                reason=(
                    "Create a reviewable communication draft from the analysis artifact when the target app "
                    "cannot be resolved deterministically."
                ),
            ),
        ]

    app_shortcut_tool = _first_allowed(
        app_foreground_tool_candidates(mode, "safe_shortcut"),
        allowed,
    )
    app_tool, shortcut_tool = _app_scoped_safe_shortcut_split_tools(app_name, mode, allowed)
    type_tool, recipient_type_input = _safe_type_text_operation_preview(
        app_name=app_name,
        mode=mode,
        allowed=allowed,
        payload={"text": recipient},
    )
    recipient_type_input = _with_selected_app_payload(
        type_tool,
        recipient_type_input,
        selected_app_payload,
    )
    search_submit_tool = _app_search_submit_operation_tool(allowed)
    send_tool = _first_allowed(("desktop.submit_foreground",), allowed)
    focus_depends_on = ["discover-analysis-communication-app"] if selected_app_payload else [depends_on]
    if app_tool and shortcut_tool:
        communication_steps.append(
            _step(
                intent,
                "open-or-focus-app",
                "Open or focus app",
                "desktop.app_control",
                app_tool,
                input_preview={"app_name": app_name, **selected_app_payload},
                depends_on=focus_depends_on,
                reason="Prepare the requested communication app after the analysis artifact is available.",
            )
        )
        focus_depends_on = ["open-or-focus-app"]
        focus_tool = shortcut_tool
        focus_input = {"action": _communication_recipient_focus_action(channel)}
        focus_capability = "communication.compose"
        focus_reason = "Open foreground recipient search with a generic safe shortcut."
    else:
        focus_tool = app_shortcut_tool
        focus_input = {
            "app_name": app_name,
            **selected_app_payload,
            "action": _communication_recipient_focus_action(channel),
        }
        focus_capability = "communication.compose"
        focus_reason = "Open the app's recipient search after the analysis artifact is available."

    draft_input = {
        "body_source": "analysis_artifact",
        "artifact_path": artifact_path,
    }
    if transform:
        draft_input["transform"] = transform
    draft_tool, draft_input = _safe_type_text_operation_preview(
        app_name=app_name,
        mode=mode,
        allowed=allowed,
        payload=draft_input,
    )
    draft_input = _with_selected_app_payload(draft_tool, draft_input, selected_app_payload)
    communication_steps.extend(
        [
            _step(
                intent,
                "focus-communication-recipient-search",
                "Focus communication recipient search",
                focus_capability,
                focus_tool,
                input_preview=focus_input,
                action="resolve_recipient",
                depends_on=focus_depends_on,
                reason=focus_reason,
            ),
            _step(
                intent,
                "type-communication-recipient",
                "Type communication recipient",
                "communication.compose",
                type_tool,
                input_preview=recipient_type_input,
                depends_on=["focus-communication-recipient-search"],
                action="type",
                reason="Type only the explicit recipient from the user prompt.",
            ),
            _step(
                intent,
                "submit-communication-recipient-search",
                "Submit communication recipient search",
                "communication.compose",
                search_submit_tool,
                input_preview=_app_search_submit_input_preview(search_submit_tool),
                risk_level=_app_search_submit_risk_level(search_submit_tool),
                approval_required=_app_search_submit_approval_required(search_submit_tool),
                depends_on=["type-communication-recipient"],
                action="submit_search",
                reason=(
                    "Select or search the recipient with the dedicated safe submit tool when available; "
                    "otherwise use the foreground submit fallback through the approval gate."
                ),
            ),
            _step(
                intent,
                "draft-analysis-communication-message",
                "Draft analysis communication message",
                "communication.compose",
                draft_tool,
                input_preview=draft_input,
                depends_on=["submit-communication-recipient-search"],
                action="draft_message",
                reason="Draft the message from the generated analysis artifact before the approval-gated send step.",
            ),
            _step(
                intent,
                "send-analysis-communication-message",
                "Send analysis communication message",
                "communication.compose",
                send_tool,
                input_preview={"action": "send"},
                risk_level="high",
                approval_required=True,
                depends_on=["draft-analysis-communication-message"],
                action="send_message",
                reason="Final message sending remains approval-gated.",
            ),
        ]
    )
    return [*steps, *communication_steps]


def _append_web_research_app_write_target_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    target_app = str(intent.inputs.get("target_app_hint") or "").strip()
    target_action = str(intent.inputs.get("target_action_hint") or "").strip()
    if not target_app or target_action != "app_paste":
        return steps
    container_action = str(
        intent.inputs.get("target_container_action_hint") or ""
    ).strip()
    artifact_path = _artifact_output_path(intent.user_goal, "research-summary.md")
    next_steps = [
        *steps,
        _step(
            intent,
            "write-research-artifact",
            "Write research artifact",
            "artifact.write",
            _first_allowed(("artifact.write",), allowed),
            input_preview={"path": artifact_path},
            depends_on=[depends_on],
            reason=(
                "Persist the browser-derived research output before writing it "
                "into the requested app."
            ),
        ),
    ]
    previous_step = "write-research-artifact"
    if container_action:
        previous_step = _append_app_scoped_safe_shortcut_steps(
            next_steps,
            intent,
            step_id="prepare-research-target-app",
            title="Prepare target app",
            app_name=target_app,
            mode="open",
            shortcut_action=container_action,
            allowed=allowed,
            depends_on=[previous_step],
            prepare_reason=(
                "Open or focus the requested app after the research artifact is ready."
            ),
            shortcut_reason=(
                "Create the requested target container before inserting the research output."
            ),
            fallback_reason=(
                "Open or focus the requested app and create the target container with "
                "one safe app-scoped action."
            ),
        )
    else:
        next_steps.append(
            _step(
                intent,
                "prepare-research-target-app",
                "Prepare target app",
                "desktop.app_control",
                _first_allowed(("app.open", "app.focus"), allowed),
                input_preview={
                    "app_name": target_app,
                    "target_action": target_action,
                    "body_source": "research_artifact",
                    "artifact_path": artifact_path,
                },
                depends_on=[previous_step],
                reason=(
                    "Open or focus the requested app after the research artifact is ready."
                ),
            )
        )
        previous_step = "prepare-research-target-app"

    insert_tool, insert_input = _safe_type_text_operation_preview(
        app_name=target_app,
        mode="focus",
        allowed=allowed,
        payload={
            "body_source": "research_artifact",
            "artifact_path": artifact_path,
            "target_action": target_action,
            **(
                {"container_action": container_action}
                if container_action
                else {}
            ),
        },
    )
    next_steps.append(
        _step(
            intent,
            "insert-research-into-target-app",
            "Insert research into target app",
            "desktop.ui_operation",
            insert_tool,
            input_preview=insert_input,
            risk_level=_desktop_operation_risk_level(insert_tool),
            approval_required=_desktop_operation_approval_required(insert_tool),
            depends_on=list(
                dict.fromkeys([previous_step, "write-research-artifact"])
            ),
            input_bindings=[
                _artifact_path_input_binding(
                    intent,
                    source_step_id="write-research-artifact",
                    target_step_id="insert-research-into-target-app",
                )
            ],
            action="type",
            reason=(
                "Insert the generated research artifact into the prepared foreground target app."
            ),
        )
    )
    return _append_research_target_app_verification_step(
        intent,
        allowed,
        next_steps,
        app_name=target_app,
        depends_on="insert-research-into-target-app",
    )


def _append_web_research_discovered_app_write_target_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    depends_on: str,
) -> list[ToolPlanStepSnapshot]:
    target_capability = intent.inputs.get("target_app_capability_hint")
    target_action = str(intent.inputs.get("target_action_hint") or "").strip()
    if not isinstance(target_capability, Mapping) or target_action != "app_paste":
        return steps
    query = str(target_capability.get("query") or "").strip()
    if not query:
        return steps
    container_action = str(
        intent.inputs.get("target_container_action_hint") or ""
    ).strip()
    safe_shortcut = {"action": container_action} if container_action else None
    selected_app_tool = _selected_discovered_app_tool(
        allowed,
        safe_shortcut=safe_shortcut,
    )
    if not selected_app_tool:
        return steps
    selected_app_capability = (
        "desktop.app_control"
        if selected_app_tool in {"app.open", "desktop.open_app"}
        else "desktop.ui_operation"
    )
    selected_app_action = (
        "safe_shortcut"
        if selected_app_tool in {"app.open_and_safe_shortcut", "app.focus_and_safe_shortcut"}
        else "open_app"
    )
    artifact_path = _artifact_output_path(intent.user_goal, "research-summary.md")
    next_steps = [
        *steps,
        _step(
            intent,
            "write-research-artifact",
            "Write research artifact",
            "artifact.write",
            _first_allowed(("artifact.write",), allowed),
            input_preview={"path": artifact_path},
            depends_on=[depends_on],
            reason=(
                "Persist the browser-derived research output before selecting a target app."
            ),
        ),
        _step(
            intent,
            "discover-research-target-app",
            "Discover research target app",
            "desktop.app_discovery",
            _first_allowed(("desktop.list_apps",), allowed),
            input_preview={"query": query, "limit": 20},
            depends_on=["write-research-artifact"],
            reason=(
                "Discover an installed app by capability before writing the generated "
                "research artifact into it."
            ),
        ),
        _step(
            intent,
            "prepare-research-discovered-target-app",
            "Prepare discovered research target app",
            selected_app_capability,
            selected_app_tool,
            input_preview={
                "app_name": "<selected app from desktop.list_apps>",
                "selection_source": "desktop.list_apps",
                "query": query,
                "target_action": target_action,
                "body_source": "research_artifact",
                "artifact_path": artifact_path,
                **_selected_discovered_app_operation_preview(
                    selected_app_tool,
                    safe_shortcut=safe_shortcut,
                ),
            },
            depends_on=["discover-research-target-app"],
            action=selected_app_action,
            reason=(
                "After desktop.list_apps returns candidates, runtime resolves the best "
                "matching app and prepares it for the generated research output."
            ),
        ),
    ]
    insert_tool, insert_input = _safe_type_text_operation_preview(
        app_name="<selected app from desktop.list_apps>",
        mode="focus",
        allowed=allowed,
        payload={
            "body_source": "research_artifact",
            "artifact_path": artifact_path,
            "target_action": target_action,
            **(
                {"container_action": container_action}
                if container_action
                else {}
            ),
        },
    )
    insert_input = _with_selected_app_payload(
        insert_tool,
        insert_input,
        {"selection_source": "desktop.list_apps", "query": query},
    )
    next_steps.append(
        _step(
            intent,
            "insert-research-into-target-app",
            "Insert research into target app",
            "desktop.ui_operation",
            insert_tool,
            input_preview=insert_input,
            risk_level=_desktop_operation_risk_level(insert_tool),
            approval_required=_desktop_operation_approval_required(insert_tool),
            depends_on=[
                "prepare-research-discovered-target-app",
                "write-research-artifact",
            ],
            input_bindings=[
                _artifact_path_input_binding(
                    intent,
                    source_step_id="write-research-artifact",
                    target_step_id="insert-research-into-target-app",
                )
            ],
            action="type",
            reason=(
                "Insert the generated research artifact into the selected foreground target app."
            ),
        )
    )
    return _append_research_target_app_verification_step(
        intent,
        allowed,
        next_steps,
        app_name="<selected app from desktop.list_apps>",
        depends_on="insert-research-into-target-app",
        selected_app_payload={"selection_source": "desktop.list_apps", "query": query},
    )


def _artifact_path_input_binding(
    intent: TaskIntentSnapshot,
    *,
    source_step_id: str,
    target_step_id: str,
) -> RuntimeInputBindingSnapshot:
    """Bind an app sink to the exact artifact produced by its source step.

    The binding transfers only the bounded relative path.  Runtime then reads
    the artifact through its existing broker-owned resolver; model prose never
    supplies or replaces the durable handoff identity.
    """

    return RuntimeInputBindingSnapshot(
        binding_id=_stable_id(
            "input-binding",
            intent.intent_id,
            f"{source_step_id}|{target_step_id}|artifact_path",
        ),
        source_step_id=source_step_id,
        source_tool_name="artifact.write",
        source_result_path="/path",
        target_input_path="/input/artifact_path",
        value_type="string",
        required=True,
        max_bytes=1024,
    )


def _append_report_app_write_target_steps(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    steps: list[ToolPlanStepSnapshot],
    *,
    depends_on: list[str],
    target_app: str,
    artifact_path: str,
    body_source: str,
) -> list[ToolPlanStepSnapshot]:
    target_action = str(intent.inputs.get("target_action_hint") or "app_paste").strip()
    if not target_app or target_action != "app_paste":
        return steps
    container_action = str(
        intent.inputs.get("target_container_action_hint") or ""
    ).strip()
    next_steps = [
        *steps,
        _step(
            intent,
            "write-report-artifact",
            "Write report artifact",
            "artifact.write",
            _first_allowed(("artifact.write",), allowed),
            input_preview={
                "path": artifact_path,
                "body_source": body_source,
            },
            depends_on=depends_on,
            reason=(
                "Produce a replayable report draft from the inspected source before "
                "writing it into the requested app."
            ),
        ),
    ]
    previous_step = "write-report-artifact"
    if container_action:
        previous_step = _append_app_scoped_safe_shortcut_steps(
            next_steps,
            intent,
            step_id="prepare-report-target-app",
            title="Prepare target app",
            app_name=target_app,
            mode="open",
            shortcut_action=container_action,
            allowed=allowed,
            depends_on=[previous_step],
            prepare_reason="Open or focus the requested app after the report draft is available.",
            shortcut_reason="Create the requested target container before inserting the report.",
            fallback_reason="Open or focus the requested app and create the target container with one safe app-scoped action.",
        )
    else:
        prepare_tool = _first_allowed(("app.open", "app.focus"), allowed)
        next_steps.append(
            _step(
                intent,
                "prepare-report-target-app",
                "Prepare target app",
                "desktop.app_control",
                prepare_tool,
                input_preview={
                    "app_name": target_app,
                    "target_action": target_action,
                    "body_source": "report_artifact",
                    "artifact_path": artifact_path,
                },
                depends_on=[previous_step],
                reason=(
                    "Open or focus the requested app after the report draft is ready."
                ),
            )
        )
        previous_step = "prepare-report-target-app"

    if _step_is_unavailable(next_steps, previous_step):
        return next_steps

    insert_tool, insert_input = _safe_type_text_operation_preview(
        app_name=target_app,
        mode="focus",
        allowed=allowed,
        payload={
            "body_source": "report_artifact",
            "artifact_path": artifact_path,
            "target_action": target_action,
            **(
                {"container_action": container_action}
                if container_action
                else {}
            ),
        },
    )
    next_steps.append(
        _step(
            intent,
            "insert-report-into-target-app",
            "Insert report into target app",
            "desktop.ui_operation",
            insert_tool,
            input_preview=insert_input,
            risk_level=_desktop_operation_risk_level(insert_tool),
            approval_required=_desktop_operation_approval_required(insert_tool),
            depends_on=[previous_step],
            action="type",
            reason=(
                "Insert the generated report draft into the prepared foreground target app."
            ),
        )
    )
    return _append_report_target_app_verification_step(
        intent,
        allowed,
        next_steps,
        app_name=target_app,
        depends_on="insert-report-into-target-app",
    )


