def _runtime_dispatch_receipt_action(
    tool_name: str | None,
    input_preview: Mapping[str, Any] | None,
) -> str:
    clean_tool = str(tool_name or "").strip()
    if clean_tool not in _RUNTIME_DOV_DISPATCH_RECEIPT_TOOLS:
        return ""
    if clean_tool in _RUNTIME_DOV_MANAGEMENT_DISPATCH_RECEIPT_TOOLS:
        return "dispatch_management"
    payload = input_preview if isinstance(input_preview, Mapping) else {}
    if is_semantic_safe_shortcut(clean_tool, payload):
        return ""
    return "dispatch_shortcut"

_RUNTIME_DOV_TERMINAL_MEDIA_PREPARATION_STEPS = frozenset(
    {
        "focus-media-app-search",
        "type-media-search-query",
        "submit-media-search",
    }
)


def _runtime_dov_step_metadata(step: ToolPlanStepSnapshot) -> dict[str, Any]:
    if not _runtime_dov_step_applies(step):
        return {}
    stage = _runtime_dov_stage(step)
    role = _runtime_dov_role(step, stage)
    requires_post_action_verification = (
        _runtime_dov_step_requires_post_action_verification(step, stage=stage)
    )
    return {
        "runtime_doctrine": "discover_operate_verify",
        "runtime_stage": stage,
        "runtime_role": role,
        "requires_observation": stage in {"discover", "verify"},
        "requires_post_action_verification": requires_post_action_verification,
    }


def _runtime_dov_step_requires_post_action_verification(
    step: ToolPlanStepSnapshot,
    *,
    stage: str,
) -> bool:
    if stage != "operate":
        return False
    # These are implementation steps for one media-search transaction. Their
    # tool failures remain blocking, while the terminal media action owns the
    # playback postcondition (player state / track / playback_ok).
    if str(step.step_id or "").strip() in _RUNTIME_DOV_TERMINAL_MEDIA_PREPARATION_STEPS:
        return False
    tool_name = str(step.tool_name or "").strip()
    action = str(step.action or "").strip()
    if (
        action in {"dispatch_management", "dispatch_shortcut", "dispatch_submit"}
        or tool_name in _RUNTIME_DOV_MANAGEMENT_DISPATCH_RECEIPT_TOOLS
    ):
        return False
    if tool_name.startswith(("app.open_and_", "app.focus_and_")):
        return True
    if tool_name in _RUNTIME_DOV_DESKTOP_POST_ACTION_TOOLS:
        return True
    return action in _RUNTIME_DOV_DESKTOP_POST_ACTION_ACTIONS


def _runtime_dov_step_applies(step: ToolPlanStepSnapshot) -> bool:
    tool_name = str(step.tool_name or "").strip()
    capability_id = str(step.capability_id or "").strip()
    step_id = str(step.step_id or "").strip()
    return bool(
        tool_name.startswith(
            (
                "app.",
                "desktop.",
                "workspace.",
                "data.",
                "artifact.",
                "terminal.",
                "browser.",
                "workflow.",
                "group.",
                "fs.",
                "future_task.",
                "reminders.",
                "calendar.",
                "notification.",
                "clipboard.",
                "media.",
                "system.",
                "notes.",
            )
        )
        or tool_name == "agent.group_run"
        or tool_name == "screen.capture"
        or capability_id.startswith(
            (
                "desktop.",
                "file.",
                "data.",
                "artifact.",
                "terminal.",
                "browser.",
                "workflow.",
                "group.",
                "schedule.",
                "clipboard.",
                "media.",
                "system.",
                "information.",
            )
        )
        or _runtime_dov_code_step_applies(step_id)
    )


def _runtime_dov_code_step_applies(step_id: str) -> bool:
    return bool(
        step_id
        in {
            "inspect-workspace",
            "read-code-target-file",
            "run-code-diagnostic",
            "apply-code-changes",
            "verify-code-changes",
            "run-terminal-command",
            "write-code-report",
        }
        or step_id.startswith("inspect-code-area-")
    )


def _runtime_dov_stage(step: ToolPlanStepSnapshot) -> str:
    step_id = str(step.step_id or "").strip()
    action = str(step.action or "").strip()
    tool_name = str(step.tool_name or "").strip()
    if "verify" in step_id or action == "verify":
        return "verify"
    if tool_name.startswith("browser.") and action in {
        "extract_text",
        "current_page",
        "screenshot",
    }:
        return "discover"
    if action in {"list_files", "read_file", "search"}:
        return "discover"
    if tool_name == "clipboard.read" or action == "read_clipboard":
        return "discover"
    if (
        step_id == "write-code-report"
        or action == "write_artifact"
        or action == "create_note"
        or tool_name == "artifact.write"
        or tool_name == "notes.create"
    ):
        return "produce"
    if step_id == "run-terminal-command":
        return "operate"
    if action in {"apply_patch", "write_file"} or step_id.startswith(
        ("apply-", "insert-", "send-", "submit-", "operate-")
    ):
        return "operate"
    if (
        step_id.startswith(("discover", "inspect", "list-", "read-", "capture-"))
        or action
        in {
            "capture_screen",
            "diagnose_permissions",
            "inspect_app",
            "list_apps",
            "list_windows",
            "read_active_window",
            "read_running_apps",
            "read_ui",
        }
        or step_id.startswith("inspect-code-area-")
        or step_id in {"run-code-diagnostic", "read-code-target-file"}
    ):
        return "discover"
    return "operate"


def _runtime_dov_role(step: ToolPlanStepSnapshot, stage: str) -> str:
    step_id = str(step.step_id or "").strip()
    action = str(step.action or "").strip()
    tool_name = str(step.tool_name or "").strip()
    if stage == "produce":
        if step_id == "write-code-report" or tool_name == "artifact.write":
            return "artifact"
        if action == "create_note" or tool_name == "notes.create":
            return "create_note"
        return "produce_output"
    if stage == "discover":
        if step_id == "run-code-diagnostic":
            return "diagnose"
        if step_id in {"inspect-workspace", "read-code-target-file"} or step_id.startswith(
            "inspect-code-area-"
        ):
            return "inspect_workspace"
        if tool_name.startswith("workspace.") or action in {"read_file", "list_files"}:
            return "inspect_workspace"
        if tool_name.startswith("browser."):
            return "inspect_web_context"
        if action == "list_apps" or "discover_apps" in step_id:
            return "find_target_app"
        if action in {"inspect_app", "read_ui"}:
            return "inspect_ui"
        if action == "list_windows":
            return "inspect_windows"
        if action == "capture_screen":
            return "capture_visual_state"
        return "inspect_desktop_state"
    if stage == "verify":
        return "verify_result"
    if tool_name.startswith("data.") or action.startswith("analyze_"):
        return "analyze_data"
    if step_id == "run-terminal-command" or tool_name == "terminal.run":
        return "execute"
    if tool_name.startswith("browser."):
        if action == "open_url":
            return "open_web_url"
        return "inspect_web_context"
    if tool_name.startswith("workflow.") or action == "start_workflow":
        return "start_workflow"
    if (
        tool_name.startswith("group.")
        or tool_name == "agent.group_run"
        or action == "start_group_run"
    ):
        return "start_group_run"
    if (
        tool_name.startswith(("future_task.", "reminders."))
        or action == "schedule_task"
    ):
        return "schedule_task"
    if tool_name.startswith(("calendar.", "notification.")):
        return "schedule_event"
    if tool_name.startswith("clipboard.") or action in {
        "read_clipboard",
        "write_clipboard",
    }:
        return action or (
            "read_clipboard" if tool_name == "clipboard.read" else "write_clipboard"
        )
    if tool_name.startswith("fs.") or action in {
        "apply_file_changes",
        "move_file",
        "rename_file",
    }:
        return "organize_files"
    if tool_name.startswith("media.") or action == "play":
        return "play_media"
    if tool_name.startswith("system.") or action in {"open_settings", "control_system"}:
        return "open_settings" if action == "open_settings" else "control_system"
    if step_id == "apply-code-changes" or action == "apply_patch":
        return "apply_patch"
    if step_id.startswith("prepare-"):
        return "prepare_target_app"
    if action in {"click", "type", "shortcut", "key", "scroll", "submit"}:
        return f"{action}_ui"
    if action in {"safe_shortcut", "hotkey"}:
        return "shortcut_ui"
    if action in {"safe_key"}:
        return "key_ui"
    if action in {"safe_scroll"}:
        return "scroll_ui"
    if action in {"safe_click"}:
        return "click_ui"
    if action in {"open_app", "focus_app"} or step_id.startswith(("open-", "focus-", "prepare-")):
        return "prepare_target_app"
    if action in {"send_message", "draft_message", "submit_search"}:
        return action
    return "operate_ui"


def _timeline_preview(
    intent: TaskIntentSnapshot,
    steps: list[ToolPlanStepSnapshot],
    task_core: TaskCoreSnapshot | None = None,
) -> list[dict[str, Any]]:
    events = [
        {
            "event_type": "agent.intent.selected",
            "detail": intent.kind,
            "payload": {
                "intent_id": intent.intent_id,
                "confidence": intent.confidence,
                "required_capabilities": list(intent.required_capabilities),
            },
        }
    ]
    events.append(
        {
            "event_type": "agent.plan.created",
            "detail": f"{intent.title} Tool Plan",
            "payload": {
                "plan_id": _stable_id("runtime-plan", intent.kind, intent.user_goal),
                "tool_plan_id": _stable_id("tool-plan", intent.kind, intent.user_goal),
                "step_count": len(steps),
                "approvals_required": [step.step_id for step in steps if step.approval_required],
                "artifacts_expected": _artifacts_expected(intent, steps),
                "route_to_studio": _route_to_studio(intent, steps),
                **_runtime_dov_plan_metadata(steps),
            },
        }
    )
    if task_core is not None:
        events.append(
            {
                "event_type": "agent.task_core.created",
                "detail": task_core.workspace.title,
                "payload": {
                    "core_id": task_core.core_id,
                    "workspace_id": task_core.workspace.workspace_id,
                    "workspace_item_count": len(task_core.workspace.items),
                    "todo_count": len(task_core.todos),
                    "checkpoint_count": len(task_core.checkpoints),
                    "replan_signal_count": len(task_core.replan_signals),
                },
            }
        )
    for index, step in enumerate(steps, start=1):
        events.append(
            {
                "event_type": "agent.plan.step",
                "detail": step.title,
                "payload": {
                    "sequence": index,
                    "step_id": step.step_id,
                    "capability_id": step.capability_id,
                    "tool": step.tool_name,
                    "status": step.status,
                    "approval_required": step.approval_required,
                    **_runtime_dov_step_metadata(step),
                },
            }
        )
    if task_core is not None:
        events.extend(task_core_initial_progress_preview_events(task_core))
    return events


def _clean_prompt(prompt: str) -> str:
    return re.sub(r"\s+", " ", str(prompt or "").strip())


