def _looks_like_report_app_delivery_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if not _contains_any(
        value,
        [
            "report",
            "summary",
            "brief",
            "document",
            "write",
            "output",
            "报告",
            "总结",
            "摘要",
            "文档",
            "周报",
            "日报",
            "月报",
            "纪要",
            "写",
            "输出",
            "生成",
            "整理",
        ],
    ):
        return False
    return bool(
        _app_write_followup_target_hint(value)
        or _discovered_app_write_followup_target_hint(
            value,
            require_data_analysis=False,
        )
    )


def _web_research_artifact_requested(intent: TaskIntentSnapshot) -> bool:
    instruction_text = _web_output_instruction_text(
        intent.user_goal,
        url_hint=str(intent.inputs.get("url_hint") or ""),
        query=str(intent.inputs.get("query") or ""),
    )
    if _task_output_target_hint(instruction_text) == "clipboard":
        return False
    explicit_artifact_request = _contains_any(
        instruction_text,
        [
            "write a report",
            "report file",
            "presentation",
            "outline",
            "markdown",
            "md file",
            "document",
            "artifact",
            "save",
            "export",
            "报告",
            "文档",
            "文件",
            "产物",
            "演示文稿",
            "大纲",
            "保存",
            "导出",
            "生成报告",
            "输出报告",
        ],
    )
    browser_action = str(intent.inputs.get("browser_action") or "").strip()
    click_search_result = (
        browser_action == "open_search"
        and str(intent.inputs.get("followup_action") or "").strip()
        == "click_search_result"
    )
    if (
        browser_action in {"click", "type_text", "open_url_screenshot"}
        or click_search_result
    ) and not explicit_artifact_request:
        return False
    if (
        browser_action in {"current_page", "extract_text", "screenshot"}
        and not explicit_artifact_request
    ):
        return False
    outputs = {
        str(item or "").strip()
        for item in intent.expected_outputs
        if str(item or "").strip()
    }
    # A conversational summary is a presentation mode, not an implicit request
    # to create a durable file. Only artifact-shaped output or explicit
    # save/export/file language should add artifact.write to the plan.
    if outputs.intersection({"report", "table", "links", "presentation"}):
        return True
    return explicit_artifact_request or _contains_any(
        instruction_text,
        [
            "write a report",
            "report",
            "table",
            "markdown",
            "md file",
            "document",
            "artifact",
            "报告",
            "文档",
            "文件",
            "产物",
            "链接清单",
            "链接列表",
            "列出链接",
            "link list",
            "list links",
            "links list",
            "source list",
            "sources",
            "生成报告",
            "输出报告",
            "整理成表格",
            "整理为表格",
            "输出表格",
            "生成表格",
        ],
    )


def _web_search_readback_requested(
    intent: TaskIntentSnapshot,
    *,
    target_app: str,
    target_app_capability: Any,
) -> bool:
    return bool(
        _web_research_artifact_requested(intent)
        or isinstance(intent.inputs.get("communication_target_hint"), Mapping)
        or str(target_app or "").strip()
        or isinstance(target_app_capability, Mapping)
    )


def _code_task_diagnostic_command_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value:
        return {}
    if re.search(r"\b(?:npm|pnpm|yarn)\s+test\b", value, flags=re.IGNORECASE):
        package_runner = re.search(
            r"\b(?P<command>(?:npm|pnpm|yarn)\s+test(?:\s+[^\n。！？!?]*)?)",
            value,
            flags=re.IGNORECASE,
        )
        command = "npm test"
        if package_runner:
            command = str(package_runner.group("command") or "").strip() or command
        return {"command": command}
    if re.search(r"\bpytest\b|pytest\s*失败|pytest\s*报错", value, flags=re.IGNORECASE):
        return {"command": "python -m pytest"}
    if _contains_any(
        value,
        (
            "jest",
            "vitest",
            "javascript tests",
            "typescript tests",
            "js tests",
            "ts tests",
            "node tests",
        ),
    ):
        return {"command": "npm test"}
    if re.search(
        r"(?:run|check|diagnose|fix|repair).{0,40}(?:failing\s+tests?|test\s+failures?|tests?)",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"(?:运行|执行|跑|检查|诊断|修复).{0,40}(?:failing\s+tests?|test\s+failures?|tests?)",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"(?:运行|执行|跑|检查|诊断|修复).{0,24}(?:测试|单测|失败测试|测试失败)",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"(?:测试|单测).{0,16}(?:失败|报错|不过|不通过)",
        value,
        flags=re.IGNORECASE,
    ):
        return {"command": "python -m pytest"}
    return {}


def _looks_like_workspace_code_context_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if _looks_like_external_docs_lookup(value):
        return False
    workspace_subject = _contains_any(
        value,
        (
            "repo",
            "repository",
            "codebase",
            "workspace",
            "this project",
            "current project",
            "this repo",
            "current repo",
            "仓库",
            "代码库",
            "这个项目",
            "当前项目",
            "本项目",
            "工作区",
        ),
    )
    code_target = _contains_any(
        value,
        (
            "code task",
            "entrypoint",
            "entry point",
            "入口",
            "代码",
            "模块",
            "函数",
            "类",
            "文件",
            "readme",
            "docs",
            "documentation",
        ),
    )
    context_action = bool(
        re.search(
            r"(?:read|inspect|review|find|locate|trace|summari[sz]e|explain|"
            r"阅读|查看|检查|审阅|找出|查找|定位|梳理|总结|摘要|解释|说明)",
            value,
            flags=re.IGNORECASE,
        )
    )
    return workspace_subject and (code_target or context_action)


def _looks_like_workspace_file_edit_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value or not _code_task_write_requested(value):
        return False
    file_subject = bool(
        re.search(
            r"\b(?:readme|changelog|license|contributing|agents\.md|"
            r"package\.json|pyproject\.toml|tsconfig\.json|vite\.config|"
            r"docs?/|documentation)\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"[\w./-]+\.(?:md|mdx|txt|py|ts|tsx|js|jsx|json|toml|yaml|yml|css|html)\b",
            value,
            flags=re.IGNORECASE,
        )
        or _contains_any(
            value,
            (
                "安装说明",
                "使用说明",
                "开发说明",
                "配置文件",
                "文档文件",
                "项目文档",
                "仓库文档",
            ),
        )
    )
    workspace_context = _contains_any(
        value,
        (
            "repo",
            "repository",
            "codebase",
            "workspace",
            "project",
            "仓库",
            "代码库",
            "项目",
            "工作区",
        ),
    )
    return file_subject or (workspace_context and _contains_any(value, ("文档", "docs", "documentation")))


def _looks_like_workspace_ui_development_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value or not _code_task_write_requested(value):
        return False
    product_surface = _contains_any(
        value,
        (
            "agent studio",
            "studio",
            "chat",
            "bubble",
            "live2d",
            "workflow",
            "workflows",
            "groups",
            "group run",
            "run timeline",
            "timeline",
            "approval",
            "artifact",
            "AgentTaskCard",
            "Chat",
            "Agent Studio",
            "Workflow",
            "Groups",
            "Run Timeline",
            "页面",
            "界面",
            "组件",
            "按钮",
            "筛选",
            "过滤",
        ),
    )
    development_surface = bool(
        re.search(
            r"(?:page|view|screen|panel|tab|component|card|button|filter|timeline|route|ui|"
            r"页面|界面|视图|面板|标签页|组件|卡片|按钮|筛选|过滤|入口|路由|保存失败)",
            value,
            flags=re.IGNORECASE,
        )
    )
    product_action = bool(
        re.search(
            r"(?:增加|新增|添加|实现|修复|修改|改一下|调整|接入|显示|支持|"
            r"add|implement|fix|modify|change|update|support|show)",
            value,
            flags=re.IGNORECASE,
        )
    )
    return product_surface and development_surface and product_action


def _code_task_area_context_hints(text: str) -> list[dict[str, str]]:
    value = _clean_prompt(text)
    if not value or not _looks_like_workspace_ui_development_request(value):
        return []
    hints: list[dict[str, str]] = []

    def add_hint(path: str, *, pattern: str = "", reason: str = "") -> None:
        if not path:
            return
        hint = {"path": path}
        if pattern:
            hint["pattern"] = pattern
        if reason:
            hint["reason"] = reason
        if hint not in hints:
            hints.append(hint)

    if _contains_any(value, ("agenttaskcard", "agent task card", "chat", "bubble", "live2d")):
        add_hint(
            "apps/frontend/src/features/yachiyo-chat",
            pattern="*AgentTask*",
            reason="Chat, Bubble, Live2D, and AgentTaskCard UI live under yachiyo-chat.",
        )
    if _contains_any(value, ("agent studio", "studio", "agentstudio")):
        add_hint(
            "apps/frontend/src/features/agent-studio",
            pattern="*Studio*",
            reason="Agent Studio views, tabs, and panels live under agent-studio.",
        )
    if _contains_any(value, ("run timeline", "timeline", "时间线")):
        add_hint(
            "apps/frontend/src/features/agent-studio",
            pattern="*Timeline*",
            reason="Run Timeline implementation is part of Agent Studio.",
        )
        add_hint(
            "apps/frontend/src/features/runtime-shared",
            pattern="*Timeline*",
            reason="Shared runtime timeline components live under runtime-shared.",
        )
    if _contains_any(value, ("workflow", "workflows", "工作流")):
        add_hint(
            "apps/frontend/src/features/agent-studio",
            pattern="*Workflow*",
            reason="Workflow management UI is part of Agent Studio.",
        )
    if _contains_any(value, ("groups", "group run", "群组", "多 agent", "multi agent")):
        add_hint(
            "apps/frontend/src/features/agent-studio",
            pattern="*Group*",
            reason="Groups and GroupRun UI are part of Agent Studio.",
        )
    if _contains_any(value, ("approval", "审批")):
        add_hint(
            "apps/frontend/src/features/agent-studio",
            pattern="*Approval*",
            reason="Approval inspectors and request views live under Agent Studio.",
        )
    if _contains_any(value, ("artifact", "产物")):
        add_hint(
            "apps/frontend/src/features/agent-studio",
            pattern="*Artifact*",
            reason="Artifact inspectors live under Agent Studio.",
        )

    if not hints:
        add_hint(
            "apps/frontend/src",
            reason="Inspect frontend source for the requested UI development task.",
        )
    return hints[:4]


_WORKSPACE_NAMED_FILE_RE = re.compile(
    r"(?<![A-Za-z0-9_./:~-])"
    r"(?P<path>(?:\./)?(?:[\w.-]+/)*[\w.-]+"
    r"\.(?:md|mdx|txt|py|ts|tsx|js|jsx|json|toml|yaml|yml|css|html))\b",
    flags=re.IGNORECASE,
)

_WORKSPACE_FILE_READ_ACTION_RE = re.compile(
    r"\b(?:read(?![- ]only\b)|view|inspect)\b|(?:读取|阅读|查看|检查)",
    flags=re.IGNORECASE,
)

_REPORT_ARTIFACT_AUTHORING_ACTION_RE = re.compile(
    r"\b(?:create|write|generate|produce|save|export|output|draft|make)\b|"
    r"(?:创建|新建|生成|写入|写|编写|保存|另存|输出|导出|产出|制作)",
    flags=re.IGNORECASE,
)


def _workspace_named_file_occurrences(
    text: str,
) -> list[tuple[str, int, int]]:
    value = unicodedata.normalize("NFKC", str(text or ""))
    occurrences: list[tuple[str, int, int]] = []
    for match in _WORKSPACE_NAMED_FILE_RE.finditer(value):
        path = normalized_workspace_relative_path(match.group("path"))
        if path and path not in {item[0] for item in occurrences}:
            occurrences.append((path, match.start("path"), match.end("path")))
    return occurrences


def _artifact_path_follows_authoring_action(
    clause: str,
    *,
    action_end: int,
    path_start: int,
) -> bool:
    if path_start < action_end:
        return False
    bridge = clause[action_end:path_start].strip(" \t\r\n\"'`“”‘’：:，,")
    if not bridge:
        return True
    if len(bridge) > 96:
        return False
    if re.fullmatch(
        r"(?:(?:a|an|the|one|new|named|called|file|artifact|report|summary|"
        r"document|markdown|text)\s*)+|"
        r"(?:(?:一个|一份|一篇|新的?|名为|叫|名称为|文件|产物|报告|总结|"
        r"摘要|文档|markdown|文本)\s*)+",
        bridge,
        flags=re.IGNORECASE,
    ):
        return True
    return bool(
        re.search(
            r"(?:\b(?:to|as|into|at|named|called)\b|"
            r"(?:到|至|进|入|为|成|作为|名为|叫|名称为))\s*"
            r"(?:(?:a|an|the|new|file|artifact|report|document|markdown)\s*|"
            r"(?:一个|一份|一篇|新的?|文件|产物|报告|文档)\s*)*$",
            bridge,
            flags=re.IGNORECASE,
        )
    )


def _artifact_path_precedes_authoring_action(
    clause: str,
    *,
    path_start: int,
    path_end: int,
    action_start: int,
) -> bool:
    if path_end > action_start:
        return False
    prefix = clause[:path_start]
    bridge = clause[path_end:action_start].strip(" \t\r\n\"'`“”‘’：:，,")
    return bool(
        re.search(r"(?:^|[\s，把将])(?:在|向)\s*$", prefix)
        and re.fullmatch(r"(?:中|里|内)?", bridge)
    )


def _explicit_workspace_artifact_output_path_hint(text: str) -> str:
    """Return a path syntactically owned by one authorized authoring action."""

    value = unicodedata.normalize("NFKC", str(text or ""))
    if not value.strip():
        return ""
    for action_match in _REPORT_ARTIFACT_AUTHORING_ACTION_RE.finditer(value):
        if not _speech_act_action_occurrence_is_authorized(
            value,
            action_match.start(),
            action_match.end(),
        ):
            continue
        clause_start, clause_end = _speech_act_clause_bounds(
            value,
            action_match.start(),
        )
        clause = value[clause_start:clause_end]
        local_action_start = action_match.start() - clause_start
        local_action_end = action_match.end() - clause_start
        for path, path_start, path_end in _workspace_named_file_occurrences(clause):
            if _artifact_path_follows_authoring_action(
                clause,
                action_end=local_action_end,
                path_start=path_start,
            ) or _artifact_path_precedes_authoring_action(
                clause,
                path_start=path_start,
                path_end=path_end,
                action_start=local_action_start,
            ):
                return path
    return ""


def _explicit_workspace_file_read_target_hint(text: str) -> str:
    """Return an exact workspace-relative file from one authorized read clause.

    The action and path must occur in the same top-level clause.  This avoids
    binding a negated or quoted example to an unrelated affirmative action,
    while URL, absolute, home-relative, and parent-traversal operands stay on
    their existing external/desktop routes.
    """

    value = unicodedata.normalize("NFKC", str(text or ""))
    if not value.strip():
        return ""
    if (
        _desktop_content_artifact_requested(value)
        or _looks_like_document_artifact_transform_request(value)
    ):
        return ""
    for action_match in _WORKSPACE_FILE_READ_ACTION_RE.finditer(value):
        if not _speech_act_action_occurrence_is_authorized(
            value,
            action_match.start(),
            action_match.end(),
        ):
            continue
        clause_start, clause_end = _speech_act_clause_bounds(
            value,
            action_match.start(),
        )
        clause = value[clause_start:clause_end]
        if _explicit_browser_url_hint(clause):
            continue
        if re.search(
            r"(?<![\w.])(?:~[/\\]|(?:\.\.[/\\])+|/[^\s/]|[a-z]:[/\\])",
            clause,
            flags=re.IGNORECASE,
        ):
            continue
        target_path = normalized_workspace_relative_path(
            _code_task_target_file_hint(clause)
        )
        if target_path:
            return target_path
    return ""


def _code_task_target_file_hint(text: str) -> str:
    value = _clean_prompt(text)
    if not value:
        return ""
    explicit_path = re.search(
        r"(?P<path>(?:[\w.-]+/)*[\w.-]+"
        r"\.(?:md|mdx|txt|py|ts|tsx|js|jsx|json|toml|yaml|yml|css|html))\b",
        value,
        flags=re.IGNORECASE,
    )
    if explicit_path:
        return explicit_path.group("path")
    lowered = value.lower()
    named_files = (
        ("readme", "README.md"),
        ("agents.md", "AGENTS.md"),
        ("changelog", "CHANGELOG.md"),
        ("license", "LICENSE"),
        ("package.json", "package.json"),
        ("pyproject.toml", "pyproject.toml"),
        ("tsconfig.json", "tsconfig.json"),
    )
    for marker, path in named_files:
        if marker in lowered:
            return path
    return ""


_CODE_TASK_WRITE_ACTION_RE = re.compile(
    r"\b(?:fix|repair|change|modify|edit|implement|add|create|write|generate|"
    r"scaffold|refactor|patch|update)\b|"
    r"(?:修复|修正|修改|改一下|改成|实现|新增|添加|增加|创建|新建|生成|编写|"
    r"写一个|写个|写出|重构|补上|接入|调整|更新|改造)",
    flags=re.IGNORECASE,
)


def _code_task_write_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    return _text_has_authorized_family_action(
        value,
        _CODE_TASK_WRITE_ACTION_RE,
    )


def _looks_like_contextual_advisory_response(text: str) -> bool:
    """Return true for context-to-advice work without mutation authority.

    Workflow child prompts commonly ask an Agent to turn upstream research or
    design into a proposal, review, or verification plan. Code nouns inside
    that brief describe the response; they do not authorize workspace writes.
    An explicit terminal, file, workspace, or mutation request always wins.
    """

    value = _clean_prompt(text)
    if not value:
        return False
    if (
        terminal_command_hint(value)
        or _looks_like_explicit_terminal_execution_request(value)
        or _code_task_target_file_hint(value)
        or _looks_like_workspace_file_edit_request(value)
        or _looks_like_workspace_ui_development_request(value)
    ):
        return False
    if re.search(
        r"\b(?:fix|repair|edit|modify|patch|refactor|apply|commit|change|update)\b|"
        r"(?:修复|修正|修改|改动|重构|编写|写入|提交|应用补丁|改造|"
        r"落地(?:代码|变更)|实现(?:功能|代码|修复|改动))",
        value,
        flags=re.IGNORECASE,
    ):
        return False
    contextual_source = bool(
        re.search(
            r"\b(?:upstream|research\s+(?:notes?|results?|findings?)|"
            r"provided\s+(?:context|design|notes?)|design\s+(?:constraints?|notes?|results?)|"
            r"global\s+goal)\b|"
            r"(?:上游|研究(?:结果|结论|笔记|资料)|设计(?:结果|约束|方案)|"
            r"全局目标|已有(?:方案|结论|材料))",
            value,
            flags=re.IGNORECASE,
        )
    )
    if not contextual_source:
        return False
    advisory_action = bool(
        re.search(
            r"^(?:based\s+on|using|from|turn|review|assess|propose|outline|"
            r"summari[sz]e|identify|list|explain|provide)\b|"
            r"^(?:基于|根据|结合|审查|评审|整理|提出|给出|列出|识别|说明|总结|拆解)",
            value,
            flags=re.IGNORECASE,
        )
    )
    advisory_output = bool(
        re.search(
            r"\b(?:plan|proposal|review|risks?|tradeoffs?|verification|test\s+gaps?)\b|"
            r"(?:方案|计划|风险|结论|要点|验证|缺失测试|汇报|依据)",
            value,
            flags=re.IGNORECASE,
        )
    )
    return advisory_action and advisory_output


def _looks_like_explicit_terminal_execution_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    return bool(
        re.search(
            r"\b(?:run|execute)\b.{0,48}\b(?:terminal|shell)\s+command\b|"
            r"\b(?:run|execute)\b.{0,48}\bcommand\b.{0,24}\b(?:in|through|via)\s+"
            r"(?:the\s+)?(?:terminal|shell)\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:运行|执行).{0,36}(?:终端|命令行|shell).{0,12}(?:命令|指令)|"
            r"(?:在|通过)(?:终端|命令行|shell).{0,12}(?:运行|执行).{0,24}(?:命令|指令)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_explicit_code_authoring_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value or not _code_task_write_requested(value):
        return False
    if not _contains_any(
        value,
        (
            "code",
            "script",
            "python",
            "javascript",
            "typescript",
            "代码",
            "脚本",
            "程序",
            "编程",
        ),
    ):
        return False
    # Explicit report/document wording owns the route even when its subject is
    # code; otherwise a request to generate executable code must not fall into
    # the generic written-artifact route.
    return not _contains_any(
        value,
        (
            "report",
            "summary",
            "document",
            "brief",
            "报告",
            "总结",
            "文档",
            "简报",
        ),
    )


def _code_task_change_mode(text: str) -> str:
    value = _clean_prompt(text)
    lowered = value.lower()
    if re.search(r"\b(?:create|write|generate|scaffold|add)\b", lowered) or re.search(
        r"(?:新增|添加|增加|创建|新建|生成|编写|写一个|写个|写出)",
        value,
    ):
        return "create"
    if re.search(r"\b(?:refactor|restructure)\b", lowered) or re.search(r"(?:重构|改造)", value):
        return "refactor"
    if re.search(r"\b(?:fix|repair|patch)\b", lowered) or re.search(r"(?:修复|修正|补上)", value):
        return "fix"
    return "modify"


def _score_terms(text: str, terms: Iterable[str]) -> float:
    lowered = text.lower()
    score = 0.0
    for term in terms:
        clean_term = str(term).lower()
        present = (
            bool(
                re.search(
                    rf"(?<![a-z0-9]){re.escape(clean_term)}(?![a-z0-9])",
                    lowered,
                )
            )
            if clean_term == "app"
            else clean_term in lowered
        )
        if present:
            score += 0.08
    return min(score, 0.45)


def _contains_any(text: str, terms: Iterable[str]) -> bool:
    lowered = text.lower()
    return any(str(term).lower() in lowered for term in terms)


def _context_artifact_source_hint(text: str) -> str:
    if _looks_like_visible_text_artifact_source(text):
        return "visible_text"
    source = _task_context_source_hint(text)
    if source:
        return source
    if _looks_like_current_page_artifact_source(text):
        return "current_page_content"
    return ""


def _communication_context_source_hint(text: str) -> str:
    if _looks_like_screen_capture_communication_source(text):
        return "screen_capture"
    if _looks_like_visible_text_artifact_source(text):
        return "visible_text"
    source = _task_context_source_hint(text)
    if source:
        return source
    if _communication_file_context_hint(text):
        return "file"
    if _looks_like_current_page_artifact_source(text):
        return "current_page_content"
    return ""


def _looks_like_screen_capture_communication_source(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if not _contains_any(value, _COMMUNICATION_ACTION_TERMS):
        return False
    return bool(
        re.search(
            r"(?:截图|截屏|屏幕截图|当前截图|当前屏幕截图|当前窗口截图|"
            r"screenshot|screen\s+capture)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _communication_file_context_hint(
    text: str,
    metadata: Mapping[str, Any] | None = None,
) -> dict[str, str]:
    source_hint = str(data_source_hint(text, metadata) or "").strip()
    if source_hint:
        source_scope = str(data_source_scope_hint(text, metadata) or "").strip()
        source_kind = data_source_kind_hint(source_hint, text)
        path = _scoped_data_source_path(source_hint, source_scope)
        hint = _data_source_inspect_input_preview(
            path,
            source_kind,
            selection_hint=_file_open_selection_hint(text),
        )
        if source_kind:
            hint.setdefault("source_kind", source_kind)
        return hint
    file_context = _report_file_context_hint(text)
    if not file_context:
        return {}
    hint: dict[str, str] = {}
    location = str(file_context.get("location") or "").strip()
    if location:
        hint["path"] = location
    for key in ("file_type", "pattern", "selection"):
        value = str(file_context.get(key) or "").strip()
        if value:
            hint[key] = value
    return hint if hint.get("path") or hint.get("pattern") else {}


def _communication_content_transform_hint(text: str) -> str:
    value = _clean_prompt(text)
    if not value:
        return ""
    if _contains_any(value, ("报告", "report", "文档", "document", "markdown", "md")):
        return "report"
    if _contains_any(value, ("摘要", "总结", "概括", "summary", "summarize")):
        return "summary"
    return ""


def _app_search_result_communication_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value or not _contains_any(value, _COMMUNICATION_ACTION_TERMS):
        return {}
    if not _contains_any(
        value,
        (
            "搜索结果",
            "当前结果",
            "查询结果",
            "检索结果",
            "结果",
            "search result",
            "search results",
            "results",
        ),
    ):
        return {}
    target = _app_search_result_communication_target_text(value)
    if not target:
        return {}

    foreground_search = _foreground_app_search_hint(value)
    source_app = ""
    source_scope = ""
    query = ""
    if foreground_search:
        source_scope = "foreground"
        query = str(foreground_search.get("query") or "").strip()
    else:
        source_search = _app_search_result_source_hint(value)
        if source_search:
            source_app = str(source_search.get("app_name") or "").strip()
            query = str(source_search.get("query") or "").strip()
        else:
            leading_search = _leading_app_search_hint(value)
            source_app = str(leading_search.get("app_name") or "").strip()
            query = str(leading_search.get("query") or "").strip()
            if not source_app:
                source_app = _app_name_hint(value)
            if source_app and not query:
                query = _app_search_query_hint(value, source_app)

    query = _clean_app_search_query(query)
    if not query:
        return {}

    target_app, recipient = _split_communication_surface_and_recipient(target)
    if target_app and _looks_like_person_name_communication_target(target):
        target_app = ""
        recipient = _clean_communication_recipient_text(target)
    if not recipient:
        recipient = _clean_communication_recipient_text(target)
    if not target_app and recipient:
        target_app = _communication_surface_for_recipient_hint(recipient)
    if (
        not target_app
        and source_app
        and supports_new_message_app_hint(source_app)
    ):
        target_app = source_app
    if not recipient:
        return {}

    hint: dict[str, str] = {
        "recipient": recipient,
        "body_source": "app_search_result",
        "source_app_search_query": query,
        "mode": _communication_app_mode(value),
        "send_action": _communication_send_action(value),
    }
    if target_app:
        hint["app_name"] = target_app
    if source_app:
        hint["source_app_name"] = source_app
        hint["source_app_mode"] = _app_search_result_source_mode(value)
    if source_scope:
        hint["source_scope"] = source_scope
    transform = _communication_content_transform_hint(value)
    if transform:
        hint["content_transform_hint"] = transform
    return hint


def _app_search_result_source_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value:
        return {}
    search_verb = r"(?:搜索|查找|查询|检索|找(?:到)?)"
    result_noun = r"(?:搜索结果|查询结果|检索结果|结果)"
    delivery_verb = r"(?:发给|发送给|发到|发送到|转发给|转发到)"
    patterns = (
        rf"^(?:把|将)\s*(?:在\s*)?(?P<app>[\w .·-]{{1,60}}?)"
        rf"(?:\s*(?:里|中|上|内))?\s*{search_verb}\s*"
        rf"(?P<query>[^。！？!?，,]+?)\s*(?:的)?{result_noun}"
        rf"[^。！？!?]{{0,40}}?{delivery_verb}",
        r"^(?:send|message|forward)\s+(?:the\s+)?"
        r"(?P<app_en>[A-Za-z][A-Za-z0-9 ._-]{1,60}?)\s+"
        r"(?:search\s+)?results?\s+(?:for|about)\s+"
        r"(?P<query_en>[^.!?,]+?)\s+(?:to|for)\s+",
        r"^(?:send|message|forward)\s+(?:the\s+)?results?\s+of\s+"
        r"(?:searching|finding|looking\s+up)\s+"
        r"(?P<app_result_en>[A-Za-z][A-Za-z0-9 ._-]{1,60}?)\s+"
        r"(?:for|about)\s+(?P<query_result_en>[^.!?,]+?)\s+(?:to|for)\s+",
        r"^(?:summari[sz]e|write|generate|draft)\s+(?:the\s+)?"
        r"(?P<app_transform_en>[A-Za-z][A-Za-z0-9 ._-]{1,60}?)\s+"
        r"(?:search\s+)?results?\s+(?:for|about)\s+"
        r"(?P<query_transform_en>[^.!?,]+?)\s+(?:and\s+)?"
        r"(?:send|message|forward)\s+(?:to|for)\s+",
        r"^(?:open|launch|start|focus)\s+"
        r"(?P<app_open_en>[A-Za-z][A-Za-z0-9 ._-]{1,60}?)\s+"
        r"(?:and\s+)?(?:search|find|look\s+up)\s+(?:for\s+)?"
        r"(?P<query_open_en>[^.!?,]+?)\s+(?:and|then)\s+"
        r"(?:send|message|forward)\s+(?:the\s+)?results?\s+(?:to|for)\s+",
        r"^(?P<app_leading_en>[A-Za-z][A-Za-z0-9 ._-]{1,60}?)\s+"
        r"(?:search|find|look\s+up)\s+(?:for\s+)?"
        r"(?P<query_leading_en>[^.!?,]+?)\s+(?:and|then)\s+"
        r"(?:send|message|forward)\s+(?:the\s+)?results?\s+(?:to|for)\s+",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        app_name = _canonical_app_name_hint(
            groups.get("app")
            or groups.get("app_en")
            or groups.get("app_result_en")
            or groups.get("app_transform_en")
            or groups.get("app_open_en")
            or groups.get("app_leading_en")
            or ""
        )
        query = _clean_app_search_query(
            groups.get("query")
            or groups.get("query_en")
            or groups.get("query_result_en")
            or groups.get("query_transform_en")
            or groups.get("query_open_en")
            or groups.get("query_leading_en")
            or ""
        )
        if (
            app_name
            and query
            and not _invalid_app_scoped_followup_app(app_name)
            and not _is_generic_foreground_app_label(app_name)
        ):
            return {"app_name": app_name, "query": query}
    return {}


def _app_search_result_communication_target_text(text: str) -> str:
    value = _clean_prompt(text)
    patterns = (
        r"(?:把|将)?.{0,40}?(?:搜索结果|当前结果|查询结果|检索结果|结果).{0,30}?"
        r"(?:发给|发送给|发到|发送到|转发给|转发到)\s*(?P<target>[^。！？!?]+)$",
        r"(?:send|message|forward)\s+(?:the\s+)?"
        r"(?:[A-Za-z][A-Za-z0-9 ._-]{1,60}?\s+)?(?:search\s+)?results?\s+"
        r"(?:for|about)\s+[^.!?,]+?\s+(?:to|for)\s+(?P<target_en_scoped>[^.!?]+)$",
        r"(?:send|message|forward)\s+(?:the\s+)?results?\s+of\s+"
        r"(?:searching|finding|looking\s+up)\s+[A-Za-z][A-Za-z0-9 ._-]{1,60}?\s+"
        r"(?:for|about)\s+[^.!?,]+?\s+(?:to|for)\s+(?P<target_en_result>[^.!?]+)$",
        r"(?:summari[sz]e|write|generate|draft)\s+(?:the\s+)?"
        r"[A-Za-z][A-Za-z0-9 ._-]{1,60}?\s+(?:search\s+)?results?\s+"
        r"(?:for|about)\s+[^.!?,]+?\s+(?:and\s+)?"
        r"(?:send|message|forward)\s+(?:to|for)\s+(?P<target_en_transform>[^.!?]+)$",
        r"(?:and|then)\s+(?:send|message|forward)\s+(?:the\s+)?results?\s+"
        r"(?:to|for)\s+(?P<target_en_followup>[^.!?]+)$",
        r"(?:send|message|forward)\s+(?:the\s+)?(?:search\s+)?results?\s+"
        r"(?:to|for)\s+(?P<target_en>[^.!?]+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        return _clean_communication_hint_text(
            match.groupdict().get("target")
            or match.groupdict().get("target_en_scoped")
            or match.groupdict().get("target_en_result")
            or match.groupdict().get("target_en_transform")
            or match.groupdict().get("target_en_followup")
            or match.groupdict().get("target_en")
            or ""
        )
    return ""


def _looks_like_person_name_communication_target(value: str) -> bool:
    text = _clean_communication_hint_text(value)
    if not text:
        return False
    if _communication_surface_for_recipient_hint(text):
        return False
    known_surface_prefixes = (
        "Microsoft Teams",
        "Google Chat",
        "Apple Messages",
        "Messages",
        "Telegram",
        "WhatsApp",
        "Discord",
        "Slack",
        "WeChat",
        "Mail",
    )
    lowered = text.lower()
    if any(
        lowered == surface.lower() or lowered.startswith(surface.lower() + " ")
        for surface in known_surface_prefixes
    ):
        return False
    return bool(re.fullmatch(r"[A-Z][A-Za-z'-]+(?:\s+[A-Z][A-Za-z'-]+)+", text))


def _app_search_result_source_mode(text: str) -> str:
    value = _clean_prompt(text)
    if re.search(r"(?:打开|启动|开启|open|launch|start)", value, flags=re.IGNORECASE):
        return "open"
    return "focus"


def _orchestration_communication_target_hint(text: str, *, body_source: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value or not _contains_any(value, _COMMUNICATION_ACTION_TERMS):
        return {}
    target = _data_analysis_delivery_target_text(value) or _web_research_delivery_target_text(value)
    if not target:
        return {}
    app_name, recipient = _split_communication_surface_and_recipient(target)
    if not recipient:
        recipient = _clean_communication_recipient_text(target)
        if recipient and not app_name:
            app_name = _communication_surface_for_recipient_hint(recipient)
    if not recipient:
        return {}
    hint: dict[str, str] = {
        "recipient": recipient,
        "body_source": body_source,
        "mode": _communication_app_mode(value),
        "send_action": _communication_send_action(value),
    }
    if app_name:
        hint["app_name"] = app_name
    channel = (
        _data_analysis_delivery_channel_hint(value)
        or _communication_delivery_channel_hint(value)
        or _generic_communication_target_channel_hint(target)
    )
    if channel:
        hint["channel"] = channel
    transform = _communication_content_transform_hint(value)
    if not transform and _contains_any(value, ("结论", "conclusion", "findings")):
        transform = "summary"
    if transform:
        hint["content_transform_hint"] = transform
    return hint


def _web_research_communication_target_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value or not _contains_any(value, _COMMUNICATION_ACTION_TERMS):
        return {}
    if not (
        _looks_like_external_info_lookup(value)
        or _contains_any(value, ("调研", "研究", "搜索", "查找", "查询", "检索", "research", "search"))
    ):
        return {}
    target = _web_research_delivery_target_text(value)
    if not target:
        return {}
    app_name, recipient = _split_communication_surface_and_recipient(target)
    if not recipient:
        recipient = _clean_communication_recipient_text(target)
        if recipient and not app_name:
            app_name = _communication_surface_for_recipient_hint(recipient)
    if not recipient:
        return {}
    hint: dict[str, str] = {
        "recipient": recipient,
        "body_source": "research_artifact",
        "mode": _communication_app_mode(value),
        "send_action": _communication_send_action(value),
    }
    if app_name:
        hint["app_name"] = app_name
    channel = _data_analysis_delivery_channel_hint(value) or _generic_communication_target_channel_hint(target)
    if channel:
        hint["channel"] = channel
    transform = _communication_content_transform_hint(value)
    if transform:
        hint["content_transform_hint"] = transform
    return hint


def _web_research_delivery_target_text(text: str) -> str:
    value = _clean_prompt(text)
    patterns = (
        r"(?:把|将)?.{0,80}?(?:报告|摘要|总结|表格|结果|内容|调研|研究|research|report|summary)?"
        r".{0,30}?(?:发给|发送给|发到|发送到|转发给|转发到)\s*(?P<target>[^。！？!?]+)$",
        r"(?:send|message|forward)\s+(?:the\s+)?"
        r"(?:research|report|summary|results?|content)?\s*"
        r"(?:to|for)\s+(?P<target_en>[^.!?]+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        return _clean_communication_hint_text(
            match.groupdict().get("target")
            or match.groupdict().get("target_en")
            or ""
        )
    return ""


def _data_analysis_communication_target_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not _looks_like_data_analysis_delivery_request(value):
        return {}
    target = _data_analysis_delivery_target_text(value)
    if not target:
        return {}
    app_name, recipient = _split_communication_surface_and_recipient(target)
    if not recipient and not app_name:
        recipient = _clean_communication_recipient_text(target)
        if recipient and not app_name:
            app_name = _communication_surface_for_recipient_hint(recipient)
    if not recipient and not app_name:
        return {}
    hint: dict[str, str] = {
        "body_source": "analysis_artifact",
        "mode": _communication_app_mode(value),
        "send_action": "draft" if app_name and not recipient else _communication_send_action(value),
    }
    if recipient:
        hint["recipient"] = recipient
    if app_name:
        hint["app_name"] = app_name
    channel = _data_analysis_delivery_channel_hint(value) or _generic_communication_target_channel_hint(target)
    if channel:
        hint["channel"] = channel
    transform = _communication_content_transform_hint(value)
    if transform:
        hint["content_transform_hint"] = transform
    return hint


def _looks_like_data_analysis_delivery_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if not _data_delivery_send_requested(value):
        return False
    return _data_source_or_output_mentioned(value) and _data_analysis_action_requested(value)


def _looks_like_data_delivery_without_analysis(text: str) -> bool:
    value = _clean_prompt(text)
    if not _data_delivery_send_requested(value):
        return False
    if _data_analysis_action_requested(value):
        return False
    return _data_source_or_output_mentioned(value)


def _data_delivery_send_requested(text: str) -> bool:
    return _contains_any(
        text,
        (
            "发给",
            "发到",
            "发送给",
            "发送到",
            "发邮件",
            "发送邮件",
            "分享给",
            "转发给",
            "send ",
            "email ",
            "share ",
        ),
    )


def _data_source_or_output_mentioned(text: str) -> bool:
    return _contains_any(
        text,
        (
            "数据",
            "数据集",
            "表格",
            "csv",
            "tsv",
            "xlsx",
            "xls",
            "json",
            "parquet",
            "dataset",
            "table",
            "spreadsheet",
        ),
    )


def _data_analysis_app_search_result_source_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value or not _data_analysis_action_requested(value):
        return {}

    foreground_search = _foreground_app_search_hint(value)
    if foreground_search:
        query = _clean_app_search_query(str(foreground_search.get("query") or ""))
        if query:
            return {
                "source_scope": "foreground",
                "source_app_search_query": query,
            }

    parsed = _leading_app_search_hint(value)
    app_name = str(parsed.get("app_name") or "").strip()
    query = _clean_app_search_query(str(parsed.get("query") or ""))
    if not app_name:
        app_name = _app_name_hint(value)
    if app_name and not query:
        app_search = _app_search_hint(value, app_name)
        app_name = str(app_search.get("app_name") or app_name).strip()
        query = _clean_app_search_query(str(app_search.get("query") or ""))
    if (
        not app_name
        or not query
        or _invalid_app_scoped_followup_app(app_name)
        or _is_generic_foreground_app_label(app_name)
        or _is_browser_or_search_app_name(app_name)
    ):
        return {}

    return {
        "source_app_name": app_name,
        "source_app_mode": _app_search_result_source_mode(value),
        "source_app_search_query": query,
    }


def _data_analysis_action_requested(text: str) -> bool:
    value = _clean_prompt(text)
    return _contains_any(
        value,
        (
            "分析",
            "数据分析",
            "统计",
            "汇总",
            "趋势",
            "可视化",
            "图表",
            "报告",
            "分析成",
            "分析为",
            "chart",
            "plot",
            "graph",
            "analyze",
            "analyse",
            "analysis",
            "summary",
            "summarize",
            "trend",
            "report",
        ),
    )


def _looks_like_data_analysis_concept_question(text: str) -> bool:
    value = _clean_prompt(text)
    if not value or not _contains_any(
        value,
        ("data analysis", "data analytics", "数据分析"),
    ):
        return False
    value = re.sub(r"[?？。.!！]+$", "", value).strip()
    if re.fullmatch(
        r"(?:"
        r"what\s+is\s+data\s+(?:analysis|analytics)"
        r"|what\s+does\s+data\s+(?:analysis|analytics)\s+mean"
        r"|how\s+does\s+data\s+(?:analysis|analytics)\s+work"
        r"|(?:define|explain|describe|introduce)\s+(?:the\s+concept\s+of\s+)?"
        r"data\s+(?:analysis|analytics)"
        r"|(?:what|which)\s+(?:methods|techniques|approaches|types|steps|tools)\s+"
        r"(?:are\s+(?:there|used)\s+)?(?:in|for|of)\s+data\s+(?:analysis|analytics)"
        r"|what\s+are\s+(?:the\s+)?(?:methods|techniques|approaches|types|steps|tools)\s+"
        r"(?:of|for)\s+data\s+(?:analysis|analytics)"
        r"|data\s+(?:analysis|analytics)\s+"
        r"(?:methods|techniques|approaches|types|steps|tools)"
        r")",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    return bool(
        re.fullmatch(
            r"(?:"
            r"什么是数据分析"
            r"|数据分析(?:是)?(?:什么|什么意思)"
            r"|数据分析(?:这一)?(?:概念|定义|含义)(?:是)?什么"
            r"|数据分析(?:通常|一般)?(?:有|包括)?哪些(?:常见的)?"
            r"(?:方法|技术|方式|类型|步骤|流程|工具|用途|应用)"
            r"|数据分析(?:通常|一般)?(?:怎么做|如何进行|如何工作)"
            r"|(?:请)?(?:解释|介绍|说明)数据分析(?:这一)?(?:概念)?"
            r")",
            value,
        )
    )


def _app_search_result_analysis_action_requested(
    text: str,
    app_search_result_source: Mapping[str, Any],
) -> bool:
    value = _clean_prompt(text)
    query = str(app_search_result_source.get("source_app_search_query") or "").strip()
    value_outside_query = value.replace(query, "", 1) if query else value
    if _data_analysis_action_requested(value_outside_query):
        return True
    return bool(
        re.search(
            r"(?:并|然后|再|接着|之后|后|\band\s+then\b|\bthen\b)\s*"
            r"(?:帮我|请|please\s+)?"
            r"(?:分析|统计|汇总|可视化|生成(?:图表|报告)?|输出报告|整理成报告|"
            r"analy[sz]e|summari[sz]e|chart|plot|graph|report)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_document_report_analysis_request(
    text: str,
    metadata: Mapping[str, Any] | None = None,
) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if not _contains_any(
        value,
        (
            "分析",
            "解析",
            "总结",
            "摘要",
            "报告",
            "写",
            "生成",
            "analyze",
            "analyse",
            "summarize",
            "summarise",
            "summary",
            "report",
            "write",
        ),
    ):
        return False
    if _contains_any(
        value,
        (
            "数据",
            "数据集",
            "表格",
            "电子表格",
            "报表",
            "明细",
            "统计",
            "可视化",
            "图表",
            "csv",
            "tsv",
            "xlsx",
            "xls",
            "json",
            "jsonl",
            "parquet",
            "dataset",
            "table",
            "spreadsheet",
            "chart",
            "plot",
            "graph",
        ),
    ):
        return False

    file_context = _report_file_context_hint(value)
    file_type = str(file_context.get("file_type") or "").strip().lower()
    if file_type in {"pdf", "docx", "markdown", "text"}:
        return True

    metadata = metadata or {}
    for key in ("attachment", "file", "path"):
        candidate = str(metadata.get(key) or "").strip()
        if _looks_like_document_report_source(candidate):
            return True
    return _looks_like_document_report_source(value)


def _looks_like_document_artifact_transform_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if _contains_any(
        value,
        (
            "数据",
            "数据集",
            "表格",
            "电子表格",
            "csv",
            "tsv",
            "xlsx",
            "xls",
            "json",
            "jsonl",
            "dataset",
            "table",
            "spreadsheet",
        ),
    ):
        return False
    source_hint = (
        _looks_like_meeting_content_task(value)
        or _looks_like_document_report_source(value)
        or bool(_report_file_context_hint(value))
    )
    if not source_hint:
        return False
    return bool(
        re.search(
            r"(?:整理|转换|转|输出|导出|生成|写|保存|另存|format|convert|export|output|write|save)"
            r".{0,24}(?:成|为|as|to)\s*"
            r"(?:markdown|\bmd\b|文档|文件|报告|纪要|摘要|summary|report|document|file)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:输出|导出|生成|写|保存|另存|export|output|write|save)"
            r".{0,24}(?:markdown|\bmd\b|报告|纪要|摘要|summary|report|document)",
            value,
            flags=re.IGNORECASE,
        )
        or (
            _looks_like_meeting_content_task(value)
            and _contains_any(value, ("markdown", "md", "文件", "文档", "纪要", "摘要"))
        )
    )


def _looks_like_document_report_source(value: str) -> bool:
    return bool(
        re.search(
            r"\.(?:pdf|docx?|rtf|pages|md|markdown|txt)\b",
            str(value or ""),
            flags=re.IGNORECASE,
        )
    )


def _data_analysis_delivery_target_text(text: str) -> str:
    value = _clean_prompt(text)
    recipient_stop = (
        r"(?=(?:\s*(?:并|然后|再|之后|后)?\s*"
        r"(?:说明|说|附上|备注|告诉|解释|汇报|概括)|[，,。；;！!？?]|$))"
    )
    patterns = (
        r"(?:然后|并|再|之后|后|同时)?\s*(?:把|将)?"
        r"(?:生成的|这份|这个|分析的|分析)?"
        r"(?:数据分析)?(?:报告|结果|图表报告|图表|csv|CSV|汇总|分析结果|产物|文件)?"
        r"\s*"
        r"(?:(?:发|发送|分享|转发)\s*"
        r"(?:邮件|电子邮件|消息|微信|email|e-mail|mail|message)?\s*"
        r"(?:给|到|发给|发送给|向|对)|(?:发给|发送给|发到|发送到|分享给|转发给))\s*"
        rf"(?P<target>[^，,。；;！!？?\n]+?){recipient_stop}",
        r"(?:send|share)\s+(?:the\s+)?"
        r"(?:(?:analysis|data)\s+)?(?:report|result|results|artifact|chart|csv|table|summary)?"
        r"\s*(?:to|with)\s+(?P<target>[^.!?,;\n]+)",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        target = _clean_communication_hint_text(match.group("target") or "")
        target = re.sub(
            r"\s*(?:并|然后|再|之后|后)\s*(?:发送|发出|send)?$",
            "",
            target,
            flags=re.IGNORECASE,
        ).strip()
        if target:
            return target
    return ""


def _data_analysis_delivery_channel_hint(text: str) -> str:
    value = _clean_prompt(text)
    if re.search(
        r"(?:发|发送|写|撰写|起草|草拟)\s*(?:一封|封)?\s*(?:邮件|电子邮件)"
        r"|(?:send|email|mail)\b",
        value,
        flags=re.IGNORECASE,
    ):
        return "email"
    generic_prefix = r"(?:(?:任意|任何|默认|可用|合适|适合|推荐|已安装)(?:的)?\s*)?"
    app_suffix = (
        r"(?:应用(?:程序)?|app|软件|客户端|工具|程序|client|tool|program)?"
    )
    email_surface = r"(?:邮件|电子邮件|邮箱|mail|email|e-mail)"
    if re.search(
        rf"(?:用|使用|通过|经由|借助|在|到|发到|发送到|分享到|转发到)\s*"
        rf"{generic_prefix}{email_surface}\s*{app_suffix}"
        r"(?:里|中|上|内|里面)?"
        r"(?:\s*(?:发|发送|分享|转发|send|email|mail|forward))?",
        value,
        flags=re.IGNORECASE,
    ):
        return "email"
    message_surface = r"(?:聊天|通讯|通信|消息|即时通讯|短信|chat|messaging|message|messenger)"
    if re.search(
        r"(?:发|发送|分享|转发)\s*(?:一条|条|一则|则)?\s*"
        r"(?:消息|短信|微信|message)\s*(?:给|到|发给|发送给|向|对)",
        value,
        flags=re.IGNORECASE,
    ):
        return "message"
    if re.search(
        rf"(?:用|使用|通过|经由|借助|在|到|发到|发送到|分享到|转发到)\s*"
        rf"{generic_prefix}{message_surface}\s*{app_suffix}"
        r"(?:里|中|上|内|里面)?"
        r"(?:\s*(?:发|发送|分享|转发|send|message|forward))?",
        value,
        flags=re.IGNORECASE,
    ):
        return "message"
    if re.search(
        rf"{generic_prefix}{message_surface}\s*"
        r"(?:应用(?:程序)?|app|软件|客户端|工具|程序|client|tool|program)"
        r".{0,20}?(?:发给|发送给|发到|发送到|分享给|转发给|send|message|forward|to)",
        value,
        flags=re.IGNORECASE,
    ):
        return "message"
    return ""


def _task_context_source_hint(text: str) -> str:
    source = context_source_hint(text)
    if (
        source == "clipboard"
        and _clipboard_output_target_requested(text)
        and not _clipboard_context_source_requested(text)
    ):
        return ""
    return source


def _task_output_target_hint(text: str) -> str:
    return "clipboard" if _clipboard_output_target_requested(text) else ""


def _clipboard_output_target_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    return bool(
        re.search(
            r"(?:复制|拷贝|写入|写回|放到|放进|放回|保存到|保存回|输出到|输出至|输出回|"
            r"复制到|复制回|拷贝到|拷贝回|存到|存回|设为|设置为)"
            r"(?:一下|下)?\s*(?:到|进|至|回)?\s*(?:系统)?(?:剪贴板|粘贴板)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:到|进|至|回)\s*(?:系统)?(?:剪贴板|粘贴板)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:copy|write|put|save|output)\b.{0,80}\b(?:to|into)\s+"
            r"(?:the\s+)?(?:system\s+)?clipboard\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:copy|write|put|save|output)\b.{0,80}\bback\s+to\s+"
            r"(?:the\s+)?(?:system\s+)?clipboard\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:复制|拷贝)(?:一下|下)?(?:分析)?(?:结论|结果|摘要|总结|报告|输出)(?:到剪贴板)?(?:[。.!！]|$)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _clipboard_context_source_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    return bool(
        re.search(
            r"(?:剪贴板|粘贴板).{0,8}(?:内容|里|里面|中的|上|中|里的)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:根据|使用|用|读取|读|从).{0,8}(?:剪贴板|粘贴板)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:clipboard\s+contents?|contents?\s+of\s+(?:the\s+)?clipboard|"
            r"from\s+(?:the\s+)?clipboard|using\s+(?:the\s+)?clipboard)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _clipboard_output_step(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    *,
    depends_on: list[str],
    body_source: str,
) -> ToolPlanStepSnapshot:
    return _step(
        intent,
        "write-clipboard-output",
        "Write clipboard output",
        "clipboard.read_write",
        _first_allowed(("clipboard.write",), allowed),
        input_preview={
            "body_source": body_source,
            "transform": _clipboard_output_transform_hint(intent.user_goal),
        },
        depends_on=depends_on,
        reason="Write the generated task result to the clipboard after inspecting the requested source.",
    )


def _clipboard_output_transform_hint(text: str) -> str:
    value = _clean_prompt(text)
    if _contains_any(value, ("摘要", "总结", "summary", "summarize")):
        return "summary"
    if _contains_any(value, ("报告", "report", "文档", "document")):
        return "report"
    return "text"


def _web_clipboard_body_source(browser_action: str) -> str:
    action = str(browser_action or "").strip()
    if action in {"current_page", "extract_text", "screenshot"}:
        return "current_page_content"
    if action in {"open_url_extract", "open_url_screenshot", "open_url"}:
        return "web_url_content"
    if action == "open_search":
        return "web_search_result"
    return "web_content"


