def _looks_like_archive_extract_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    archive_target = _contains_any(
        value,
        [
            "zip",
            ".zip",
            "rar",
            ".rar",
            "7z",
            ".7z",
            "tar",
            ".tar",
            "gz",
            ".gz",
            "tgz",
            ".tgz",
            "archive",
            "archives",
            "压缩包",
            "归档包",
        ],
    )
    if not archive_target:
        return False
    extract_action = _contains_any(
        value,
        [
            "unzip",
            "decompress",
            "extract archive",
            "extract zip",
            "extract the zip",
            "extract this zip",
            "解压",
            "解压缩",
            "展开压缩包",
        ],
    ) or bool(
        re.search(
            r"\bextract\b.{0,32}\b(?:zip|archive|rar|7z|tar|gz|tgz)\b",
            value,
            flags=re.IGNORECASE,
        )
    )
    if not extract_action:
        return False
    concrete_scope = _contains_any(
        value,
        [
            "download",
            "downloads",
            "desktop",
            "documents",
            "finder",
            "~/",
            "/",
            "下载",
            "桌面",
            "文档",
            "当前",
            "这个",
            "这份",
            "this",
        ],
    ) or bool(_file_open_selection_hint(value))
    if (
        _contains_any(value, ["how to", "guide", "tutorial", "如何", "怎么", "怎样", "教程"])
        and not concrete_scope
    ):
        return False
    local_scope = _contains_any(
        value,
        [
            "download",
            "downloads",
            "desktop",
            "documents",
            "finder",
            "file",
            "folder",
            "directory",
            "下载",
            "桌面",
            "文档",
            "文件",
            "文件夹",
            "目录",
            "当前",
            "这个",
            "这份",
            "this",
        ],
    )
    if local_scope:
        return True
    return _contains_any(value, ["把", "将", "帮我", "请", "please"])


