def _looks_like_multi_agent_request(text: str) -> bool:
    value = _clean_prompt(text)
    lowered = value.lower()
    if re.search(
        r"(?:group|群组|小组|团队|"
        r"(?:研究|调研|写作|分析|设计|开发|工程|审阅|审核|内容|产品|数据|市场|"
        r"运营|测试)(?:组|小组|团队))",
        value,
        flags=re.IGNORECASE,
    ) and re.search(
        r"(?:让|安排|派发|派活|委派|分配|指派|运行|启动|开启|开|创建|新建|"
        r"组建|组成|执行|协作|做|产出|用|通过|调用|选择|一起|"
        r"coordinate|delegate|dispatch|assign|run|start|open|create|execute)",
        value,
        flags=re.IGNORECASE,
    ):
        if _looks_like_timed_schedule_request(value) and not re.search(
            r"(?:agent|Agent|AI|智能体|代理|group|群组|小组|多\s*agent|多Agent)",
            value,
            flags=re.IGNORECASE,
        ):
            return False
        return True
    role_terms = re.search(
        r"(?:研究员|调研员|写作者|作者|分析师|设计师|开发者|工程师|审阅者|审核员|"
        r"(?:研究|调研|写作|分析|设计|开发|工程|审阅|审核|内容|产品|数据|市场|"
        r"运营|测试)(?:组|小组|团队)|"
        r"researcher|writer|analyst|designer|developer|engineer|reviewer)",
        value,
        flags=re.IGNORECASE,
    )
    role_task_terms = re.search(
        r"(?:协作|合作|分别|各自|并行|分工|汇总|产出|生成|输出|报告|分析(?!师)|研究(?!员)|调研|"
        r"总结|比较|评审|撰写|写作(?!者)|"
        r"collaborate|coordinate|parallel|separately|divide|report|analy[sz]e|"
        r"research|summari[sz]e|compare|review|write|produce|deliver)",
        value,
        flags=re.IGNORECASE,
    )
    role_together_task = re.search(
        r"(?:一起|together)",
        value,
        flags=re.IGNORECASE,
    ) and re.search(
        r"(?:产出|生成|输出|报告|分析(?!师)|研究(?!员)|调研|总结|比较|评审|撰写|写作(?!者)|"
        r"produce|deliver|report|analy[sz]e|research|summari[sz]e|compare|review|write)",
        value,
        flags=re.IGNORECASE,
    )
    role_collaboration_marker = re.search(
        r"(?:让|安排|派发|派活|委派|分配|指派|协作|合作|分别|各自|并行|分工|一起|"
        r"两个|两个以上|多个|多位|几位|一组|"
        r"coordinate|delegate|dispatch|assign|collaborate|together|parallel|separately)",
        value,
        flags=re.IGNORECASE,
    )
    if role_terms and (role_together_task or (role_task_terms and role_collaboration_marker)):
        return True
    if re.search(
        r"(?:two|three|multiple|several)\s+(?:agents?|ai\s+agents?)",
        lowered,
        flags=re.IGNORECASE,
    ):
        return True
    if re.search(
        r"(?:两个|两个以上|多个|多位|几位|一组)\s*(?:agent|Agent|AI|智能体|代理)",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    return bool(
        re.search(r"(?:agent|Agent|智能体|代理)", value, flags=re.IGNORECASE)
        and _contains_any(value, ("分别", "各自", "并行", "协作", "分工", "委派", "分配", "指派", "派发"))
    )


