def _explicit_generic_named_app_hint(text: str) -> str:
    value = str(text or "").strip()
    if not value:
        return ""
    patterns = (
        r"(?:打开|启动|开启|运行|拉起|切到|聚焦)\s*"
        r"(?P<opened_app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)"
        r"(?=\s*(?:，|,|。|！|!|？|\?|并|然后|再|接着|之后|后|先|"
        r"搜索|查找|检索|读取|读|查看|看看|点击|点按|输入|写|按|操作|$))",
        r"(?:在|用|通过)\s*"
        r"(?P<scoped_app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)"
        r"(?:里|中|上|内)?\s*"
        r"(?=(?:新建|创建|打开|点击|点按|输入|写|搜索|查找|检索|按|操作|"
        r"create|new|open|click|press|type|search))",
        r"(?:use|using|with)\s+"
        r"(?P<use_app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?=(?:to\s+)?(?:create|new|open|click|press|type|search|write|make))",
        r"(?:打开|启动|开启|运行|拉起|切到|聚焦)?\s*"
        r"(?:一个|一款|这个|那个)?"
        r"(?:(?:我没提过的|我没有提过的|没提过的|没有提过的|从未提过的|"
        r"没见过的|未知的?|陌生的|新的?|刚装的?|新装的?|"
        r"刚安装的?|新安装的?|安装的?)\s*)*"
        r"(?:新\s*)?(?:应用(?:程序)?|app|软件)\s+"
        r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)"
        r"(?=\s*(?:，|,|。|！|!|？|\?|并|然后|再|接着|之后|后|$))",
        r"(?:叫|名叫|名称是|名字是|called|named)\s*"
        r"(?P<called_app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s*"
        r"(?:的)?(?:应用(?:程序)?|app|软件)"
        r"(?=\s*(?:，|,|。|！|!|？|\?|并|然后|再|接着|之后|后|"
        r"\band\b|\bthen\b|\bto\b|\bclick\b|\bpress\b|\btap\b|"
        r"\btype\b|\bsearch\b|\bopen\b|\bcreate\b|\bnew\b|\bwrite\b|$))",
        r"(?:应用(?:程序)?|app|软件)\s*(?:叫|名叫|名称是|名字是|called|named)\s*"
        r"(?P<named_app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)"
        r"(?=\s*(?:，|,|。|！|!|？|\?|并|然后|再|接着|之后|后|"
        r"\band\b|\bthen\b|\bto\b|\bclick\b|\bpress\b|\btap\b|"
        r"\btype\b|\bsearch\b|\bopen\b|\bcreate\b|\bnew\b|\bwrite\b|$))",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        raw_app = next(
            (
                item
                for item in match.groupdict().values()
                if item is not None and str(item).strip()
            ),
            "",
        )
        app = _clean_app_name_hint(raw_app)
        if (
            app
            and not _invalid_app_scoped_followup_app(app)
            and not _is_generic_foreground_app_label(app)
        ):
            return app
    return ""


def _explicit_app_action_target_hint(text: str) -> str:
    app = _clean_app_name_hint(raw_explicit_app_action_target_hint(text))
    if (
        app
        and not _invalid_app_scoped_followup_app(app)
        and not _is_generic_foreground_app_label(app)
    ):
        return app
    return ""


def _explicit_known_app_action_target_hint(text: str) -> str:
    app = _explicit_app_action_target_hint(text)
    if (
        app
        and is_legacy_app_name_hint(app)
        and not _is_generic_browser_app_label(app)
    ):
        return app
    return ""


def _app_name_hint(text: str) -> str:
    system_hint = system_control_hint(affirmative_desktop_action_text(text, "focus"))
    if str(system_hint.get("kind") or "").strip() == "settings_open":
        settings_target = str(
            (system_hint.get("payload") or {}).get("target") or ""
        ).strip()
        if settings_target not in {"", "系统设置"}:
            return ""
    clean_text = _clean_prompt(text)
    if _looks_like_running_apps_request(clean_text, clean_text.lower()):
        return ""
    app_scoped_current_window = _app_scoped_current_window_app_name_hint(text)
    if app_scoped_current_window:
        return app_scoped_current_window
    explicit_generic_named_app = _explicit_generic_named_app_hint(text)
    if explicit_generic_named_app:
        return _clean_app_name_hint(explicit_generic_named_app)
    explicit_known_app = _explicit_known_app_action_target_hint(text)
    if explicit_known_app:
        return explicit_known_app
    if _looks_like_non_desktop_content_task(text):
        return ""
    if _app_capability_discovery_hint(text):
        return ""
    if (
        _looks_like_workspace_code_context_request(text)
        or _looks_like_workspace_file_edit_request(text)
        or _looks_like_workspace_ui_development_request(text)
    ):
        return ""
    if _looks_like_ui_click_advice_request(text):
        return ""
    if re.fullmatch(
        r"(?:press|hit|tap)\s+(?:the\s+)?(?:enter|return|"
        r"(?:command|cmd|control|ctrl|option|alt|shift)(?:\s*[+ ]\s*\w+)?)",
        str(text or "").strip(),
        flags=re.IGNORECASE,
    ):
        return ""
    if _foreground_app_search_hint(text):
        return ""
    explicit_app = _explicit_app_action_target_hint(text)
    if explicit_app and not _is_generic_browser_app_label(explicit_app):
        return explicit_app
    app_click_scope = _app_first_click_scope_hint(text)
    if app_click_scope:
        return str(app_click_scope.get("app_name") or "").strip()
    app_type_scope = _app_first_type_scope_hint(text)
    if app_type_scope:
        return str(app_type_scope.get("app_name") or "").strip()
    if _target_first_foreground_click_hint(text):
        return ""
    if _target_first_foreground_type_hint(text):
        return ""
    patterns = [
        r"^(?:帮我|请|麻烦|能否|能不能|能|可以|可不可以)?(?:直接)?"
        r"(?:切换到|切到|切回|切)(?:一下|下)?\s*"
        r"(?P<focus_app_cn>[\w .·-]{1,40}?)\s*"
        r"(?:吗|嘛|呢|吧|么|可以|可不可以|行不行|好不好|好吗|好么)?[?？。！!]*$",
        r"(?:把|将)\s*(?P<app>[\w .·-]{1,40}?)\s*(?:打开|启动|开启|切到|聚焦)(?:起来|到前台|前台)?",
        r"^(?!(?:在|用|通过|点击|点按|把|将))(?P<app>[\w .·-]{1,40}?)\s*"
        r"(?:打开起来|启动起来|开启起来|开起来|打开|启动|开启|运行|拉起|开)"
        r"(?:一下|下|起来)?\s*(?:吗|嘛|呢|吧|么|可以|可不可以|行不行|好不好|好吗|好么)?[?？。！!]*$",
        r"^(?!(?:在|用|通过|点击|点按|把|将))(?P<app>[\w .·-]{1,40}?)\s*"
        r"(?:切到|切回|切|聚焦|激活)(?:一下|下|到前台|前台)?\s*"
        r"(?:吗|嘛|呢|吧|么|可以|可不可以|行不行|好不好|好吗|好么)?[?？。！!]*$",
        r"(?:go\s+back\s+to|switch\s+back\s+to|back\s+to)\s+(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40})",
        r"^(?:帮我|请|麻烦|能否|能不能|能|可以|可不可以)?(?:直接)?"
        r"(?:打开|启动|开启|运行|拉起|"
        r"开(?!展|发|始|放|会|通|设|创|具|销|源|票|幕|工|课|心))"
        r"(?:一下|下|起来)?\s*"
        r"(?P<polite_app_cn>[\w .·-]{1,40}?)\s*"
        r"(?:这个|那个|该)?(?:应用(?:程序)?|app|软件)?"
        r"(?:吗|嘛|呢|吧|么|可以|可不可以|行不行|好不好|好吗|好么)?[?？。！!]*$",
        r"^(?:帮我|请|麻烦)?(?:找一下|找下|找找|找)\s*"
        r"(?P<find_open_app_cn>[\w .·-]{1,40}?)\s*"
        r"(?:并|然后|再|接着|之后|后)\s*"
        r"(?:打开|启动|开启|运行|拉起|开)(?:一下|下|起来)?"
        r"(?:吗|嘛|呢|吧|么|可以|可不可以|行不行|好不好|好吗|好么)?[?？。！!]*$",
        r"^(?:please\s+)?(?:find|look\s+for)\s+"
        r"(?P<find_open_app_en>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:and|then)\s+(?:open|launch|start(?:\s+up)?)(?:\s+it)?"
        r"(?:\s+for\s+me)?(?:\s+please)?[.!?]*$",
        r"^(?:please\s+)?(?:open|launch|start(?:\s+up)?|focus|activate)\s+"
        r"(?P<polite_app_en>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)"
        r"(?:\s+for\s+me)?(?:\s+please)?[.!?]*$",
        r"(?:can|could|would)\s+you\s+(?:please\s+)?"
        r"(?:open|launch|focus|start(?:\s+up)?)\s+(?P<polite_app>[A-Za-z][A-Za-z0-9 ._-]{1,40})",
        r"(?:open|launch|focus|start)\s+(?:the\s+)?(?:app|application)\s+(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40})",
        r"(?:bring|switch)\s+(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+(?:to\s+(?:the\s+)?(?:front|foreground)|forward)",
        r"(?:activate)\s+(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40})",
        r"^(?!(?:can|could|would|please|pls|search|find|press|hit|tap|type|enter|click|send|submit)\b)"
        r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:open|launch|start|focus|activate)(?:\s+(?:please|pls))?[.!?]*$",
        r"(?:^|[\s，,。])(?:在|用|通过)\s*(?P<app>[\w .·-]{1,40}?)"
        r"(?:里|中|上|内)?\s*(?:打开|启动|开启|运行|查看|编辑)(?:\s+|(?=[^。！？!?，,]))",
        r"(?:open|launch|focus|start)\s+(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40})",
        r"(?:打开|启动|切到|聚焦)\s*(?P<app>[\w .·-]{1,40})",
        r"^(?!(?:在|用|通过|点击|点按))(?P<app>[\w .·-]{2,40}?)\s*点(?!名)\s*[^。！？!?，,]+",
        r"^(?!(?:在|用|通过|点击|点按|把|将))(?P<app>[\w .·-]{1,40}?)"
        r"(?:关闭|隐藏|最小化|退出)(?:窗口|应用|app|application)?",
        r"^(?!(?:在|用|通过|点击|点按))(?P<app>[\w .·-]{1,40}?)"
        r"(?:按|敲|tap|press|hit).{0,8}(?:回车|return|enter)",
        r"(?:in|inside|within|using|with)\s+"
        r"(?:(?:an?|the)\s+)?(?:app|application|software)\s+"
        r"(?:called|named)\s+(?P<named_app_en_early>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)"
        r"(?:\s+(?:to|and|then|click|press|type|search|open|create|write|play|analyze|analyse)|[.!?,]|$)",
        r"^(?!(?:can|could|would|please|pls|search|find|open|launch|focus|start|"
        r"press|hit|tap|type|enter|click|send|submit)\b)"
        r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:点击|点按|按|输入|搜索|查找|click|press|tap|type|enter|search)\b",
        r"^(?!(?:在|用|通过|点击|点按))(?P<app>[\w .·-]{1,40}?)(?:点击|点按)",
        r"(?:^|[\s，,。])(?:在|用|通过)\s*(?:一个|一款|这个|那个)?"
        r"(?:叫|名叫|名称是|名字是)\s*(?P<named_app_cn>[\w .·-]{1,40}?)"
        r"\s*(?:的)?(?:应用(?:程序)?|软件)?(?:里|中|上|内)?"
        r"(?:打开|启动|点击|点按|按|输入|搜索|查找|检索|找|播放|创建|新建|写|发送|分析|操作|帮|$)",
        r"(?:in|inside|within|using|with)\s+(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)(?:\s+(?:to|and|then|click|press|type|search|open|create|write|play|analyze|analyse)|[.!?,]|$)",
        r"(?:^|[\s，,。])(?:在|用|通过)\s*(?P<app>[\w .·-]{1,40}?)(?:里|中|上|内|来|去|打开|启动|点击|点按|按|输入|搜索|查找|检索|找|播放|创建|新建|写|发送|分析|操作|帮|$)",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if not match:
            continue
        raw_app = next(
            (
                item
                for item in match.groupdict().values()
                if item is not None and str(item).strip()
            ),
            "",
        )
        app = _clean_app_name_hint(raw_app)
        if (
            app
            and not _invalid_app_scoped_followup_app(app)
            and not _is_generic_foreground_app_label(app)
        ):
            return app
    return ""


def _looks_like_non_desktop_content_task(text: str) -> bool:
    value = str(text or "").strip()
    if not value:
        return False
    # A content verb can describe the action to perform *inside* a discovered
    # application (for example, "create a document in an app that can write
    # markdown").  Preserve that explicit desktop scope before considering the
    # same verb as an unscoped model-only authoring request.
    if _app_capability_discovery_hint(value):
        return False
    if _looks_like_unscoped_content_generation_task(value):
        return True
    if not re.match(
        r"^(?:summari[sz]e|write|draft|create|produce|generate|"
        r"analy[sz]e|review|compare|explain)\b",
        value,
        flags=re.IGNORECASE,
    ):
        return False
    return bool(
        re.search(
            r"\b(?:launch|release|market|business|project|product|risk|plan|"
            r"strategy|report|analysis|summary|notes?|proposal|brief|"
            r"current\s+(?:web\s+)?page|web\s*page|visible\s+text|"
            r"selected\s+text|selection)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


_MODEL_GENERATED_CHINESE_CONTENT_NOUN = (
    r"(?:诗(?:歌)?|信件|(?:道歉|感谢|邀请|求职|辞职|推荐|慰问|告别|情书)?信(?!息|号|用|任)|"
    r"邮件|文章|作文|故事|报告|文案|方案|计划|总结|摘要|简历|提纲|大纲|"
    r"说明|介绍|脚本|演讲稿|歌词|回复)"
)
_MODEL_GENERATED_ENGLISH_CONTENT_NOUN = (
    r"(?:poem|letter|email|story|essay|article|report|proposal|brief|plan|summary|"
    r"outline|script|speech|copy|bio|introduction|lyrics|reply)"
)
_MODEL_GENERATED_CHINESE_AUTHORING_VERB = (
    r"(?:写(?!入|下)|撰写|起草|拟写|生成|创作|产出|输出|制作)"
)
_MODEL_GENERATED_ENGLISH_AUTHORING_VERB = (
    r"(?:write|draft|compose|create|produce|generate)"
)


def _authoring_brief_requires_model_generation(
    brief: str,
    *,
    verb: str,
    language: str,
) -> bool:
    """Classify an authoring operand by syntax, not a closed noun list.

    ``type``/``enter`` are literal-input verbs elsewhere in the parser.  An
    authoring verb is model work when its operand has natural-language shape;
    a bare ASCII token such as ``hello`` remains compatible with the legacy
    literal shortcut unless the user explicitly asks the model to draft it.
    """

    value = _clean_foreground_compose_text(brief)
    if not value or _looks_like_discovered_app_capability_phrase(value):
        return False
    clean_verb = str(verb or "").strip().lower()
    if language == "zh":
        if clean_verb != "写":
            return True
        if re.search(r"[\u3400-\u9fff]", value):
            return True
        return bool(
            re.search(
                _MODEL_GENERATED_CHINESE_CONTENT_NOUN,
                value,
                flags=re.IGNORECASE,
            )
        )
    if clean_verb != "write":
        return True
    if re.match(r"^(?:a|an|the|some|one|two|three|several)\b", value, flags=re.IGNORECASE):
        return True
    if re.search(
        rf"\b{_MODEL_GENERATED_ENGLISH_CONTENT_NOUN}\b",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    return len(re.findall(r"[A-Za-z]+", value)) > 1


def _authoring_match_uses_literal_delimiter(match: re.Match[str]) -> bool:
    raw = str(match.groupdict().get("raw_brief") or "")
    return bool(re.match(r"\s*(?:[:：]|[\"'`“‘])", raw))


def _model_generated_content_phrase_brief(
    text: str,
    *,
    anchored: bool = False,
) -> str:
    """Return a creative-content brief without treating literal typing as generation.

    The same semantic vocabulary is used for both unscoped routing and app-scoped
    model follow-up. Keeping it centralized prevents one entry point from typing a
    short creative brief while another correctly asks the model to author it.
    """

    value = _clean_prompt(text)
    if not value:
        return ""
    chinese_prefix = (
        r"^(?:帮我|请|麻烦(?:你)?|给我)?\s*"
        if anchored
        else ""
    )
    chinese_pattern = (
        chinese_prefix
        + rf"(?P<verb>{_MODEL_GENERATED_CHINESE_AUTHORING_VERB})"
        + r"(?P<raw_brief>\s*[^。！？!?，,]{1,120})"
    )
    for chinese_match in re.finditer(chinese_pattern, value, flags=re.IGNORECASE):
        if _authoring_match_uses_literal_delimiter(chinese_match):
            continue
        brief = _clean_foreground_compose_text(chinese_match.group("raw_brief"))
        if _authoring_brief_requires_model_generation(
            brief,
            verb=chinese_match.group("verb"),
            language="zh",
        ):
            return brief
    english_prefix = (
        r"^(?:please\s+|could\s+you\s+|can\s+you\s+)?"
        if anchored
        else ""
    )
    english_pattern = (
        english_prefix
        + rf"\b(?P<verb_en>{_MODEL_GENERATED_ENGLISH_AUTHORING_VERB})\b"
        + r"(?P<raw_brief>\s*[^.!?,]{1,160})"
    )
    for english_match in re.finditer(english_pattern, value, flags=re.IGNORECASE):
        if _authoring_match_uses_literal_delimiter(english_match):
            continue
        brief = _clean_foreground_compose_text(english_match.group("raw_brief"))
        if _authoring_brief_requires_model_generation(
            brief,
            verb=english_match.group("verb_en"),
            language="en",
        ):
            return brief
    return ""


def _looks_like_unscoped_content_generation_task(text: str) -> bool:
    value = str(text or "").strip()
    if not value:
        return False
    if _contains_any(
        value,
        (
            "输入框",
            "文本框",
            "搜索框",
            "搜索栏",
            "消息框",
            "聊天框",
            "地址栏",
            "前台",
            "当前窗口",
            "current window",
            "foreground",
            "search field",
            "message field",
            "address bar",
            "input field",
            "text box",
        ),
    ):
        return False
    return bool(_model_generated_content_phrase_brief(value, anchored=True))


def _app_first_click_scope_hint(text: str) -> dict[str, Any]:
    value = str(text or "").strip()
    patterns = (
        r"^(?:双击|点击|点一下|点按|单击|按一下|按(?!钮)|点(?!击|按|一下))\s*"
        r"(?P<app_cn_post>[\w .·-]{1,40}?)(?:的|里|中|上|内|里面|中的|里的|上的|内的)\s*"
        r"(?P<target_cn_post>[^。！？!?，,]{1,40}?"
        r"(?:按钮|控件|元素|菜单项|菜单|复选框)?)$",
        r"^(?:double\s+click|click|press|tap)\s+(?:the\s+)?"
        r"(?P<target_en_post>[^.!?,]{1,40}?"
        r"(?:button|menu\s+item|menu|checkbox)?)\s+"
        r"(?:in|on|inside|within)\s+(?:the\s+)?"
        r"(?P<app_en_post>[A-Za-z][A-Za-z0-9 ._-]{1,40})$",
        r"^(?!(?:in|inside|within|using|with)\b)(?P<app>[A-Za-z][A-Za-z0-9_-]{1,40})\s+"
        r"(?P<target>[^。！？!?，,]{1,40}?"
        r"(?:button|menu\s+item|menu|checkbox))\s*"
        r"(?P<verb>click|press|tap)$",
        r"^(?!(?:in|inside|within|using|with)\b)(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?P<target>[^。！？!?，,]{1,40}?"
        r"(?:按钮|控件|元素|菜单项|菜单|复选框|button|menu\s+item|menu|checkbox))\s*"
        r"(?P<verb>双击|点击|点一下|点按|单击|click|press|tap)$",
        r"^(?!(?:在|用|通过|点击|点按))(?P<app>[\w .·-]{2,40}?)\s+"
        r"(?P<target>[^。！？!?，,]{1,40}?"
        r"(?:按钮|控件|元素|菜单项|菜单|复选框))\s*"
        r"(?P<verb>双击|点击|点一下|点按|单击)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        raw_app = (
            groups.get("app")
            or groups.get("app_cn_post")
            or groups.get("app_en_post")
            or ""
        )
        if _is_generic_foreground_app_label(raw_app):
            continue
        app_name = _clean_app_name_hint(raw_app)
        if not app_name or _is_generic_foreground_app_label(app_name):
            continue
        raw_target = (
            groups.get("target")
            or groups.get("target_cn_post")
            or groups.get("target_en_post")
            or ""
        )
        target = clean_type_target(raw_target, app_name=app_name) or raw_target.strip()
        target = re.sub(r"^(?:的|上(?:的)?|里(?:的)?|中(?:的)?|内(?:的)?)\s*", "", target).strip()
        if _generic_click_target_label(target):
            continue
        verb = groups.get("verb") or (
            "click" if groups.get("target_en_post") else "点击"
        )
        target_request = (
            click_target_hint(f"{verb} {raw_target}")
            if re.fullmatch(r"(?:click|press|tap)", verb, flags=re.IGNORECASE)
            else click_target_hint(f"{raw_target} {verb}")
        )
        if not target_request:
            continue
        return {"app_name": app_name, "click_target": target_request}
    return {}


def _target_first_foreground_click_hint(text: str) -> bool:
    value = str(text or "").strip()
    return bool(
        re.fullmatch(
            r"[A-Za-z][A-Za-z0-9 ._-]{1,40}?\s+"
            r"(?:button|menu\s+item|menu|checkbox)\s+"
            r"(?:click|press|tap)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _app_first_type_scope_hint(text: str) -> dict[str, Any]:
    value = str(text or "").strip()
    patterns = (
        r"^(?:打开|启动|开启|切到|聚焦)\s*(?P<app>[\w .·-]{1,40}?)(?:的|里|中|上|内|在)\s*"
        r"(?P<target>[^。！？!?，,]{0,40}?"
        r"(?:搜索框|搜索栏|消息框|聊天框|地址栏|输入框|文本框|输入栏))\s*"
        r"(?:输入|键入|填写|填入|写入|写|填)\s*(?P<text>[^。！？!?，,]+)$",
        r"^(?:打开|启动|开启|切到|聚焦)\s*(?P<app>[\w .·-]{1,40}?)"
        r"(?P<target>搜索框|搜索栏|消息框|聊天框|地址栏)\s*"
        r"(?:输入|键入|填写|填入|写入|写|填)\s*(?P<text>[^。！？!?，,]+)$",
        r"^(?:打开|启动|开启|切到|聚焦)\s*(?P<app>[\w .·-]{1,40}?)\s+"
        r"(?P<target>[^。！？!?，,]{0,40}?"
        r"(?:搜索框|搜索栏|消息框|聊天框|地址栏|输入框|文本框|输入栏))\s*"
        r"(?:输入|键入|填写|填入|写入|写|填)\s*(?P<text>[^。！？!?，,]+)$",
        r"^(?:在|用|通过)\s*(?P<app>[\w .·-]{1,40}?)(?:里|中|上|内|的|上的)\s*"
        r"(?P<target>[^。！？!?，,]{0,40}?"
        r"(?:搜索框|搜索栏|消息框|聊天框|地址栏|输入框|文本框|输入栏))\s*"
        r"(?:输入|键入|填写|填入|写入|写|填)\s*(?P<text>[^。！？!?，,]+)$",
        r"^(?:在|用|通过)\s+(?P<app>[\w .·-]{2,40}?)\s+"
        r"(?P<target>[^。！？!?，,]{0,40}?"
        r"(?:搜索框|搜索栏|消息框|聊天框|地址栏|输入框|文本框|输入栏))\s*"
        r"(?:输入|键入|填写|填入|写入|写|填)\s*(?P<text>[^。！？!?，,]+)$",
        r"^(?!(?:在|用|通过|点击|点按|把|将))(?P<app>[\w .·-]{2,40}?)(?:的|里|中|上|内|在)\s*"
        r"(?P<target>[^。！？!?，,]{0,40}?"
        r"(?:搜索框|搜索栏|消息框|聊天框|地址栏|输入框|文本框|输入栏))\s*"
        r"(?:输入|键入|填写|填入|写入|写|填)\s*(?P<text>[^。！？!?，,]+)$",
        r"^(?!(?:在|用|通过|点击|点按|把|将))(?P<app>[\w .·-]{2,40}?)\s+"
        r"(?P<target>[^。！？!?，,]{0,40}?"
        r"(?:搜索框|搜索栏|消息框|聊天框|地址栏|输入框|文本框|输入栏))\s*"
        r"(?:输入|键入|填写|填入|写入|写|填)\s*(?P<text>[^。！？!?，,]+)$",
        r"^(?!(?:in|inside|within|using|with)\b)(?P<app>[A-Za-z][A-Za-z0-9_-]{1,40})\s+"
        r"(?P<target>[^.!?,]{0,40}?"
        r"(?:search box|search field|message field|address bar|input field|text box|input|field))\s+"
        r"(?:type|enter|fill)\s+(?P<text>[^.!?,]+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        app_name = _canonical_app_name_hint(match.group("app"))
        if not app_name:
            continue
        raw_target = match.group("target")
        target = _clean_app_first_type_target(raw_target, app_name=app_name)
        if _generic_type_target_label(target):
            continue
        typed_text = clean_followup_text(match.group("text"))
        if not target or not typed_text:
            continue
        return {
            "app_name": app_name,
            "type_target": {
                "target": target,
                "text": typed_text,
                "role_filter": "text",
            },
        }
    return {}


def _clean_app_first_type_target(value: str, *, app_name: str) -> str:
    target = str(value or "").strip(" .，,。")
    clean_app = str(app_name or "").strip()
    if clean_app and target.lower().startswith(clean_app.lower()):
        target = target[len(clean_app) :].strip(" .，,。")
    target = re.sub(
        r"^(?:打开|启动|开启|切到|聚焦|open|launch|focus|switch\s+to)\s*",
        "",
        target,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    target = re.sub(
        r"^(?:(?:在|用|通过)\s+|(?:in|inside|within|using|with)\s+)",
        "",
        target,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    target = re.sub(r"^(?:的|在|里|中|上|内|上的|里的|中的|内的)\s*", "", target)
    target = re.sub(
        r"^(?:点击|点一下|点按|单击|按一下|按|click|press|tap)\s*",
        "",
        target,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    if re.fullmatch(
        r"(?:搜索框|搜索栏|消息框|聊天框|地址栏|input field|search box|search field|message field|address bar|text box)",
        target,
        flags=re.IGNORECASE,
    ):
        return clean_type_target(f"{app_name} {target}", app_name=app_name) or target
    target = re.sub(
        r"\s*(?:搜索框|搜索栏|消息框|聊天框|地址栏|输入框|文本框|输入栏|"
        r"search box|search field|message field|address bar|input field|text box|input|field)$",
        "",
        target,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    if not target:
        return clean_type_target(value, app_name=app_name)
    if re.fullmatch(r"(?:搜索|search)", target, flags=re.IGNORECASE):
        return "search" if re.search(r"[A-Za-z]", target) else "搜索"
    if re.fullmatch(r"(?:消息|message)", target, flags=re.IGNORECASE):
        return "message" if re.search(r"[A-Za-z]", target) else "消息"
    if re.fullmatch(r"(?:地址|address)", target, flags=re.IGNORECASE):
        return "address" if re.search(r"[A-Za-z]", target) else "地址"
    return target


def _target_first_foreground_type_hint(text: str) -> bool:
    value = str(text or "").strip()
    return bool(
        re.fullmatch(
            r"[A-Za-z][A-Za-z0-9 ._-]{1,40}?\s+"
            r"(?:search box|search field|message field|address bar|input field|text box|input|field)\s+"
            r"(?:type|enter|fill)\s+[^.!?,]+",
            value,
            flags=re.IGNORECASE,
        )
        or re.fullmatch(
            r"[\w .·-]{1,40}?"
            r"(?:搜索框|搜索栏|消息框|聊天框|地址栏|输入框|文本框|输入栏|"
            r"收件人|发件人|联系人|主题|标题|姓名|名称|邮箱|邮件地址|电话|用户名|账号|账户|密码)\s*"
            r"(?:输入|键入|填写|填入|写入|写|填)\s*[^。！？!?，,]+",
            value,
            flags=re.IGNORECASE,
        )
    )


def _generic_click_target_label(value: str) -> bool:
    compact = re.sub(r"[\s._·-]+", "", str(value or "").strip().lower())
    return compact in {"", "button", "menu", "menuitem", "checkbox", "按钮", "控件", "元素", "菜单", "菜单项", "复选框"}


def _generic_type_target_label(value: str) -> bool:
    compact = re.sub(r"[\s._·-]+", "", str(value or "").strip().lower())
    return compact in {
        "",
        "input",
        "field",
        "inputfield",
        "textbox",
        "输入框",
        "文本框",
        "输入栏",
    }


def _app_first_control_app_name_hint(text: str) -> str:
    value = str(text or "").strip()
    if re.search(r"://|(?:^|\s)[\w-]+\.[A-Za-z]{2,}(?:/|\s|$)", value):
        return ""
    if not re.search(
        r"(?:打开起来|启动起来|开启起来|开起来|打开|启动|开启|运行|拉起|开|"
        r"切到|切回|聚焦|激活|open|launch|start|focus|activate)\s*"
        r"(?:一下|下|起来|到前台|前台|please|pls)?[?？。！!.]*$",
        value,
        flags=re.IGNORECASE,
    ):
        return ""
    return _app_name_hint(value)


def _clean_app_name_hint(value: str) -> str:
    raw_app = str(value or "").strip()
    raw_app = re.split(
        r"[。！!？?;\n]|\.\s+(?=(?:do\s+not|don['’]t|dont|then|reply|"
        r"click|type|input|press|open|launch|focus|switch)\b)",
        raw_app,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0].strip(" .，,。")
    raw_app = re.sub(
        r"\s+(?:(?:only|just)\s+)?(?:in|into)\s+(?:the\s+)?background\b.*$",
        "",
        raw_app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    raw_app = re.sub(
        r"\s+without\b.*$",
        "",
        raw_app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    folder_aliases = {"folder", "folders", "afolder", "directory", "directories", "文件夹", "目录"}
    if compact_app_name_hint(raw_app) in folder_aliases:
        return "Finder"
    polite_legacy_app = re.sub(
        r"\s*(?:这个|那个|该|好|可以|行)$",
        "",
        raw_app,
        flags=re.IGNORECASE,
    ).strip()
    if polite_legacy_app != raw_app and is_legacy_app_name_hint(polite_legacy_app):
        return polite_legacy_app.strip(" .，,。")
    if is_legacy_app_name_hint(raw_app):
        return raw_app.strip(" .，,。")
    scoped_raw_app = re.sub(
        r"^(?:在|用|通过)\s*",
        "",
        raw_app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    if compact_app_name_hint(scoped_raw_app) in folder_aliases:
        return "Finder"
    if scoped_raw_app != raw_app and is_legacy_app_name_hint(scoped_raw_app):
        return scoped_raw_app.strip(" .，,。")
    app = re.split(
        r"(?:并|然后|再|接着|之后|后|播放|点击|点按|点|按|输入|粘贴|搜索|创建|新建|重命名|上一级|显示简介|查看简介|快速查看|快速预览|预览|复制选中|写|发送|回车|确认|提交|分析|操作|查看|看看|看一下|看下|观察|识别|有没有|是否|可以|可不可以|行不行|好不好|好吗|好么|\b(?:and|then|to|paste|thanks)\b)",
        raw_app,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    if compact_app_name_hint(app) in folder_aliases:
        return "Finder"
    if is_legacy_app_name_hint(app):
        return app.strip(" .，,。")
    app = re.sub(r"\s*(?:并|然后|再|接着|之后|后|and|then)\s*$", "", app, flags=re.IGNORECASE).strip()
    app = re.sub(r"^(?:the\s+)?", "", app, flags=re.IGNORECASE).strip(" .，,。")
    app = re.sub(
        r"^(?:帮我|请|麻烦|能否|能不能|可以|直接)\s*",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(
        r"^(?:把|将)\s*(?:在|用|通过)?\s*",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(
        r"^(?:打开|启动|开启|运行|拉起|切到|聚焦)\s*",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(
        r"^(?:open|launch|start|focus|activate|switch\s+to)\s+",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    bring_up_match = re.fullmatch(
        r"bring\s+(?P<app>.+?)\s+up",
        app,
        flags=re.IGNORECASE,
    )
    if bring_up_match:
        app = bring_up_match.group("app").strip(" .，,。")
    scoped_called_app_match = re.match(
        r"^(?:一个|一款|这个|那个)?"
        r"(?:(?:我(?:的)?(?:电脑|mac|机器|系统)?|本机|本地)(?:上|里|中|内)?(?:的)?\s*)?"
        r"(?:(?:我)?(?:刚|新)?装(?:的)?|刚安装(?:的)?|新安装(?:的)?|安装(?:的)?)?\s*"
        r"(?:叫|名叫|名称是|名字是)\s*(?P<app>.+?)\s*(?:的)?(?:应用(?:程序)?|软件)?$",
        app,
        flags=re.IGNORECASE,
    )
    if scoped_called_app_match:
        app = scoped_called_app_match.group("app")
    app = re.sub(
        r"^(?:我(?:的)?(?:电脑|mac|机器|系统)(?:上|里|中|内)?(?:的)?|"
        r"本机(?:上|里|中|内)?(?:的)?|本地(?:的)?)\s*",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    called_app_match = re.match(
        r"^(?:一个|一款|这个|那个)?(?:叫|名叫|名称是|名字是)\s*(?P<app>.+?)\s*(?:的)?(?:应用(?:程序)?|软件)$",
        app,
        flags=re.IGNORECASE,
    )
    if called_app_match:
        app = called_app_match.group("app")
    english_called_app_match = re.match(
        r"^(?:(?:an?|the)\s+)?(?:app|application|software)\s+"
        r"(?:called|named)\s+(?P<app>.+?)$",
        app,
        flags=re.IGNORECASE,
    )
    if english_called_app_match:
        app = english_called_app_match.group("app")
    owned_app_instance_match = re.fullmatch(
        r"^(?:一个|一款|这个|那个)?\s*"
        r"(?:由\s*(?:Agent|Runtime|智能体|代理(?:程序)?|助手|系统)\s*"
        r"(?:(?:单独|独立|专属)\s*)?(?:拥有|控制|管理)(?:的)?)\s*"
        r"(?:新(?:的)?\s*)?(?P<owned_app>.+?)\s*"
        r"(?:应用(?:程序)?|软件)?\s*(?:实例|窗口|副本|进程)$",
        app,
        flags=re.IGNORECASE,
    )
    if owned_app_instance_match:
        app = owned_app_instance_match.group("owned_app")
    english_owned_app_instance_match = re.fullmatch(
        r"^(?:(?:an?|the)\s+)?"
        r"(?:(?:agent|assistant|runtime)[ -]owned\s+)?"
        r"(?:new\s+)?(?P<owned_app_en>.+?)\s+"
        r"(?:(?:app|application)\s+)?(?:instance|window|process|copy)$",
        app,
        flags=re.IGNORECASE,
    )
    if english_owned_app_instance_match:
        app = english_owned_app_instance_match.group("owned_app_en")
    app = re.sub(
        r"^(?:一个|一款|这个|那个)?"
        r"(?:任意(?:的)?|(?:(?:我)?(?:没|没有)提过的|从未提过的|没见过的|未知(?:的)?|陌生的|新(?:的)?|"
        r"(?:我)?(?:刚|新)?装(?:的)?|刚安装(?:的)?|新安装(?:的)?|安装(?:的)?))\s*"
        r"(?:新\s*)?(?:应用(?:程序)?|软件)?"
        r"(?:\s*(?:叫|名叫|名称是|名字是))?\s*",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(
        r"^(?:(?:an?|the)\s+)?"
        r"(?:(?:any|new|unknown|unmentioned|unfamiliar)\s+)+"
        r"(?:(?:app|application|software)\s+)?"
        r"(?:(?:called|named)\s+)?",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.split(
        r"\s*(?:(?:的|里(?:的)?|中(?:的)?|上(?:的)?|内(?:的)?)\s*)?"
        r"(?:搜索框|搜索栏|消息框|聊天框|地址栏|输入框|文本框|输入栏|"
        r"search box|search field|message field|address bar|input field|text box)",
        app,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0].strip(" .，,。")
    app = re.sub(
        r"^(?:一个|一款|这个|那个)?(?:任意(?:的)?|(?:(?:我)?(?:没|没有)提过的|从未提过的|新的|未知的))?"
        r"(?:应用(?:程序)?|软件|\b(?:app|application)\b)"
        r"(?:\s*(?:叫|名叫|名称是|名字是|called|named))?\s*",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(r"^(?:called|named)\s+", "", app, flags=re.IGNORECASE).strip(" .，,。")
    app = re.sub(r"^(?:在|用|通过)\s*", "", app, flags=re.IGNORECASE).strip(" .，,。")
    app = re.sub(
        r"^(?:in|inside|within|using|with)\s+",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(r"\s*(?:吗|嘛|呢|吧|么|\?|？)$", "", app, flags=re.IGNORECASE).strip(" .，,。")
    app = re.sub(r"\s*(?:帮我|请|麻烦)$", "", app).strip(" .，,。")
    app = re.sub(r"\s*(?:please|pls)$", "", app, flags=re.IGNORECASE).strip(" .，,。")
    app = re.sub(r"\s*(?:for\s+me)$", "", app, flags=re.IGNORECASE).strip(" .，,。")
    app = re.sub(
        r"\s*(?:客户端|桌面客户端|桌面版|desktop\s+client|client)$",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(r"\s*(?:搜索|查找|检索|找)\s*.+$", "", app).strip(" .，,。")
    app = re.sub(
        r"\s+\b(?:search|find|look\s+up|look)\b\s+.+$",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(r"\s*(?:一下|下|起来)$", "", app).strip(" .，,。")
    app = re.sub(r"\s*(?:这个|那个|该)$", "", app).strip(" .，,。")
    app = re.sub(r"\s*(?:的|里(?:的)?|里面(?:的)?|中(?:的)?|上(?:的)?|内(?:的)?)$", "", app).strip(" .，,。")
    app = re.sub(r"\s*(?:在|里|里面|中|上|内)$", "", app).strip(" .，,。")
    app = re.sub(r"\s+(?:app|application)$", "", app, flags=re.IGNORECASE).strip(" .，,。")
    app = re.sub(r"(?:应用(?:程序)?|软件)$", "", app).strip(" .，,。")
    app = re.sub(r"\s*(?:这个|那个|该)$", "", app).strip(" .，,。")
    app = re.sub(r"^(?:一下|下|这个|那个)\s*", "", app).strip()
    generic = {
        "app",
        "application",
        "desktop",
        "window",
        "应用",
        "应用程序",
        "桌面",
        "窗口",
        "当前窗口",
        "现在窗口",
        "前台窗口",
        "这个窗口",
        "该窗口",
        "当前界面",
        "现在界面",
        "前台界面",
        "屏幕",
        "当前屏幕",
        "现在屏幕",
        "界面",
        "画面",
        "页面",
        "网页",
        "标签页",
        "新标签",
        "新标签页",
        "打开新标签",
        "打开新标签页",
        "当前页面",
        "当前网页",
        "这个页面",
        "这个网页",
        "关闭的标签页",
        "刚才关闭的标签页",
        "刚关闭的标签页",
        "当前",
        "任何当前",
        "任意当前",
        "任何当前应用",
        "任意当前应用",
        "当前所有",
        "当前全部",
        "当前app",
        "当前应用",
        "前台应用",
        "前台",
        "现在",
        "这个",
        "该",
        "current",
        "current app",
        "foreground app",
        "current window",
        "active window",
        "foreground window",
        "this window",
        "current interface",
        "active interface",
        "foreground interface",
        "new tab",
        "button",
        "buttons",
        "control",
        "controls",
        "element",
        "elements",
        "field",
        "fields",
        "click",
        "click the",
        "type",
        "type the",
        "press",
        "press the",
        "can you",
        "could you",
        "would you",
        "do not",
        "don't",
        "dont",
        "never",
        "without",
        "你",
        "我",
        "帮我",
        "请",
        "不要",
        "别",
        "请勿",
        "点",
        "点击",
        "切换",
        "退出",
        "toggle",
        "leave",
    }
    if context_source_hint(app):
        return ""
    if _looks_like_too_short_cjk_app_label(app):
        return ""
    if compact_app_name_hint(app) in {
        "folder",
        "folders",
        "afolder",
        "directory",
        "directories",
        "文件夹",
        "目录",
    }:
        return "Finder"
    return "" if app.lower() in generic else app


def _browser_scoped_safe_shortcut_app_candidate(
    text: str,
    hint: Mapping[str, Any] | None,
) -> str:
    if not _browser_foreground_safe_shortcut_hint(hint):
        return ""
    value = _clean_prompt(text)
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:打开|启动|切到|聚焦)?\s*(?P<app>[\w .·-]{1,40}?)\s*"
        r"(?:新建|打开)?(?:无痕|隐身|私密)窗口$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:打开|启动|切到|聚焦)?\s*(?P<app>[\w .·-]{1,40}?)\s*"
        r"(?:(?:聚焦|打开|选中)地址栏|(?:打开|显示)?(?:浏览器)?历史记录|"
        r"(?:打开|显示)?开发者工具|刷新(?:一下)?|(?:网页|页面)?(?:放大|缩小)|"
        r"(?:恢复)?实际大小|前进(?:下一页)?|(?:返回|后退)(?:上一页)?)$",
        r"^(?:please\s+)?(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:open\s+(?:an?\s+)?(?:incognito|private)\s+window|"
        r"focus\s+(?:the\s+)?(?:address|url)\s+bar|"
        r"(?:open|show)\s+(?:browser|browsing)?\s*history|"
        r"(?:open|show)\s+devtools|refresh|reload|zoom\s+(?:in|out)|"
        r"reset\s+zoom|go\s+(?:forward|back)|forward|back)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if match:
            app_name = re.sub(
                r"(?:打开|启动|开启|开|切到|聚焦)(?:起来)?$",
                "",
                _clean_app_name_hint(match.group("app")),
                flags=re.IGNORECASE,
            ).strip()
            return _canonical_app_name_hint(app_name)
    return ""


def _app_scoped_safe_shortcut_app_name_hint(
    text: str,
    safe_shortcut: Mapping[str, Any] | None = None,
) -> str:
    hint = safe_shortcut or safe_shortcut_hint(text)
    action = str((hint or {}).get("action") or "").strip()
    if not action:
        return ""
    value = _clean_prompt(text)
    if _safe_shortcut_requires_finder_scope_for_text(value, hint):
        patterns = (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?:打开|启动|切到|聚焦)?\s*"
            r"(?P<app>Finder|访达)\s*(?:然后|并|再|接着|之后|后)?\s*.+$",
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?:在|用|通过)\s*"
            r"(?P<app>Finder|访达)\s*(?:里|中|上|内)?\s*.+$",
            r"^(?:open|launch|focus|start)?\s*(?:the\s+)?(?P<app>Finder)\b.+$",
        )
        for pattern in patterns:
            match = re.search(pattern, value, flags=re.IGNORECASE)
            if not match:
                continue
            app = _clean_app_name_hint(match.group("app"))
            if _is_finder_app_name(app):
                return "Finder"
        return ""
    if action in {
        "bookmark_page",
        "browser_back",
        "browser_forward",
        "close_tab",
        "focus_address_bar",
        "new_private_window",
        "new_tab",
        "new_window",
        "next_tab",
        "open_devtools",
        "previous_tab",
        "refresh",
        "reopen_closed_tab",
        "reset_zoom",
        "show_history",
        "zoom_in",
        "zoom_out",
    }:
        app = _browser_scoped_safe_shortcut_app_candidate(value, hint)
        if (
            app
            and _is_browser_or_search_app_name(app)
            and not _is_generic_browser_app_label(app)
        ):
            return app
        return ""
    if action != "toggle_full_screen":
        return ""
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:把|将)?\s*"
        r"(?P<app>[\w .·-]{1,40}?)\s*(?:窗口)?"
        r"(?:最大化|全屏|进入全屏(?:模式)?)"
        r"(?:一下|下)?(?:可以吗|好吗|好么|行吗|吗|嘛|吧|呢)?$",
        r"^(?:please\s+)?(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:maximize|fullscreen|full\s*screen)(?:\s+(?:window|app))?(?:\s+please)?$",
        r"^(?:please\s+)?(?:maximize|fullscreen|full\s*screen|enter\s+full\s*screen)\s+"
        r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)(?:\s+(?:window|app))?(?:\s+please)?$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        app = _clean_app_name_hint(match.group("app"))
        if not app or _contains_any(app, ["音量", "声音", "亮度", "volume", "sound", "brightness"]):
            continue
        return app
    return ""


def _safe_shortcut_requires_finder_scope(hint: Mapping[str, Any] | None) -> bool:
    return str((hint or {}).get("action") or "").strip() in {
        "finder_quick_look",
        "finder_get_info",
        "finder_airdrop",
        "finder_network",
        "finder_recents",
        "new_folder",
        "rename_selected",
        "parent_folder",
    }


def _safe_shortcut_requires_finder_scope_for_text(
    text: str,
    hint: Mapping[str, Any] | None,
) -> bool:
    if _safe_shortcut_requires_finder_scope(hint):
        return True
    if str((hint or {}).get("action") or "").strip() != "copy":
        return False
    return _contains_any(
        text,
        (
            "复制选中项",
            "复制选中文件",
            "复制当前选中项",
            "复制当前选中文件",
            "copy selected file",
            "copy selected item",
        ),
    )


def _is_finder_app_name(value: str) -> bool:
    return str(value or "").strip().lower() in {"finder", "访达"}


def _click_then_submit_hint(text: str) -> bool:
    value = _clean_prompt(text)
    if re.search(
        r"(?:确认|验证|检查|查看|看看|判断|verify|confirm|check).{0,16}"
        r"(?:是否|有没有|成功|结果|状态|whether|if|success|result|state|status)",
        value,
        flags=re.IGNORECASE,
    ):
        return False
    return bool(
        re.search(
            r"(?:点击|点一下|点按|单击|按一下|click|press|tap).{0,60}"
            r"(?:然后|并|再|接着|之后|后|and\s+then|then|and).{0,16}"
            r"(?:确认|提交|confirm|submit)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _input_then_submit_hint(text: str) -> bool:
    value = _clean_prompt(text)
    return bool(
        re.search(
            r"(?:输入|键入|填写|填入|写入|写|type|enter|fill).{0,80}"
            r"(?:并|然后|再|接着|之后|后|and\s+then|then|and).{0,16}"
            r"(?:搜索|查找|确认|提交|search|find|confirm|submit)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _explicit_submit_hint(text: str) -> bool:
    value = _clean_prompt(text)
    return bool(
        re.search(
            r"(?:回车键?|enter|return).{0,12}(?:确认|提交|confirm|submit)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:确认|提交|confirm|submit).{0,12}(?:回车键?|enter|return)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _foreground_submit_action_hint(text: str) -> str:
    value = _clean_prompt(text)
    if ui_control_presence_hint(value):
        return ""
    lowered = value.lower()
    app_scoped_submit = bool(_app_scoped_foreground_submit_app_name_hint(value))
    looks_like_send = _contains_any(value, ("发送", "发出", "send")) or bool(
        _looks_like_chinese_foreground_send_verb(value)
    )
    if looks_like_send and (
        _looks_like_foreground_submit_scope(value, lowered) or app_scoped_submit
        or bool(_foreground_compose_text_hint(value))
    ):
        return "send"
    if _contains_any(value, ("提交", "submit")) and (
        _looks_like_foreground_submit_scope(value, lowered) or app_scoped_submit
    ):
        return "submit"
    if re.search(r"(?:按|敲|点|tap|press|hit).{0,8}(?:回车|return|enter).{0,8}(?:发送|send)", value, flags=re.IGNORECASE):
        return "send"
    if re.search(r"(?:按|敲|点|tap|press|hit).{0,8}(?:回车|return|enter).{0,8}(?:提交|submit)", value, flags=re.IGNORECASE):
        return "submit"
    if re.search(r"(?:发送|send).{0,8}(?:回车|return|enter)", value, flags=re.IGNORECASE):
        return "send"
    if re.search(r"(?:提交|submit).{0,8}(?:回车|return|enter)", value, flags=re.IGNORECASE):
        return "submit"
    return ""


def _looks_like_chinese_foreground_send_verb(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    return bool(
        re.search(
            r"(?:发给|发到|发往|发去|发一下|发下|发出去|发消息|发信息|发这条|发这个)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:并|然后|再|接着|之后|后|把|将)\s*发(?:给|到|出去|一下|下)?",
            value,
            flags=re.IGNORECASE,
        )
        or (
            not re.search(
                r"(?:输入|键入|填写|写入|写下|记录下|记下|写)\s*[^。！？!?，,]*?(?<!开)发",
                value,
                flags=re.IGNORECASE,
            )
            and re.search(
                r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
                r"(?:打开|启动|切到|聚焦)?\s*[\w .·-]{1,40}?\s*"
                r"(?<![开派转分研触首补签颁印])发\s*[^。！？!?，,]+$",
                value,
                flags=re.IGNORECASE,
            )
        )
    )


def _foreground_search_submit_hint(text: str) -> bool:
    value = _clean_prompt(text)
    lowered = value.lower()
    return bool(
        re.fullmatch(r"(?:提交|确认|执行)?\s*(?:当前|这个|前台)?\s*(?:搜索|查询|查找)", value)
        or re.fullmatch(r"(?:按|敲|点)?\s*(?:回车|enter|return)\s*(?:搜索|查询|查找)", value, flags=re.IGNORECASE)
        or re.fullmatch(r"(?:press|hit|tap)\s+(?:enter|return)\s+to\s+(?:search|find)", lowered)
    )


def _return_hotkey_followup_hint(text: str) -> dict[str, Any] | None:
    value = _clean_prompt(text)
    if not re.search(
        r"(?:并|再|然后|接着|之后|后)\s*(?:搜索|查找|检索)(?:一下|下)?\s*$",
        value,
        flags=re.IGNORECASE,
    ):
        return None
    return {"key": "return", "modifiers": []}


def _explicit_return_key_followup_hint(text: str) -> dict[str, Any] | None:
    value = _clean_prompt(text)
    if not re.search(
        r"(?:并|再|然后|接着|之后|后|and\s+then|then)?.{0,8}"
        r"(?:按|敲|触发|press|hit|tap)?\s*"
        r"(?:回车键?|(?<![A-Za-z])(?:enter|return)(?![A-Za-z]))"
        r"(?:\s|$|[。！？!?，,])",
        value,
        flags=re.IGNORECASE,
    ):
        return None
    if re.search(r"(?:发送|提交|send|submit).{0,8}(?:回车|enter|return)", value, flags=re.IGNORECASE):
        return None
    return {"key": "return", "modifiers": []}


def _model_generated_hint_is_bare_container_operand(
    hint: Mapping[str, Any] | None,
    safe_shortcut: Mapping[str, Any] | None,
) -> bool:
    if not isinstance(hint, Mapping) or not isinstance(safe_shortcut, Mapping):
        return False
    if str(hint.get("title") or "").strip():
        return False
    action = str(safe_shortcut.get("action") or "").strip()
    patterns = {
        "new_task": (
            r"(?:(?:a|an|the)\s+)?(?:new\s+)?(?:issue|task|ticket|bug\s+ticket)|"
            r"(?:一个|一条|新的)?(?:问题|任务|事项|工单|bug)"
        ),
        "new_message": (
            r"(?:(?:a|an|the)\s+)?(?:new\s+)?(?:message|email|chat)|"
            r"(?:一封|一条|一个|新的)?(?:消息|邮件|聊天)"
        ),
        "new_document": (
            r"(?:(?:a|an|the)\s+)?(?:new\s+)?(?:document|page|workspace|project|"
            r"presentation|slide\s+deck|spreadsheet|table)|"
            r"(?:一个|一份|一篇|新的)?(?:文档|页面|工作区|项目|演示文稿|幻灯片|表格)"
        ),
        "new_note": (
            r"(?:(?:a|an|the)\s+)?(?:new\s+)?(?:note|journal\s+entry)|"
            r"(?:一条|一篇|一个|新的)?(?:笔记|备忘录|便签|日志)"
        ),
        "new_event": (
            r"(?:(?:a|an|the)\s+)?(?:new\s+)?(?:event|meeting)|"
            r"(?:一个|一场|新的)?(?:日程|事件|会议)"
        ),
        "new_reminder": (
            r"(?:(?:a|an|the)\s+)?(?:new\s+)?reminder|"
            r"(?:一个|一条|新的)?提醒"
        ),
    }
    pattern = patterns.get(action)
    if not pattern:
        return False
    brief = re.sub(
        r"\s+",
        " ",
        str(hint.get("brief") or "").strip(" .，,。"),
    ).casefold()
    return bool(re.fullmatch(pattern, brief, flags=re.IGNORECASE))


def _model_generated_foreground_content_hint(
    text: str,
    compose_text: str = "",
) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value:
        return {}
    if re.search(r"(?:粘贴|paste)", value, flags=re.IGNORECASE):
        return {}
    title = _generic_create_title_text_hint(value)
    title_scoped_brief = _title_scoped_model_generated_content_brief(value)
    if title and title_scoped_brief:
        return {
            "body_source": "model_generated_content",
            "brief": title_scoped_brief,
            "title": title,
        }
    if re.search(
        r"(?:标题|名称|名字|题目)\s*(?:是|为|叫|:|：)|\b(?:titled|called|named)\b",
        value,
        flags=re.IGNORECASE,
    ):
        return {}
    brief = _clean_foreground_compose_text(compose_text)
    if not brief:
        brief = _model_generated_foreground_content_brief(value)
    if not brief:
        return {}
    if _foreground_text_has_delimited_literal_provenance(value, brief):
        return {}
    if _foreground_text_has_explicit_literal_provenance(value, brief) and (
        _foreground_text_has_strong_literal_command_provenance(value, brief)
        or not _foreground_content_brief_requires_generation(brief)
    ):
        return {}
    if not _looks_like_model_generated_foreground_content_request(value, brief):
        return {}
    return {
        "body_source": "model_generated_content",
        "brief": brief,
    }


def _title_scoped_model_generated_content_brief(text: str) -> str:
    value = _clean_prompt(text)
    if not value:
        return ""
    title_then_body = re.search(
        r"(?:标题|名称|名字|题目)\s*(?:是|为|叫|:|：)\s*"
        r"[^。！？!?，,]{1,80}?\s*(?:[，,]\s*)?"
        r"(?:并|然后|再|接着|之后|后|and\s+then|then)\s*"
        r"(?P<body>[^。！？!?]{1,160})",
        value,
        flags=re.IGNORECASE,
    )
    if title_then_body:
        brief = _model_generated_content_phrase_brief(title_then_body.group("body"))
        if brief:
            return brief
    patterns = (
        r"(?:内容|正文)\s*(?:写成|写下|写入|写|撰写|生成|创建|制作|列出|总结|整理|摘要|输出|包含|包括)\s*"
        r"(?P<brief>[^。！？!?，,]{1,100})",
        r"\b(?:content|body)\s*(?:to|should)?\s*"
        r"(?:write|generate|create|make|list|summari[sz]e|outline|include)\s+"
        r"(?P<brief_en>[^.!?]{1,120})",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        brief = _clean_foreground_compose_text(
            match.groupdict().get("brief")
            or match.groupdict().get("brief_en")
            or ""
        )
        if brief:
            return brief
    return ""


def _model_generated_foreground_content_brief(text: str) -> str:
    value = _clean_prompt(text)
    creative_brief = _model_generated_content_phrase_brief(value)
    if creative_brief:
        return creative_brief
    patterns = (
        r"(?:画|绘制|画出|绘出|生成|创建|制作|做|输出|撰写|写一份|写一篇)\s*"
        r"(?P<brief>[^。！？!?，,]{1,80}?"
        r"(?:流程图|思维导图|脑图|图表|图像|图片|报告|计划|方案|大纲|演示文稿|演示|幻灯片|表格|预算表|数据)"
        r"[^。！？!?，,]{0,80})",
        r"\b(?:draw|create|make|generate|write|produce|fill)\s+"
        r"(?P<brief_en>[^.!?]{1,100}?"
        r"(?:flowchart|diagram|chart|report|plan|outline|presentation|slides?|spreadsheet|table|budget|sample data)"
        r"[^.!?]{0,100})",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        brief = _clean_foreground_compose_text(
            match.groupdict().get("brief") or match.groupdict().get("brief_en") or ""
        )
        if brief:
            return brief
    return ""


def _foreground_text_literal_candidates(
    text: str,
    literal_text: str,
) -> tuple[str, str, set[str]]:
    value = _clean_prompt(text)
    literal = _clean_foreground_compose_text(literal_text)
    candidates = {
        _clean_foreground_compose_text(safe_type_text_hint(value)),
        _clean_foreground_compose_text(standalone_safe_type_text_hint(value)),
        _clean_foreground_compose_text(_foreground_compose_text_hint(value)),
    }
    candidates.discard("")
    return value, literal, candidates


def _foreground_text_has_delimited_literal_provenance(
    text: str,
    literal_text: str,
) -> bool:
    value, literal, extracted_candidates = _foreground_text_literal_candidates(
        text,
        literal_text,
    )
    if not value or not literal or literal not in extracted_candidates:
        return False
    escaped_literal = re.escape(literal)
    if re.search(
        rf"[\"'`“‘]\s*{escaped_literal}\s*[\"'`”’]",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    if re.search(
        rf"(?:task|issue|ticket|note|message|email|event|meeting|reminder|"
        rf"任务|问题|工单|笔记|备忘录|消息|邮件|日程|会议|提醒)\s*"
        rf"[:：]\s*{escaped_literal}(?=$|[。！？!?，,])",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    return bool(
        re.search(
            r"(?:输入|键入|填写|填入|写入|写下|记录下|记下|写|撰写|起草|创作|"
            r"type|enter|fill|write|draft|compose)\s*[:：]",
            value,
            flags=re.IGNORECASE,
        )
    )


def _foreground_text_has_strong_literal_command_provenance(
    text: str,
    literal_text: str,
) -> bool:
    value, literal, extracted_candidates = _foreground_text_literal_candidates(
        text,
        literal_text,
    )
    if not value or not literal or literal not in extracted_candidates:
        return False
    return bool(
        re.search(
            r"(?:帮我打(?:字|上|入)?|打字|打上|打入|输入(?!框|栏)|键入|"
            r"\btype\b|\benter\b)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _foreground_content_brief_requires_generation(brief: str) -> bool:
    value = _clean_foreground_compose_text(brief)
    if not value:
        return False
    if re.search(
        _MODEL_GENERATED_CHINESE_CONTENT_NOUN,
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        rf"\b{_MODEL_GENERATED_ENGLISH_CONTENT_NOUN}\b",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    if re.search(
        r"(?:检查清单|待办(?:清单)?|会议纪要|新闻(?:发布)?稿|合同|产品描述|"
        r"日记|推文|press\s+release|checklist|meeting\s+minutes|contract|"
        r"product\s+description|journal\s+entry|tweet)",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    return bool(
        re.search(
            r"(?:\d+\s*(?:页|行|列|张|段)|"
            r"[一二两三四五六七八九十几多]+\s*(?:页|行|列|张|段)|"
            r"示例数据|样例数据|项目计划|预算表|流程图|思维导图|脑图|图表|"
            r"演示文稿|幻灯片|表格|工作簿|"
            r"slides?|rows?|columns?|sample\s+data|project\s+plan|budget|"
            r"flowchart|diagram|chart|presentation|table)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _foreground_text_has_explicit_literal_provenance(
    text: str,
    literal_text: str,
) -> bool:
    """Return true only when the user explicitly supplied text to type.

    Shortness is not provenance: `一首诗` is a generation brief, while
    `输入：“一首诗”` is a literal payload.  Require an explicit typing verb or
    a quoted/colon-delimited payload so unknown creative nouns fail closed.
    """

    value, literal, extracted_candidates = _foreground_text_literal_candidates(
        text,
        literal_text,
    )
    if not value or not literal or literal not in extracted_candidates:
        return False
    if _foreground_text_has_delimited_literal_provenance(value, literal):
        return True
    escaped_literal = re.escape(literal)
    if re.search(
        rf"(?:内容|正文)\s*(?:写|写入|写下|填入|填写)\s*"
        rf"{escaped_literal}(?=$|[。！？!?，,])",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    if re.search(
        rf"\b(?:saying|that\s+says?|with\s+(?:the\s+)?(?:content|body|text))\s+"
        rf"{escaped_literal}(?=$|[.!?,])",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    if re.search(
        r"(?:帮我打(?:字|上|入)?|打字|打上|打入|输入(?!框|栏)|键入|填写|填入|"
        r"写入|写下|记录下|记下|\btype\b|\benter\b|\bfill\b)",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    if re.search(
        r"(?:标题|名称|名字|题目)\s*(?:是|为|叫|[:：])|"
        r"\b(?:titled|called|named)\b",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    return False


def _looks_like_model_generated_foreground_content_request(text: str, brief: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if _model_generated_content_phrase_brief(value):
        return True
    content_shape = (
        r"(?:\d+\s*(?:页|行|列|张|段)|[一二两三四五六七八九十几多]+\s*(?:页|行|列|张|段)|"
        r"示例数据|样例数据|项目计划|预算表|流程图|思维导图|脑图|图表|报告|方案|大纲|"
        r"演示文稿|幻灯片|表格|工作簿|"
        r"slides?|rows?|columns?|sample\s+data|project\s+plan|budget|flowchart|diagram|chart|report|outline|presentation|table)"
    )
    generation_verb = (
        r"(?:写入|填入|填写|生成|创建|制作|做|画|绘制|输出|撰写|写一份|写一篇|"
        r"\b(?:write|fill|generate|create|make|draw|produce)\b)"
    )
    if re.search(
        rf"{generation_verb}.{{0,60}}{content_shape}",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    if re.search(
        rf"{content_shape}.{{0,40}}{generation_verb}",
        value,
        flags=re.IGNORECASE,
    ):
        return True
    if re.search(content_shape, brief, flags=re.IGNORECASE) and re.search(
        generation_verb,
        value,
        flags=re.IGNORECASE,
    ):
        return True
    return False


def _foreground_compose_text_hint(text: str) -> str:
    value = _clean_prompt(text)
    if re.search(r"(?:粘贴|paste)", value, flags=re.IGNORECASE):
        return ""
    if _looks_like_recipient_message_request(value):
        return ""
    create_text = _app_scoped_create_text_hint(value)
    if create_text:
        return create_text
    create_title_text = _generic_create_title_text_hint(value)
    if create_title_text:
        return create_title_text
    followup_text = _generic_followup_compose_text_hint(value)
    if followup_text:
        return followup_text
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?:打开|启动|切到|聚焦)?\s*"
        r"(?P<app>[\w .·-]{1,40}?)\s*(?:输入|键入|填写|写入|写下|记录下|记下|写)\s*(?P<text>[^。！？!?，,]+?)"
        r"\s*(?:并|然后|再|后)?\s*(?:发送|发出|send)?$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?:打开|启动|切到|聚焦)?\s*"
        r"(?P<app>[\w .·-]{1,40}?)\s*"
        r"(?:发送|发出|(?<![开派转分研触首补签颁印])发)\s*"
        r"(?P<text>[^。！？!?，,]+)$",
        r"^(?:open|launch|focus|switch\s+to)?\s*(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:type|enter|write|send)\s+(?P<text>[^.!?]+?)(?:\s+(?:and|then)\s+send)?$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        raw_app = match.groupdict().get("app") or ""
        if _looks_like_too_short_cjk_app_label(raw_app):
            continue
        if re.search(r"(?:回车|return|enter)", raw_app, flags=re.IGNORECASE):
            continue
        app = _canonical_app_name_hint(raw_app)
        if not _credible_foreground_compose_app_target(raw_app, app):
            continue
        typed_text = _clean_foreground_compose_text(match.group("text"))
        if not typed_text:
            continue
        if _looks_like_discovered_app_capability_phrase(typed_text):
            continue
        if not app and not _looks_like_foreground_text_scope(value):
            continue
        if not app and not re.search(r"(?:输入|键入|填写|写入|type|enter|write)", value, flags=re.IGNORECASE):
            continue
        if typed_text in {"框", "栏", "送"}:
            continue
        if typed_text:
            return typed_text
    return ""


def _generic_followup_compose_text_hint(text: str) -> str:
    value = _clean_prompt(text)
    if not value:
        return ""
    patterns = (
        r"(?:^|[，,；;]\s*|(?:并且|并|然后|再|接着|之后|随后|后)\s*)"
        r"(?:输入(?!框|栏)|键入|填写|填入|写入|写下|记录下|记下|写)\s*"
        r"(?P<text_after_separator>[^。！？!?]+)$",
        r"(?:并且|并|然后|再|接着|之后|随后|后)\s*"
        r"(?:输入(?!框|栏)|键入|填写|填入|写入|写下|记录下|记下|写)\s*"
        r"(?P<text>[^。！？!?]+)$",
        r"(?:^|[.!?,;]\s*|\b(?:and\s+then|then|and)\s*)"
        r"(?:type|enter|fill|write)\s+(?P<text_en_after_separator>[^.!?]+)$",
        r"\b(?:and\s+then|then|and)\s*"
        r"(?:type|enter|fill|write)\s+(?P<text_en>[^.!?]+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        text_value = _clean_foreground_compose_text(
            match.groupdict().get("text_after_separator")
            or match.groupdict().get("text")
            or match.groupdict().get("text_en_after_separator")
            or match.groupdict().get("text_en")
            or ""
        )
        if _looks_like_discovered_app_capability_phrase(text_value):
            continue
        if text_value:
            return text_value
    return ""


def _text_hint_is_ui_target_tail(
    prompt: str,
    text_hint: str,
    click_target: Mapping[str, Any] | None,
) -> bool:
    value = _clean_prompt(text_hint)
    if not value or not isinstance(click_target, Mapping) or not click_target:
        return False
    prompt_value = _clean_prompt(prompt)
    if not re.search(
        r"(?:点击|点一下|点按|单击|双击|点|click|press|tap)",
        prompt_value,
        flags=re.IGNORECASE,
    ):
        return False
    if _contains_any(
        value,
        (
            "按钮",
            "链接",
            "菜单项",
            "菜单",
            "控件",
            "元素",
            "button",
            "link",
            "menu item",
            "menu",
            "control",
            "element",
        ),
    ):
        return True
    target = _clean_prompt(str(click_target.get("target") or ""))
    return bool(target and (value == target or value in target))


def _generic_create_title_text_hint(text: str) -> str:
    value = _clean_prompt(text)
    if not re.search(r"(?:新建|创建|新增|\b(?:new|create|make)\b)", value, flags=re.IGNORECASE):
        return ""
    container = (
        r"(?:页面|页|笔记|备忘录|日志|日记|文档|文件(?!夹)|演示|演示文稿|幻灯片|"
        r"项目|任务|卡片|工单|事项|page|note|document|file|presentation|slide|"
        r"project|task|card|bug\s+ticket|issue\s+ticket|ticket|issue|bug|board|whiteboard|wireframe|mockup)"
    )
    chinese_patterns = (
        rf"(?:新建|创建|新增).{{0,80}}?"
        rf"(?:标题|名称|名字|题目)\s*(?:是|为|叫|:|：)\s*"
        rf"(?P<text>[^。！？!?，,]+?)\s*的\s*{container}",
        rf"(?:新建|创建|新增).{{0,80}}?{container}.{{0,30}}?"
        rf"(?:标题|名称|名字|题目)\s*(?:是|为|叫|:|：)\s*"
        rf"(?P<text>[^。！？!?，,]+)",
    )
    for pattern in chinese_patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        text_value = _clean_foreground_compose_text(match.group("text"))
        if text_value:
            return text_value
    english_patterns = (
        rf"\b(?:new|create|make)\b.{{0,80}}\b{container}\b.{{0,30}}"
        rf"\b(?:titled|called|named)\s+(?P<text_en>[^.!?,]+)",
    )
    for pattern in english_patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        text_value = _clean_foreground_compose_text(match.group("text_en"))
        if text_value:
            return text_value
    return ""


def _generic_create_container_action_hint(text: str) -> str:
    value = _clean_prompt(text)
    if _looks_like_clicking_create_control(value):
        return ""
    if re.search(
        r"(?:新建|创建|新增)\s*(?:一个|一条|一篇|一份|一则)?\s*"
        r"(?:今天的|今日的|新的|新|关于.+?的)?\s*"
        r"(?:(?:标题|名称|名字|题目)\s*(?:是|为|叫|:|：)\s*[^。！？!?，,]{1,80}?\s*的\s*)?"
        r"(?:笔记|备忘录|日志|日记)",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"\b(?:new|create|make)\b.{0,40}\b(?:note|journal|diary)\b",
        value,
        flags=re.IGNORECASE,
    ):
        return "new_note"
    if re.search(
        r"(?:新建|创建|新增)\s*(?:一个|一条|一篇|一份|一则)?\s*"
        r"(?:今天的|今日的|新的|新|关于.+?的)?\s*"
        r"(?:(?:标题|名称|名字|题目)\s*(?:是|为|叫|:|：)\s*[^。！？!?，,]{1,80}?\s*的\s*)?"
        r"(?:任务|卡片|工单|事项|ticket|issue|bug|bug\s*ticket)",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"(?:把|将)?\s*[^。！？!?，,]{1,80}?\s*"
        r"(?:记录成|记成|登记为|转成|作为)\s*"
        r"(?:ticket|issue|bug|工单|事项|任务|卡片)",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"\b(?:new|create|make|record|file)\b.{0,60}\b"
        r"(?:task|card|ticket|issue|bug|bug\s*ticket)\b",
        value,
        flags=re.IGNORECASE,
    ):
        return "new_task"
    if re.search(
        r"(?:新建|创建|新增)\s*(?:一个|一份|一篇|一条|一张|一幅)?\s*"
        r"(?:\d{2,5}\s*(?:x|×|X|\*)\s*\d{2,5}\s*)?"
        r"(?:新的|新)?\s*"
        r"(?:(?:标题|名称|名字|题目)\s*(?:是|为|叫|:|：)\s*[^。！？!?，,]{1,80}?\s*的\s*)?"
        r"(?:一页|一个页面|一张页面|页面|页|文档|(?:[A-Za-z0-9_+#.-]+\s*)?文件(?!夹)|图片|图像|图(?!标)|"
        r"流程图|思维导图|脑图|图表|画布|表格|工作簿|[^。！？!?，,]{0,20}?表|演示|演示文稿|幻灯片|"
        r"项目|board|whiteboard|wireframe|mockup)",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"\b(?:new|create|make)\b.{0,60}\b"
        r"(?:page|document|file|image|picture|diagram|flowchart|mind\s*map|canvas|"
        r"spreadsheet|workbook|presentation|slide|project|"
        r"board|whiteboard|wireframe|mockup)\b",
        value,
        flags=re.IGNORECASE,
    ):
        return "new_document"
    return ""


def _app_scoped_create_text_hint(text: str) -> str:
    value = _clean_prompt(text)
    parsed = _app_scoped_followup_hint(value)
    followup = str(parsed.get("followup") or "").strip()
    if not followup:
        return ""
    if not _looks_like_app_scoped_create_followup(followup):
        return ""
    patterns = (
        r"(?:新建|创建|新增)\s*(?:一个|一条|一篇|一份|一则|一张|一幅|新的|新)?\s*"
        r"(?:页面|页|笔记|备忘录|日志|日记|文档|文件|演示|演示文稿|幻灯片|"
        r"项目|任务|卡片|工单|事项|bug\s+ticket|issue\s+ticket|ticket|issue|bug)"
        r"\s*(?:(?:标题|名称|名字|题目)\s*)?(?:是|为|叫|:|：)\s*"
        r"(?P<text>[^。！？!?，,]+)",
        r"(?:标题|名称|名字|题目)\s*(?:是|为|叫|:|：)\s*"
        r"(?P<text>[^。！？!?，,]+?)"
        r"(?:\s*的\s*(?:页面|页|笔记|备忘录|日志|日记|文档|文件|演示|演示文稿|"
        r"幻灯片|项目|任务|卡片|工单|事项|bug\s+ticket|issue\s+ticket|ticket|issue|bug))?"
        r"(?:$|[。！？!?，,])",
        r"(?:名为|叫做|叫)\s*(?P<text>[^。！？!?，,]+)",
        r"(?:关于|有关)\s*(?P<text>.+?)\s*的\s*"
        r"(?:页面|页|笔记|备忘录|日志|日记|文档|文件|演示|演示文稿|幻灯片|"
        r"项目|任务|卡片|工单|事项|ticket|issue|bug)",
        r"(?:内容|正文)\s*(?:是|为|写|写成|写下|:|：)\s*(?P<text>[^。！？!?，,]+)",
        r"(?:写下|写入|记录下|记下|写)\s*(?P<text>[^。！？!?，,]+)",
        r"(?:把|将)?\s*(?P<text>[^。！？!?，,]+?)\s*"
        r"(?:记录成|记成|登记为|转成|作为)\s*"
        r"(?:ticket|issue|bug|工单|事项|任务|卡片)",
        r"\b(?:titled|called|named)\s+(?P<text_en>[^.!?,]+)",
        r"\b(?:new|create|make)\b.{0,40}\b"
        r"(?:page|note|document|file|presentation|slide|project|task|card|ticket|issue|bug)\b"
        r"\s*(?::|-)\s*(?P<text_en>[^.!?,]+)",
        r"\babout\s+(?P<text_en>[^.!?,]+)",
        r"\b(?:saying|with(?:\s+(?:content|text|body))?|content|text|body)\s+"
        r"(?P<text_en>[^.!?,]+)",
    )
    for pattern in patterns:
        match = re.search(pattern, followup, flags=re.IGNORECASE)
        if not match:
            continue
        text_value = _clean_foreground_compose_text(
            match.groupdict().get("text") or match.groupdict().get("text_en") or ""
        )
        if text_value:
            return text_value
    return ""


def _looks_like_app_scoped_create_followup(text: str) -> bool:
    value = _clean_prompt(text)
    if _looks_like_clicking_create_control(value):
        return False
    return bool(
        re.search(
            r"(?:新建|创建|新增)\s*(?:一个|一条|一篇|一份|一则)?\s*"
            r"(?:今天的|今日的|新的|新|关于.+?的)?\s*"
            r"(?:新的|新)?\s*"
            r"(?:(?:标题|名称|名字|题目)\s*(?:是|为|叫|:|：)\s*[^。！？!?，,]{1,80}?\s*的\s*)?"
            r"(?:一页|一个页面|一张页面|页面|页|笔记|备忘录|日志|日记|文档|(?:[A-Za-z0-9_+#.-]+\s*)?文件(?!夹)|"
            r"图片|图像|图(?!标)|流程图|思维导图|脑图|图表|画布|表格|工作簿|[^。！？!?，,]{0,20}?表|演示|演示文稿|"
            r"幻灯片|项目|任务|卡片|工单|事项|ticket|issue|bug|board|whiteboard|wireframe|mockup)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:把|将)?\s*[^。！？!?，,]{1,80}?\s*"
            r"(?:记录成|记成|登记为|转成|作为)\s*"
            r"(?:ticket|issue|bug|工单|事项|任务|卡片)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:new|create|make)\b.{0,40}\b"
            r"(?:page|note|document|file|image|picture|diagram|flowchart|mind\s*map|"
            r"canvas|spreadsheet|workbook|presentation|slide|project|task|card|ticket|issue|bug|"
            r"board|whiteboard|wireframe|mockup)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_clicking_create_control(text: str) -> bool:
    value = _clean_prompt(text)
    if not click_target_hint(value):
        return False
    return bool(
        re.search(
            r"(?:点击|点按|点一下|单击|按一下|按下|按|click|press|tap)"
            r".{0,60}(?:new|create|新建|创建|新增)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _pending_action_click_precedes_type(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    click_match = re.search(
        r"(?:点击|点按|点一下|单击|按一下|按下|click|press|tap)",
        value,
        flags=re.IGNORECASE,
    )
    type_match = re.search(
        r"(?:输入|键入|填写|填入|写入|type|enter|fill)",
        value,
        flags=re.IGNORECASE,
    )
    return bool(click_match and type_match and click_match.start() < type_match.start())


def _foreground_paste_hint(text: str) -> bool:
    value = _clean_prompt(text)
    if not re.search(r"(?:粘贴|paste)", value, flags=re.IGNORECASE):
        return False
    return bool(
        _contains_any(value, ("发送", "提交", "send", "submit"))
        or _looks_like_foreground_submit_scope(value, value.lower())
        or _current_or_foreground_app_scope_hint(value)
    )


def _current_or_foreground_app_scope_hint(text: str) -> bool:
    value = _clean_prompt(text)
    return _contains_any(
        value,
        (
            "当前打开",
            "已打开",
            "打开的",
            "当前应用",
            "当前 app",
            "当前App",
            "当前软件",
            "当前前台",
            "当前前台应用",
            "当前前台窗口",
            "当前窗口",
            "前台应用",
            "前台窗口",
            "foreground app",
            "foreground window",
            "current app",
            "current window",
            "opened app",
            "open app",
        ),
    )


def _dynamic_context_ui_transfer_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    if _dynamic_context_transform_target_hint(value):
        return {}
    source = _dynamic_context_source_hint(value)
    if source not in {"selection", "clipboard", "current_page_link", "current_page_content"}:
        return {}
    target_kind, target = _dynamic_context_ui_target_hint(value)
    app_name = _dynamic_context_transfer_app_name_hint(value)
    if app_name and target_kind == "current_input":
        target_kind = "app_paste"
        target = ""
    if app_name and not target_kind and _looks_like_dynamic_context_transfer(value):
        target_kind = "app_paste"
    if (
        target_kind == "current_input"
        and source == "current_page_content"
    ):
        return {}
    if _looks_like_dynamic_context_copy_only(value):
        if source != "current_page_content":
            return {}
        return {
            "source": source,
            "action": "copy_context",
            "target_kind": "",
            "target": "",
            "app_name": "",
            "mode": "focus",
        }
    if not target_kind:
        return {}
    if not _looks_like_dynamic_context_transfer(value):
        return {}
    return {
        "source": source,
        "action": "transfer_context",
        "target_kind": target_kind,
        "target": target,
        "app_name": app_name,
        "mode": "open" if _explicit_app_open_request(value) else "focus",
    }


def _capability_dynamic_context_ui_transfer_hint(
    text: str,
    app_capability: Mapping[str, Any],
) -> dict[str, Any]:
    value = _clean_prompt(text)
    if _dynamic_context_transform_target_hint(value):
        return {}
    source = _dynamic_context_source_hint(value)
    if source not in {"selection", "clipboard", "current_page_link", "current_page_content"}:
        return {}
    target_kind, _target = _dynamic_context_ui_target_hint(value)
    if target_kind:
        return {}
    if _looks_like_dynamic_context_copy_only(value):
        return {}
    if not _looks_like_dynamic_context_transfer(value):
        return {}
    app_name = str(
        app_capability.get("description") or app_capability.get("query") or ""
    ).strip()
    if not app_name:
        return {}
    return {
        "source": source,
        "action": "transfer_context",
        "target_kind": "app_paste",
        "target": "",
        "app_name": app_name,
        "mode": "open" if _explicit_app_open_request(value) else "focus",
    }


def _app_scoped_dynamic_context_ui_transfer_hint(
    text: str,
    app_name: str,
) -> dict[str, Any]:
    value = _clean_prompt(text)
    clean_app_name = str(app_name or "").strip()
    if not clean_app_name:
        return {}
    if _dynamic_context_transform_target_hint(value):
        return {}
    source = _dynamic_context_source_hint(value)
    if source not in {"selection", "clipboard", "current_page_link", "current_page_content"}:
        return {}
    if _looks_like_dynamic_context_copy_only(value):
        return {}
    if not _looks_like_dynamic_context_transfer(value):
        return {}
    target_kind, target = _dynamic_context_ui_target_hint(value)
    if target_kind == "current_input" and source == "current_page_content":
        return {}
    if target_kind not in {"ui_field", "current_input"}:
        target_kind = "app_paste"
        target = ""
    return {
        "source": source,
        "action": "transfer_context",
        "target_kind": target_kind,
        "target": target,
        "app_name": clean_app_name,
        "mode": "open" if _explicit_app_open_request(value) else "focus",
    }


def _plain_dynamic_context_discovered_app_transfer(
    text: str,
    app_write_target: Mapping[str, Any],
    transform_target: Mapping[str, Any],
) -> bool:
    if transform_target:
        return False
    target_app_capability = app_write_target.get("target_app_capability_hint")
    target_app = str(app_write_target.get("target_app_hint") or "").strip()
    if not target_app and not isinstance(target_app_capability, Mapping):
        return False
    value = _clean_prompt(text)
    source = _dynamic_context_source_hint(value)
    if source not in {"selection", "clipboard", "current_page_link", "current_page_content"}:
        return False
    if not _looks_like_dynamic_context_transfer(value):
        return False
    if _dynamic_context_transform_requested(value) or _looks_like_document_artifact_transform_request(value):
        return False
    if _contains_any(
        value,
        (
            "报告",
            "总结",
            "摘要",
            "汇报",
            "周报",
            "日报",
            "月报",
            "年报",
            "纪要",
            "简报",
            "复盘",
            "发布说明",
            "release notes",
            "changelog",
            "report",
            "summary",
            "brief",
            "write up",
            "deck",
        ),
    ):
        return False
    return True


def _dynamic_context_transform_target_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    if not _dynamic_context_transform_requested(value):
        return {}
    if not _looks_like_dynamic_context_transfer(value):
        return {}
    source = _dynamic_context_source_hint(value)
    if not source and _browser_current_page_hint(value):
        source = "current_page_content"
    if not source and re.search(r"\bcurrent\s+page\b|当前网页|当前页面", value, flags=re.IGNORECASE):
        source = "current_page_content"
    if not source and _looks_like_visible_text_artifact_source(value):
        source = "visible_text"
    if source not in {
        "selection",
        "clipboard",
        "current_page_link",
        "current_page_content",
        "visible_text",
    }:
        return {}
    if _dynamic_context_current_input_write_target(value):
        return {
            "context_source": source,
            "target_action_hint": "current_input_write",
        }
    app_name = _non_notes_dynamic_context_target_app(value)
    if not app_name:
        return {}
    if _normalize_artifact_output_location(app_name):
        return {}
    container_action = _dynamic_context_target_container_action_hint(value)
    app_capability = _app_capability_discovery_hint(value)
    if app_capability and _looks_like_generic_capability_app_phrase(value, app_name):
        return {
            "context_source": source,
            "target_app_capability_hint": app_capability,
            "target_action_hint": "app_paste",
            "target_container_action_hint": container_action or "new_document",
        }
    return {
        "context_source": source,
        "target_app_hint": app_name,
        "target_action_hint": "app_paste",
        **(
            {"target_container_action_hint": container_action}
            if container_action
            else {}
        ),
    }


def _app_write_followup_target_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    if _running_browser_page_context_hint(value):
        return {}
    opened_app_target = _opened_app_transform_target_hint(value)
    if opened_app_target:
        return opened_app_target
    if not _looks_like_dynamic_context_transfer(value):
        return {}
    if _app_capability_discovery_hint(value):
        return {}
    app_name = _non_notes_dynamic_context_target_app(value)
    if not app_name:
        return {}
    if (
        _normalize_artifact_output_location(app_name)
        or _looks_like_file_output_target(app_name)
        or _looks_like_non_app_dynamic_context_target(app_name)
    ):
        return {}
    container_action = _dynamic_context_target_container_action_hint(value)
    return {
        "target_app_hint": app_name,
        "target_action_hint": "app_paste",
        **(
            {"target_container_action_hint": container_action}
            if container_action
            else {}
        ),
    }


def _web_research_app_write_followup_target_hint(text: str) -> dict[str, Any]:
    """Resolve any explicit app sink for a web-derived value.

    Some local-note capture routes intentionally reserve structured note apps.
    That reservation cannot erase an explicit sink from a cross-application
    research task, so the web route falls back to the same general named-app
    extractor without changing the routing rules for simple note capture.
    """

    existing = _app_write_followup_target_hint(text)
    if existing:
        return existing
    value = _clean_prompt(text)
    if (
        _running_browser_page_context_hint(value)
        or not _looks_like_dynamic_context_transfer(value)
        or _app_capability_discovery_hint(value)
    ):
        return {}
    app_name = _dynamic_context_transfer_app_name_hint(value)
    if (
        not app_name
        or _normalize_artifact_output_location(app_name)
        or _looks_like_file_output_target(app_name)
        or _looks_like_non_app_dynamic_context_target(app_name)
    ):
        return {}
    container_action = _dynamic_context_target_container_action_hint(value)
    return {
        "target_app_hint": app_name,
        "target_action_hint": "app_paste",
        **(
            {"target_container_action_hint": container_action}
            if container_action
            else {}
        ),
    }


def _opened_app_transform_target_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    if not (
        _dynamic_context_transform_requested(value)
        and _context_artifact_source_hint(value)
        and _explicit_app_open_request(value)
    ):
        return {}
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:打开|启动|开启)\s*"
        r"(?P<app>[\w .·-]{1,40}?)"
        r"(?:\s*(?:或|或者)\s*(?:其他|其它|任意|任何|可用|合适)?\s*"
        r"[^，,。！？!?]{0,40}?(?:应用(?:程序)?|app|软件|工具|程序|编辑器))?"
        r"\s*[，,].+",
        r"^(?:open|launch|start)\s+"
        r"(?P<app_en>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)"
        r"(?:\s+or\s+(?:another|other|any|available|suitable)?\s*"
        r"[^.!?,]{0,40}?(?:app|application|tool|program|editor))?"
        r"\s*[,，].+",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        raw_app = (match.groupdict().get("app") or match.groupdict().get("app_en") or "").strip()
        app = _clean_dynamic_context_target_app(raw_app)
        if app and not _looks_like_generic_capability_app_phrase(raw_app, app):
            container_action = _dynamic_context_target_container_action_hint(value)
            return {
                "target_app_hint": app,
                "target_action_hint": "app_paste",
                **(
                    {"target_container_action_hint": container_action}
                    if container_action
                    else {}
                ),
            }
    capability = _app_capability_discovery_hint(value)
    if not capability:
        return {}
    container_action = _dynamic_context_target_container_action_hint(value) or "new_document"
    return {
        "target_app_capability_hint": capability,
        "target_action_hint": "app_paste",
        **(
            {"target_container_action_hint": container_action}
            if container_action
            else {}
        ),
    }


def _looks_like_generic_capability_app_phrase(value: str, app_name: str) -> bool:
    raw = _clean_prompt(value)
    if not raw:
        return False
    app_noun = re.search(
        r"(?:应用(?:程序)?|app|application|软件|工具|程序|编辑器|tool|program|editor)",
        raw,
        flags=re.IGNORECASE,
    )
    if not app_noun:
        return False
    if re.search(
        r"(?:一个|一款|任意|任何|默认|可用|合适|其他|其它|"
        r"\b(?:an?|any|some|available|default|suitable|other|another|local)\b)",
        raw,
        flags=re.IGNORECASE,
    ):
        return True
    query = _app_capability_discovery_query(raw)
    return bool(query and query.lower() == _clean_prompt(app_name).lower())


def _discovered_app_write_followup_target_hint(
    text: str,
    *,
    require_data_analysis: bool = True,
) -> dict[str, Any]:
    value = _clean_prompt(text)
    if require_data_analysis and not _data_analysis_action_requested(value):
        return {}
    if not (
        _looks_like_dynamic_context_transfer(value)
        or _contains_any(
            value,
            (
                "报告",
                "报表",
                "文档",
                "文件",
                "markdown",
                "Markdown",
                "report",
                "document",
                "file",
            ),
        )
    ):
        return {}
    app_capability = _app_capability_discovery_hint(value)
    if not app_capability:
        return {}
    container_action = _dynamic_context_target_container_action_hint(value)
    if not container_action and _contains_any(
        value,
        (
            "报告",
            "报表",
            "文档",
            "文件",
            "markdown",
            "Markdown",
            "report",
            "document",
            "file",
        ),
    ):
        container_action = "new_document"
    return {
        "target_app_capability_hint": app_capability,
        "target_action_hint": "app_paste",
        **(
            {"target_container_action_hint": container_action}
            if container_action
            else {}
        ),
    }


def _looks_like_file_output_target(value: str) -> bool:
    target = str(value or "").strip()
    if not target:
        return False
    if target.startswith(("~", ".", "/")) or "/" in target or "\\" in target:
        return True
    return bool(re.search(r"\.[A-Za-z0-9]{1,8}$", target))


def _looks_like_non_app_dynamic_context_target(app_name: str) -> bool:
    normalized = re.sub(r"[\s._·-]+", " ", str(app_name or "").strip().lower())
    if not normalized:
        return True
    if re.fullmatch(
        r"(?:当前)?(?:网页|页面)(?:坐标|位置)?(?:\s+\d+(?:\s+\d+)?)?",
        normalized,
        flags=re.IGNORECASE,
    ) or re.fullmatch(
        r"(?:current\s+)?(?:web\s+)?page(?:\s+(?:coordinates?|position))?"
        r"(?:\s+\d+(?:\s+\d+)?)?",
        normalized,
        flags=re.IGNORECASE,
    ):
        return True
    if normalized in {
        "current page",
        "current web",
        "current webpage",
        "current web page",
        "current window",
        "current app",
        "selected text",
        "clipboard",
        "research current page",
        "research current webpage",
        "research current web page",
    }:
        return True
    return bool(
        re.search(
            r"\b(?:current\s+web|current\s+(?:web\s+)?page|current\s+window|selected\s+text|clipboard)\b",
            normalized,
            flags=re.IGNORECASE,
        )
    )


def _dynamic_context_target_container_action_hint(text: str) -> str:
    value = _clean_prompt(text)
    if re.search(
        r"(?:新笔记|新建笔记|创建笔记|新备忘录|新建备忘录|创建备忘录|"
        r"\bnew\s+note\b|\bcreate\s+(?:a\s+)?new\s+note\b|\bmake\s+(?:a\s+)?new\s+note\b)",
        value,
        flags=re.IGNORECASE,
    ):
        return "new_note"
    if re.search(
        r"(?:新页面|新建页面|创建页面|新页|新建页|创建页|新建一页|创建一页|新文档|新建文档|创建文档|新文件|新建文件|创建文件|"
        r"新表格|新建表格|创建表格|"
        r"\bnew\s+(?:page|document|file|table|spreadsheet)\b|"
        r"\bcreate\s+(?:a\s+)?new\s+(?:page|document|file|table|spreadsheet)\b|"
        r"\bmake\s+(?:a\s+)?new\s+(?:page|document|file|table|spreadsheet)\b)",
        value,
        flags=re.IGNORECASE,
    ):
        return "new_document"
    return ""


def _dynamic_context_transform_requested(text: str) -> bool:
    value = _clean_prompt(text)
    return bool(
        re.search(
            r"(?:总结|摘要|概括|归纳|整理|提炼|改写|润色|翻译|转成|转换成|"
            r"变成|做成|生成|待办|任务清单|清单|"
            r"summarize|summary|summarise|brief|organize|organise|rewrite|"
            r"polish|translate|translation|convert|format|todo|to-do|task list)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _blocked_dynamic_context_ui_transfer_hint(text: str) -> bool:
    value = _clean_prompt(text)
    source = _dynamic_context_source_hint(value)
    target_kind, _target = _dynamic_context_ui_target_hint(value)
    return source == "current_page_content" and target_kind == "current_input"


def _dynamic_context_source_hint(text: str) -> str:
    lowered = _clean_prompt(text).lower()
    if _contains_any(
        lowered,
        (
            "current page link",
            "current browser page link",
            "current browser tab link",
            "current url",
            "当前网页链接",
            "当前页面链接",
            "当前浏览器页面链接",
            "当前浏览器网页链接",
            "当前浏览器标签页链接",
            "当前链接",
            "当前页地址",
        ),
    ):
        return "current_page_link"
    if _contains_any(
        lowered,
        (
            "current page content",
            "current page text",
            "current window content",
            "copy current window content",
            "current page table",
            "current page data",
            "current window table",
            "current window data",
            "当前网页内容",
            "当前页面内容",
            "当前网页正文",
            "当前页面正文",
            "当前网页表格",
            "当前页面表格",
            "当前网页数据",
            "当前页面数据",
            "当前窗口表格",
            "当前窗口数据",
            "当前窗口内容",
            "当前应用内容",
        ),
    ):
        return "current_page_content"
    if _contains_any(
        lowered,
        (
            "selected text",
            "highlighted text",
            "selection",
            "selected link",
            "selected url",
            "选中文字",
            "选中文本",
            "选中链接",
            "选中网址",
            "选中的文字",
            "选中的文本",
            "选中的内容",
            "选中的数据",
            "当前选择的文字",
            "当前选择的文本",
            "当前选择的内容",
            "当前选中的文字",
            "当前选中的文本",
            "当前选中的内容",
            "选中内容",
            "选中数据",
        ),
    ):
        return "selection"
    return context_source_hint(lowered)


def _dynamic_context_ui_target_hint(text: str) -> tuple[str, str]:
    value = _clean_prompt(text)
    lowered = value.lower()
    if _contains_any(
        lowered,
        (
            "address bar",
            "url bar",
            "location bar",
            "地址栏",
            "网址栏",
        ),
    ):
        return "ui_field", "地址"
    if _contains_any(
        lowered,
        (
            "search box",
            "search field",
            "search bar",
            "搜索框",
            "搜索栏",
            "查找框",
            "检索框",
        ),
    ):
        return "ui_field", "搜索"
    if _contains_any(
        lowered,
        (
            "current input",
            "current field",
            "current text box",
            "foreground input",
            "当前输入框",
            "当前文本框",
            "前台输入框",
            "前台文本框",
            "粘贴回去",
            "贴回去",
            "粘贴回来",
            "贴回来",
            "粘贴回当前窗口",
            "贴回当前窗口",
            "粘贴到当前窗口",
            "贴到当前窗口",
            "回填",
            "这里",
            "此处",
            "here",
            "paste back",
            "replace selection",
        ),
    ):
        return "current_input", ""
    return "", ""


def _dynamic_context_current_input_write_target(text: str) -> bool:
    value = _clean_prompt(text)
    target_kind, _target = _dynamic_context_ui_target_hint(value)
    if target_kind == "current_input":
        return True
    return bool(
        re.search(
            r"(?:粘贴回去|贴回去|粘贴回来|贴回来|粘贴回当前窗口|贴回当前窗口|"
            r"粘贴到当前窗口|贴到当前窗口|回填|替换选中|替换原文|"
            r"\bpaste\s+back\b|\breplace\s+(?:the\s+)?(?:selection|selected\s+text)\b|"
            r"\bback\s+into\s+(?:the\s+)?(?:current|same)\b)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_dynamic_context_copy_only(text: str) -> bool:
    value = _clean_prompt(text)
    if not re.search(r"(?:复制|copy)", value, flags=re.IGNORECASE):
        return False
    return not re.search(
        r"(?:粘贴|贴到|输入到|输入进|填到|填入|填写到|paste|type|enter|insert|put)",
        value,
        flags=re.IGNORECASE,
    )


def _looks_like_dynamic_context_transfer(text: str) -> bool:
    value = _clean_prompt(text)
    return bool(
        re.search(
            r"(?:粘贴|贴到|输入到|输入进|输入|键入|填到|填入|填写到|填写|"
            r"写进|写入|写到|保存到|记录到|记到|放到|"
            r"替换|paste|type|enter|insert|put|write|save|record|replace)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:总结|摘要|概括|归纳|整理|提炼|生成|输出|导出|做成).{0,16}(?:到|进|至)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:summari[sz]e|summary|organize|organise|convert|format|export|output)\b"
            r".{0,40}\b(?:to|into|in)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _dynamic_context_transfer_app_name_hint(text: str) -> str:
    value = _clean_prompt(text)
    patterns = (
        r"(?:总结|摘要|概括|归纳|整理|提炼|生成|输出|导出|做成).{0,16}(?:到|进|至)\s*"
        r"(?P<app>[\w .·-]{1,40}?)(?:\s*(?:新笔记|新备忘录|新便签|"
        r"新页面|新文档|新文件|笔记|备忘录|便签|页面|文档|文件|"
        r"new\s+note|new\s+page|new\s+document|new\s+file|"
        r"note|page|document|file))(?:$|[。！？!?，,])",
        r"(?:粘贴到|粘贴在|贴到|输入到|输入进|填到|填入|填写到|放到)\s*"
        r"(?P<app>[\w .·-]{1,40}?)(?:$|[。！？!?，,])",
        r"(?:写进|写入|写到|保存到|记录到|记到|放到)\s*"
        r"(?P<app>[\w .·-]{1,40}?)(?:\s*(?:新笔记|新备忘录|新便签|"
        r"新页面|新文档|新文件|笔记|备忘录|便签|页面|文档|文件|"
        r"new\s+note|new\s+page|new\s+document|new\s+file|"
        r"note|page|document|file))?(?:$|[。！？!?，,])",
        r"\b(?:summari[sz]e|summary|organize|organise|convert|format|export|output)\b"
        r".{0,40}\b(?:to|into|in)\s+"
        r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:new\s+note|new\s+page|new\s+document|new\s+file|"
        r"note|page|document|file)(?:$|[.!?,])",
        r"(?:在|用|通过)\s*(?P<app>[\w .·-]{1,40}?)(?:里|中|上|内)?\s*"
        r"(?:粘贴|贴|输入|填入|填写|写进|写入|写到|保存|记录|记下)",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?:打开|启动|开启|切到|聚焦)?\s*"
        r"(?P<app>[\w .·-]{1,40}?)(?:里|中|上|内)?\s*"
        r"(?:粘贴|贴|输入|填入|填写|写进|写入|写到|保存|记录|记下)\s*"
        r"(?:当前|选中|剪贴板|粘贴板|网页|页面|窗口|链接|内容|文本|文字|clipboard|current|selected)",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?:打开|启动|开启|切到|聚焦)?\s*"
        r"(?P<app>[\w .·-]{1,40}?)(?:的)?\s*"
        r"(?:搜索框|搜索栏|查找框|检索框|地址栏|输入框|文本框)\s*"
        r"(?:粘贴|贴|输入|填入|填写)",
        r"(?:paste|type|enter|insert|put|write|save|record)\b.+?\b(?:in|into|to)\s+"
        r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)(?:$|[.!?,])",
        r"\b(?:in|inside|within|using|with)\s+"
        r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:paste|type|enter|insert|put|write|save|record)\b",
        r"^(?:open|launch|focus|switch\s+to)?\s*"
        r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:(?:search|input|text)\s+(?:box|field)|address\s+bar)?\s*"
        r"(?:paste|type|enter|insert|put|write|save|record)\b",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        app = _clean_dynamic_context_target_app(match.group("app"))
        if app:
            return app
    return ""


def _non_notes_dynamic_context_target_app(text: str) -> str:
    app = _dynamic_context_transfer_app_name_hint(text)
    return app if app and not _is_structured_notes_app_target(app) else ""


def _is_structured_notes_app_target(app_name: str) -> bool:
    normalized = re.sub(r"[\s._·-]+", "", str(app_name or "").strip().lower())
    return normalized in {"notes", "applenotes", "备忘录", "笔记"}


def _clean_dynamic_context_target_app(value: str) -> str:
    app = str(value or "").strip(" .，,。")
    if _is_structured_notes_app_target(app):
        return "Notes"
    app = re.sub(
        r"(?:的)?\s*(?:搜索框|搜索栏|查找框|检索框|地址栏|网址栏|输入框|文本框)$",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(
        r"\s*(?:(?:search|input|text)\s+(?:box|field)|search\s+bar|address\s+bar|url\s+bar|location\s+bar)$",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(
        r"\s*(?:new\s+)?(?:note|page|document|file|table|spreadsheet)$",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    app = re.sub(
        r"\s*(?:新笔记|新备忘录|新便签|新页面|新文档|新文件|新表格|新建表格|"
        r"笔记|备忘录|便签|页面|文档|文件|表格)$",
        "",
        app,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    normalized_named_app = _clean_app_name_hint(app)
    if normalized_named_app:
        app = normalized_named_app
    if (
        not app
        or context_source_hint(app)
        or _is_generic_foreground_app_label(app)
        or _invalid_app_scoped_followup_app(app)
    ):
        return ""
    return _canonical_app_name_hint(app)


def _foreground_compose_app_name_hint(text: str) -> str:
    value = _clean_prompt(text)
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?:打开|启动|切到|聚焦)?\s*"
        r"(?P<app>[\w .·-]{1,40}?)\s*"
        r"(?:输入|键入|填写|写入|写|发送|发出|"
        r"(?<![开派转分研触首补签颁印])发|粘贴|paste)",
        r"^(?:open|launch|focus|switch\s+to)?\s*(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
        r"(?:type|enter|write|send|paste)\b",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        raw_app = match.group("app")
        if _looks_like_too_short_cjk_app_label(raw_app):
            continue
        app = _clean_dynamic_context_target_app(raw_app)
        if _credible_foreground_compose_app_target(raw_app, app):
            return app
    return ""


def _credible_foreground_compose_app_target(raw_app: str, app: str) -> bool:
    """Reject task clauses that a bare compose regex mistook for app names."""

    raw = str(raw_app or "").strip()
    clean_app = str(app or "").strip()
    if not clean_app or _is_generic_foreground_app_label(clean_app):
        return False
    if is_legacy_app_name_hint(raw) or is_legacy_app_name_hint(clean_app):
        return True
    return not bool(
        re.match(
            r"(?:做|完成|执行|进行|开展|处理|安排|实现|验证|校验|检查|"
            r"确认|评估|测试|模拟|演示)|"
            r"(?:perform|complete|execute|conduct|validate|verify|check|test)\b",
            raw,
            flags=re.IGNORECASE,
        )
    )


def _clean_foreground_compose_text(value: str) -> str:
    text = str(value or "").strip()
    text = re.sub(r"^(?:[:：]\s*)+", "", text).strip()
    text = re.sub(r"^[\"'`“”‘’]+|[\"'`“”‘’]+$", "", text).strip()
    text = re.sub(r"^(?:[:：]\s*)+", "", text).strip()
    text = re.sub(
        r"\s*[，,；;]?\s*(?:并|然后|再|后|之后|随后|接着|\band\s+then\b|\bthen\b|\band\b)\s*"
        r"(?:按下|按一下|按|press|hit)\s*(?:回车|enter|return)"
        r"(?:确认|确定|提交|发送|send|submit|confirm)?$",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip()
    text = re.sub(
        r"\s*[，,；;]?\s*(?:并|然后|再|后|之后|随后|接着|\band\s+then\b|\bthen\b|\band\b)\s*"
        r"(?:点击|点一下|点按|单击|按一下|按下|按|click|tap|press)\s+[^。！？!?，,；;]+$",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip()
    text = re.sub(r"\s*(?:并|然后|再|后)?\s*(?:发送|发出|send)$", "", text, flags=re.IGNORECASE).strip()
    text = re.sub(
        r"\s*[，,；;]?\s*(?:并|然后|再|后|之后|随后|接着)?\s*"
        r"(?:确认|确定|提交|保存|回车|send|submit|confirm|save|press\s+enter|hit\s+enter)$",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip()
    text = re.sub(
        r"\s*[，,；;]?\s*(?:并|然后|再|后|之后|随后|接着|\band\s+then\b|\bthen\b|\band\b)\s*"
        r"(?:点击|点一下|点按|单击|按一下|按下|按|click|tap|press)\s+[^。！？!?，,；;]+$",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip()
    text = re.sub(r"[。！？!?，,；;]+$", "", text).strip()
    return text


def _looks_like_foreground_text_scope(value: str) -> bool:
    return _contains_any(
        value,
        (
            "当前输入框",
            "当前文本框",
            "前台输入框",
            "前台文本框",
            "current input",
            "current field",
            "foreground input",
        ),
    )


def _is_generic_foreground_app_label(value: str) -> bool:
    clean = str(value or "").strip().lower()
    normalized = re.sub(r"[\s._·-]+", "", clean)
    qualifier_only = {
        "可用",
        "可用的",
        "任意可用",
        "任意可用的",
        "任何可用",
        "任何可用的",
        "可使用",
        "可使用的",
        "能用",
        "能用的",
        "合适",
        "合适的",
        "适合",
        "适合的",
        "推荐",
        "推荐的",
        "可见",
        "可见的",
        "当前可见",
        "当前可见的",
        "available",
        "anyavailable",
        "someavailable",
        "visible",
        "currentlyvisible",
        "default",
        "suitable",
        "best",
        "usable",
        "installed",
        "local",
    }
    if normalized in qualifier_only:
        return True
    normalized_without_suffix = re.sub(
        r"(?:应用程序|应用|软件|客户端|工具|程序|app|application|software)$",
        "",
        normalized,
    )
    if normalized_without_suffix in qualifier_only:
        return True
    if any(
        term in normalized
        for term in (
            "当前窗口",
            "前台窗口",
            "当前应用",
            "当前前台",
            "前台应用",
            "当前输入框",
            "前台输入框",
            "currentwindow",
            "foregroundwindow",
            "currentapp",
            "foregroundapp",
        )
    ):
        return True
    return normalized in {
        "当前",
        "任何当前",
        "在当前",
        "在任何当前",
        "可见",
        "可见的",
        "当前可见",
        "当前可见的",
        "前台",
        "在前台",
        "可用",
        "可用的",
        "任意可用",
        "任意可用的",
        "任何可用",
        "任何可用的",
        "当前输入框",
        "前台输入框",
        "当前文本框",
        "前台文本框",
        "当前消息",
        "前台消息",
        "current",
        "foreground",
        "any",
        "available",
        "anyavailable",
        "任意",
        "currentinput",
        "foregroundinput",
        "currentfield",
        "foregroundfield",
        "currentmessage",
        "foregroundmessage",
    }


def _looks_like_too_short_cjk_app_label(value: str) -> bool:
    clean = str(value or "").strip()
    return bool(re.fullmatch(r"[\u4e00-\u9fff]", clean))


def _looks_like_recipient_message_request(value: str) -> bool:
    return bool(
        re.search(
            r"(?:发消息|发送|发)\s*(?:一条|条|一则|则)?\s*"
            r"(?:消息|短信|微信)?\s*(?:给|到)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:给|向|对)\s*[^：:，,。]+?\s*(?:发送|发消息|发)\s*"
            r"(?:一条|条|一则|则)?\s*(?:消息|短信|微信)?\s*"
            r"(?:说|[:：]|内容是|内容为)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:给|向|对)\s*[^：:，,。]+?\s*(?:发送|发出|发消息|发)\s*"
            r"(?:在|用|通过)?\s*"
            r"(?:Microsoft Teams|Google Chat|企业微信|Apple Messages|Messages|"
            r"Telegram|WhatsApp|Discord|Slack|WeChat|微信|飞书|钉钉|QQ|Mail|"
            r"[A-Za-z][A-Za-z0-9 ._-]{1,40})?\s*(?:里|中|上|内)?\s*"
            r"(?:一条|条|一则|则)?\s*"
            r"(?:邮件|电子邮件|消息|短信|微信|email|e-mail|mail|message)?\s*"
            r"(?:说明|说(?!明)|[:：]|内容是|内容为)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(r"\b(?:send|message)\s+.+?\s+(?:to|for)\s+", value, flags=re.IGNORECASE)
    )


def _looks_like_communication_task_request(value: str) -> bool:
    text = _clean_prompt(value)
    return bool(
        _looks_like_recipient_message_request(text)
        or re.search(
            r"(?:给|向|对)\s*[^：:，,。]+?\s*"
            r"(?:写|撰写|起草|草拟|发|发送|回复|回)\s*"
            r"(?:一封|封|条)?\s*(?:邮件|消息|短信|微信|email|mail|message)",
            text,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:写|撰写|起草|草拟|发|发送|回复|回)\s*"
            r"(?:一封|封|条)?\s*(?:邮件|消息|短信|微信|email|mail|message)\s*"
            r"(?:给|发给|发送给|向|对)\s*[^：:，,。]+",
            text,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:write|draft|compose|send|reply)\s+(?:an?\s+)?"
            r"(?:email|e-mail|mail|message)\s+(?:to|for)\s+",
            text,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_schedule_request(value: str) -> bool:
    return bool(
        _contains_any(value, _SCHEDULE_ACTION_TERMS)
        or (
            "会议" in value
            and _contains_any(
                value,
                ("今天", "明天", "后天", "上午", "下午", "晚上", "点", "时间", "日程"),
            )
        )
    )


def _looks_like_timed_schedule_request(value: str) -> bool:
    text = _clean_prompt(value)
    if not text or not _looks_like_schedule_request(text):
        return False
    return bool(
        re.search(
            r"(?:今天|今日|今晚|明天|明日|明晚|后天|下周[一二三四五六日天]|"
            r"下星期[一二三四五六日天]|上午|早上|下午|晚上|中午|凌晨|"
            r"\d{1,2}\s*点|\d{1,2}\s*[:：]\s*\d{1,2}|"
            r"\b(?:today|tomorrow|tonight)\b|\bat\s+\d{1,2}(?::\d{2})?\b)",
            text,
            flags=re.IGNORECASE,
        )
    )


