def _looks_like_explicit_group_run_request(value: str) -> bool:
    text = _clean_prompt(value)
    if not text:
        return False
    if _looks_like_timed_schedule_request(text) and not re.search(
        r"(?:agent|Agent|AI|智能体|代理|group|群组|小组|多\s*agent|多Agent)",
        text,
        flags=re.IGNORECASE,
    ):
        return False
    return bool(
        re.search(r"(?:group|群组|小组|团队)", text, flags=re.IGNORECASE)
        and re.search(
            r"(?:运行|启动|执行|让|安排|委派|分配|指派|协作|run|start|execute|delegate|assign)",
            text,
            flags=re.IGNORECASE,
        )
    )


def _desktop_content_artifact_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    value_without_paths = re.sub(
        r"(?:~|/|\./|\../)?[^\s\"'“”‘’，,。；;]+"
        r"\.(?:pdf|md|markdown|txt|csv|tsv|xlsx|xls|json|jsonl|doc|docx|rtf|"
        r"pages|numbers|py|js|jsx|ts|tsx|java|go|rs|swift|kt|kts|c|cc|cpp|h|hpp|"
        r"png|jpg|jpeg|heic|gif|webp|ppt|pptx|key)",
        "",
        value,
        flags=re.IGNORECASE,
    )
    if re.search(r"(?<![\w.])md(?![\w.])", value_without_paths, flags=re.IGNORECASE):
        return True
    return _contains_any(
        value_without_paths,
        (
            "报告",
            "总结",
            "摘要",
            "整理",
            "markdown",
            "report",
            "summary",
            "summarize",
            "write up",
            "document",
            "link list",
            "list links",
            "links list",
            "source list",
            "sources",
            "链接清单",
            "链接列表",
            "列出链接",
            "发布说明",
            "变更说明",
            "更新说明",
            "release notes",
            "changelog",
        ),
    )


def _release_notes_report_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if not _contains_any(
        value,
        (
            "发布说明",
            "发行说明",
            "变更说明",
            "更新说明",
            "release notes",
            "changelog",
        ),
    ):
        return False
    return not _contains_any(value, _COMMUNICATION_ACTION_TERMS)


def _desktop_content_artifact_hint(text: str) -> dict[str, str]:
    if not _desktop_content_artifact_requested(text):
        return {}
    return {
        "path": _artifact_output_path(text, "desktop-content-report.md"),
        "body_source": "desktop_content",
    }


def _negated_app_control_clause(text: str) -> bool:
    value = str(text or "").strip()
    return bool(
        re.search(
            r"(?:不要|不需要|无需|不用|不必|不可|别|禁止|避免|不)\s*(?:再\s*)?"
            r"(?:打开|启动|开启|运行|拉起|切换到?|切到|切回|聚焦|激活|置前)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:不要|不需要|无需|不用|不必|不可|别|禁止|避免|不)\s*(?:再\s*)?(?:把|将)\s*"
            r"[^，,。；;！!？?\n]{1,60}?\s*"
            r"(?:打开|启动|开启|运行|拉起|切换到?|切到|切回|聚焦|激活|置前)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:do\s+not|don['’]t|dont|never|without)\s+"
            r"(?:open|launch|start(?:\s+up)?|run|switch(?:\s+to)?|focus|activate|bring)\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\bwithout\s+(?:opening|launching|starting|running|switching(?:\s+to)?|"
            r"focusing|activating|bringing)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _affirmative_app_control_text(text: str) -> str:
    value = _clean_prompt(text)
    separator_pattern = re.compile(
        r"[，,。；;！!？?\n]+|(?:但是|不过|然而|然后|接着|随后|同时|并且|但)|"
        r"\b(?:but|however|then|and|without)\b",
        flags=re.IGNORECASE,
    )
    kept: list[str] = []
    pending_separator = ""
    cursor = 0
    for separator in separator_pattern.finditer(value):
        clause = value[cursor : separator.start()]
        if clause.strip():
            if not _negated_app_control_clause(pending_separator + clause):
                kept.extend((pending_separator if kept else "", clause))
            pending_separator = separator.group(0)
        else:
            pending_separator += clause + separator.group(0)
        cursor = separator.end()
    clause = value[cursor:]
    if clause.strip() and not _negated_app_control_clause(pending_separator + clause):
        kept.extend((pending_separator if kept else "", clause))
    return "".join(kept).strip()


def _authorized_app_control_text(text: str) -> str:
    """Remove app-control mentions that lack authority while preserving payloads."""

    value = _affirmative_app_control_text(text)
    if not value:
        return ""
    action_matches = tuple(_APP_CONTROL_AUTHORITY_ACTION_RE.finditer(value))
    unauthorized = [
        action_match
        for action_match in action_matches
        if not _speech_act_action_occurrence_is_authorized(
            value,
            action_match.start(),
            action_match.end(),
        )
    ]
    if not unauthorized:
        return value

    quote_spans = _speech_act_quote_spans(value)
    removals: list[tuple[int, int]] = []
    for action_match in unauthorized:
        quoted_span = next(
            (
                (quote_start, quote_end)
                for quote_start, quote_end in quote_spans
                if quote_start < action_match.end()
                and action_match.start() < quote_end
            ),
            None,
        )
        if quoted_span is not None:
            removals.append(quoted_span)
            continue
        clause_start, clause_end = _speech_act_clause_bounds(
            value,
            action_match.start(),
        )
        relative_start = action_match.start() - clause_start
        prefix = value[clause_start : action_match.start()]
        removal_start = clause_start
        contextual_matches = [
            *list(_SPEECH_ACT_REPORTED_PREFIX_RE.finditer(prefix)),
            *list(_SPEECH_ACT_LOCAL_CONDITIONAL_RE.finditer(prefix)),
        ]
        if contextual_matches:
            removal_start = clause_start + max(
                contextual_matches,
                key=lambda match: match.start(),
            ).start()
        elif _SPEECH_ACT_DIAGNOSTIC_PREFIX_RE.search(prefix):
            removal_start = clause_start
        else:
            negation_matches = tuple(_SPEECH_ACT_NEGATION_RE.finditer(prefix))
            if negation_matches:
                removal_start = clause_start + negation_matches[-1].start()
            elif relative_start > 0:
                removal_start = action_match.start()
        removals.append((removal_start, clause_end))

    characters = list(value)
    for start, end in removals:
        characters[start:end] = " " * (end - start)
    sanitized = re.sub(r"\s+", " ", "".join(characters)).strip()
    sanitized = re.sub(
        r"(?:\b(?:and|or|then)\b|并且|以及|然后|或者)\s*$",
        "",
        sanitized,
        flags=re.IGNORECASE,
    ).strip(" ，,;；")
    return sanitized


def _explicit_app_open_request(text: str) -> bool:
    text = _affirmative_app_control_text(text)
    return _contains_any(
        text,
        ("打开", "启动", "开启", "运行", "拉起", "open ", "launch ", "start "),
    ) or bool(
        re.search(r"(?:开了|开起来|开一下|开下|\bstart\s+up\b)", text, flags=re.IGNORECASE)
        or re.search(r"开\s+[\w.·-]", text, flags=re.IGNORECASE)
    )


def _explicit_app_focus_request(text: str) -> bool:
    return _contains_any(
        _affirmative_app_control_text(text),
        (
            "切换到",
            "切到",
            "切回",
            "回到",
            "切一下",
            "切下",
            "聚焦",
            "激活",
            "置前",
            "focus",
            "switch to",
            "switch ",
            "activate ",
            "bring ",
            "go back to",
            "switch back to",
            "back to",
        ),
    )


def _app_find_then_open_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    return bool(
        re.search(
            r"^(?:帮我|请|麻烦)?(?:找一下|找下|找找|找)\s*"
            r"[\w .·-]{1,40}?\s*(?:并|然后|再|接着|之后|后)\s*"
            r"(?:打开|启动|开启|运行|拉起|开)(?:一下|下|起来)?",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:find|look\s+for)\s+"
            r"[A-Za-z][A-Za-z0-9 ._-]{1,40}?\s+"
            r"(?:and|then)\s+(?:open|launch|start(?:\s+up)?)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_foreground_submit_scope(value: str, lowered: str) -> bool:
    return bool(
        _contains_any(
            value,
            (
                "前台",
                "当前输入框",
                "当前文本框",
                "当前消息",
                "当前内容",
                "foreground",
                "current input",
                "current field",
                "current text box",
                "current message",
            ),
        )
        or re.search(
            r"(?:按|敲|点|tap|press|hit).{0,8}(?:回车|return|enter)",
            lowered,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:回车|return|enter).{0,12}(?:发送|提交|send|submit)",
            lowered,
            flags=re.IGNORECASE,
        )
    )


def _foreground_submit_hotkey_only_hint(text: str) -> bool:
    value = _clean_prompt(text)
    return bool(
        re.search(
            r"(?:(?:按|敲|点|tap|press|hit).{0,8})?"
            r"(?:回车键?|return|enter).{0,12}"
            r"(?:发送|提交|send|submit)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _foreground_submit_app_name_hint(text: str, action: str) -> str:
    if not action:
        return ""
    value = _clean_prompt(text)
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?P<app>[\w .·-]{1,40}?)"
        r"(?:按|敲|点|tap|press|hit).{0,8}(?:回车|return|enter).{0,8}(?:发送|提交|send|submit)",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?P<app>[\w .·-]{1,40}?)"
        r"(?:发送|提交|send|submit).{0,8}(?:回车|return|enter)",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        app = _canonical_app_name_hint(match.group("app"))
        if app:
            return app
    app_scoped_submit = _app_scoped_foreground_submit_app_name_hint(value)
    if app_scoped_submit:
        return app_scoped_submit
    return ""


def _app_scoped_foreground_submit_app_name_hint(text: str) -> str:
    value = _clean_prompt(text)
    if not value or _looks_like_recipient_message_request(value):
        return ""
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?:打开|启动|开启|切到|聚焦)?"
        r"(?:在|到|用|通过)?\s*"
        r"(?P<app>[\w .·-]{1,40}?)(?:里|中|上|内)?\s*(?:确认)?(?:发送|提交)\s*$",
        r"^(?:please\s+)?(?:open|launch|focus|switch\s+to)?\s*"
        r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+(?:confirm\s+)?(?:send|submit)\s*$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        raw_app = str(match.group("app") or "").strip()
        if not raw_app or raw_app.startswith(("给", "向", "对")):
            continue
        if re.search(
            r"(?:粘贴|输入|键入|填写|写入|点击|搜索|查找|复制|剪贴板|"
            r"按|敲|回车|paste|type|enter|return|press|hit|tap|click|search|copy|clipboard)",
            raw_app,
            flags=re.IGNORECASE,
        ):
            continue
        if _is_generic_foreground_app_label(raw_app):
            continue
        app = _canonical_app_name_hint(raw_app)
        if app and not _is_generic_foreground_app_label(app):
            return app
    return ""


def _canonical_app_name_hint(value: str) -> str:
    app = _clean_app_name_hint(value)
    if not app:
        return ""
    return legacy_app_name_hint(app)


def _browser_internal_page_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    surface = (
        r"(?:下载内容|下载页面|下载页|下载记录|下载|书签|收藏夹|扩展程序|扩展|插件|"
        r"历史记录|浏览历史|设置|偏好设置|"
        r"downloads?|download\s+page|bookmarks?|favorites?|extensions?|add-?ons?|addons?|"
        r"history|settings|preferences)"
    )
    patterns: tuple[tuple[str, str], ...] = (
        (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?P<mode>打开|启动|开启|切到|聚焦)\s*"
            rf"(?P<app>[\w .·-]{{1,40}}?)\s*(?:的)?\s*(?P<surface>{surface})"
            r"(?:一下|下)?(?:可以吗|好吗|好么|行吗|吗|嘛|吧|呢)?$",
            "",
        ),
        (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            rf"(?P<app>[\w .·-]{{1,40}}?)\s*(?:打开|显示|查看|进入|切到|聚焦)\s*"
            rf"(?P<surface>{surface})(?:一下|下)?(?:可以吗|好吗|好么|行吗|吗|嘛|吧|呢)?$",
            "focus",
        ),
        (
            r"^(?P<mode>open|launch|start|focus|switch\s+to|activate)\s+"
            rf"(?:the\s+)?(?P<app>[A-Za-z][A-Za-z0-9 ._-]{{1,40}}?)\s+"
            rf"(?:the\s+)?(?P<surface>{surface})$",
            "",
        ),
        (
            rf"^(?P<app>[A-Za-z][A-Za-z0-9 ._-]{{1,40}}?)\s+"
            rf"(?P<surface>{surface})$",
            "focus",
        ),
    )
    for pattern, default_mode in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        app_name = _clean_app_name_hint(groups.get("app") or "")
        if (
            not app_name
            or _is_generic_browser_app_label(app_name)
            or not _is_browser_or_search_app_name(app_name)
        ):
            continue
        surface_kind = _browser_internal_surface_kind(groups.get("surface") or "")
        if not surface_kind:
            continue
        result: dict[str, str] = {
            "app_name": app_name,
            "surface": surface_kind,
            "mode": _command_palette_mode(groups.get("mode") or default_mode),
        }
        shortcut_action = _browser_internal_shortcut_action(surface_kind)
        if shortcut_action:
            result["action"] = shortcut_action
            return result
        url = _browser_internal_surface_url(app_name, surface_kind)
        if url:
            result["url"] = url
            return result
    return {}


def _browser_internal_surface_kind(value: str) -> str:
    normalized = re.sub(r"[\s_-]+", "", str(value or "").strip().lower())
    if "下载" in normalized or "download" in normalized:
        return "downloads"
    if "书签" in normalized or "收藏" in normalized or "bookmark" in normalized or "favorite" in normalized:
        return "bookmarks"
    if "扩展" in normalized or "插件" in normalized or "extension" in normalized or "addon" in normalized:
        return "extensions"
    if "历史" in normalized or "history" in normalized:
        return "history"
    if "设置" in normalized or "偏好" in normalized or "setting" in normalized or "preference" in normalized:
        return "settings"
    return ""


def _is_generic_browser_app_label(app_name: str) -> bool:
    raw = str(app_name or "").strip().lower()
    normalized = re.sub(r"\s+", " ", raw)
    return normalized in {
        "browser",
        "any browser",
        "default browser",
        "浏览器",
        "任意浏览器",
        "任何浏览器",
        "默认浏览器",
        "网页",
        "页面",
        "当前网页",
        "当前页面",
        "current page",
        "current webpage",
        "web page",
    } or _normalized_generic_browser_label(raw)


def _normalized_generic_browser_label(value: str) -> bool:
    compact = re.sub(r"[\s._·-]+", "", str(value or "").strip().lower())
    if compact in {"browser", "webbrowser", "浏览器", "网页", "页面"}:
        return True
    compact_without_qualifiers = re.sub(
        r"^(?:(?:一个|一款|个)(?:的)?|(?:任意|任何|默认|当前|可用|可使用|能用|"
        r"已安装|本地|系统自带|内置|合适|适合|推荐)(?:的)?)+",
        "",
        compact,
    )
    compact_without_suffix = re.sub(
        r"(?:应用程序|应用|软件|客户端|工具|程序|app)$",
        "",
        compact_without_qualifiers,
    )
    if compact_without_suffix in {"browser", "webbrowser", "浏览器", "网页", "页面"}:
        return True
    english = re.sub(r"[^a-z0-9]+", " ", str(value or "").strip().lower()).strip()
    english = re.sub(
        r"^(?:(?:a|an|the|any|some|available|default|current|suitable|best|"
        r"usable|installed|local|system)\s+)+",
        "",
        english,
    ).strip()
    english = re.sub(
        r"\s+(?:app|application|client|tool|program|software)$",
        "",
        english,
    ).strip()
    return english in {"browser", "web browser", "web", "web page", "webpage"}


def _generic_browser_app_search_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value:
        return {}
    if _looks_like_external_info_lookup(value):
        return {}
    if _explicit_browser_url_hint(value) or _known_web_destination_request_url_hint(value):
        return {}
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:找|找个|找一个|找一款|打开|启动|开启)\s*"
        r"(?:一个|一款|任意|任何|默认|可用|合适|适合)?\s*浏览器"
        r"(?:\s*(?P<action_cn>打开|访问|进入|搜索|搜|查找|检索))?\s*(?P<query>.+)$",
        r"\b(?:find|open|launch|start)\s+"
        r"(?:an?\s+|the\s+|any\s+|default\s+|available\s+|suitable\s+)?"
        r"(?:browser|web\s+browser)\b"
        r"(?:\s+(?:and|then|to|for))?"
        r"(?:\s+(?P<action_en>open|visit|go\s+to|search|find|look\s+up))?"
        r"\s+(?P<query_en>.+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        action = str(groups.get("action_cn") or groups.get("action_en") or "").strip()
        query = _clean_generic_browser_app_search_query(
            groups.get("query")
            or groups.get("query_en")
            or "",
            preserve_leading_english_action=bool(
                re.fullmatch(
                    r"(?:搜索|搜|查找|检索|search|find|look\s+up)",
                    action,
                    flags=re.IGNORECASE,
                )
            ),
        )
        if (
            query
            and _browser_internal_surface_kind(query)
            and not re.fullmatch(
                r"(?:搜索|搜|查找|检索|search|find|look\s+up)",
                action,
                flags=re.IGNORECASE,
            )
        ):
            continue
        if query:
            return {
                "query": query,
                "target": "搜索" if _contains_any(value, ("搜索", "搜", "查找", "检索")) else "Search",
            }
    return {}


def _clean_generic_browser_app_search_query(
    query: str,
    *,
    preserve_leading_english_action: bool = False,
) -> str:
    value = _clean_app_search_query(query).strip(" .，,。?？!！")
    if not value:
        return ""
    value = re.sub(
        r"^(?:打开|开启|访问|进入|搜索|搜一下|搜|查找|检索)\s*",
        "",
        value,
        flags=re.IGNORECASE,
    )
    value = re.sub(
        r"\s*(?:上|里|中|内)?\s*(?:搜索|搜一下|搜|查找|检索)\s*",
        " ",
        value,
        flags=re.IGNORECASE,
    )
    if not preserve_leading_english_action:
        value = re.sub(
            r"^(?:open|visit|go\s+to|search|find|look\s+up)\s+",
            "",
            value,
            flags=re.IGNORECASE,
        )
    value = re.sub(
        r"\s+(?:and|then|to)?\s*(?:search|find|look\s+up)\s+",
        " ",
        value,
        flags=re.IGNORECASE,
    )
    return re.sub(r"\s+", " ", value).strip(" .，,。?？!！")


def _generic_browser_app_target_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if _is_generic_browser_app_label(raw_explicit_app_action_target_hint(value)):
        return True
    if _explicit_browser_url_hint(value) or _known_web_destination_request_url_hint(value):
        return False
    if _known_web_destination_search_hint(value):
        return False
    if _browser_internal_surface_kind(value):
        return False
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:打开|启动|开启|切到|聚焦|检查|查看|看看)\s*"
        r"(?:一个|一款|默认|任意|任何|可用)?\s*浏览器(?:\s*(?:一下|下|起来|开了吗|打开了吗))?\s*[?？。！!]*$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:切换到|切到|聚焦|激活|置前)\s*"
        r"(?:(?:一个|一款|任意|任何|默认|可用|正在运行|运行中|已打开|打开的)(?:的)?\s*)*"
        r"浏览器\s*窗口\s*[?？。！!]*$",
        r"^(?:默认|任意|任何)?\s*浏览器.{0,24}"
        r"(?:有哪些|有什么|按钮|控件|元素|界面|窗口|开了吗|打开了吗|是否打开)",
        r"\b(?:open|launch|start|focus|inspect|check)\s+(?:the\s+)?"
        r"(?:(?:default|any)\s+)?browser\b\s*[.!?]*$",
        r"\b(?:focus|activate|switch\s+to)\s+"
        r"(?:(?:a|an|the|any|default|available|running|open)\s+)*"
        r"(?:browser|web\s+browser)\s+window\b\s*[.!?]*$",
        r"\b(?:(?:default|any)\s+)?browser\s+"
        r"(?:buttons?|controls?|elements?|visible|running|open)\b",
    )
    return any(re.search(pattern, value, flags=re.IGNORECASE) for pattern in patterns)


def _generic_music_app_target_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    open_only_pattern = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:打开|启动|开启|切到|聚焦|查看|看看|检查)\s*"
        r"(?:一个|一款|任意|任何|默认|可用)?\s*"
        r"(?:音乐\s*(?:应用|app|软件|播放器)|"
        r"(?:能|可以|可|会)?播放音乐的?(?:应用|app|软件|播放器)|"
        r"播放器|music\s+(?:app|player))"
        r"(?:\s*(?:一下|下|起来|开了吗|打开了吗))?\s*[?？。！!]*$"
    )
    if re.search(
        r"(?:搜索|搜一下|搜|查找|找|检索|播放|播|放|\bplay\b|\bsearch\b|\bfind\b)",
        value,
        flags=re.IGNORECASE,
    ) and not re.search(open_only_pattern, value, flags=re.IGNORECASE):
        return False
    patterns = (
        open_only_pattern,
        r"\b(?:open|launch|start|focus|inspect|check)\s+"
        r"(?:an?\s+|the\s+|any\s+|default\s+)?music\s+(?:app|player)\b\s*[.!?]*$",
    )
    return any(re.search(pattern, value, flags=re.IGNORECASE) for pattern in patterns)


