def _generic_communication_app_target_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    generic_prefix = (
        r"(?:(?:一个|一款|任意|任何|默认|可用|合适|适合)(?:的)?\s*)*"
    )
    generic_prefix_en = (
        r"(?:(?:an?|the|any|some|available|default|suitable|best|usable)\s+)*"
    )
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:打开|启动|开启|切到|聚焦|查看|看看|检查)\s*"
        rf"{generic_prefix}"
        r"(?:聊天|通讯|通信|消息|即时通讯|IM)\s*(?:应用|app|软件|工具|程序)?"
        r"(?:\s*(?:一下|下|起来|开了吗|打开了吗))?\s*[?？。！!]*$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:打开|启动|开启|切到|聚焦|查看|看看|检查)\s*"
        rf"{generic_prefix}"
        r"(?:邮件|电子邮件|邮箱)\s*(?:应用|app|软件|客户端|工具|程序)?"
        r"(?:\s*(?:一下|下|起来|开了吗|打开了吗))?\s*[?？。！!]*$",
        r"\b(?:open|launch|start|focus|inspect|check)\s+"
        rf"{generic_prefix_en}"
        r"(?:chat|messaging|message|messenger|communication|email|mail)\s+"
        r"(?:app|application|client|tool|program)\b\s*[.!?]*$",
        r"\b(?:open|launch|start|focus|inspect|check)\s+"
        rf"{generic_prefix_en}(?:messenger|email|mail)\b\s*[.!?]*$",
    )
    return any(re.search(pattern, value, flags=re.IGNORECASE) for pattern in patterns)


def _generic_communication_app_discovery_query(text: str, app_name_hint: str = "") -> str:
    value = _clean_prompt(f"{app_name_hint} {text}")
    if _contains_any(value, ("邮件", "电子邮件", "邮箱", "email", "mail")):
        return "mail"
    return "messaging"


def _communication_capability_query(value: str) -> bool:
    return str(value or "").strip().lower() in {"mail", "messaging"}


def _generic_communication_compose_detail_hint(
    text: str,
    *,
    channel_hint: str = "",
) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value or not _generic_communication_compose_requested(value):
        return {}
    channel = _canonical_communication_channel(
        "email" if str(channel_hint or "").strip().lower() == "mail" else channel_hint
    )
    if not channel and str(channel_hint or "").strip().lower() == "messaging":
        channel = "message"
    recipient = _generic_communication_compose_recipient_hint(value)
    body = _generic_communication_compose_body_hint(value)
    send_action = "send" if _generic_communication_compose_send_requested(value) else "draft"
    hint: dict[str, str] = {"send_action": send_action}
    if channel:
        hint["channel"] = channel
    if recipient:
        hint["recipient"] = recipient
    if body:
        hint["body"] = body
    return hint


def _generic_communication_compose_recipient_hint(text: str) -> str:
    value = _clean_prompt(text)
    patterns = (
        r"(?:给|向|对|发给|发送给)\s*(?P<recipient_action>[^：:，,。；;！!？?]+?)\s*"
        r"(?:输入|键入|发送|发|写|撰写|起草|草拟)",
        r"(?:给|向|对|发给|发送给)\s*(?P<recipient>[^：:，,。；;！!？?]+?)\s*"
        r"(?:写|撰写|起草|草拟|发|发送|输入|键入)?\s*"
        r"(?:一封|封|一条|条)?\s*(?:邮件|电子邮件|消息|短信|微信|mail|email|message)?"
        r"(?=\s*(?:说|说明|内容是|内容为|[:：]|$|[，,。；;！!？?]))",
        r"(?:写|撰写|起草|草拟|发|发送)\s*(?:一封|封|一条|条)?\s*"
        r"(?:邮件|电子邮件|消息|短信|微信|mail|email|message)\s*"
        r"(?:给|发给|发送给|向|对)\s*(?P<recipient>[^：:，,。；;！!？?]+)",
        r"\b(?:compose|draft|write|create|new|send|type)\b.{0,48}?"
        r"\b(?:email|mail|message|chat)\b.{0,24}?\b(?:to|for)\s+"
        r"(?P<recipient_en>[^.!?,]+?)(?:\s+(?:saying|about|that|with)\b|$)",
        r"\b(?:email|mail|message)\s+(?:to|for)\s+"
        r"(?P<recipient_to_en>[^.!?,]+?)(?:\s+(?:saying|about|that|with)\b|$)",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        recipient = _clean_communication_recipient_text(
            groups.get("recipient_action")
            or groups.get("recipient")
            or groups.get("recipient_en")
            or groups.get("recipient_to_en")
            or ""
        )
        recipient = re.sub(
            r"\s*(?:的)?(?:邮件|电子邮件|消息|短信|微信|mail|email|message)\s*$",
            "",
            recipient,
            flags=re.IGNORECASE,
        ).strip()
        recipient = re.sub(r"\s*的$", "", recipient).strip()
        if recipient and not _is_generic_communication_app_label(recipient):
            return recipient
    return ""


def _generic_communication_compose_body_hint(text: str) -> str:
    value = _clean_prompt(text)
    patterns = (
        r"(?:说明|说|内容是|内容为|[:：])\s*(?P<body>[^。！？!?]+)",
        r"(?:输入|键入)\s*(?P<input_body>[^。！？!?，,]+)",
        r"(?:给|向|对|发给|发送给)\s*[^：:，,。；;！!？?]+?\s*"
        r"(?:发送|发)\s*(?P<send_body>[^。！？!?，,]+)",
        r"\b(?:saying|that|about|with(?:\s+(?:body|text|message))?)\s+"
        r"(?P<body_en>[^.!?]+)",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        body = _clean_communication_body_text(
            match.groupdict().get("body")
            or match.groupdict().get("input_body")
            or match.groupdict().get("send_body")
            or match.groupdict().get("body_en")
            or ""
        )
        if body and not re.fullmatch(
            r"(?:邮件|电子邮件|消息|短信|微信|mail|email|message)",
            body,
            flags=re.IGNORECASE,
        ):
            return body
    return ""


def _generic_communication_compose_send_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if _looks_like_communication_draft_request(value):
        return False
    return bool(
        re.search(
            r"(?:发送|发出|发给|发送给|发消息|\bsend\b|\bmessage\b)",
            value,
            flags=re.IGNORECASE,
        )
        and not re.search(r"(?:写|撰写|起草|草拟|草稿|compose|draft|write)", value, flags=re.IGNORECASE)
    )


def _generic_communication_compose_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    return bool(
        re.search(
            r"(?:新建|创建|写|撰写|起草|草拟|草稿|发|发送|输入|键入).{0,24}"
            r"(?:邮件|电子邮件|邮箱|消息|短信|聊天|会话|mail|email|message|chat)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:给|向|发给|发送给)\s*[^。！？!?，,]{1,40}?"
            r"(?:写|发|发送|输入|键入)?\s*"
            r"(?:邮件|电子邮件|消息|短信|微信|hello|你好|您好|hi|在吗)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:邮件|电子邮件|邮箱|聊天|通讯|通信|消息|即时通讯|"
            r"mail|email|chat|messaging|message)"
            r"\s*(?:应用|app|软件|客户端|工具|程序)?\s*"
            r"(?:给|向|对|发给|发送给)\s*[^。！？!?，,]{1,40}?\s*"
            r"(?:写|撰写|起草|草拟|发|发送|输入|键入|说|说明|内容是|内容为|[:：])",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:compose|draft|write|create|new|send|type)\b.{0,40}"
            r"\b(?:email|mail|message|chat)\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:email|mail|message)\s+(?:to|for)\s+[^.!?,]{1,60}",
            value,
            flags=re.IGNORECASE,
        )
    )


def _browser_internal_shortcut_action(surface: str) -> str:
    if surface == "history":
        return "show_history"
    if surface == "settings":
        return "preferences"
    return ""


def _browser_internal_surface_url(app_name: str, surface: str) -> str:
    family = _browser_family(app_name)
    urls = {
        "chrome": {
            "downloads": "chrome://downloads/",
            "bookmarks": "chrome://bookmarks/",
            "extensions": "chrome://extensions/",
        },
        "edge": {
            "downloads": "edge://downloads/",
            "bookmarks": "edge://favorites/",
            "extensions": "edge://extensions/",
        },
        "brave": {
            "downloads": "brave://downloads/",
            "bookmarks": "brave://bookmarks/",
            "extensions": "brave://extensions/",
        },
        "firefox": {
            "downloads": "about:downloads",
            "extensions": "about:addons",
        },
    }
    return urls.get(family, {}).get(surface, "")


def _browser_family(app_name: str) -> str:
    compact = compact_app_name_hint(app_name)
    if compact in {"chrome", "googlechrome", "chromium"}:
        return "chrome"
    if compact in {"edge", "microsoftedge"}:
        return "edge"
    if compact in {"brave", "bravebrowser"}:
        return "brave"
    if compact == "firefox":
        return "firefox"
    return ""


def _app_preferences_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if _explicit_known_app_action_target_hint(value):
        return {}
    surface = r"(?:偏好设置|设置|preferences|settings)"
    patterns: tuple[tuple[str, str], ...] = (
        (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?P<mode>打开|启动|开启|开了|开起来|切到|聚焦)\s*"
            rf"(?P<app>[\w .·-]{{1,40}}?)\s*(?:的)?\s*(?P<surface>{surface})"
            r"(?:一下|下)?(?:可以吗|好吗|好么|行吗|吗|嘛|吧|呢)?$",
            "",
        ),
        (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            rf"(?:在|用|通过)\s*(?P<app>[\w .·-]{{1,40}}?)(?:里|中|上|内|里面)?\s*"
            rf"(?:打开|显示|查看|进入|切到|聚焦)\s*(?P<surface>{surface})"
            r"(?:一下|下)?(?:可以吗|好吗|好么|行吗|吗|嘛|吧|呢)?$",
            "focus",
        ),
        (
            r"^(?P<mode>open|launch|start|focus|switch\s+to|activate)\s+"
            rf"(?:the\s+)?(?P<app>[A-Za-z][A-Za-z0-9 ._-]{{1,40}}?)\s+"
            rf"(?P<surface>{surface})$",
            "",
        ),
        (
            r"^(?!(?:open|launch|start|focus|switch\s+to|activate)\b)"
            rf"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{{1,40}}?)\s+(?P<surface>{surface})$",
            "focus",
        ),
    )
    for pattern, default_mode in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        app_name = _clean_app_name_hint(groups.get("app") or "")
        if (
            not app_name
            or _is_browser_or_search_app_name(app_name)
            or _is_system_settings_app_label(app_name)
        ):
            continue
        return {
            "app_name": app_name,
            "mode": _command_palette_mode(groups.get("mode") or default_mode),
            "action": "preferences",
        }
    return {}


