def _clean_app_scoped_followup(value: str) -> str:
    return re.sub(
        r"^(?:并且|并|然后|之后|后(?!退)|再|接着|and\s+then|and|then)\s*",
        "",
        _clean_prompt(value),
        flags=re.IGNORECASE,
    ).strip()


def _app_command_palette_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    if _invalid_command_palette_request_reason(value):
        return {}
    if not re.search(
        r"命令面板|指令面板|command\s+palette|(?:执行|运行|打开)\s*命令|\b(?:run|execute|open)\s+(?:the\s+)?command\b",
        value,
        flags=re.IGNORECASE,
    ):
        return {}
    palette = r"(?:命令面板|指令面板|命令\s*palette|command\s+palette)"
    verb = (
        r"(?P<verb>输入|打字|键入|敲入|打入|打上|搜索|查找|找|执行|运行|打开|启动|"
        r"type|enter|search|find|run|execute|open|launch)"
    )
    open_patterns: tuple[tuple[str, str], ...] = (
        (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?:在|用|通过)\s*(?P<app>[\w .·-]{1,40}?)(?:里|中|上|内|里面)?\s*"
            rf"(?:打开|调出|唤起|显示|open|show)\s*{palette}"
            r"(?:一下|下)?(?:可以吗|好吗|好么|行吗|吗|嘛|吧|呢)?$",
            "focus",
        ),
        (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?P<mode>打开|启动|开启|切到|聚焦)\s*(?P<app>[\w .·-]{1,40}?)\s*"
            rf"(?:的)?(?:打开|调出|唤起|显示)?\s*{palette}"
            r"(?:一下|下)?(?:可以吗|好吗|好么|行吗|吗|嘛|吧|呢)?$",
            "",
        ),
        (
            rf"^(?P<app>[A-Za-z][A-Za-z0-9 ._-]{{1,40}}?)\s+{palette}$",
            "focus",
        ),
        (
            r"^(?P<mode>open|launch|start|focus|switch\s+to|activate)\s+"
            r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
            rf"(?:(?:and|then)\s+)?(?:open|show)?\s*{palette}$",
            "",
        ),
    )
    for pattern, default_mode in open_patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        app_name = _canonical_app_name_hint(groups.get("app") or "")
        if not app_name:
            continue
        return {
            "app_name": app_name,
            "mode": _command_palette_mode(groups.get("mode") or default_mode),
            "action": _command_palette_action_for_app(app_name),
        }
    patterns: tuple[tuple[str, str], ...] = (
        (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?:在|用|通过)\s*(?P<app>[\w .·-]{1,40}?)(?:里|中|上|内|里面)?\s*"
            rf"(?:打开|调出|唤起|显示|open|show)?\s*{palette}\s*"
            r"(?:(?:并且|并|然后|之后|后(?!退)|再|and\s+then|and|then)\s*)?"
            rf"{verb}\s*(?P<command>[^。！？!?]+)$",
            "focus",
        ),
        (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?P<mode>打开|启动|开启|切到|聚焦)\s*(?P<app>[\w .·-]{1,40}?)\s*"
            rf"(?:的)?(?:打开|调出|唤起|显示|open|show)?\s*{palette}\s*"
            r"(?:(?:并且|并|然后|之后|后(?!退)|再|and\s+then|and|then)\s*)?"
            rf"{verb}\s*(?P<command>[^。！？!?]+)$",
            "",
        ),
        (
            rf"^(?P<app>[A-Za-z][A-Za-z0-9 ._-]{{1,40}}?)\s+{palette}\s+"
            rf"{verb}\s+(?P<command>[^.!?]+)$",
            "focus",
        ),
        (
            r"^(?P<mode>open|launch|start|focus|switch\s+to|activate)\s+"
            r"(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
            rf"(?:(?:and|then)\s+)?(?:open|show)?\s*{palette}\s+"
            rf"(?:(?:and|then)\s+)?{verb}\s+(?P<command>[^.!?]+)$",
            "",
        ),
    )
    for pattern, default_mode in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        app_name = _canonical_app_name_hint(groups.get("app") or "")
        command_text = _clean_command_palette_text(groups.get("command") or "")
        if not app_name or not command_text:
            continue
        mode = _command_palette_mode(groups.get("mode") or default_mode)
        raw_command = str(groups.get("command") or "")
        result: dict[str, Any] = {
            "app_name": app_name,
            "mode": mode,
            "action": _command_palette_action_for_app(app_name),
            "text": command_text,
        }
        safe_key = _command_palette_safe_key_hint(raw_command)
        if safe_key:
            result["safe_key"] = safe_key
        if _command_palette_should_submit(raw_command, str(groups.get("verb") or "")):
            result["submit"] = True
        return result
    implicit_patterns: tuple[tuple[str, str], ...] = (
        (
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?:在|用|通过)\s*(?P<app>[\w .·-]{1,40}?)(?:里|中|上|内|里面)?\s*"
            r"(?P<verb>执行|运行|打开|run|execute|open)\s*命令\s*(?P<command>[^。！？!?]+)$",
            "focus",
        ),
        (
            r"^(?:in|inside|within|using|with)\s+(?P<app>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+"
            r"(?P<verb>run|execute|open)\s+(?:the\s+)?command\s+(?P<command>[^.!?]+)$",
            "focus",
        ),
    )
    for pattern, default_mode in implicit_patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        app_name = _canonical_app_name_hint(groups.get("app") or "")
        command_text = _clean_command_palette_text(groups.get("command") or "")
        if not app_name or not command_text:
            continue
        result = {
            "app_name": app_name,
            "mode": default_mode,
            "action": _command_palette_action_for_app(app_name),
            "text": command_text,
        }
        if _command_palette_should_submit(
            str(groups.get("command") or ""),
            str(groups.get("verb") or ""),
        ):
            result["submit"] = True
        return result
    return {}


def _invalid_command_palette_request_reason(text: str) -> str:
    value = _clean_prompt(text)
    palette = r"(?:命令面板|指令面板|command\s+palette)"
    if not re.search(palette, value, flags=re.IGNORECASE):
        return ""
    if re.search(
        rf"{palette}\s*(?:输入|打字|键入|敲入|打入|打上|type|enter)\s*$",
        value,
        flags=re.IGNORECASE,
    ):
        return "missing_command"
    if re.search(
        rf"{palette}\s*(?:(?:并|然后|再|接着|and\s+then|and|then)\s*)?"
        r"(?:发送|send)(?:\s|$)",
        value,
        flags=re.IGNORECASE,
    ):
        return "unsupported_send_action"
    return ""


def _command_palette_mode(value: str) -> str:
    lowered = str(value or "").strip().lower()
    if lowered in {"打开", "启动", "开启", "开了", "开起来", "open", "launch", "start"}:
        return "open"
    return "focus"


def _command_palette_action_for_app(app_name: str) -> str:
    if compact_app_name_hint(app_name) == "obsidian":
        return "obsidian_command_palette"
    return "command_palette"


def _clean_command_palette_text(value: str) -> str:
    text = _clean_prompt(value)
    text = re.sub(
        r"\s*(?:并且|并|然后|之后|随后|后(?!退)|再|接着)\s*"
        r"(?:(?:按一下|按下|按|发送|触发)\s*)?"
        r"(?:回车|enter|return|确认|确定)$",
        "",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(
        r"\s+(?:and\s+then|then|and)\s*(?:(?:press|hit|send)\s+)?(?:the\s+)?"
        r"(?:enter|return|confirm|ok)$",
        "",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(
        r"\s*(?:并且|并|然后|之后|随后|后(?!退)|再|接着)\s*"
        r"(?:(?:按一下|按下|按|发送|触发)\s*)?"
        r"(?:下箭头|向下箭头|down\s+arrow)\s*"
        r"(?:再|然后|并|and\s+then|then|and)?\s*(?:确认|确定|回车|enter|return)?$",
        "",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(
        r"\s*(?:并且|并|然后|之后|随后|后(?!退)|再|接着)\s*"
        r"(?:选择|选中|打开|点击|点一下|点按|单击|点|进入|访问|执行|确认)?\s*"
        r"(?:搜索结果|结果|命令|指令|条目|项目)?(?:中|里|里的|的)?\s*"
        r"(?:第?一个|第一条|首个|第1个|第1条|1)\s*"
        r"(?:搜索结果|结果|命令|指令|条目|项目)?$",
        "",
        text,
        flags=re.IGNORECASE,
    )
    text = re.sub(
        r"\s+(?:and\s+then|then|and)\s*"
        r"(?:select|choose|open|click|run|execute|confirm)\s+"
        r"(?:the\s+)?(?:first|1st)\s+(?:result|item|command|match)$",
        "",
        text,
        flags=re.IGNORECASE,
    )
    return text.strip(" .，,。 「」『』“”\"'`")


def _command_palette_safe_key_hint(value: str) -> dict[str, Any]:
    if re.search(r"(?:下箭头|向下箭头|down\s+arrow)", str(value or ""), flags=re.IGNORECASE):
        return {"action": "arrow_down", "repeat_count": 1}
    return {}


def _command_palette_should_submit(value: str, verb: str) -> bool:
    raw = str(value or "")
    lowered_verb = str(verb or "").strip().lower()
    if lowered_verb in {"执行", "运行", "打开", "启动", "run", "execute", "open", "launch"}:
        return True
    return bool(
        re.search(r"(?:回车|确认|确定|enter|return|confirm|ok)", raw, flags=re.IGNORECASE)
        or re.search(
            r"(?:选择|选中|打开|点击|执行|select|choose|open|click|run|execute).{0,12}"
            r"(?:第?一个|第一条|首个|第1个|第1条|1|first|1st)",
            raw,
            flags=re.IGNORECASE,
        )
    )


def _foreground_app_search_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value:
        return {}
    if (
        _ambiguous_visible_target_action_requested(value)
        or _looks_like_find_visible_target_action(value)
    ):
        return {}
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?\s*"
        r"(?:在|用|通过)?\s*(?:(?:任意|任何)\s*)?(?:(?:当前|现在|前台|这个|该)\s*){1,2}"
        r"(?:应用|app|application|窗口|界面|ui)"
        r"(?:里|中|上|内)?\s*(?:找到|找|定位|聚焦|点击|点按|选择|选中)?(?:一下|下)?\s*"
        r"(?:搜索框|搜索栏|搜索输入框|搜索输入栏|"
        r"search\s+field|search\s+box|search\s+input|search\s+bar)[\s，,：:]*"
        r"(?:(?:并|然后|再|接着|之后|后|and\s+then|then)\s*)?"
        r"(?:输入|键入|填写|填入|写入|写|搜索|查找|检索|type|enter|fill|search|find)\s*"
        r"(?P<field_query>.+?)(?:\s*(?:并|然后|再|后|之后|and|then)?\s*"
        r"(?:搜索|查找|检索|提交|确认|回车|search|submit|confirm|press\s+enter|hit\s+enter))?$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?\s*"
        r"(?:在|用|通过)?\s*(?:(?:任意|任何)\s*)?(?:(?:当前|现在|前台|这个|该)\s*){1,2}"
        r"(?:应用|app|application|窗口|界面|ui)"
        r"(?:里|中|上|内)?\s*(?:搜索|查找|检索|找)(?:一下|下)?\s*"
        r"(?P<query>.+)$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?\s*(?:把|将)?\s*"
        r"(?:(?:任意|任何)\s*)?(?:(?:当前|现在|前台|这个|该)\s*){1,2}"
        r"(?:应用|app|application|窗口|界面|ui)"
        r"(?:里|中|上|内)?\s*(?:搜索|查找|检索|找)(?:一下|下)?\s*"
        r"(?P<query_result>.+?)\s*(?:的)?(?:搜索结果|结果|内容).*$",
        r"^(?:search|find)\s+(?:for\s+)?(?P<query_en>.+?)\s+"
        r"(?:in|inside|within)\s+(?:the\s+)?(?:current|active|foreground)\s+"
        r"(?:app|application|window|ui)$",
        r"^(?:in|inside|within)\s+(?:the\s+)?(?:current|active|foreground)\s+"
        r"(?:app|application|window|ui)\s+(?:search|find)\s+(?:for\s+)?(?P<query_en2>.+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        query = _clean_app_search_query(
            match.groupdict().get("field_query")
            or match.groupdict().get("query")
            or match.groupdict().get("query_result")
            or match.groupdict().get("query_en")
            or match.groupdict().get("query_en2")
            or ""
        ).strip(" .，,。?？!！")
        if not query:
            continue
        return {
            "query": query,
            "target": "搜索" if _contains_any(value, ("搜索", "查找", "检索", "找")) else "Search",
            "scope": "foreground",
        }
    return {}


def _app_search_hint(text: str, app_name: str) -> dict[str, str]:
    if _contains_any(text, _COMMUNICATION_ACTION_TERMS):
        return {}
    if _looks_like_find_visible_target_action(text):
        return {}
    field_query = ""
    app = str(app_name or "").strip()
    foreground_query = _foreground_find_query_hint(text)
    if foreground_query and not app:
        return {
            "query": foreground_query,
            "target": "搜索",
            "scope": "foreground",
        }
    if _looks_like_app_search_field_input(text):
        if _app_search_field_input_allows_safe_search(text):
            field_query = _app_search_field_input_submit_query(text)
            if not field_query and app:
                field_query = _app_search_field_input_query(text)
        if not field_query:
            return {}
    if app and _is_browser_or_search_app_name(app) and not field_query:
        return {}
    query = field_query or _app_search_query_hint(text, app)
    if not query:
        parsed = _leading_app_search_hint(text)
        parsed_app = str(parsed.get("app_name") or "").strip() if parsed else ""
        if parsed and (
            not app
            or _looks_like_app_search_followup_app(app)
            or parsed_app.lower() == app.lower()
            or compact_app_name_hint(app).startswith(compact_app_name_hint(parsed_app))
        ):
            return parsed
    if not query:
        return {}
    result = {
        "query": query,
        "target": "搜索" if _contains_any(text, ("搜索", "查找", "检索", "找")) else "Search",
    }
    if app and _app_search_query_needs_app_scope(query, text):
        result["app_name"] = app
    return result


def _app_capability_search_hint(text: str, app_capability: Mapping[str, str]) -> dict[str, str]:
    if not isinstance(app_capability, Mapping):
        return {}
    if not str(app_capability.get("query") or "").strip():
        return {}
    value = _clean_prompt(text)
    if not value:
        return {}
    patterns = (
        r"(?:并|然后|再|接着|之后|后|\band\s+then\b|\bthen\b|\band\b)\s*"
        r"(?:(?:在|到)?(?:里面|其中|应用(?:程序)?(?:里|中|内|上)?|"
        r"app|application|tool|program|client|editor|reader|viewer)\s*)?"
        r"(?:搜索|查找|检索|找|search|find|look\s+up)(?:一下|下|for)?\s*(?P<followup_query>.+)$",
        r"(?:在|到)?(?:里面|其中|里|中|内|上)\s*"
        r"(?:搜索|查找|检索|找)(?:一下|下)?\s*(?P<scoped_query>.+)$",
        r"\b(?:inside|within|in)\s+(?:it|the\s+app|the\s+application|the\s+tool|the\s+program)"
        r"\s+(?:search|find|look\s+up)(?:\s+for)?\s+(?P<scoped_query_en>.+)$",
        r"(?:应用(?:程序)?|app|软件|工具|程序|客户端|编辑器|阅读器|查看器|浏览器)"
        r"(?:里|中|内|上)?\s*(?:[，,]\s*)?(?:并|然后|再|去|来|用于|用来)?\s*"
        r"(?:搜索|查找|检索|找)(?:一下|下)?\s*(?P<query>.+)$",
        r"\b(?:app|application|tool|program|client|editor|reader|viewer)\b"
        r"(?:\s*,)?(?:\s+(?:and|then|to|for))?\s*"
        r"(?:search|find|look\s+up)(?:\s+for)?\s+(?P<query_en>.+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        query = _clean_app_search_query(
            match.groupdict().get("followup_query")
            or match.groupdict().get("scoped_query")
            or match.groupdict().get("scoped_query_en")
            or match.groupdict().get("query")
            or match.groupdict().get("query_en")
            or ""
        ).strip(" .，,。?？!！")
        if not query:
            continue
        return {
            "query": query,
            "target": "搜索" if _contains_any(value, ("搜索", "查找", "检索", "找")) else "Search",
        }
    return {}


def _app_search_query_needs_app_scope(query: str, text: str) -> bool:
    value = _clean_prompt(query)
    return bool(
        _app_search_followup_hint(text).get("action") and re.search(
            r"(?:剪贴板|粘贴板|选中|当前|clipboard|selected|current)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_find_visible_target_action(text: str) -> bool:
    value = _clean_prompt(text)
    return bool(
        re.search(
            r"(?:找到|找|定位|选择|选中).{1,80}"
            r"(?:按钮|控件|元素|菜单项|菜单|复选框|项目|条目)?.{0,12}"
            r"(?:点击|点一下|点按|点开|单击|打开|进入)"
            r"(?:[，,。；;！!？?]?\s*(?:并|然后|再|后|之后)?\s*"
            r"(?:确认|验证|检查|查看|看看|判断).{0,24}"
            r"(?:成功|结果|状态|是否成功))?$",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:find|locate|choose|select)\b.{1,80}"
            r"\b(?:click|press|tap|open)\b(?:\s+(?:it|that|them))?"
            r"(?:\s+(?:and|then)\s+(?:verify|confirm|check).{0,24}"
            r"(?:success|result|state|status))?[.!?]?$",
            value,
            flags=re.IGNORECASE,
        )
    )


def _ambiguous_visible_target_action_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if not (
        re.search(
            r"(?:最像|最接近|相关|有关|匹配|合适|适合|应该|可能|哪个|哪里|哪一个|哪项|哪条)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:closest|similar|related|matching|appropriate|suitable|which|where|"
            r"should|possible)\b",
            value,
            flags=re.IGNORECASE,
        )
    ):
        return False
    return bool(
        re.search(
            r"(?:当前|前台|这个|该)?(?:应用|app|application|窗口|界面|ui|页面|网页)?"
            r".{0,40}(?:找到|找|定位|选择|选中|点击|点按|点开|打开|进入)",
            value,
            flags=re.IGNORECASE,
        )
        and re.search(
            r"(?:按钮|控件|元素|菜单项|菜单|复选框|项目|条目|链接|button|control|element|menu|item|link)",
            value,
            flags=re.IGNORECASE,
        )
    )


