    return bool(
        re.search(
            r"(?:最像|最接近|相关|有关|匹配|合适|适合|应该|可能|哪个|哪里|哪一个|哪项|哪条)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:closest|similar|related|matching|appropriate|suitable|which|where|should)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


