def _web_search_hint(text: str, context_source: str) -> dict[str, Any]:
    if context_source in {"selection", "clipboard"}:
        return {}
    value = _clean_prompt(text)
    destination_search = _known_web_destination_search_hint(value)
    if destination_search:
        hint: dict[str, Any] = {
            "browser_action": "open_search",
            "query": destination_search["query"],
            "url_hint": destination_search["url_hint"],
            "destination": destination_search["destination"],
        }
        followup = _web_search_followup_hint(value)
        if followup:
            hint.update(followup)
            hint.update(_web_search_post_followup_hint(value))
        else:
            hint.update(_web_search_results_output_hint(value))
        return hint
    query = _web_search_query(value)
    if not query:
        return {}
    engine = _web_search_engine_hint(value)
    hint: dict[str, Any] = {
        "browser_action": "open_search",
        "query": query,
        "url_hint": _web_search_url(engine, query),
    }
    followup = _web_search_followup_hint(value)
    if followup:
        hint.update(followup)
        hint.update(_web_search_post_followup_hint(value))
    else:
        hint.update(_web_search_results_output_hint(value))
    return hint


def _web_search_post_followup_hint(text: str) -> dict[str, Any]:
    output_hint = _web_search_results_output_hint(text)
    browser_action = str(output_hint.get("browser_action") or "").strip()
    if browser_action == "open_url_extract":
        hint: dict[str, Any] = {"post_followup_action": "extract_text"}
        presentation = str(output_hint.get("presentation") or "").strip()
        if presentation:
            hint["presentation"] = presentation
        return hint
    return {}


def _web_search_results_output_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    query = _web_search_query(value)
    instruction_value = _web_output_instruction_text(value, query=query)
    if _looks_like_url_screenshot_request(instruction_value):
        return {
            "browser_action": "open_url_screenshot",
            "reason": "user asked to capture the browser page after opening a URL",
        }
    if re.search(
        r"(?:并|然后|并且|再|接着|之后|后).{0,4}"
        r"(?:读|读取|看看|看一下|看下|概括|总结|摘要).{0,8}(?:结果|内容|搜索结果)$",
        instruction_value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"(?:并|然后|并且|再|接着|之后|后).{0,4}"
        r"(?:读|读取|看看|看一下|看下|概括|总结|摘要).{0,8}"
        r"(?:当前|这个|该)?(?:网页|页面|页|current\s+page)$",
        instruction_value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"\b(?:and|then)\s+(?:read|extract|summari[sz]e)\s+results?\b",
        instruction_value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"\b(?:and|then)\s+(?:read|extract|summari[sz]e)\s+(?:the\s+)?(?:current\s+)?page\b",
        instruction_value,
        flags=re.IGNORECASE,
    ):
        hint: dict[str, Any] = {"browser_action": "open_url_extract"}
        if _looks_like_url_summary_request(instruction_value):
            hint["presentation"] = "summary"
        return hint
    if _browser_search_deliverable_extract_requested(instruction_value):
        return {"browser_action": "open_url_extract"}
    return {}


def _browser_search_deliverable_extract_requested(text: str) -> bool:
    surface = _web_search_surface_hint(text)
    if not _desktop_content_artifact_requested(text):
        return False
    if not surface:
        return _plain_web_search_deliverable_extract_requested(text)
    if _is_generic_browser_app_label(surface):
        return _plain_web_search_deliverable_extract_requested(text)
    return bool(
        _is_browser_or_search_app_name(surface)
    )


def _plain_web_search_deliverable_extract_requested(text: str) -> bool:
    value = _clean_prompt(text)
    return bool(
        re.search(
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?:搜索|查找|查询|检索|找一下|找下|查一下|查查|查(?!看))\s*",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?:打开|启动|开启|新建|开|用|在|通过)?\s*"
            r"(?:一个|个|任意|任何|默认|可用)?\s*"
            r"(?:Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave|浏览器)"
            r"(?:里|中|上|内)?\s*(?:搜索|查找|检索)\s*",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"^(?:(?:please|can\s+you|could\s+you|would\s+you)\s+)?"
            r"(?:search|look\s+up|find\s+out\s+about)\s+",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?:研究|调研|查研究|做(?:一份)?(?:调研|研究)|写(?:一份)?(?:关于)?.*?(?:分析|报告))",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?:做|制作|写|生成|输出|整理)\s*(?:一份|一个|一篇|个)?"
            r"[^，,。！？!?]{0,40}(?:分析|报告|调研|研究)[^。！？!?]{0,80}"
            r"(?:找资料|查资料|搜集资料|收集资料|总结|摘要|输出报告|输出总结|"
            r"markdown|文档)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"^(?:(?:please|can\s+you|could\s+you|would\s+you)\s+)?"
            r"(?:research|investigate|write\s+(?:a\s+)?(?:research\s+)?report|"
            r"write\s+(?:a\s+)?competitive\s+analysis)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _web_search_query(text: str) -> str:
    text = _speech_act_strip_unauthorized_contextual_tails(text)
    if _url_hint(text):
        return ""
    direct_engine_query = _direct_web_search_query(text)
    if direct_engine_query:
        return direct_engine_query
    leading_app_search = _leading_app_search_hint(text)
    leading_app_name = str(leading_app_search.get("app_name") or "").strip()
    if (
        leading_app_name
        and not _known_web_destination_search_hint(text)
        and not _is_browser_or_search_app_name(leading_app_name)
    ):
        return ""
    if _looks_like_local_observation_or_control_request(text):
        return ""
    if (
        (data_source_hint(text) or data_source_scope_hint(text) or context_source_hint(text))
        and not _looks_like_external_info_lookup(text)
    ):
        return ""
    search_surface = _web_search_surface_hint(text)
    if search_surface and not _is_browser_or_search_app_name(search_surface):
        return ""
    app_name = _app_name_hint(text)
    explicit_browser_app = _explicit_browser_app_name_hint(text)
    if (
        app_name
        and not search_surface
        and not explicit_browser_app
        and not _is_browser_or_search_app_name(app_name)
    ):
        return ""
    research_report_query = _external_research_report_query(text)
    if research_report_query:
        return research_report_query
    lowered = text.lower()
    patterns = (
        r"^(?:(?:please|can|could|would)\s+(?:you\s+)?)?"
        r"(?:research|look\s+up|find\s+out\s+about)\s+(.+)$",
        r"\b(?:can\s+you\s+)?search\s+(?:google\s+chrome|chrome|safari|browser|web|google)\s+for\s+(.+)$",
        r"\b(?:can\s+you\s+)?search\s+for\s+(.+)$",
        r"\b(?:google|search)\s+(.+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, lowered)
        if match:
            query = _clean_web_search_query(match.group(1))
            if query:
                return query

    chinese_patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:研究|调研|了解|查找|查询|检索|搜索|找一下|找下|查一下|查查|查(?!看)|看一下|看看)"
        r"(?:一下|下|查)?\s*(.+)$",
        r"(?:在|用|通过)?\s*"
        r"(?:(?:一个|一款|任意|任何|默认|当前|可用|可使用|能用|已安装|本地|"
        r"系统自带|内置|合适|适合|推荐)(?:的)?\s*){0,8}"
        r"(?:浏览器|Google|谷歌)\s*(?:搜索|查找)\s*(.+)$",
        r"(?:搜索|查找|检索)\s*(.+)$",
    )
    for pattern in chinese_patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            query = _clean_web_search_query(match.group(1))
            if query:
                return query
    return ""


def _generic_web_research_query_hint(text: str) -> str:
    value = _clean_prompt(text)
    if not value:
        return ""
    if _url_hint(value):
        return ""
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?"
        r"(?:做|制作|写|生成|输出|整理)\s*(?:一份|一个|一篇|个)?"
        r"[^，,。！？!?]{0,48}(?:报告|分析)[，,]\s*"
        r"(?:调研|研究|了解|查找|查询|检索|搜索)\s*"
        r"(?P<query>[^，,。！？!?]+)",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:调研|研究|了解|查找|查询|检索|搜索)\s*"
        r"(?P<query>[^，,。！？!?]+)",
        r"(?P<query>[^，,。！？!?]{2,80})(?:，|,)?\s*(?:找资料|查资料|搜集资料|收集资料)",
        r"^(?:(?:please|can|could|would)\s+(?:you\s+)?)?"
        r"(?:research|investigate|look\s+up|find\s+sources\s+for|gather\s+info(?:rmation)?\s+for)\s+"
        r"(?P<query>[^.!?,]+)",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        query = _clean_generic_web_research_query(match.group("query"))
        if query:
            return query
    return ""


def _clean_generic_web_research_query(query: str) -> str:
    value = _clean_web_search_query(query)
    value = re.sub(
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:做|制作|写|生成|输出|整理)?"
        r"(?:一份|一个|一篇|个)?",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"(?:并|然后|，|,)?\s*(?:输出|生成|写成|整理成|保存成).*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    if value in {"资料", "信息", "内容", "sources", "information", "info"}:
        return ""
    return value


def _external_research_report_query(text: str) -> str:
    value = _clean_prompt(text)
    if not value:
        return ""
    chinese_patterns = (
        r"(?:写|生成|输出|整理|做|制作)\s*(?:一份|一个|篇)?\s*"
        r"(?:关于|有关)\s*(?P<query>.+?)\s*(?:的)?"
        r"(?:竞品分析|竞品|竞争分析|产品分析|产品能力|调研|研究|分析)?"
        r"(?:报告|简报|文档)$",
        r"(?:关于|有关)\s*(?P<query>.+?)\s*(?:的)?"
        r"(?:竞品分析|竞品|竞争分析|产品分析|产品能力|调研|研究|分析)"
        r"(?:报告|简报|文档)$",
    )
    for pattern in chinese_patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if match:
            query = _clean_web_search_query(match.group("query"))
            if query:
                return query
    english_patterns = (
        r"\b(?:write|create|generate|produce)\s+(?:a\s+)?"
        r"(?:competitive|competitor|market|research|analysis)[\w\s-]{0,30}?"
        r"report\s+(?:about|on)\s+(?P<query>.+)$",
        r"\b(?:about|on)\s+(?P<query>.+?)\s+"
        r"(?:competitive|competitor|market|research|analysis)[\w\s-]{0,30}?report$",
    )
    for pattern in english_patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if match:
            query = _clean_web_search_query(match.group("query"))
            if query:
                return query
    return ""


def _report_external_research_query_hint(text: str) -> str:
    value = _clean_prompt(text)
    if not value:
        return ""
    query = _external_research_report_query(value) or _generic_web_research_query_hint(value)
    if query:
        return query
    if not _contains_any(
        value,
        (
            "report",
            "summary",
            "brief",
            "document",
            "markdown",
            "报告",
            "总结",
            "简报",
            "文档",
        ),
    ):
        return ""
    if not (
        _contains_any(
            value,
            (
                "competitive",
                "competitor",
                "market",
                "research",
                "latest",
                "current",
                "news",
                "pricing",
                "price",
                "竞品",
                "竞争",
                "市场",
                "调研",
                "研究",
                "最新",
                "当前",
                "新闻",
                "价格",
                "定价",
            ),
        )
        or _looks_like_external_info_lookup(value)
    ):
        return ""
    fallback = (
        "竞品分析"
        if _contains_any(value, ("竞品", "竞争"))
        else "market analysis"
        if _contains_any(value, ("market", "市场"))
        else "research report"
    )
    return _clean_report_research_query(value, fallback=fallback)


def _clean_report_research_query(text: str, *, fallback: str) -> str:
    value = _clean_web_search_query(text)
    value = re.sub(
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:做|制作|写|生成|输出|整理|创建|新建|create|make|write|generate|produce)?"
        r"(?:一份|一个|一篇|个|a|an)?",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"(?:并|然后|，|,)?\s*(?:输出|生成|写成|整理成|保存成|导出|save|export|output|write).*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"(?:报告|总结|简报|文档|markdown|\bmd\b|report|summary|brief|document)$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    return value or fallback


def _direct_web_search_query(text: str) -> str:
    value = _clean_prompt(
        _speech_act_strip_unauthorized_contextual_tails(text)
    )
    patterns = (
        r"^(?:(?:please|can\s+you|could\s+you|would\s+you)\s+)?"
        r"search\s+(?:google|baidu|chrome|google\s+chrome|browser|safari)\s+"
        r"for\s+(?P<query>[^.!?,。！？]+)$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:百度|baidu)\s*(?:搜索|搜一下|搜|查一下|查查|检索|一下)?\s*(?P<query>[^。！？!?]+)$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:google|谷歌)\s*(?:搜索|搜一下|搜|查一下|查查|检索|一下)?\s*(?P<query>[^。！？!?]+)$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:打开|新建|开)\s*(?:一个|个)?\s*(?:新标签页?|新标签|new\s+tab)\s*"
        r"(?:并|然后|再)?\s*(?:搜索|查找|检索)\s*(?P<query>[^。！？!?]+)$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:(?:在|用|通过|打开|启动|开启)\s*)?"
        r"(?:(?:一个|一款|个|任意|任何|默认|当前|可用|可使用|能用|已安装|本地|"
        r"系统自带|内置|合适|适合|推荐)(?:的)?\s*)*"
        r"(?:Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave|浏览器)"
        r"(?:里|中|上|内)?\s*[，,、]?\s*"
        r"(?:打开|访问|浏览|搜索|搜一下|搜|查找|查询|查一下|查查|检索)\s*"
        r"(?!新标签页?|新标签|new\s+tab)(?P<query>[^。！？!?]+)$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:在|用|通过)?\s*"
        r"(?:(?:一个|一款|个|任意|任何|默认|当前|可用|可使用|能用|已安装|本地|"
        r"系统自带|内置|合适|适合|推荐)(?:的)?\s*)*"
        r"(?:Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave|浏览器)"
        r"(?:里|中|上|内)?\s*[，,、]?\s*"
        r"(?:(?:打开|启动|开启|新建|开)\s*(?:一个|个)?\s*"
        r"(?:新标签页?|新标签|new\s+tab)?\s*)?"
        r"(?:并|然后|再)?\s*(?:搜索|搜一下|搜|查找|查询|查一下|查查|检索)\s*(?P<query>[^。！？!?]+)$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:搜索|搜一下|查找|查询|检索|找一下|找下|查一下|查查|查(?!看))\s*"
        r"(?P<query>[^。！？!?]+)$",
        r"^(?:(?:please|can\s+you|could\s+you|would\s+you)\s+)?"
        r"search\s+"
        r"(?P<query>[^.!?]+)$",
        r"^(?:(?:please|can\s+you|could\s+you|would\s+you)\s+)?"
        r"(?:(?:open|launch|start|in|with|using)\s+)?"
        r"(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave|browser)\s+"
        r"(?:and\s+)?(?:open|visit|browse|search|find|look\s+up)\s+(?:for\s+)?"
        r"(?P<query>[^.!?]+)$",
        r"\b(?:google|baidu)\s+(?P<query>[^.!?,]+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        query = _clean_web_search_query(match.group("query"))
        if (
            query
            and not _looks_like_local_search_query(query)
            and not _looks_like_non_browser_search_surface(value)
        ):
            return query
    return ""


def _looks_like_local_search_query(query: str) -> bool:
    if _looks_like_external_docs_subject(query):
        return False
    clean_query = _clean_prompt(query)
    lowered = clean_query.lower()
    return bool(
        context_source_hint(clean_query)
        or data_source_hint(clean_query)
        or data_source_scope_hint(clean_query)
        or _looks_like_running_apps_request(clean_query, lowered)
        or _looks_like_installed_apps_request(clean_query, lowered)
        or _is_system_settings_app_label(clean_query)
    )


def _looks_like_non_browser_search_surface(text: str) -> bool:
    surface = _web_search_surface_hint(text)
    return bool(surface and not _is_browser_or_search_app_name(surface))


def _web_search_engine_hint(text: str) -> str:
    return "baidu" if re.search(r"(?:百度|baidu)", text, flags=re.IGNORECASE) else "google"


def _web_search_followup_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    match = re.search(
        r"(?:并|然后|再|接着|之后|后)?\s*"
        r"(?:打开|点击|点一下|点按|进入|访问|选择|选中)\s*"
        r"(?P<rank>第?一个|第一条|首个|第1个|第1条|1)\s*(?:搜索结果|结果|链接|条目)",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"(?:并|然后|再|接着|之后|后)\s*(?:播放|打开播放|点开播放)\s*$",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"\b(?:and|then)\s+(?:play|open\s+and\s+play)\b",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"\b(?:and|then)\s+(?:open|click|visit|select|choose)\s+(?:the\s+)?"
        r"(?P<rank_en>first|1st)\s+(?:search\s+)?(?:result|link|item)\b",
        value,
        flags=re.IGNORECASE,
    )
    if not match:
        return {}
    rank = match.groupdict().get("rank") or match.groupdict().get("rank_en") or "first"
    index = _browser_search_result_rank_index(rank)
    if not index:
        return {}
    return {
        "followup_action": "click_search_result",
        "selector": f"search-result={index}",
        "click_count": 1,
    }


def _web_search_url(engine: str, query: str) -> str:
    if str(engine or "").strip().lower() == "baidu":
        return f"https://www.baidu.com/s?wd={quote_plus(query)}"
    return f"https://www.google.com/search?q={quote_plus(query)}"


def _known_web_destination_search_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:在|用|通过)?\s*(?:任意|任何|默认|当前)?"
        r"(?:浏览器|chrome|google\s*chrome|google|谷歌|safari)?"
        r"\s*(?:里|中|上|内)?\s*(?:打开|访问|浏览|前往|去|上)?\s*"
        r"(?P<site>[\w .·-]{1,60}?)(?:里|中|上|内)?\s*"
        r"(?:并|然后|并且|再|接着|之后|后)?\s*"
        r"(?:搜索|搜一下|搜|查找|检索|找)\s*(?P<query>[^。！？!?]+)$",
        r"^(?P<site>[\w .·-]{1,60}?)(?:里|中|上|内)?\s*"
        r"(?:并|然后|并且|再|接着|之后|后)?\s*"
        r"(?:搜索|搜一下|搜|查找|检索|找)\s*(?P<query>[^。！？!?]+)$",
        r"^(?:(?:please|can\s+you|could\s+you|would\s+you)\s+)?"
        r"(?:(?:use|using|in|on|with)\s+(?:the\s+)?"
        r"(?:browser|chrome|google\s+chrome|google|safari)\s+(?:to\s+)?)?"
        r"(?:open|visit|browse|go\s+to)\s+(?:the\s+)?"
        r"(?P<site>[A-Za-z][A-Za-z0-9 ._-]{1,60}?)\s+"
        r"(?:and\s+|then\s+)?(?:search|find|look\s+up)\s+(?:for\s+)?"
        r"(?P<query>[^.!?,]+)$",
        r"^(?:(?:please|can\s+you|could\s+you|would\s+you)\s+)?"
        r"(?:search|find|look\s+up)\s+(?:the\s+)?"
        r"(?P<site>[A-Za-z][A-Za-z0-9 ._-]{1,60}?)\s+for\s+"
        r"(?P<query>[^.!?,]+)$",
        r"^(?P<site>[A-Za-z][A-Za-z0-9 ._-]{1,60}?)\s+"
        r"(?:search|find|look\s+up)\s+(?:for\s+)?(?P<query>[^.!?,]+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        destination = _clean_web_destination_site_hint(match.group("site"))
        query = _clean_web_search_query(match.group("query"))
        url = legacy_known_web_destination_search_url(destination, query)
        if url:
            return {
                "destination": destination,
                "query": query,
                "url_hint": url,
            }
    return {}


def _clean_web_destination_site_hint(site_name: str) -> str:
    value = str(site_name or "").strip(" .，,。")
    value = re.sub(
        r"^(?:打开|访问|浏览|前往|去|上|open|visit|browse|go\s+to)\s+",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    value = re.sub(r"^(?:the\s+)?", "", value, flags=re.IGNORECASE).strip(" .，,。")
    return value


def _web_search_surface_hint(text: str) -> str:
    direct_browser = re.search(
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:(?:在|用|通过|打开|启动|开启)\s*)?"
        r"(?:(?:一个|一款|个|任意|任何|默认|当前|可用|可使用|能用|已安装|本地|"
        r"系统自带|内置|合适|适合|推荐)(?:的)?\s*)*"
        r"(?P<surface>Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave|浏览器)"
        r"(?:里|中|上|内)?\s*[，,、]?\s*"
        r"(?:打开|访问|浏览|搜索|搜一下|搜|查找|查询|查一下|查查|检索)",
        text,
        flags=re.IGNORECASE,
    )
    if direct_browser:
        return _clean_web_search_surface_hint(str(direct_browser.group("surface") or ""))
    patterns = (
        r"\b(?:can\s+you\s+)?search\s+(?P<surface>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+for\s+.+$",
        r"^(?P<surface>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s*(?:搜索|查找|检索)\s*.+$",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:在|用|通过)\s*"
        r"(?P<surface>[\w .·-]{1,40}?)\s*(?:里|中|上|内)?\s*"
        r"(?:搜索|查找|检索)\s*.+$",
    )
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if match:
            return _clean_web_search_surface_hint(str(match.group("surface") or ""))
    return ""


def _clean_web_search_surface_hint(surface: str) -> str:
    value = _clean_prompt(surface)
    if not value:
        return ""
    value = re.split(
        r"\s*(?:打开|启动|开启|新建|开|"
        r"\b(?:open|launch|start|new\s+tab)\b)\s*",
        value,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0].strip(" .，,。")
    value = _clean_app_name_hint(value)
    if not value:
        return ""
    if _is_generic_browser_app_label(value):
        return value
    if _is_browser_or_search_app_name(value):
        return value
    return legacy_app_name_hint(value)


def _is_browser_or_search_app_name(app_name: str) -> bool:
    if _is_generic_browser_app_label(app_name):
        return True
    normalized = re.sub(r"\s+", " ", str(app_name or "").strip().lower())
    return normalized in {
        "browser",
        "any browser",
        "default browser",
        "chrome",
        "google chrome",
        "safari",
        "firefox",
        "edge",
        "microsoft edge",
        "brave",
        "google",
        "谷歌",
        "浏览器",
        "任意浏览器",
        "任何浏览器",
        "默认浏览器",
        "网页",
        "页面",
        "当前网页",
        "当前页面",
        "current page",
        "current webpage",
        "web page",
        "spotlight",
    }


def _looks_like_media_search_play_request(text: str) -> bool:
    hint = media_playback_hint(text)
    return bool(
        str(hint.get("action") or "").strip() == "play"
        and str(hint.get("query") or "").strip()
        and (
            str(hint.get("app_name") or "").strip()
            or _contains_any(text, ("apple music", "spotify", "网易云", "qq music", "QQ 音乐"))
        )
    )


def _looks_like_generic_media_playback_request(text: str) -> bool:
    hint = media_playback_hint(text)
    return bool(
        str(hint.get("action") or "").strip() == "play"
        and not str(hint.get("query") or "").strip()
        and _contains_any(text, ("music", "song", "songs", "音乐", "歌曲", "歌"))
    )


def _looks_like_generic_media_control_request(text: str) -> bool:
    hint = media_playback_hint(text)
    action = str(hint.get("action") or "").strip()
    if str(hint.get("control_only") or "").strip().lower() == "true":
        return True
    if action not in {"pause", "next", "previous", "status"}:
        return False
    return bool(
        not str(hint.get("app_name") or "").strip()
        and _contains_any(text, ("music", "song", "songs", "音乐", "歌曲"))
    )


def _clean_web_search_query(query: str) -> str:
    value = re.sub(r"^[：:，,\s]+", "", str(query or "").strip())
    value = re.sub(
        r"^(?:网页|网上|网络|web)\s*(?:上|里|中|内)?\s*"
        r"(?:研究|调研|了解|查找|查询|检索|搜索)(?:一下|下)?\s*",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"\s+(?:and|then)\s+"
        r"(?:write|create|generate|produce|make|format|organize|summari[sz]e|output|list)\b.*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"\s+(?:and|then)\s+(?:send|message|forward).*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"\s+(?:and|then)\s+(?:open|click|visit|select|choose)\s+(?:the\s+)?"
        r"(?:first|1st)\s+(?:search\s+)?(?:result|link|item).*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"\s+(?:and|then)\s+(?:play|open\s+and\s+play).*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"\s*(?:并|然后|并且|再|接着|之后|后)?\s*"
        r"(?:打开|点击|点一下|点按|进入|访问|选择|选中)\s*"
        r"(?:第?一个|第一条|首个|第1个|第1条|1)\s*(?:搜索结果|结果|链接|条目).*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"\s*(?:并|然后|并且|再|接着|之后|后)\s*(?:播放|打开播放|点开播放).*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"\s*(?:并|然后|并且|再|接着|之后|后|\b(?:and|then)\b)?\s*"
        r"(?:截图|截屏|screen\s*capture|screenshot)(?:\s+results?)?$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"\s*(?:并|然后|并且|再|接着|之后|后|\b(?:and|then)\b)?\s*"
        r"(?:读|读取|看看|看一下|看下|概括|总结|摘要|做总结|做摘要)(?:一下|下)?"
        r"(?:搜索)?(?:结果|内容|当前页面|当前网页|网页|页面|current\s+page)?$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"(?:[，,]\s*|并|然后|并且|再)(?:输出|生成|写|写出|整理|总结|做总结|汇总|列出)(?:一份|一下|成)?"
        r"[^。；;！!？?]{0,40}(?:报告|总结|文档|结果|表格|清单|列表|链接|markdown|artifact|md|table|links?)$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"(?:并|然后|并且|再|接着|之后|后)?\s*"
        r"(?:把|将)?(?:报告|总结|摘要|结果|内容|表格|清单|文档)?"
        r"\s*(?:发给|发送给|发到|发送到|转发给|转发到).*$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"(?:[，,]\s*)?(?:并|然后|并且|再|接着|之后|后)\s*"
        r"(?:把|将)?(?:搜索)?(?:结果|内容|信息|报告|摘要|总结|表格|清单|文档)?\s*"
        r"(?:写进|写入|写到|保存到|记录到|记到|放到|粘贴到|贴到|输入到|输入进|填到|填入|填写到)\s*.+$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(r"[。.,，；;！!？?]+$", "", value).strip()
    value = re.sub(
        r"(?:[，,]\s*|并|然后|并且|再)(?:输出|生成|写|写出|整理|总结|汇总|列出)(?:一份|一下|成)?"
        r"[^。；;！!？?]{0,40}(?:报告|总结|文档|结果|表格|清单|列表|链接|markdown|artifact|md|table|links?)$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"(?:并|然后|并且|再)?(?:输出|生成|写|写出|整理|总结|汇总|列出)(?:一份|一下|成)?"
        r"(?:报告|总结|文档|结果|表格|清单|列表|链接|table|links?)?$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(
        r"\s+(?:in|on|with)\s+(?:chrome|google\s+chrome|safari|browser)$",
        "",
        value,
        flags=re.IGNORECASE,
    ).strip()
    value = re.sub(r"[。.,，；;！!？?]+$", "", value).strip()
    value = re.sub(r"\s+(?:please|pls)$", "", value, flags=re.IGNORECASE).strip()
    if not value:
        return ""
    if value.casefold() in {
        "一下",
        "下",
        "查",
        "找",
        "搜索",
        "查找",
        "查询",
        "current page",
        "this page",
        "current webpage",
        "this webpage",
        "当前网页",
        "当前页面",
        "当前页",
        "这个网页",
        "这个页面",
    }:
        return ""
    if _contains_any(
        value,
        (
            "selected text",
            "current selection",
            "剪贴板内容",
            "选中的内容",
            "当前选中文字",
        ),
    ):
        return ""
    return value


def _browser_click_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    rank_match = re.search(
        r"(?:点击|点一下|点按|单击|打开|进入|访问)\s*"
        r"(?:当前)?(?:网页|页面|浏览器|当前页)?(?:上|里|中|内|的|上的)?\s*"
        r"(?P<rank>第?一个|第一条|首个|第1个|第1条|1)\s*(?:搜索结果|结果|链接|条目)$",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"\b(?:click|open|visit|press)\s+(?:the\s+)?"
        r"(?P<rank_en>first|1st)\s+"
        r"(?:search\s+)?(?:result|link)\b",
        value,
        flags=re.IGNORECASE,
    )
    if rank_match and _has_browser_page_context(value):
        rank = rank_match.groupdict().get("rank") or rank_match.groupdict().get("rank_en") or ""
        index = _browser_search_result_rank_index(rank)
        if index:
            return {
                "browser_action": "click",
                "selector": f"search-result={index}",
                "click_count": 1,
            }
    if _looks_like_browser_app_field_typing(value):
        return {}
    if not _has_browser_page_context(value):
        return {}
    point = _browser_click_point(value)
    if point:
        return {
            "browser_action": "click",
            "selector": f"point={point['x']},{point['y']}",
            "fallback_x": point["x"],
            "fallback_y": point["y"],
            "click_count": point["click_count"],
        }
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:在|用|通过)?\s*"
        r"(?:google\s*chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave|浏览器|谷歌)"
        r"(?:里|中|上|内|上面)?\s*"
        r"(?:点击|点一下|点按|单击|点)\s*"
        r"(?P<label>[^。！？!?，,]+?)\s*(?:按钮|链接|元素)?$",
        r"(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:点击|点一下|点按|单击|点)\s*"
        r"(?:当前)?(?:网页|页面|浏览器|当前页)?(?:上|里|中|内|的|上的)?\s*"
        r"(?P<label>[^。！？!?，,]+?)\s*(?:按钮|链接|元素)?$",
        r"\b(?:click|press)\s+(?:the\s+)?(?P<label>[^.!?]+?)"
        r"(?:\s+(?:button|link|element))?"
        r"(?:\s+(?:on|in)\s+(?:the\s+)?(?:current\s+)?(?:page|browser))?$",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        label = _clean_browser_element_label(match.group("label"))
        if not label or _looks_like_click_coordinate_label(label):
            continue
        if _browser_click_target_needs_observation_choice(value, label):
            return {
                "browser_action": "current_page",
                "target_hint": label,
                "reason": "resolve_ambiguous_click_target",
            }
        return {
            "browser_action": "click",
            "selector": _browser_selector_from_label(label),
            "click_count": 1,
        }
    return {}


def _browser_click_target_needs_observation_choice(text: str, label: str) -> bool:
    value = f"{_clean_prompt(text)} {str(label or '').strip()}"
    return bool(
        re.search(
            r"(?:最像|最接近|相关|有关|匹配|合适|适合|应该|可能|哪个|哪里|哪一个|哪项|哪条)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:closest|similar|related|matching|appropriate|suitable|which|where|should|possible)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_browser_app_field_typing(text: str) -> bool:
    return bool(
        _explicit_browser_app_name_hint(text)
        and re.search(
            r"(?:搜索框|搜索栏|地址栏|search\s+(?:box|field|bar)|address\s+bar|url\s+bar).{0,20}"
            r"(?:输入|键入|填写|填入|搜索|type|enter|fill|search)",
            str(text or ""),
            flags=re.IGNORECASE,
        )
    )


def _browser_click_point(text: str) -> dict[str, Any]:
    patterns = (
        r"(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:(?P<double>双击|double\s+click)|点击|点一下|点按|单击|click)\s*"
        r"(?:当前)?(?:网页|页面|浏览器|当前页)(?:上|里|中|内|的|上的)?\s*"
        r"(?:坐标|位置|coordinate|point)?\s*"
        r"(?P<x>\d+(?:\.\d+)?)\s*(?:,|，|\s)\s*(?P<y>\d+(?:\.\d+)?)$",
        r"(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:(?P<double2>双击|double\s+click)|点击|点一下|点按|单击|click)\s*"
        r"(?:当前)?(?:网页|页面|浏览器|当前页)?(?:上|里|中|内|的|上的)?\s*"
        r"(?:坐标|位置|coordinate|point)\s*"
        r"(?P<x>\d+(?:\.\d+)?)\s*(?:,|，|\s)\s*(?P<y>\d+(?:\.\d+)?)$",
        r"(?:当前)?(?:网页|页面|浏览器|当前页)?(?:上|里|中|内|的|上的)?\s*"
        r"(?:坐标|位置|coordinate|point)\s*"
        r"(?P<x>\d+(?:\.\d+)?)\s*(?:,|，|\s)\s*(?P<y>\d+(?:\.\d+)?)$",
    )
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if not match:
            continue
        groups = match.groupdict()
        return {
            "x": _number_value(match.group("x")),
            "y": _number_value(match.group("y")),
            "click_count": 2 if groups.get("double") or groups.get("double2") else 1,
        }
    return {}


def _browser_search_result_rank_index(value: str) -> int:
    compact = re.sub(r"[\s._-]+", "", str(value or "").strip().lower())
    if compact in {"第一个", "第一条", "首个", "第1个", "第1条", "1", "first", "1st"}:
        return 1
    return 0


def _browser_selector_from_label(label: str) -> str:
    clean = str(label or "").strip()
    if _looks_like_css_selector(clean):
        return clean
    return f"text={clean}"


def _looks_like_click_coordinate_label(value: str) -> bool:
    return bool(re.fullmatch(r"\d+(?:\.\d+)?\s*(?:,|，|\s)\s*\d+(?:\.\d+)?", str(value or "").strip()))


def _number_value(value: str) -> int | float:
    number = float(value)
    if number.is_integer():
        return int(number)
    return number


def _browser_type_text_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    if not _has_browser_page_context(value):
        return {}
    patterns = (
        r"\b(?:type|enter|fill)\s+(?P<text>[^.!?]+?)\s+"
        r"(?:into|in)\s+(?:the\s+)?(?:current|this)?\s*"
        r"(?:web\s*page|webpage|page|browser)\s+(?P<target>[^.!?]+)$",
        r"(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:在|向|给)?\s*(?:当前)?(?:网页|页面|浏览器|当前页)"
        r"(?:上|里|中|内)?(?:的)?\s*(?P<target>[^。！？!?，,]*?)"
        r"(?:输入|填写|键入|打入|填入)\s*(?P<text>[^。！？!?]+)$",
        r"(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:填写|填入|输入)\s*(?:当前)?(?:网页|页面|浏览器|当前页)?(?:的)?"
        r"(?P<target>[^。！？!?，,]+?)\s*(?:为|成|:|：)\s*(?P<text>[^。！？!?]+)$",
        r"\b(?:type|enter|fill)\s+(?P<text>[^.!?]+?)\s+"
        r"(?:into|in)\s+(?P<target>[^.!?]+?)\s+"
        r"(?:on|in)\s+(?:the\s+)?(?:current\s+)?(?:page|browser)\b",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        typed_text = _clean_browser_typed_text(match.group("text"))
        if not typed_text:
            continue
        target = _clean_browser_element_label(match.group("target"))
        point = _browser_click_point(target)
        if point:
            return {
                "browser_action": "type_text",
                "selector": f"point={point['x']},{point['y']}",
                "text": typed_text,
                "fallback_x": point["x"],
                "fallback_y": point["y"],
            }
        return {
            "browser_action": "type_text",
            "selector": _browser_input_selector_from_target(target),
            "text": typed_text,
        }
    return {}


def _has_browser_page_context(text: str) -> bool:
    return bool(
        re.search(r"(?:网页|页面|浏览器|当前页)", text, flags=re.IGNORECASE)
        or re.search(r"(?:搜索结果|链接)", text, flags=re.IGNORECASE)
        or re.search(r"\b(?:browser|page|webpage|web\s+page)\b", text, flags=re.IGNORECASE)
        or re.search(r"\b(?:search\s+)?(?:result|link)s?\b", text, flags=re.IGNORECASE)
    )


def _browser_action_app_name_hint(text: str, browser_action: str) -> str:
    if browser_action not in {
        "click",
        "type_text",
        "open_search",
        "open_url",
        "open_url_extract",
        "open_url_screenshot",
        "extract_text",
        "current_page",
        "screenshot",
    }:
        return ""
    explicit_browser_app = _explicit_browser_app_name_hint(text)
    if explicit_browser_app and _browser_app_prepare_needed(text, browser_action):
        return explicit_browser_app
    app_name = _app_name_hint(text)
    if (
        app_name
        and _is_browser_or_search_app_name(app_name)
        and not _is_generic_browser_app_label(app_name)
        and (browser_action in {"click", "type_text"} or _browser_app_prepare_needed(text, browser_action))
    ):
        return app_name
    search_surface = _web_search_surface_hint(text)
    if (
        search_surface
        and _is_browser_or_search_app_name(search_surface)
        and not _is_generic_browser_app_label(search_surface)
        and _browser_app_prepare_needed(text, browser_action)
    ):
        return search_surface
    return ""


def _browser_search_prepare_app_name_hint(text: str) -> str:
    explicit_browser_app = _explicit_browser_app_name_hint(text)
    if explicit_browser_app:
        return explicit_browser_app
    app_name = _app_name_hint(text)
    if (
        app_name
        and _is_browser_or_search_app_name(app_name)
        and not _is_generic_browser_app_label(app_name)
        and _browser_app_prepare_needed(text, "open_search")
    ):
        return app_name
    search_surface = _web_search_surface_hint(text)
    if (
        search_surface
        and _is_browser_or_search_app_name(search_surface)
        and not _is_generic_browser_app_label(search_surface)
        and _browser_app_prepare_needed(text, "open_search")
    ):
        return legacy_app_name_hint(search_surface) or search_surface
    return ""


def _browser_search_prepare_action_hint(text: str) -> str:
    value = str(text or "")
    return (
        "new_tab"
        if re.search(
            r"(?:新建标签页|新标签页|new\s+tab)",
            value,
            flags=re.IGNORECASE,
        )
        else ""
    )


def _browser_app_prepare_tool_candidates(app_mode: str, action: str = "") -> tuple[str, ...]:
    if not action:
        return tuple(app_control_tool_candidates(app_mode))
    if app_mode == "open":
        return ("app.open_and_safe_shortcut", "app.focus_and_safe_shortcut")
    return ("app.focus_and_safe_shortcut", "app.open_and_safe_shortcut")


def _explicit_browser_app_name_hint(text: str) -> str:
    value = str(text or "")
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:在|用|通过)\s*"
        r"(?P<app>Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave)"
        r"(?:里|中|上|内)?",
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        r"(?:打开|启动|开启|切到|聚焦)\s*"
        r"(?P<app>Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave)\b",
        r"^(?P<app>Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave)\s*"
        r"(?:点击|点一下|点按|单击|点|输入|填写|键入|搜索|查找|检索|新建标签页|新标签页)",
        r"\b(?:open|launch|start|focus|switch\s+to|activate)\s+"
        r"(?P<app>google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave)\b",
        r"^(?P<app>google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave)\s+"
        r"(?:click|press|tap|type|enter|fill|search|find|look\s+up|new\s+tab)\b",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        app_name = legacy_app_name_hint(match.group("app"))
        if app_name and not _is_generic_browser_app_label(app_name):
            return app_name
    return ""


def _browser_app_prepare_needed(text: str, browser_action: str) -> bool:
    if browser_action in {"click", "type_text"}:
        return True
    if browser_action in {"open_search", "open_url", "open_url_extract", "open_url_screenshot"}:
        if browser_action == "open_search" and not _web_search_followup_hint(text):
            return _browser_search_app_prepare_requested(text)
        if browser_action in {"open_url_extract", "open_url_screenshot"} and _explicit_browser_app_name_hint(text):
            return True
        if browser_action != "open_search":
            return False
        value = str(text or "")
        return bool(
            re.search(
                r"(?:在|用|通过)\s*"
                r"(?:Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave)"
                r"(?:里|中|上|内)?",
                value,
                flags=re.IGNORECASE,
            )
            or re.search(
                r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
                r"(?:打开|启动|开启|切到|聚焦)\s*"
                r"(?:Chrome|Google\s*Chrome|谷歌浏览器|浏览器|Safari|Firefox|Edge|Brave)\b",
                value,
                flags=re.IGNORECASE,
            )
            or re.search(
                r"^(?:Chrome|Google\s*Chrome|谷歌浏览器|浏览器|Safari|Firefox|Edge|Brave)\s*"
                r"(?:搜索|查找|检索)",
                value,
                flags=re.IGNORECASE,
            )
            or re.search(
                r"\b(?:in|with|using)\s+"
                r"(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave)\b",
                value,
                flags=re.IGNORECASE,
            )
            or re.search(
                r"^(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave|browser)\s+"
                r"(?:search|find|look\s+up)\b",
                value,
                flags=re.IGNORECASE,
            )
            or re.search(
                r"\b(?:open|launch|start|focus|switch\s+to|activate)\s+"
                r"(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave|browser)\b",
                value,
                flags=re.IGNORECASE,
            )
        )
    value = str(text or "")
    return bool(
        re.search(
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?(?:打开|启动|开启|切到|聚焦)\s*"
            r"(?:Chrome|Google\s*Chrome|谷歌浏览器|浏览器|Safari|Firefox|Edge|Brave)\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:open|launch|start|focus|switch\s+to|activate)\s+"
            r"(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave|browser)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _browser_search_app_prepare_requested(text: str) -> bool:
    value = str(text or "")
    return bool(
        re.search(
            r"(?:在|用|通过)\s*"
            r"(?:Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave)"
            r"(?:里|中|上|内)?",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?:打开|启动|开启|切到|聚焦)\s*"
            r"(?:Chrome|Google\s*Chrome|谷歌浏览器|浏览器|Safari|Firefox|Edge|Brave)\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"^(?:Chrome|Google\s*Chrome|谷歌浏览器|浏览器|Safari|Firefox|Edge|Brave)\s*"
            r"(?:搜索|查找|检索|新建标签页|新标签页)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:in|with|using)\s+"
            r"(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave)\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"^(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave|browser)\s+"
            r"(?:search|find|look\s+up|new\s+tab)\b",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:open|launch|start|focus|switch\s+to|activate)\s+"
            r"(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave|browser)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _browser_app_prepare_mode(text: str) -> str:
    value = str(text or "")
    if re.search(
        r"(?:在|用|通过)\s*"
        r"(?:Chrome|Google\s*Chrome|谷歌浏览器|Safari|Firefox|Edge|Brave)"
        r"(?:里|中|上|内)?",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"\b(?:in|with|using)\s+"
        r"(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave)\b",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"^(?:Chrome|Google\s*Chrome|谷歌浏览器|浏览器|Safari|Firefox|Edge|Brave)\s*"
        r"(?:搜索|查找|检索)",
        value,
        flags=re.IGNORECASE,
    ) or re.search(
        r"^(?:google\s+chrome|chrome|safari|firefox|edge|microsoft\s+edge|brave|browser)\s+"
        r"(?:search|find|look\s+up)\b",
        value,
        flags=re.IGNORECASE,
    ):
        return "focus"
    return (
        "open"
        if re.search(r"(?:打开|启动|开启|\bopen\b|\blaunch\b|\bstart\b)", value, flags=re.IGNORECASE)
        else "focus"
    )


def _clean_browser_typed_text(value: str) -> str:
    text = str(value or "").strip()
    text = re.sub(r"^[\"'`“”‘’]+|[\"'`“”‘’]+$", "", text).strip()
    text = re.sub(r"^(?:text|内容)\s*[:：]\s*", "", text, flags=re.IGNORECASE).strip()
    text = re.sub(
        r"\s*(?:并|然后|and\s+then|then)\s*"
        r"(?:提交|发送|确认|submit|send|confirm)$",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip()
    text = re.sub(r"\s+(?:please|pls)$", "", text, flags=re.IGNORECASE).strip()
    return re.sub(r"[。！？!?]+$", "", text).strip()


def _clean_browser_element_label(value: str) -> str:
    label = str(value or "").strip()
    label = re.sub(r"^[：:，,\s]+", "", label)
    label = re.sub(r"[。.,，；;！!？?]+$", "", label).strip()
    label = re.sub(r"^(?:当前)?(?:网页|页面|浏览器|当前页)(?:上的|上|里|中|内|的)?\s*", "", label)
    label = re.sub(r"^(?:上的|的|上|里|中|内)\s*", "", label)
    label = re.sub(
        r"^(?:the\s+)?(?:current|this)?\s*(?:web\s*page|webpage|page|browser)\s+",
        "",
        label,
        flags=re.IGNORECASE,
    )
    label = re.sub(r"\s*(?:按钮|链接|元素|button|link|element|field|input|box)$", "", label, flags=re.IGNORECASE)
    return label.strip()


def _browser_input_selector_from_target(target: str) -> str:
    clean = str(target or "").strip()
    if _looks_like_css_selector(clean):
        return clean
    lowered = clean.lower()
    if re.search(r"(?:搜索|查找|search|query|q)", lowered):
        return _BROWSER_SEARCH_INPUT_SELECTOR
    if re.search(r"(?:密码|password)", lowered):
        return 'input[type="password"]'
    if re.search(r"(?:邮箱|邮件|email|e-mail)", lowered):
        return 'input[type="email"], input[name*="email" i], input[autocomplete="email"]'
    if re.search(r"(?:用户名|账号|账户|user|username|login)", lowered):
        return 'input[name*="user" i], input[autocomplete="username"], input[type="text"]'
    return _BROWSER_TEXT_INPUT_SELECTOR


def _browser_action_tool_candidates(
    browser_action: str,
    inputs: Mapping[str, Any],
) -> tuple[str, ...]:
    if browser_action == "click":
        selector = str(inputs.get("selector") or "").strip()
        if selector.startswith("point="):
            return ("browser.click", "desktop.click")
        return ("browser.click", "desktop.click_ui_element")
    if browser_action == "type_text":
        return ("browser.type_text", "desktop.type_into_ui_element")
    return {
        "current_page": ("browser.current_page",),
        "extract_text": ("browser.extract_text", "browser.extract"),
        "screenshot": ("browser.screenshot",),
        "open_search": ("browser.open_url", "browser.search", "browser.open"),
        "open_url": ("browser.open_url", "browser.open"),
        "open_url_extract": ("browser.open_url_and_extract_text",),
        "open_url_screenshot": ("browser.open_url_and_screenshot",),
    }.get(browser_action, ())


def _browser_navigation_tool_owns_target(
    browser_action: str,
    tool_name: str,
) -> bool:
    """Navigation tools create the run-owned target; no foreground app prep."""

    return bool(
        browser_action
        in {
            "open_search",
            "open_url",
            "open_url_extract",
            "open_url_screenshot",
        }
        and tool_name
        in {
            "browser.open",
            "browser.open_url",
            "browser.search",
            "browser.open_url_and_extract_text",
            "browser.open_url_and_screenshot",
        }
    )


def _browser_click_desktop_preview(selector: str, click_count: Any) -> dict[str, Any]:
    target = _desktop_target_from_browser_selector(selector)
    if not target:
        return {}
    return {
        "target": target,
        "role_filter": _desktop_role_filter_from_browser_selector(
            selector,
            default="button",
        ),
        "click_count": _safe_click_count(click_count),
        "limit": 80,
    }


def _browser_click_point_preview(
    inputs: Mapping[str, Any],
    click_count: Any,
) -> dict[str, Any]:
    x = inputs.get("fallback_x")
    y = inputs.get("fallback_y")
    if x in (None, "") or y in (None, ""):
        return {}
    return {"x": x, "y": y, "click_count": _safe_click_count(click_count)}


def _browser_type_desktop_preview(selector: str, text: str) -> dict[str, Any]:
    target = _desktop_target_from_browser_selector(selector) or "text input"
    payload = {
        "target": target,
        "text": text,
        "role_filter": _desktop_role_filter_from_browser_selector(
            selector,
            default="text field",
        ),
        "limit": 80,
    }
    return {key: value for key, value in payload.items() if value not in (None, "")}


def _desktop_target_from_browser_selector(selector: str) -> str:
    value = str(selector or "").strip()
    if value.startswith("text="):
        return value.removeprefix("text=").strip()
    lowered = value.lower()
    if value.startswith("input:not") or (
        "textarea" in lowered and "contenteditable" in lowered
    ):
        return "text input"
    if "search" in lowered or "搜索" in lowered:
        return "search"
    if "password" in lowered or "密码" in lowered:
        return "password"
    if "email" in lowered or "邮箱" in lowered or "邮件" in lowered:
        return "email"
    if (
        "user" in lowered
        or "username" in lowered
        or "login" in lowered
        or "用户名" in lowered
        or "账号" in lowered
    ):
        return "username"
    if (
        value.startswith("input")
        or value.startswith("textarea")
        or "contenteditable" in lowered
    ):
        return "text input"
    return value


def _desktop_role_filter_from_browser_selector(selector: str, *, default: str) -> str:
    value = str(selector or "").strip().lower()
    if value.startswith("text="):
        return default
    if (
        value.startswith("input")
        or value.startswith("textarea")
        or "contenteditable" in value
        or "search" in value
        or "password" in value
        or "email" in value
    ):
        return "text field"
    return default


def _safe_click_count(value: Any) -> int:
    try:
        count = int(value or 1)
    except (TypeError, ValueError):
        return 1
    return count if count > 0 else 1


def _looks_like_css_selector(value: str) -> bool:
    stripped = str(value or "").strip()
    return bool(
        stripped.startswith(("#", ".", "[", "input", "textarea", "select", "button"))
        or re.search(r"^(?:[a-z][a-z0-9_-]*)(?:[#.\[:][^\s]+)$", stripped, flags=re.IGNORECASE)
    )


def _browser_current_page_find_hint(text: str, context_source: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    lowered = value.lower()
    if _looks_like_browser_field_input(value, lowered):
        return {}
    if not _looks_like_browser_current_page_find(value, lowered):
        return {}
    source = context_source if context_source in {"selection", "clipboard"} else ""
    query = _current_page_find_query(value, lowered)
    if not source and not query:
        return {}
    hint = {"browser_action": "find_current_page"}
    if source:
        hint["context_source"] = source
    if query:
        hint["query"] = query
    return hint


def _looks_like_browser_field_input(value: str, lowered: str) -> bool:
    return bool(
        (
            _contains_any(
                lowered,
                (
                    "search field",
                    "search box",
                    "search input",
                    "input field",
                    "text field",
                    "text box",
                ),
            )
            and _contains_any(lowered, ("type ", "enter ", "input ", "write "))
        )
        or re.search(
            r"(?:输入|键入|填写).{0,24}(?:搜索框|搜索栏|输入框|输入栏|文本框)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_browser_current_page_find(value: str, lowered: str) -> bool:
    return bool(
        re.search(
            r"(?:当前|这个|本页).{0,8}(?:网页|页面|页|标签页).{0,12}(?:查找|搜索|检索)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:查找|搜索|检索).{0,16}(?:当前|这个|本页).{0,8}(?:网页|页面|页|标签页)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:search|find)\s+(?:the\s+)?(?:current|this)\s+(?:web\s*)?page\b",
            lowered,
        )
        or re.search(
            r"\b(?:search|find)\s+.+?\s+(?:on|in)\s+(?:the\s+)?(?:current|this)"
            r"\s+(?:web\s*)?page\b",
            lowered,
        )
        or re.search(
            r"\bfind\s+(?:selected\s+text|current\s+selection|clipboard\s+contents|"
            r"the\s+clipboard)\s+(?:on|in)\s+(?:current\s+)?page\b",
            lowered,
        )
    )


def _current_page_find_query(value: str, lowered: str) -> str:
    patterns = (
        r"\b(?:search|find)\s+(?:the\s+)?(?:current|this)\s+(?:web\s*)?page\s+for\s+(.+)$",
        r"\b(?:search|find)\s+(.+?)\s+(?:on|in)\s+(?:the\s+)?(?:current|this)\s+(?:web\s*)?page\b",
        r"\b(?:current|this)\s+(?:web\s*)?page\s+(?:search|find)\s+(.+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, lowered)
        if match:
            query = _clean_current_page_find_query(match.group(1))
            if query:
                return query

    chinese_patterns = (
        r"(?:当前|这个|本页).{0,8}(?:网页|页面|页|标签页).{0,4}(?:查找|搜索|检索)\s*(.+)$",
        r"(?:查找|搜索|检索)\s*(.+?)\s*(?:在|于|到).{0,4}(?:当前|这个|本页).{0,8}(?:网页|页面|页|标签页)",
        r"(?:在|于).{0,4}(?:当前|这个|本页).{0,8}(?:网页|页面|页|标签页).{0,4}(?:查找|搜索|检索)\s*(.+)$",
    )
    for pattern in chinese_patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if match:
            query = _clean_current_page_find_query(match.group(1))
            if query:
                return query
    return ""


def _clean_current_page_find_query(query: str) -> str:
    value = re.sub(r"^[：:，,\s]+", "", str(query or "").strip())
    value = re.sub(r"[。.,，；;！!？?]+$", "", value).strip()
    lowered = value.lower()
    if not value:
        return ""
    context_terms = (
        "选中的内容",
        "选中内容",
        "当前选中文字",
        "当前选择",
        "剪贴板内容",
        "selected text",
        "current selection",
        "clipboard contents",
        "the clipboard",
        "clipboard",
    )
    if _contains_any(value, context_terms):
        return ""
    if lowered in {"current page", "this page", "current webpage", "this webpage"}:
        return ""
    return value


def _browser_current_page_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    lowered = value.lower()
    if safe_shortcut_hint(value):
        return {}
    if _looks_like_browser_current_page_screenshot(value, lowered):
        return {
            "browser_action": "screenshot",
            "reason": "user asked to capture the browser page",
        }
    if _looks_like_current_page_link_artifact_request(value):
        return {"browser_action": "extract_text"}
    if (
        _looks_like_browser_current_page_text(value, lowered)
        and _looks_like_browser_current_page_summary(value, lowered)
    ):
        return {"browser_action": "extract_text", "presentation": "summary"}
    if _looks_like_browser_current_page_metadata(value, lowered):
        return {"browser_action": "current_page"}
    if _looks_like_browser_current_page_text(value, lowered):
        hint = {"browser_action": "extract_text"}
        if _looks_like_browser_current_page_summary(value, lowered):
            hint["presentation"] = "summary"
        return hint
    return {}


def _looks_like_browser_current_page_screenshot(value: str, lowered: str) -> bool:
    return bool(
        re.search(
            r"(?:当前|这个|本页).{0,8}(?:网页|页面|标签页).{0,8}(?:截图|截屏)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"^(?:网页|页面|标签页).{0,4}(?:截图|截屏|截一下|截下|截个图|截个屏)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:截图|截屏|截取).{0,8}(?:当前|这个|本页).{0,8}(?:网页|页面|标签页)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(r"\bscreenshot\s+(?:this|current)\s+(?:web\s*)?page\b", lowered)
    )


def _looks_like_browser_current_page_text(value: str, lowered: str) -> bool:
    return bool(
        re.search(
            r"(?:读|读取|提取|总结|摘要|概括).{0,8}"
            r"(?:当前|这个|本页).{0,8}(?:网页|页面|标签页|页|正文|内容)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:当前|这个|本页).{0,8}(?:网页|页面|标签页|页|正文|内容)"
            r".{0,8}(?:读|读取|提取|总结|摘要|概括)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:read|extract|summari[sz]e)\s+(?:the\s+)?(?:current|this)"
            r"\s+(?:web\s*)?page(?:\s+text)?\b",
            lowered,
        )
        or re.search(
            r"\b(?:read|extract|summari[sz]e)\s+(?:the\s+)?(?:web\s*)?page\s+(?:text|content)\b",
            lowered,
        )
        or re.search(
            r"\bwhat(?:'s|\s+is)\s+(?:this|the\s+current|current)"
            r"\s+(?:web\s*)?page\s+about\b",
            lowered,
        )
        or re.search(
            r"(?:根据|基于|用|使用).{0,6}(?:当前|这个|本页).{0,8}"
            r"(?:网页|页面|标签页|页).{0,16}(?:写|生成|输出|整理|做|制作|总结|调研|分析)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:研究|调研|分析|整理|总结|摘要|写|生成|输出|制作|做).{0,8}"
            r"(?:当前|这个|本页).{0,8}(?:网页|页面|标签页|页)"
            r"(?:.{0,24}(?:写|生成|输出|整理|做|制作|报告|分析|总结|摘要))?",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:research|analy[sz]e|write|create|generate|produce|summari[sz]e)"
            r".{0,24}\b(?:from|based\s+on|using)?\s*(?:the\s+)?(?:current|this)"
            r"\s+(?:web\s*)?page\b",
            lowered,
        )
        or re.search(r"\bextract\s+(?:the\s+)?(?:current|this)\s+page\s+text\b", lowered)
    )


def _looks_like_browser_current_page_summary(value: str, lowered: str) -> bool:
    return _contains_any(value, ("总结", "摘要", "概括")) or bool(
        re.search(r"\bsummari[sz]e|summary\b", lowered)
        or re.search(
            r"\bwhat(?:'s|\s+is)\s+(?:this|the\s+current|current)"
            r"\s+(?:web\s*)?page\s+about\b",
            lowered,
        )
    )


def _looks_like_browser_current_page_metadata(value: str, lowered: str) -> bool:
    return bool(
        re.search(
            r"(?:当前|这个|本页).{0,8}(?:网址|链接|地址).{0,8}(?:是什么|多少|读取|读|打开)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:读取|读|打开).{0,8}(?:当前|这个|本页).{0,8}(?:网址|链接|地址)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:当前|这个|本页).{0,8}(?:网页|页面|标签页).{0,8}(?:是什么|是啥|标题)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:what(?:'s| is)|read|open)\s+(?:the\s+)?(?:current|this)"
            r"\s+(?:page|tab)\s+(?:url|link|address)\b",
            lowered,
        )
        or re.search(r"\b(?:current|this)\s+(?:page|tab)\s+(?:url|link|address)\b", lowered)
        or re.search(
            r"\bwhat(?:'s| is)\s+(?:the\s+)?(?:current|this)\s+(?:page|tab)\b",
            lowered,
        )
    )


def _pure_desktop_discovery_question(text: str) -> bool:
    """Recognize bounded observations before rejecting unauthorized mutations.

    An open-app question can contain an action word without authorizing that
    action. Compound instructions retain their normal planning and policy path.
    """
    value = _clean_prompt(text).rstrip("。！？!?.").strip()
    app_label = r"(?:应用程序|应用|软件|程序|apps?|applications?)"
    permission_question = (
        rf"(?:为什么|为何|怎么)(?:我|你|现在)?(?:不能|无法|没法)"
        rf"(?:(?:打开|启动|开启){app_label}|(?:读取|查看|控制)屏幕)"
    )
    running_question = (
        rf"(?:(?:现在|当前)(?:开了|打开了?|开着|运行着?)(?:哪些|什么){app_label}|"
        rf"(?:现在|当前)(?:有哪些|哪些|什么){app_label}(?:开着|打开|在运行|运行中)|"
        rf"(?:列一下|列出|列|看看|查看)(?:当前|现在)?"
        rf"(?:打开|开着|运行|正在运行)(?:的)?{app_label})"
    )
    return bool(
        re.fullmatch(
            rf"(?:请|帮我|麻烦)?\s*(?:{permission_question}|{running_question})",
            value,
            flags=re.IGNORECASE,
        )
    )


def _desktop_discovery_hint(text: str) -> dict[str, Any] | None:
    value = _clean_prompt(text)
    lowered = value.lower()
    if _looks_like_desktop_permissions_request(value, lowered):
        return {"action": "diagnose_permissions"}
    if _looks_like_active_window_request(value, lowered):
        return {"action": "read_active_window"}
    if _looks_like_running_apps_request(value, lowered):
        return {"action": "read_running_apps"}
    app_query = _local_app_discovery_query(value)
    if app_query:
        return {"action": "discover_apps", "query": app_query}
    if _looks_like_installed_apps_request(value, lowered):
        return {"action": "discover_apps"}
    return None


def _creative_canvas_create_hint(text: str) -> dict[str, Any]:
    value = _clean_prompt(text)
    lowered = value.lower()
    if not value:
        return {}
    if not (
        re.search(
            r"(?:新建|创建|新增|建立)\s*(?:一个|一张|一幅|一份|新的|新)?"
            r"[^。！？!?，,]{0,40}?(?:图片|图像|画布)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:make|create|open)?\s*(?:a\s+)?new\s+"
            r"(?:image|picture|canvas)\b",
            lowered,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:make|create|open)\s+"
            r"(?:an?\s+)?(?:image|picture|canvas)\b",
            lowered,
            flags=re.IGNORECASE,
        )
    ):
        return {}
    hint: dict[str, Any] = {"kind": "image_canvas"}
    dimension = re.search(
        r"(?<!\d)(?P<width>\d{2,5})\s*(?:x|×|X|\*)\s*(?P<height>\d{2,5})(?!\d)",
        value,
    )
    if dimension:
        hint["width"] = int(dimension.group("width"))
        hint["height"] = int(dimension.group("height"))
    return hint


def _app_capability_discovery_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value:
        return {}
    if safe_shortcut_hint(value) and re.search(
        r"(?:当前|前台)\s*窗口|\b(?:current|foreground)\s+window\b",
        value,
        flags=re.IGNORECASE,
    ):
        return {}
    running_scope_hint = _running_scoped_app_capability_hint(value)
    if running_scope_hint:
        return running_scope_hint
    if re.search(
        r"(?:任意|任何|一个|一款|可用|合适|适合|推荐|any|some|available|suitable)"
        r".{0,20}\b(?:issue|ticket|bug|task)\s+tracker\b",
        value,
        flags=re.IGNORECASE,
    ):
        return {
            "query": "task management",
            "description": "issue tracker",
        }
    generic_prefix = (
        r"(?:(?:一个|一款|任意|任何|默认|可用|合适|适合|推荐|能用|可使用|已安装|"
        r"当前打开|当前已打开|已打开|正在运行|运行中|开着|已开启|前台|当前|"
        r"没提过|没有提过|我没提过|我没有提过|从未提过|未知|陌生|新|新装|刚装|刚安装)"
        r"(?:的)?\s*)*"
    )
    required_generic_prefix = (
        r"(?:(?:一个|一款|任意|任何|默认|可用|合适|适合|推荐|能用|可使用|已安装|"
        r"当前打开|当前已打开|已打开|正在运行|运行中|开着|已开启|前台|当前|"
        r"没提过|没有提过|我没提过|我没有提过|从未提过|未知|陌生|新|新装|刚装|刚安装)"
        r"(?:的)?\s*)+"
    )
    generic_prefix_en = (
        r"(?:(?:an?|any|some|available|default|suitable|best|usable|installed|local|"
        r"currently\s+open|already\s+open|running|open|current|foreground)\s+)*"
    )
    required_generic_prefix_en = (
        r"(?:(?:an?|any|some|available|default|suitable|best|usable|installed|local|"
        r"currently\s+open|already\s+open|running|open|current|foreground)\s+)+"
    )
    local_scope_prefix = (
        r"(?:(?:(?:我(?:的)?|这台|这个)?(?:电脑|机器|mac|Mac|系统)"
        r"|本机|本地|桌面)"
        r"(?:里|中|上|里面|内|下)?(?:的)?\s*)*"
    )
    local_scope_infix_en = (
        r"(?:(?:on|in|from)\s+(?:(?:my|this|the)\s+)?"
        r"(?:mac|computer|machine|desktop|system|local\s+machine))?"
    )
    patterns = (
        r"(?:打开|启动|找|找个|找一个|找一款|使用|在|用|通过)\s*"
        rf"{local_scope_prefix}"
        rf"{generic_prefix}"
        r"(?:能|可以|适合|适用于|可用于|用来|用于)\s*(?P<capability>[^。！？!?，,]{1,40}?)"
        r"(?:的)?(?:应用(?:程序)?|app|软件|工具|程序|窗口)",
        r"(?:有没有|有无|是否有|装了|安装了|有没有安装).{0,12}"
        rf"{local_scope_prefix}"
        r"(?:能|可以|适合|适用于|可用于|用来|用于)\s*(?P<installed_capability>[^。！？!?，,]{1,40}?)"
        r"(?:的)?(?:应用(?:程序)?|app|软件|工具|程序|窗口)",
        r"\b(?:open|launch|start|find|use)\s+"
        rf"{generic_prefix_en}"
        r"(?:app|application|tool|program)\s+"
        rf"{local_scope_infix_en}\s*"
        r"(?:that\s+can|to|for)\s+(?P<capability_en>[^.!?,]{1,60})",
        r"\b(?:in|inside|within|using|with)\s+"
        rf"{generic_prefix_en}"
        r"(?:app|application|tool|program)\s+"
        rf"{local_scope_infix_en}\s*"
        r"(?:that\s+can|to|for)\s+(?P<scoped_capability_en>[^.!?,]{1,60})",
        r"(?:写进|写入|写到|放进|放到|保存到|导出到|输出到|整理到|总结到|发到)\s*"
        rf"{generic_prefix}"
        r"(?P<target_capability_cn>markdown|代码|编程|开发|文本|文档|文章|表单|表格|电子表格|"
        r"图片|图像|照片|看图|绘图|画图|设计|视频|视频剪辑|视频编辑|音频|音频编辑|"
        r"压缩|解压|归档|白板|数据库|截图|截屏|流程图|思维导图|脑图|pdf|PDF|"
        r"演示|幻灯片|笔记|备忘录|邮件|电子邮件|邮箱|"
        r"聊天|通讯|通信|消息|即时通讯|日历|项目管理|任务管理|工单|看板|"
        r"issue|ticket)"
        r"(?:\s*)?(?:编辑器|阅读器|查看器|浏览器|应用(?:程序)?|app|软件|客户端|工具|程序|窗口)",
        r"\b(?:write|save|export|output|put|send|copy|paste)\b.{0,80}?"
        rf"\b(?:to|into|in)\s+{generic_prefix_en}"
        r"(?P<target_capability_en>markdown|code|image|photo|design|video|audio|archive|"
        r"zip|whiteboard|database|screenshot|diagram|mindmap|document|text|form|spreadsheet|"
        r"presentation|slide|note|mail|email|chat|messaging|message|messenger|calendar|"
        r"project|task|issue|ticket|kanban)[\w\s-]{0,30}?"
        r"(?:app|application|client|tool|program|editor|window)\b",
        r"(?:打开|启动|找|找个|找一个|找一款|使用|在|用|通过)\s*"
        rf"{local_scope_prefix}"
        rf"{generic_prefix}"
        r"(?P<direct_capability_cn>markdown|代码|编程|开发|文本|文档|文章|表单|表格|电子表格|"
        r"图片|图像|照片|看图|绘图|画图|设计|视频|视频剪辑|视频编辑|音频|音频编辑|"
        r"压缩|解压|归档|白板|数据库|截图|截屏|流程图|思维导图|脑图|pdf|PDF|"
        r"演示|幻灯片|笔记|备忘录|邮件|电子邮件|邮箱|"
        r"聊天|通讯|通信|消息|即时通讯|日历|项目管理|任务管理|工单|看板|"
        r"issue|ticket)"
        r"(?:\s*)?(?:编辑器|阅读器|查看器|浏览器|应用(?:程序)?|app|软件|客户端|工具|程序|窗口)",
        r"\b(?:open|launch|start|find|use)\s+"
        rf"{generic_prefix_en}"
        r"(?P<direct_capability_en>markdown|code|image|photo|design|video|audio|archive|"
        r"zip|whiteboard|database|screenshot|diagram|mindmap|document|text|form|spreadsheet|"
        r"presentation|slide|note|mail|email|chat|messaging|message|messenger|calendar|"
        r"project|task|issue|ticket|kanban)[\w\s-]{0,30}?"
        r"(?:app|application|client|tool|program|editor|window)\b",
        r"(?:打开|启动|找|找个|找一个|找一款|使用|在|用|通过)\s*"
        rf"{local_scope_prefix}"
        rf"{required_generic_prefix}"
        r"(?P<generic_prefixed_capability_cn>[^。！？!?，,]{1,24}?)"
        r"(?:编辑器|阅读器|查看器|浏览器|应用(?:程序)?|app|软件|客户端|工具|程序|窗口)",
        r"\b(?:open|launch|start|find|use)\s+"
        rf"{required_generic_prefix_en}"
        r"(?P<generic_prefixed_capability_en>[\w\s-]{2,40}?)\s*"
        r"(?:app|application|client|tool|program|editor|window)\b",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        raw = next(
            (
                item
                for item in match.groupdict().values()
                if item is not None and str(item).strip()
            ),
            "",
        )
        query = _app_capability_discovery_query(raw)
        if query:
            return {
                "query": query,
                "description": _clean_app_capability_description(raw),
            }
    return {}


def _app_capability_explicit_app_name_hint(
    text: str,
    capability_hint: Mapping[str, Any] | None,
) -> str:
    if not isinstance(capability_hint, Mapping):
        return ""
    description = str(capability_hint.get("description") or "").strip()
    if not description:
        return ""
    capability = re.escape(description)
    suffix = (
        r"(?:编辑器|阅读器|查看器|浏览器|应用(?:程序)?|app|软件|客户端|工具|程序|窗口)"
    )
    patterns = (
        rf"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
        rf"(?:打开|启动|开启|运行|拉起|使用|用)\s*"
        rf"(?:一个|一款|任意|任何|默认|可用|合适|适合)?\s*"
        rf"{capability}\s*{suffix}\s+"
        rf"(?:叫|名为|名字是)?\s*(?P<app>[^。！？!?，,]{{1,60}})$",
        rf"^(?:(?:can|could|would)\s+you\s+)?(?:please\s+)?"
        rf"(?:open|launch|start|use)\s+"
        rf"(?:an?|any|some|default|available|suitable)?\s*"
        rf"{capability}\s*"
        rf"(?:app|application|client|tool|program|software|editor|viewer)\s+"
        rf"(?:(?:called|named)\s+)?(?P<app>[^.!?,]{{1,60}})$",
    )
    for pattern in patterns:
        match = re.search(pattern, _clean_prompt(text), flags=re.IGNORECASE)
        if not match:
            continue
        app_name = _clean_app_name_hint(match.group("app"))
        if not app_name or re.match(
            r"^(?:并|然后|再|接着|之后|随后|and|then)\b",
            app_name,
            flags=re.IGNORECASE,
        ):
            return ""
        return _canonical_app_name_hint(app_name)
    return ""


def _running_scoped_app_capability_hint(text: str) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value:
        return {}
    cn_scope = (
        r"(?:当前打开|当前已打开|已打开|打开的|正在运行|运行中|当前运行|"
        r"开着|已开启|前台|当前)"
    )
    cn_capability = (
        r"markdown|代码|编程|开发|文本|文档|文章|表单|表格|电子表格|"
        r"图片|图像|照片|看图|绘图|画图|设计|视频|视频剪辑|视频编辑|"
        r"音频|音频编辑|压缩|解压|归档|白板|数据库|截图|截屏|"
        r"流程图|思维导图|脑图|pdf|PDF|演示|幻灯片|笔记|备忘录|"
        r"邮件|电子邮件|邮箱|聊天|通讯|通信|消息|即时通讯|日历|"
        r"项目管理|任务管理|工单|看板|issue|ticket|浏览器|终端|命令行"
    )
    en_scope = r"(?:currently\s+open|already\s+open|running|current|foreground)"
    en_capability = (
        r"markdown|code|image|photo|design|video|audio|archive|zip|"
        r"whiteboard|database|screenshot|diagram|mind\s*map|mindmap|"
        r"document|text|form|spreadsheet|sheet|presentation|slide|note|mail|"
        r"email|chat|messaging|message|messenger|calendar|project|task|"
        r"issue|ticket|kanban|browser|web\s+browser|terminal|command\s+line"
    )
    patterns = (
        rf"(?:^|[\s，,。])(?:在|用|通过)?\s*(?:一个|一款|任意|任何)?\s*"
        rf"{cn_scope}(?:的)?\s*(?P<capability_cn>{cn_capability})"
        r"(?:应用(?:程序)?|app|软件|客户端|工具|程序|编辑器|阅读器|查看器|窗口)?"
        r"\s*(?:里|中|上|内|里面|窗口)?"
        r"(?=\s*(?:打开|启动|点击|点按|按|输入|搜索|查找|检索|找|播放|"
        r"创建|新建|写|发送|分析|操作|查看|看看|把|将|改|修改|"
        r"改成|改为|设置|设为|设置为|填|填写|$))",
        rf"\b(?:in|inside|within|using|with)?\s*(?:the\s+)?{en_scope}\s+"
        rf"(?P<capability_en>{en_capability})"
        r"(?:\s+(?:app|application|client|tool|program|software|editor|viewer|window))?"
        r"(?=\s*(?:to|and|then|click|press|tap|type|enter|search|find|"
        r"open|create|write|send|set|change|update|fill|analy[sz]e|view|inspect|$))",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        raw = next(
            (
                item
                for item in match.groupdict().values()
                if item is not None and str(item).strip()
            ),
            "",
        )
        query = _app_capability_discovery_query(raw)
        if query:
            return {
                "query": query,
                "description": _clean_app_capability_description(raw),
            }
    return {}


def _scoped_app_label_capability_hint(value: str) -> dict[str, str]:
    label = _clean_prompt(value)
    if not label:
        return {}
    if not _contains_any(
        label,
        (
            "当前打开",
            "当前已打开",
            "已打开",
            "打开的",
            "正在运行",
            "运行中",
            "开着",
            "已开启",
            "当前",
            "前台",
            "currently open",
            "already open",
            "running",
            "open",
            "current",
            "foreground",
        ),
    ):
        return {}
    scoped_label = re.sub(
        r"(?:当前打开|当前已打开|已打开|打开的|正在运行|运行中|开着|已开启|当前|前台)",
        " ",
        label,
        flags=re.IGNORECASE,
    )
    scoped_label = re.sub(
        r"\b(?:currently\s+open|already\s+open|running|open|current|foreground)\b",
        " ",
        scoped_label,
        flags=re.IGNORECASE,
    )
    scoped_label = re.sub(r"^\s*(?:的|地|得)\s*", "", scoped_label).strip()
    query = _app_capability_discovery_query(scoped_label)
    if not query:
        return {}
    return {
        "query": query,
        "description": _clean_app_capability_description(scoped_label),
    }


def _app_capability_discovery_query(value: str) -> str:
    description = _clean_app_capability_description(value)
    lowered = description.lower()
    if not description:
        return ""
    if description in {"的", "地", "得"} or lowered in {
        "app",
        "application",
        "tool",
        "program",
        "software",
    }:
        return ""
    if _explicit_named_app_descriptor(description):
        return ""
    if _generic_unknown_app_descriptor(description):
        return ""
    if _contains_any(
        description,
        (
            "播放音乐",
            "听音乐",
            "音乐",
            "歌曲",
            "播放器",
            "music playback",
            "play music",
            "music player",
        ),
    ):
        return "music"
    if "markdown" in lowered:
        return "markdown"
    if "pdf" in lowered:
        return "pdf"
    if _contains_any(description, ("代码", "编程", "开发", "code", "coding", "programming")):
        return "code"
    if _contains_any(description, ("图片", "图像", "照片", "看图", "绘图", "画图", "设计", "image", "photo", "picture", "design")):
        return "image"
    if _contains_any(
        description,
        (
            "视频",
            "剪辑",
            "剪片",
            "视频剪辑",
            "视频编辑",
            "video",
            "movie",
            "film",
            "video editing",
            "video editor",
        ),
    ):
        return "video"
    if _contains_any(
        description,
        (
            "音频",
            "录音",
            "声音",
            "音频编辑",
            "audio",
            "sound",
            "voice recording",
            "audio editing",
            "audio editor",
        ),
    ):
        return "audio"
    if _contains_any(
        description,
        (
            "压缩",
            "解压",
            "归档",
            "zip",
            "archive",
            "compress",
            "decompress",
            "unzip",
        ),
    ):
        return "archive"
    if _contains_any(description, ("白板", "whiteboard")):
        return "whiteboard"
    if _contains_any(
        description,
        (
            "截图",
            "截屏",
            "录屏",
            "screenshot",
            "screen capture",
            "screen recording",
        ),
    ):
        return "screenshot"
    if _contains_any(description, ("数据库", "database", "db", "sql")):
        return "database"
    if _contains_any(description, ("浏览器", "网页", "browser", "web")):
        return "browser"
    if _contains_any(description, ("终端", "命令行", "terminal", "command line", "cli")):
        return "terminal"
    if _contains_any(description, ("流程图", "思维导图", "脑图", "diagram", "flowchart", "mind map", "mindmap")):
        return "diagram"
    if _contains_any(description, ("表格", "数据表", "spreadsheet", "sheet", "csv")):
        return "spreadsheet"
    if _contains_any(description, ("演示", "幻灯片", "presentation", "slide")):
        return "presentation"
    if _contains_any(description, ("笔记", "备忘录", "note", "notes")):
        return "notes"
    if _contains_any(description, ("聊天", "通讯", "通信", "消息", "即时通讯", "chat", "messaging", "message", "messenger")):
        return "messaging"
    if _contains_any(description, ("邮件", "电子邮件", "邮箱", "email", "mail")):
        return "mail"
    if _contains_any(description, ("日历", "calendar")):
        return "calendar"
    if _contains_any(
        description,
        (
            "项目管理",
            "project",
            "projects",
            "project management",
            "project-management",
            "kanban",
            "看板",
        ),
    ):
        return "project management"
    if _contains_any(
        description,
        (
            "任务管理",
            "任务",
            "工单",
            "issue",
            "ticket",
            "task management",
            "task-management",
            "issue tracker",
            "issue-tracker",
            "ticket tracker",
        ),
    ):
        return "task management"
    if _contains_any(
        description,
        ("文档", "文本", "文章", "表单", "document", "text", "form", "writing", "write"),
    ):
        return "document"
    return description[:40].strip()


def _generic_unknown_app_descriptor(description: str) -> bool:
    value = _clean_prompt(description)
    if not value:
        return True
    lowered = value.lower()
    generic_values = {
        "任意",
        "任何",
        "可用",
        "合适",
        "适合",
        "推荐",
        "已安装",
        "本机",
        "本地",
        "当前",
        "当前应用",
        "前台",
        "前台应用",
        "未知",
        "新的",
        "新",
        "没提过",
        "没有提过",
        "我没提过",
        "我没有提过",
        "没提过的新",
        "没有提过的新",
        "我没提过的新",
        "我没有提过的新",
        "any",
        "some",
        "available",
        "default",
        "suitable",
        "best",
        "usable",
        "installed",
        "current",
        "current app",
        "foreground",
        "foreground app",
        "active app",
        "unknown",
        "new",
        "unmentioned",
        "unfamiliar",
    }
    if value in generic_values or lowered in generic_values:
        return True
    return bool(
        re.fullmatch(
            r"(?:(?:我)?(?:没|没有)提过(?:的)?|从未提过(?:的)?|"
            r"没见过(?:的)?|未知(?:的)?|陌生(?:的)?|新(?:的)?|"
            r"(?:我)?(?:刚|新)?装(?:的)?|刚安装(?:的)?|新安装(?:的)?|安装(?:的)?)"
            r"(?:\s*新)?",
            value,
            flags=re.IGNORECASE,
        )
        or re.fullmatch(
            r"(?:(?:any|some|available|default|suitable|best|usable|installed|"
            r"unknown|new|unmentioned|unfamiliar)\s*)+",
            lowered,
            flags=re.IGNORECASE,
        )
    )


def _explicit_named_app_descriptor(description: str) -> bool:
    value = _clean_prompt(description)
    if not value:
        return False
    return bool(
        re.match(
            r"^(?:一个|一款|这个|那个)?"
            r"(?:(?:我(?:的)?(?:电脑|mac|机器|系统)?|本机|本地)(?:上|里|中|内)?(?:的)?\s*)?"
            r"(?:(?:我)?(?:刚|新)?装(?:的)?|刚安装(?:的)?|新安装(?:的)?|安装(?:的)?)?\s*"
            r"(?:叫|名叫|叫做|名称是|名字是)\s*[^。！？!?，,]{1,80}(?:的)?"
            r"(?:应用(?:程序)?|app|软件|工具|程序)?$",
            value,
            flags=re.IGNORECASE,
        )
        or re.match(
            r"^(?:(?:an?|the)\s+)?"
            r"(?:(?:new|unknown|installed|local|unmentioned|unfamiliar)\s+)*"
            r"(?:(?:app|application|software|tool|program)\s+)?"
            r"(?:called|named)\s+[A-Za-z][A-Za-z0-9 ._-]{1,80}$",
            value,
            flags=re.IGNORECASE,
        )
    )


def _media_playback_target_app_capability_hint(text: str) -> dict[str, str]:
    hint = _app_capability_discovery_hint(text)
    if str(hint.get("query") or "").strip() == "music":
        return hint
    value = _clean_prompt(text)
    if not value:
        return {}
    if not re.search(
        r"(?:任意|任何|一个|一款|可用|默认|any|some|available).{0,12}"
        r"(?:音乐\s*(?:应用|app|软件|播放器)?|播放器|music\s+(?:app|player))",
        value,
        flags=re.IGNORECASE,
    ):
        playback = media_playback_hint(value)
        if (
            str(playback.get("action") or "").strip() == "play"
            and str(playback.get("query") or "").strip()
            and not _explicit_media_playback_app_scope_requested(value)
        ):
            return {"query": "music", "description": "music"}
        return {}
    return {"query": "music", "description": "音乐"}


def _explicit_media_playback_app_scope_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    scoped_app_name = media_app_scope_hint(value)
    if scoped_app_name and scoped_app_name != "Music":
        return True
    return bool(
        re.search(
            r"(?:apple\s*music|苹果音乐|spotify|网易云(?:音乐)?|qq\s*音乐|qq\s*music|youtube\s*music)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _app_file_open_discovery_hint(
    text: str,
    metadata: Mapping[str, Any] | None = None,
) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value or not _explicit_app_open_request(value):
        return {}
    if _looks_like_app_scoped_create_followup(value):
        return {}
    app_name = _app_name_hint(value)
    if not app_name or _is_generic_foreground_app_label(app_name):
        return {}
    if data_source_hint(value, metadata):
        return {}
    explicit_target_path, explicit_target_name = _file_open_explicit_target_parts(value)
    scope = (
        data_source_scope_hint(value, metadata)
        or explicit_target_path
        or _file_open_location_hint(value)
    )
    file_type = data_source_kind_hint("", value) or _file_open_type_hint(value)
    if file_type == "unknown":
        file_type = _file_open_type_hint(value)
    if not scope or not file_type:
        return {}
    if not explicit_target_name and not _looks_like_dynamic_file_open_target(value):
        return {}
    pattern = explicit_target_name or _file_open_pattern(file_type)
    hint = {
        "app_name": app_name,
        "path": scope,
        "file_type": file_type,
        "selection": "" if explicit_target_name else _file_open_selection_hint(value),
    }
    if pattern:
        hint["pattern"] = pattern
    return {key: item for key, item in hint.items() if item}


def _generic_app_file_open_discovery_hint(
    text: str,
    metadata: Mapping[str, Any] | None = None,
    *,
    app_capability: Mapping[str, Any] | None = None,
) -> dict[str, str]:
    value = _clean_prompt(text)
    if not value or not app_capability:
        return {}
    if not _explicit_app_open_request(value):
        return {}
    if _looks_like_app_scoped_create_followup(value):
        return {}
    if data_source_hint(value, metadata):
        return {}
    if not _looks_like_dynamic_file_open_target(value):
        return {}
    explicit_target_path, explicit_target_name = _file_open_explicit_target_parts(value)
    if explicit_target_path and explicit_target_name:
        return {}
    scope = (
        data_source_scope_hint(value, metadata)
        or explicit_target_path
        or _file_open_location_hint(value)
    )
    selection = _file_open_selection_hint(value)
    if not scope and selection:
        scope = "Downloads"
    file_type = data_source_kind_hint("", value) or _file_open_type_hint(value)
    if file_type == "unknown":
        file_type = _file_open_type_hint(value)
    if not scope or not file_type:
        return {}
    pattern = explicit_target_name or _file_open_pattern(file_type)
    hint = {
        "path": scope,
        "file_type": file_type,
        "selection": "" if explicit_target_name else selection,
    }
    if pattern:
        hint["pattern"] = pattern
    return {key: item for key, item in hint.items() if item}


def _file_open_location_hint(text: str) -> str:
    value = _clean_prompt(text)
    lowered = value.lower()
    if re.search(r"(?:桌面|desktop)", value, flags=re.IGNORECASE):
        return "Desktop"
    if re.search(r"(?:下载|downloads?)", value, flags=re.IGNORECASE):
        return "Downloads"
    if re.search(r"(?:文档|documents?)", value, flags=re.IGNORECASE):
        return "Documents"
    if re.search(r"\b(?:home|主目录)\b", lowered, flags=re.IGNORECASE):
        return "~"
    return ""


def _file_open_type_hint(text: str) -> str:
    value = _clean_prompt(text)
    lowered = value.lower()
    extension_type = _file_open_extension_type(value)
    if extension_type:
        return extension_type
    type_markers = (
        ("csv", "csv"),
        ("tsv", "tsv"),
        ("xlsx", "xlsx"),
        ("xls", "xls"),
        ("pdf", "pdf"),
        ("markdown", "markdown"),
        ("md", "markdown"),
        ("txt", "text"),
        ("文本", "text"),
        ("文档", "document"),
        ("图片", "image"),
        ("图像", "image"),
        ("照片", "image"),
        ("image", "image"),
        ("photo", "image"),
        ("picture", "image"),
    )
    for marker, file_type in type_markers:
        if marker in lowered or marker in value:
            return file_type
    return ""


def _file_open_extension_type(text: str) -> str:
    match = re.search(
        r"\.(?P<ext>csv|tsv|xlsx|xls|pdf|md|markdown|txt|png|jpg|jpeg|heic|gif|webp)"
        r"(?:$|[\s\"'“”‘’，,。；;])",
        _clean_prompt(text),
        flags=re.IGNORECASE,
    )
    if not match:
        return ""
    ext = str(match.group("ext") or "").strip().lower()
    return {
        "csv": "csv",
        "tsv": "tsv",
        "xlsx": "xlsx",
        "xls": "xls",
        "pdf": "pdf",
        "md": "markdown",
        "markdown": "markdown",
        "txt": "text",
        "png": "image",
        "jpg": "image",
        "jpeg": "image",
        "heic": "image",
        "gif": "image",
        "webp": "image",
    }.get(ext, "")


def _file_open_pattern(file_type: str) -> str:
    return {
        "csv": "*.csv",
        "tsv": "*.tsv",
        "xlsx": "*.xlsx",
        "xls": "*.xls",
        "pdf": "*.pdf",
        "markdown": "*.md",
        "text": "*.txt",
        "image": "*.{png,jpg,jpeg,heic,gif,webp}",
    }.get(str(file_type or "").strip().lower(), "")


def _file_open_selection_hint(text: str) -> str:
    value = _clean_prompt(text)
    if re.search(r"(?:最大|最大的|largest|biggest)", value, flags=re.IGNORECASE):
        return "largest"
    if re.search(
        r"(?:最新|最近|最后|上一个|刚刚|刚才|刚下载|新下载|recent|latest|newest|last|most\s+recent)",
        value,
        flags=re.IGNORECASE,
    ):
        return "latest"
    if not _looks_like_file_collection_selection_context(value):
        return ""
    if re.search(
        r"(?:所有|全部|每个|每一[份个张条]?|全量|\ball\b|\bevery\b|\beach\b)",
        value,
        flags=re.IGNORECASE,
    ):
        return "all"
    if re.search(
        r"(?:多个|多份|若干|一批|几份|几张|几条|\bmultiple\b|\bseveral\b)",
        value,
        flags=re.IGNORECASE,
    ):
        return "multiple"
    if re.search(r"(?:比较|对比|\bcompare\b)", value, flags=re.IGNORECASE):
        return "multiple"
    if re.search(r"(?:合并|\bmerge\b)", value, flags=re.IGNORECASE) and re.search(
        r"(?:downloads?|desktop|documents?|folder|directory|下载|桌面|文档|文件夹|目录|里|里的|中|中的|内)",
        value,
        flags=re.IGNORECASE,
    ):
        return "all"
    return ""


def _looks_like_file_collection_selection_context(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    return bool(
        re.search(
            r"(?:文件|数据|数据集|表格|电子表格|图片|图像|照片|文档|"
            r"\bfiles?\b|\bdata(?:sets?)?\b|\btables?\b|\bspreadsheets?\b|"
            r"\bimages?\b|\bphotos?\b|\bpictures?\b|\bdocuments?\b|"
            r"\b(?:csv|tsv|xlsx|xls|json|jsonl|txt|md|markdown|pdf)s?\b)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_dynamic_file_open_target(text: str) -> bool:
    value = _clean_prompt(text)
    if _file_open_explicit_path_hint(value):
        return True
    if _file_open_selection_hint(value):
        return True
    return bool(
        re.search(
            r"(?:里|里的|中|中的|内|内的|下|下面).{0,24}"
            r"(?:文件|表格|电子表格|图片|图像|照片|pdf|csv|tsv|xlsx|xls|txt|md|markdown)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:in|from|under|inside)\s+(?:the\s+)?"
            r"(?:downloads?|desktop|documents?|folder|directory)\b.{0,60}"
            r"(?:file|image|photo|picture|pdf|csv|tsv|xlsx|xls|txt|md|markdown)\b",
            value,
            flags=re.IGNORECASE,
        )
    )


def _selected_discovered_app_target_path_hint(text: str) -> str:
    source_hint = data_source_hint(text)
    if source_hint:
        if _path_hint_is_app_search_query(text, source_hint):
            return ""
        path = _clean_file_open_explicit_path(source_hint, text)
        location = _file_open_location_hint(text)
        if location and path and "/" not in path and not path.startswith(("~", ".")):
            return f"{location}/{path}"
        return path or source_hint
    file_hint = file_access_hint(text)
    if str(file_hint.get("action") or "").strip() == "open_path":
        path = str(file_hint.get("path") or "").strip()
        if path:
            return path
    value = _clean_prompt(text)
    match = re.search(
        r"(?P<path>(?:~|/|\./|\../)?[^\s\"'“”‘’，,。；;]+"
        r"\.(?:pdf|md|markdown|txt|csv|tsv|xlsx|xls|json|jsonl|doc|docx|rtf|"
        r"pages|numbers|py|js|jsx|ts|tsx|java|go|rs|swift|kt|kts|c|cc|cpp|h|hpp|"
        r"png|jpg|jpeg|heic|gif|webp|ppt|pptx|key))",
        value,
        flags=re.IGNORECASE,
    )
    if not match:
        return ""
    if _path_hint_is_app_search_query(value, str(match.group("path") or "")):
        return ""
    path = _clean_file_open_explicit_path(
        str(match.group("path") or ""),
        value,
    )
    location = _file_open_location_hint(value)
    if location and path and "/" not in path and not path.startswith(("~", ".")):
        return f"{location}/{path}"
    return path


def _file_open_explicit_target_parts(text: str) -> tuple[str, str]:
    target = _file_open_explicit_path_hint(text)
    if not target:
        return "", ""
    if "/" not in target:
        return "", target
    path, name = target.rsplit("/", 1)
    return path or ".", name


def _file_open_explicit_path_hint(text: str) -> str:
    value = _clean_prompt(text)
    match = re.search(
        r"(?P<path>(?:~|/|\./|\../)?[^\s\"'“”‘’，,。；;]+"
        r"\.(?:pdf|md|markdown|txt|csv|tsv|xlsx|xls|json|jsonl|doc|docx|rtf|"
        r"pages|numbers|py|js|jsx|ts|tsx|java|go|rs|swift|kt|kts|c|cc|cpp|h|hpp|"
        r"png|jpg|jpeg|heic|gif|webp|ppt|pptx|key))",
        value,
        flags=re.IGNORECASE,
    )
    if not match:
        return ""
    path = _clean_file_open_explicit_path(
        str(match.group("path") or ""),
        value,
    )
    if _path_hint_is_app_search_query(value, path):
        return ""
    location = _file_open_location_hint(value)
    if location and path and "/" not in path and not path.startswith(("~", ".")):
        return f"{location}/{path}"
    return path


def _clean_file_open_explicit_path(path: str, prompt: str) -> str:
    value = str(path or "").strip().rstrip("。.,，；;")
    if not value:
        return ""
    if "/" in value or value.startswith(("~", ".")):
        return value
    if _file_open_location_hint(prompt):
        for marker in (
            "桌面上的",
            "桌面的",
            "下载文件夹里的",
            "下载里的",
            "文档里的",
            "文件夹里的",
            "目录里的",
            "里面的",
            "中的",
            "里的",
            "上的",
            "的",
        ):
            if marker in value:
                value = value.rsplit(marker, 1)[-1].strip()
                break
    return value


def _path_hint_is_app_search_query(text: str, path: str) -> bool:
    value = _clean_prompt(text)
    target = str(path or "").strip()
    if not value or not target:
        return False
    index = value.lower().find(target.lower())
    if index <= 0:
        return False
    return bool(
        re.search(
            r"(?:搜索|查找|检索|找|search|find|look\s+up)(?:一下|下|for)?\s*$",
            value[:index],
            flags=re.IGNORECASE,
        )
    )


def _clean_app_capability_description(value: str) -> str:
    description = _clean_prompt(value)
    description = re.sub(
        r"^(?:用来|用于|可以|能够|能|处理|编辑|写|创建|新建|打开|查看|分析|生成|输出|"
        r"to|for|can|edit|write|create|open|view|analy[sz]e|generate|produce)\s*",
        "",
        description,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    description = re.sub(
        r"^(?:(?:一个|一款|任意|任何|默认|可用|合适|适合|推荐|能用|可使用|已安装|"
        r"当前打开|当前已打开|已打开|正在运行|运行中|开着|已开启|前台|当前)"
        r"(?:的)?\s*)+",
        "",
        description,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    description = re.sub(
        r"^(?:(?:an?|any|some|available|default|suitable|best|usable|installed|local|"
        r"currently\s+open|already\s+open|running|open|current|foreground)\s+)+",
        "",
        description,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    description = re.split(
        r"(?:并|然后|再|接着|之后|后|标题|名称|大小|尺寸|\b(?:and|then|with|titled|named)\b)",
        description,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0].strip(" .，,。")
    description = re.sub(
        r"\s*(?:的)?(?:本机|本地|桌面|电脑|mac|系统|"
        r"local|desktop|mac|machine|system)\s*$",
        "",
        description,
        flags=re.IGNORECASE,
    ).strip(" .，,。")
    return description


def _discovered_app_open_requested(intent: TaskIntentSnapshot) -> bool:
    text = _clean_prompt(intent.user_goal)
    if not text:
        return False
    if isinstance(intent.inputs.get("app_capability_hint"), Mapping):
        safe_shortcut = intent.inputs.get("safe_shortcut_hint")
        if _explicit_app_open_request(text):
            return True
        if _explicit_app_focus_request(text):
            return True
        if str(intent.inputs.get("selected_app_target_path_hint") or "").strip():
            return True
        if (
            isinstance(safe_shortcut, Mapping)
            and str(safe_shortcut.get("action") or "").strip()
        ):
            return True
        for hint_key in (
            "safe_key_hint",
            "safe_scroll_hint",
            "safe_click_hint",
            "hotkey_hint",
            "click_target_hint",
            "type_into_ui_hint",
        ):
            raw_hint = intent.inputs.get(hint_key)
            if isinstance(raw_hint, Mapping) and raw_hint:
                return True
        if str(intent.inputs.get("safe_type_text_hint") or "").strip():
            return True
        operation_hint = str(intent.inputs.get("operation_hint") or "").strip()
        if operation_hint in {"safe_key", "safe_scroll", "safe_click", "hotkey"}:
            return True
        pending_action = discovered_app_pending_user_action(text)
        if _looks_like_discovered_creative_action(intent, pending_action):
            return True
        if (
            safe_key_hint(pending_action)
            or safe_scroll_hint(pending_action)
            or safe_click_hint(pending_action)
            or hotkey_hint(pending_action)
            or click_target_hint(pending_action)
            or type_into_ui_hint(pending_action)
            or safe_type_text_hint(pending_action)
            or submit_action_hint(pending_action)
        ):
            return True
        if _looks_like_app_scoped_create_followup(text):
            return True
    desktop_discovery = intent.inputs.get("desktop_discovery_hint")
    if (
        isinstance(desktop_discovery, Mapping)
        and str(desktop_discovery.get("action") or "").strip() == "discover_apps"
        and (_explicit_app_open_request(text) or _explicit_app_focus_request(text))
    ):
        return True
    return bool(
        re.search(
            r"(?:并|然后|再|接着|之后|后|可以的话|如果可以|如果有|找到后).{0,12}"
            r"(?:打开|启动|开启|运行|拉起|开一个|打开一个)",
            text,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:and|then|after(?:wards)?|if\s+(?:available|possible|found))\b"
            r".{0,24}\b(?:open|launch|start|run|use)\b",
            text,
            flags=re.IGNORECASE,
        )
    )


def _desktop_discovery_tool_preview(
    action: str,
    hint: Mapping[str, Any],
) -> tuple[str | None, dict[str, Any]]:
    if action == "diagnose_permissions":
        return "desktop.permissions", {}
    if action == "read_active_window":
        return "desktop.active_window", {}
    if action == "read_running_apps":
        return "desktop.running_apps", {}
    if action == "discover_apps":
        query = str(hint.get("query") or "").strip()
        return (
            "desktop.list_apps",
            {"query": query, "limit": 20} if query else {},
        )
    return None, {}


def _running_app_discovery_tool_preview(
    intent: TaskIntentSnapshot,
    allowed: set[str] | None,
    tool_name: str | None,
    input_preview: Mapping[str, Any],
    *,
    app_capability: Mapping[str, Any],
) -> tuple[str | None, dict[str, Any]]:
    if tool_name != "desktop.list_apps":
        return tool_name, dict(input_preview)
    if not _running_app_capability_scope_requested(intent, app_capability):
        return tool_name, dict(input_preview)
    running_tool = _first_allowed(("desktop.running_apps",), allowed)
    if not running_tool:
        return tool_name, dict(input_preview)
    return running_tool, {}


def _running_app_capability_scope_requested(
    intent: TaskIntentSnapshot,
    app_capability: Mapping[str, Any],
) -> bool:
    if not isinstance(app_capability, Mapping):
        return False
    value = " ".join(
        item
        for item in (
            _clean_prompt(intent.user_goal),
            str(app_capability.get("description") or "").strip(),
        )
        if item
    )
    if not value:
        return False
    if _running_scoped_app_capability_hint(value):
        return True
    return _contains_any(
        value,
        (
            "当前打开",
            "已打开",
            "打开的",
            "正在运行",
            "运行中",
            "开着",
            "已开启",
            "当前已打开",
            "当前",
            "前台",
            "currently open",
            "already open",
            "opened app",
            "open app",
            "running app",
            "running application",
            "running browser",
            "running window",
            "current browser",
            "current window",
            "active browser",
            "active window",
            "foreground browser",
            "foreground window",
        ),
    )


def _selected_app_selection_source(tool_name: str | None) -> str:
    if str(tool_name or "").strip() == "desktop.running_apps":
        return "desktop.running_apps"
    return "desktop.list_apps"


def _selected_app_placeholder(selection_source: str) -> str:
    if str(selection_source or "").strip() == "desktop.running_apps":
        return "<selected app from desktop.running_apps>"
    return "<selected app from desktop.list_apps>"


def _looks_like_desktop_permissions_request(value: str, lowered: str) -> bool:
    return bool(
        re.search(r"(?:桌面|本地|自动化|辅助功能|屏幕录制|读取屏幕).{0,16}(?:权限|授权|permission)", value, flags=re.IGNORECASE)
        or re.search(r"(?:需要|缺少|检查|诊断|修复).{0,16}(?:权限|授权)", value)
        or re.search(
            r"(?:为什么|为何|怎么|why).{0,24}(?:不能|无法|can't|cannot)"
            r".{0,24}(?:打开|点击|读取屏幕|查看屏幕|控制|操作|播放|"
            r"open|click|control|play)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(r"\b(?:desktop|local|accessibility|screen recording)\s+permissions?\b", lowered)
    )


def _explicit_system_settings_request(text: str) -> bool:
    if (
        _finder_special_location_hint(text)
        or _browser_internal_page_hint(text)
        or _app_preferences_hint(text)
    ):
        return False
    hint = system_control_hint(affirmative_desktop_action_text(text, "focus"))
    if str(hint.get("kind") or "").strip() != "settings_open":
        return False
    payload = hint.get("payload") if isinstance(hint.get("payload"), Mapping) else {}
    return bool(str(payload.get("target") or "").strip())


def _looks_like_active_window_request(value: str, lowered: str) -> bool:
    if re.search(r"我现在是不是在家", value):
        return False
    return bool(
        re.search(r"(?:当前|现在|前台).{0,8}(?:窗口|应用|app).{0,8}(?:是什么|是哪个|是不是)", value, flags=re.IGNORECASE)
        or _looks_like_current_window_observation_request(value, lowered)
        or re.search(r"(?:(?:当前|现在)\s*)?前台\s*(?:窗口|应用|app)?\s*(?:是什么|是啥|哪个|什么)", value, flags=re.IGNORECASE)
        or re.search(r"(?:当前|现在)?前台是不是\s*.+", value, flags=re.IGNORECASE)
        or re.search(r"现在是不是在\s*.+", value, flags=re.IGNORECASE)
        or re.search(r"我正在用什么(?:应用|app|软件)?", value, flags=re.IGNORECASE)
        or re.search(
            r"(?:当前|现在)?\s*(?:正在用|在用|用的是|用的)\s*"
            r"(?:哪个|什么).{0,4}(?:app|应用|软件)?",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(r"\bwhat\s+app\s+am\s+i\s+using\b", lowered)
        or re.search(r"\bwhat\s+is\s+(?:the\s+)?(?:frontmost|active|foreground)\s+window\b", lowered)
        or re.search(r"\bwhich\s+(?:app|application)\s+is\s+(?:frontmost|active|foreground)\b", lowered)
        or re.search(r"\bis\s+.+\s+(?:frontmost|the\s+active\s+app|the\s+active\s+application)\b", lowered)
        or re.search(r"\bis\s+(?:the\s+)?(?:active|frontmost|foreground)\s+(?:app|application)\s+.+", lowered)
    )


def _looks_like_current_window_observation_request(value: str, lowered: str) -> bool:
    if re.search(
        r"(?:列表|清单|所有|全部|哪些|几个|多少|list|all|windows)",
        value,
        flags=re.IGNORECASE,
    ):
        return False
    return bool(
        re.search(
            r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:直接)?"
            r"(?:查看|看看|看一下|看下|显示|读取)?\s*"
            r"(?:当前|现在|前台|这个|该)\s*(?:窗口|window)"
            r"\s*(?:是什么|是啥|哪个|什么|标题|名称|名字)?"
            r"(?:一下|下|可以吗|好吗|好么|行吗|吗|嘛|吧|呢)?$",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"\b(?:show|read|inspect|look\s+at|check)\s+"
            r"(?:the\s+)?(?:current|active|foreground|frontmost|this)\s+window\b",
            lowered,
        )
    )


def _looks_like_running_apps_request(value: str, lowered: str) -> bool:
    return bool(
        re.search(r"(?:现在|当前).{0,8}(?:开了|打开|运行).{0,8}(?:哪些|什么).{0,8}(?:应用|app|软件|程序)", value, flags=re.IGNORECASE)
        or re.search(r"(?:现在|当前).{0,8}(?:哪些|什么).{0,8}(?:应用|app|软件|程序).{0,8}(?:开着|打开|运行|在运行)", value, flags=re.IGNORECASE)
        or re.search(r"(?:列|列出|列一下|看看|查看).{0,8}(?:打开|运行|正在运行).{0,8}(?:应用|app|软件|程序)", value, flags=re.IGNORECASE)
        or re.search(r"(?:搜索|搜一下|查找).{0,8}(?:当前|正在|运行中).{0,8}(?:应用|app|软件|程序)", value, flags=re.IGNORECASE)
        or re.search(r"\b(?:what|which|list|show)\s+(?:apps?|applications?)\s+(?:are\s+)?(?:running|open)\b", lowered)
        or re.search(r"\b(?:list|show)\s+(?:running|open)\s+(?:apps?|applications?)\b", lowered)
    )


def _looks_like_installed_apps_request(value: str, lowered: str) -> bool:
    return bool(
        re.search(r"(?:列出|列一下|查看|看看|有哪些).{0,8}(?:已安装|可用).{0,8}(?:应用|app|软件|程序)", value, flags=re.IGNORECASE)
        or re.search(r"(?:列出|列一下|查看|看看|显示).{0,8}(?:所有|全部).{0,4}(?:应用|app|软件|程序)", value, flags=re.IGNORECASE)
        or re.search(r"(?:有哪些|有什么|有啥).{0,4}(?:应用|app|软件|程序)", value, flags=re.IGNORECASE)
        or re.search(r"\bshow\s+installed\s+apps?\b", lowered)
        or re.search(r"\b(?:list|show)\s+all\s+(?:apps?|applications?)\b", lowered)
        or re.search(r"\blist\s+(?:installed|available)\s+(?:apps?|applications?)\b", lowered)
        or re.fullmatch(r"(?:installed|available)\s+(?:apps?|applications?)", lowered.strip())
    )


def _local_app_discovery_query(text: str) -> str:
    value = _clean_prompt(text)
    patterns = (
        r"^(?:帮我|请|麻烦|能否|能不能|可以)?(?:搜索|搜一下|查找)\s*(?P<app>[^。！？!?，,]{1,40}?)(?P<local_label>这个应用|应用|软件|程序|app|application)?$",
        r"(?:机器|电脑|mac|系统|本机|本地).{0,8}(?:有没有|是否有|有无|装了|安装了|有没有安装)\s*(?P<app>[^。！？!?，,]+)",
        r"(?:有没有|是否有|有无|装了|安装了|有没有安装).{0,8}(?P<app>[\w .·-]{2,40})(?:\s*(?:这个|这款|这个应用|这个软件|app|application|应用|软件))?$",
        r"\b(?:is|do\s+i\s+have|have)\s+(?P<app_en>[A-Za-z][A-Za-z0-9 ._-]{1,40}?)\s+(?:installed|on\s+(?:this\s+)?mac|on\s+(?:this\s+)?machine)\b",
    )
    for pattern in patterns:
        match = re.search(pattern, value, flags=re.IGNORECASE)
        if not match:
            continue
        raw_app = (
            match.groupdict().get("app")
            or match.groupdict().get("app_en")
            or ""
        )
        app = _clean_app_name_hint(raw_app)
        if (
            "local_label" in match.groupdict()
            and not _is_system_settings_app_label(app)
        ):
            continue
        if (
            app
            and not _is_generic_foreground_app_label(app)
            and not _invalid_local_app_discovery_subject(raw_app)
            and not _invalid_local_app_discovery_subject(app)
        ):
            return app
    return ""


def _invalid_local_app_discovery_subject(value: str) -> bool:
    subject = _clean_prompt(value)
    compact = compact_app_name_hint(subject)
    if compact in {
        "消息",
        "新消息",
        "未读",
        "未读消息",
        "通知",
        "新通知",
        "当前聊天",
        "聊天",
        "currentchat",
        "message",
        "messages",
        "newmessage",
        "newmessages",
        "unread",
        "unreadmessages",
        "notification",
        "notifications",
    }:
        return True
    return bool(
        re.fullmatch(
            r"(?:新|未读|当前)?(?:消息|通知|聊天|对话)",
            subject,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_ui_operation(text: str) -> bool:
    return _contains_any(
        text,
        [
            "click",
            "type",
            "press",
            "shortcut",
            "scroll",
            "create",
            "new",
            "make",
            "点击",
            "输入",
            "按",
            "快捷键",
            "滚动",
            "发送",
            "新建",
            "创建",
            "新增",
        ],
    )


def _explicit_ui_observation_before_action_requested(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    observation = (
        r"(?:查看|看看|看一下|看下|读取|读一下|识别|观察|列出|列一下|"
        r"有哪些|有什么|有啥|哪些|什么|"
        r"inspect|read|look\s+at|show|list|what|which)"
    )
    connector = r"(?:然后|并且|并|再|接着|之后|后|,|，|and\s+then|then|and)"
    action = (
        r"(?:点击|点一下|点按|单击|双击|选择|选中|打开|输入|填写|保存|提交|"
        r"click|press|tap|select|choose|open|type|enter|fill|save|submit)"
    )
    return bool(
        re.search(
            rf"{observation}[^。！？!?]{{0,80}}{connector}[^。！？!?]{{0,80}}{action}",
            value,
            flags=re.IGNORECASE,
        )
    )


def _looks_like_local_ui_inspection_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not value:
        return False
    if _contains_any(
        value,
        (
            "研究",
            "调研",
            "设计模式",
            "原理",
            "最新",
            "新闻",
            "价格",
            "定价",
            "research",
            "latest",
            "news",
            "pricing",
            "price",
            "pattern",
            "patterns",
        ),
    ):
        return False
    if not _contains_any(
        value,
        (
            "当前应用",
            "前台应用",
            "当前窗口",
            "前台窗口",
            "当前界面",
            "前台界面",
            "当前屏幕",
            "这个屏幕",
            "屏幕",
            "current app",
            "foreground app",
            "current window",
            "foreground window",
            "current screen",
            "screen",
        ),
    ):
        return False
    return bool(
        re.search(
            r"(?:看看|查看|检查|列出|列一下|读一下|识别|有哪些|有什么|有啥|"
            r"inspect|show|list|read|check).{0,24}"
            r"(?:按钮|控件|元素|菜单|输入框|文本框|button|buttons|control|controls|"
            r"element|elements|menu|field|fields|input)",
            value,
            flags=re.IGNORECASE,
        )
        or re.search(
            r"(?:按钮|控件|元素|菜单|输入框|文本框|button|buttons|control|controls|"
            r"element|elements|menu|field|fields|input).{0,24}"
            r"(?:有哪些|有什么|有啥|显示|可见|visible|available)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _generic_app_foreground_operation_tool(
    *,
    app_name: str,
    mode: str,
    allowed: set[str] | None,
    operation_tools: Iterable[str],
) -> str | None:
    if not app_name:
        return None
    if not _first_allowed(app_control_tool_candidates(mode), allowed):
        return None
    return _first_allowed(operation_tools, allowed)


def _explicit_hotkey_should_override_safe_shortcut(
    text: str,
    hotkey: Mapping[str, Any] | None,
    safe_shortcut: Mapping[str, Any] | None,
) -> bool:
    if not hotkey or not safe_shortcut:
        return False
    if (
        str(hotkey.get("key") or "").strip().lower() == "space"
        and not list(hotkey.get("modifiers") or [])
        and str((safe_shortcut or {}).get("action") or "").strip()
        == "finder_quick_look"
        and not re.search(r"(?:finder|访达)", text, flags=re.IGNORECASE)
    ):
        return True
    if str((safe_shortcut or {}).get("action") or "").strip() != "focus_address_bar":
        return False
    return not _contains_any(text, ["地址栏", "address bar", "omnibox"])


def _explicit_hotkey_request(text: str) -> bool:
    value = _clean_prompt(text)
    return bool(
        re.search(r"(?:按|按下|发送|触发|press|hit|send)\s*", value, flags=re.IGNORECASE)
        and re.search(
            r"(?:command|cmd|⌘|control|ctrl|option|alt|shift|回车|enter|return|space|空格)",
            value,
            flags=re.IGNORECASE,
        )
    )


def _standalone_hotkey_request(text: str) -> bool:
    value = _clean_prompt(text)
    if not hotkey_hint(value):
        return False
    return bool(
        re.fullmatch(
            r"(?:按|按下|敲|敲一下|触发)\s*(?:回车键?|enter|return|space|空格|"
            r"(?:command|cmd|⌘|control|ctrl|option|alt|shift)\s*[+ ]?\s*\w+)",
            value,
            flags=re.IGNORECASE,
        )
        or re.fullmatch(
            r"(?:press|hit|tap)\s+(?:the\s+)?(?:enter|return|space|spacebar|"
            r"(?:command|cmd|control|ctrl|option|alt|shift)(?:\s*[+ ]\s*\w+)?)",
            value,
            flags=re.IGNORECASE,
        )
        or re.fullmatch(
            r"(?:can|could|would)\s+you\s+(?:please\s+)?(?:press|hit|tap)\s+"
            r"(?:the\s+)?(?:enter|return|space|spacebar|"
            r"(?:command|cmd|control|ctrl|option|alt|shift)(?:\s*[+ ]\s*\w+)?)\??",
            value,
            flags=re.IGNORECASE,
        )
    )


def _desktop_operation_tool_preview(
    *,
    app_name: str,
    mode: str,
    allowed: set[str] | None,
    click_target: dict[str, Any] | None,
    hotkey: dict[str, Any] | None,
    safe_shortcut: dict[str, str] | None,
    safe_key: dict[str, Any] | None,
    safe_scroll: dict[str, Any] | None,
    safe_click: dict[str, Any] | None,
    type_target: dict[str, Any] | None,
    safe_type_text: str,
    allow_app_tools: bool = True,
) -> tuple[str | None, dict[str, Any]]:
    if safe_shortcut:
        if app_name and allow_app_tools:
            app_tool = _first_allowed(app_foreground_tool_candidates(mode, "safe_shortcut"), allowed)
            if app_tool:
                return app_tool, {"app_name": app_name, **safe_shortcut}
        generic_tool = _generic_app_foreground_operation_tool(
            app_name=app_name,
            mode=mode,
            allowed=allowed,
            operation_tools=("desktop.safe_shortcut",),
        )
        if generic_tool:
            return generic_tool, dict(safe_shortcut)
        shortcut_tool = _first_allowed(("desktop.safe_shortcut",), allowed)
        if shortcut_tool:
            return shortcut_tool, dict(safe_shortcut)
    if safe_key:
        if app_name and allow_app_tools:
            app_tool = _first_allowed(app_foreground_tool_candidates(mode, "safe_key"), allowed)
            if app_tool:
                return app_tool, {"app_name": app_name, **safe_key}
        generic_tool = _generic_app_foreground_operation_tool(
            app_name=app_name,
            mode=mode,
            allowed=allowed,
            operation_tools=("desktop.safe_key",),
        )
        if generic_tool:
            return generic_tool, dict(safe_key)
        key_tool = _first_allowed(("desktop.safe_key",), allowed)
        if key_tool:
            return key_tool, dict(safe_key)
    if safe_scroll:
        if app_name and allow_app_tools:
            app_tool = _first_allowed(app_foreground_tool_candidates(mode, "safe_scroll"), allowed)
            if app_tool:
                return app_tool, {"app_name": app_name, **safe_scroll}
        generic_tool = _generic_app_foreground_operation_tool(
            app_name=app_name,
            mode=mode,
            allowed=allowed,
            operation_tools=("desktop.safe_scroll",),
        )
        if generic_tool:
            return generic_tool, dict(safe_scroll)
        scroll_tool = _first_allowed(("desktop.safe_scroll",), allowed)
        if scroll_tool:
            return scroll_tool, dict(safe_scroll)
    if safe_click:
        click_count = int(safe_click.get("click_count") or 1)
        if click_count != 1:
            raw_click_tool = _first_allowed(("desktop.click",), allowed)
            if raw_click_tool:
                return raw_click_tool, dict(safe_click)
        safe_click_payload = {
            key: value
            for key, value in safe_click.items()
            if key in {"x", "y"}
        }
        if app_name and allow_app_tools:
            app_tool = _first_allowed(app_foreground_tool_candidates(mode, "safe_click"), allowed)
            if app_tool:
                return app_tool, {"app_name": app_name, **safe_click_payload}
        generic_tool = _generic_app_foreground_operation_tool(
            app_name=app_name,
            mode=mode,
            allowed=allowed,
            operation_tools=("desktop.safe_click", "desktop.click"),
        )
        if generic_tool:
            return generic_tool, safe_click_payload if generic_tool == "desktop.safe_click" else dict(safe_click)
        click_tool = _first_allowed(("desktop.safe_click",), allowed)
        if click_tool:
            return click_tool, safe_click_payload
        raw_click_tool = _first_allowed(("desktop.click",), allowed)
        if raw_click_tool:
            return raw_click_tool, dict(safe_click)
    if hotkey:
        if app_name and allow_app_tools:
            app_tool = _first_allowed(app_foreground_tool_candidates(mode, "hotkey"), allowed)
            if app_tool:
                return app_tool, {"app_name": app_name, **hotkey}
        generic_tool = _generic_app_foreground_operation_tool(
            app_name=app_name,
            mode=mode,
            allowed=allowed,
            operation_tools=("desktop.hotkey",),
        )
        if generic_tool:
            return generic_tool, dict(hotkey)
        return _first_allowed(("desktop.hotkey",), allowed), dict(hotkey)
    if app_name and type_target:
        if allow_app_tools:
            app_tool = _first_allowed(
                app_foreground_tool_candidates(mode, "type_into_ui_element"),
                allowed,
            )
            if app_tool:
                return app_tool, {"app_name": app_name, **type_target, "limit": 80}
        generic_tool = _generic_app_foreground_operation_tool(
            app_name=app_name,
            mode=mode,
            allowed=allowed,
            operation_tools=("desktop.type_into_ui_element",),
        )
        if generic_tool:
            return generic_tool, {**type_target, "limit": 80}
        return _first_allowed(("desktop.type_into_ui_element",), allowed), {**type_target, "limit": 80}
    if app_name and safe_type_text:
        if allow_app_tools:
            app_tool = _first_allowed(
                app_foreground_tool_candidates(mode, "safe_type_text"),
                allowed,
            )
            if app_tool:
                return app_tool, {"app_name": app_name, "text": safe_type_text}
        generic_tool = _generic_app_foreground_operation_tool(
            app_name=app_name,
            mode=mode,
            allowed=allowed,
            operation_tools=("desktop.safe_type_text", "desktop.type_text"),
        )
        if generic_tool:
            return generic_tool, {"text": safe_type_text}
        type_tool = _first_allowed(("desktop.safe_type_text", "desktop.type_text"), allowed)
        return type_tool, {"text": safe_type_text}
    if app_name and click_target:
        if allow_app_tools:
            app_tool = _first_allowed(
                app_foreground_tool_candidates(mode, "click_ui_element"),
                allowed,
            )
            if app_tool:
                return app_tool, {"app_name": app_name, **click_target, "limit": 80}
        generic_tool = _generic_app_foreground_operation_tool(
            app_name=app_name,
            mode=mode,
            allowed=allowed,
            operation_tools=("desktop.click_ui_element",),
        )
        if generic_tool:
            return generic_tool, {**click_target, "limit": 80}
        return _first_allowed(("desktop.click_ui_element",), allowed), {**click_target, "limit": 80}
    if type_target:
        return _first_allowed(("desktop.type_into_ui_element",), allowed), {**type_target, "limit": 80}
    if safe_type_text:
        type_tool = _first_allowed(("desktop.safe_type_text", "desktop.type_text"), allowed)
        return type_tool, {"text": safe_type_text}
    if click_target:
        return _first_allowed(("desktop.click_ui_element",), allowed), {**click_target, "limit": 80}
    return None, {}


def _desktop_operation_fallback_tool(
    *,
    allowed: set[str] | None,
    click_target: Mapping[str, Any] | None,
    hotkey: Mapping[str, Any] | None,
    safe_shortcut: Mapping[str, Any] | None,
    safe_key: Mapping[str, Any] | None,
    safe_scroll: Mapping[str, Any] | None,
    safe_click: Mapping[str, Any] | None,
    type_target: Mapping[str, Any] | None,
    safe_type_text: str,
) -> str | None:
    if hotkey:
        return _first_allowed(("desktop.hotkey",), allowed)
    if safe_shortcut:
        return _first_allowed(("desktop.safe_shortcut",), allowed)
    if safe_key:
        return _first_allowed(("desktop.safe_key",), allowed)
    if safe_scroll:
        return _first_allowed(("desktop.safe_scroll",), allowed)
    if safe_click:
        return _first_allowed(("desktop.safe_click", "desktop.click"), allowed)
    if type_target:
        return _first_allowed(("desktop.type_into_ui_element",), allowed)
    if safe_type_text:
        return _first_allowed(("desktop.safe_type_text", "desktop.type_text"), allowed)
    if click_target:
        return _first_allowed(("desktop.click_ui_element",), allowed)
    return _first_allowed(
        (
            "desktop.click_ui_element",
            "desktop.type_into_ui_element",
            "desktop.safe_shortcut",
            "desktop.safe_key",
            "desktop.hotkey",
            "desktop.safe_type_text",
        ),
        allowed,
    )


def _web_research_expected_outputs(
    text: str,
    *,
    browser_action: str,
    url_hint: str = "",
    query: str = "",
) -> list[str]:
    """Describe the requested web result without inventing a file artifact."""

    instruction_text = _web_output_instruction_text(
        text,
        url_hint=url_hint,
        query=query,
    )
    explicit_outputs = _expected_outputs(instruction_text, default=[])
    if explicit_outputs:
        return explicit_outputs
    if _contains_any(
        instruction_text,
        (
            "summarize",
            "summarise",
            "summary",
            "write up",
            "research",
            "总结",
            "摘要",
            "概括",
            "研究",
            "调研",
        ),
    ):
        return ["summary"]
    clean_action = str(browser_action or "").strip()
    return {
        "open_url": ["opened_page"],
        "open_search": ["search_results"],
        "open_url_extract": ["web_text"],
        "open_url_screenshot": ["screenshot"],
        "current_page": ["page_metadata"],
        "extract_text": ["web_text"],
        "screenshot": ["screenshot"],
        "find_current_page": ["browser_state"],
        "click": ["browser_state"],
        "type_text": ["browser_state"],
    }.get(clean_action, ["summary"])


def _web_output_instruction_text(
    text: str,
    *,
    url_hint: str = "",
    query: str = "",
) -> str:
    """Return command language with navigational data operands removed.

    Output words inside a URL path or a search query (for example
    ``/document`` or ``annual report``) describe what to navigate to, not a
    request to create a file. Delivery clauses remain in the command and are
    still recognized after removing those operands.
    """

    value = _clean_prompt(text)
    operands = [str(url_hint or "").strip(), str(query or "").strip()]
    operands.extend(
        match.group(0).rstrip(".,;:!?，。；：！？")
        for match in re.finditer(r"https?://[^\s<>\"']+", value, flags=re.IGNORECASE)
    )
    for operand in sorted({item for item in operands if item}, key=len, reverse=True):
        value = re.sub(re.escape(operand), " ", value, count=1, flags=re.IGNORECASE)
    return re.sub(r"\s+", " ", value).strip()


def _expected_outputs(text: str, *, default: list[str]) -> list[str]:
    outputs = []
    if _contains_any(text, ["chart", "plot", "graph", "trend chart", "图表", "趋势图", "折线图", "可视化"]):
        outputs.append("chart")
    if _contains_any(text, ["report", "报告"]):
        outputs.append("report")
    if _contains_any(
        text,
        [
            "ppt",
            "pptx",
            "slide deck",
            "slides",
            "presentation",
            "keynote",
            "演示",
            "演示文稿",
            "幻灯片",
            "PPT",
            "做成 PPT",
            "做成PPT",
        ],
    ):
        outputs.append("presentation")
    if _contains_any(
        text,
        [
            "link list",
            "links list",
            "list links",
            "source list",
            "sources",
            "url list",
            "all links",
            "all urls",
            "链接清单",
            "链接列表",
            "所有链接",
            "全部链接",
            "列出链接",
            "输出链接",
            "来源清单",
            "来源列表",
        ],
    ):
        outputs.append("links")
    if _contains_any(
        text,
        [
            "output csv",
            "export csv",
            "export as csv",
            "csv summary",
            "summary csv",
            "csv file",
            "csv 汇总",
            "csv 摘要",
            "摘要 csv",
            "输出 csv",
            "生成 csv",
            "做成 csv",
            "分析成 csv",
            "分析为 csv",
            "转成 csv",
            "转换成 csv",
            "导出 csv",
            "导出成 csv",
            "导出为 csv",
            "提取成 csv",
            "提取为 csv",
            "csv 文件",
            "表格汇总",
            "整理成表格",
            "整理为表格",
            "输出表格",
            "生成表格",
            "markdown table",
            "Markdown 表格",
            "链接表格",
            "网址表格",
            "make a table",
            "as a table",
        ],
    ):
        outputs.append("table")
    return outputs or list(default)


def _data_analysis_expected_outputs(
    text: str,
    *,
    result_open_app_hint: str = "",
) -> list[str]:
    outputs = _expected_outputs(text, default=["analysis_report"])
    if result_open_app_hint and result_open_app_hint in {"Excel", "Numbers"}:
        if "table" not in outputs:
            outputs.append("table")
    return outputs
